//! PyO3 Python bindings for FrankenPandas.
//!
//! Exposes DataFrame, Series, and core operations to Python.
//!
//! ```python
//! import frankenpandas as fp
//!
//! # Create a Series
//! s = fp.Series([1, 2, 3, 4, 5], name="values")
//! print(s.sum())  # 15
//!
//! # Create a DataFrame
//! df = fp.DataFrame({"a": [1, 2, 3], "b": [4.0, 5.0, 6.0]})
//! print(df.head(2))
//! ```

#![forbid(unsafe_code)]
#![allow(clippy::collapsible_if, clippy::needless_range_loop)]

use std::{
    collections::{BTreeMap, BTreeSet, HashMap, HashSet},
    sync::{Arc, LazyLock, Mutex},
};

use fp_columnar::{ArithmeticOp, Column, ComparisonOp};
use fp_expr::DataFrameExprExt;
use fp_frame::{
    DataFrame, DropNaHow, FrameError, LabelName, PlotKind, Series, concat_dataframes, concat_series,
};
use fp_index::{
    AlignMode, CategoricalIndex, DatetimeIndex, DuplicateKeep, Index, IndexLabel, MultiIndex,
    OrderedF64, PeriodIndex, RangeIndex, TimedeltaIndex,
};
use fp_types::{
    CategoricalMetadata, DType, IntervalClosed, NullKind, NumericWidth, Period, PeriodFreq, Scalar,
    Timedelta, Timestamp,
};
use mimalloc::MiMalloc;
use pyo3::{
    IntoPyObjectExt,
    prelude::*,
    types::{
        PyDateAccess, PyDateTime, PyDelta, PyDeltaAccess, PyDict, PyFrozenSet, PyList, PySet,
        PyTimeAccess, PyTuple, PyTzInfoAccess,
    },
};
use rustc_hash::FxHashMap;

#[global_allocator]
static GLOBAL: MiMalloc = MiMalloc;

/// Parse frequency string like "D", "2D", "h", "30s", "min", "ms", "us", "ns" into nanoseconds.
fn parse_freq_to_nanos(freq: &str) -> PyResult<i64> {
    let s = freq.trim();
    if s.is_empty() {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "empty freq",
        ));
    }
    let split_pos = s.find(|c: char| !c.is_ascii_digit()).unwrap_or(s.len());
    let (count_str, unit_str) = s.split_at(split_pos);
    let count: i64 = if count_str.is_empty() {
        1
    } else {
        count_str.parse().map_err(|_| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid freq count: {count_str}"
            ))
        })?
    };
    let unit = unit_str.trim();
    let base_nanos = match unit {
        "D" | "d" => 86_400_000_000_000_i64,
        "h" | "H" => 3_600_000_000_000_i64,
        "min" | "T" | "m" => 60_000_000_000_i64,
        "s" | "S" => 1_000_000_000_i64,
        "ms" | "L" => 1_000_000_i64,
        "us" | "U" => 1_000_i64,
        "ns" | "N" | "" => 1_i64,
        other => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "unsupported frequency: {other}"
            )));
        }
    };
    count
        .checked_mul(base_nanos)
        .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyValueError, _>("frequency overflow"))
}

/// `shift`'s `periods`: one int (1 by default), or pandas 2.1's list of them.
enum ShiftPeriods<'a, 'py> {
    One(i64),
    Many(&'a Bound<'py, PyAny>),
}

impl<'a, 'py> ShiftPeriods<'a, 'py> {
    fn of(periods: Option<&'a Bound<'py, PyAny>>) -> PyResult<Self> {
        match periods.filter(|periods| !periods.is_none()) {
            None => Ok(Self::One(1)),
            Some(periods) => match periods.extract::<i64>() {
                Ok(one) => Ok(Self::One(one)),
                Err(_)
                    if periods.try_iter().is_ok()
                        && !periods.is_instance_of::<pyo3::types::PyString>() =>
                {
                    Ok(Self::Many(periods))
                }
                Err(err) => Err(err),
            },
        }
    }
}

/// pandas' refusal of `suffix` beside one int `periods` (it was fp's
/// NotImplementedError).
fn refuse_int_shift_suffix(suffix: Option<&str>) -> PyResult<()> {
    if suffix.is_some() {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "Cannot specify `suffix` if `periods` is an int.",
        ));
    }
    Ok(())
}

/// pandas' `shift` by a list of periods: `frame` shifted by each, its
/// columns suffixed `_<period>` (`<suffix>_<period>` with a suffix), side by
/// side; axis=1 and an empty list are pandas' ValueError, a period that is
/// not an int its TypeError (a Series shifts as its one-column frame).
fn shifts_frame(
    frame: &Bound<'_, PyAny>,
    periods: &Bound<'_, PyAny>,
    freq: Option<&str>,
    axis: Option<&Bound<'_, PyAny>>,
    fill_value: Option<&Bound<'_, PyAny>>,
    suffix: Option<&str>,
) -> PyResult<Py<PyAny>> {
    let py = frame.py();
    if parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0) == 1 {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "If `periods` contains multiple shifts, `axis` cannot be 1.",
        ));
    }
    let periods: Vec<Bound<'_, PyAny>> = periods.try_iter()?.collect::<PyResult<_>>()?;
    if periods.is_empty() {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "If `periods` is an iterable, it cannot be empty.",
        ));
    }
    let kwargs = PyDict::new(py);
    if let Some(freq) = freq {
        kwargs.set_item("freq", freq)?;
    }
    if let Some(fill_value) = fill_value {
        kwargs.set_item("fill_value", fill_value)?;
    }
    let mut shifted = Vec::with_capacity(periods.len());
    for period in &periods {
        let step = match period.extract::<i64>() {
            Ok(step) if !period.is_instance_of::<pyo3::types::PyBool>() => step,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "Periods must be integer, but {} is {}.",
                    period.str()?,
                    period.get_type().repr()?
                )));
            }
        };
        let tag = format!("{}_{step}", suffix.unwrap_or(""));
        shifted.push(
            frame
                .call_method("shift", (step,), Some(&kwargs))?
                .call_method1("add_suffix", (tag,))?,
        );
    }
    let concat_kwargs = PyDict::new(py);
    concat_kwargs.set_item("axis", 1)?;
    Ok(py
        .import("frankenpandas")?
        .getattr("concat")?
        .call((PyList::new(py, shifted)?,), Some(&concat_kwargs))?
        .unbind())
}

/// `obj.shift(periods, freq=...)`: the row index moved by `periods` x
/// `freq`, the values left where they are, as pandas shifts an index (it
/// was refused). A fixed-duration freq over a datetime or timedelta index;
/// a fill_value is ignored with pandas' FutureWarning.
fn shift_index_by_freq(
    index: &Index,
    periods: i64,
    freq: &str,
    fill_value: Option<&Bound<'_, PyAny>>,
) -> PyResult<Index> {
    if let Some(fill) = fill_value.filter(|fill| !fill.is_none()) {
        let py = fill.py();
        PyErr::warn(
            py,
            &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
            c"Passing a 'freq' together with a 'fill_value' silently ignores the fill_value and is deprecated. This will raise in a future version.",
            1,
        )?;
    }
    let labels = index.labels();
    let kind = |datetime: bool| {
        labels.iter().any(|label| match label {
            IndexLabel::Datetime64(_) => datetime,
            IndexLabel::Timedelta64(_) => !datetime,
            _ => false,
        }) && labels.iter().all(|label| match label {
            IndexLabel::Datetime64(_) => datetime,
            IndexLabel::Timedelta64(_) => !datetime,
            IndexLabel::Null(_) => true,
            _ => false,
        })
    };
    if !kind(true) && !kind(false) {
        return Err(PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(
            "This method is only implemented for DatetimeIndex, PeriodIndex and TimedeltaIndex; Got type Index",
        ));
    }
    let overflow = || PyErr::new::<pyo3::exceptions::PyOverflowError, _>("Timestamp overflow");
    let step = parse_freq_to_nanos(freq)?
        .checked_mul(periods)
        .ok_or_else(overflow)?;
    let moved = labels
        .iter()
        .map(|label| match label {
            IndexLabel::Datetime64(nanos) if *nanos != i64::MIN => nanos
                .checked_add(step)
                .map(IndexLabel::Datetime64)
                .ok_or_else(overflow),
            IndexLabel::Timedelta64(nanos) if *nanos != i64::MIN => nanos
                .checked_add(step)
                .map(IndexLabel::Timedelta64)
                .ok_or_else(overflow),
            other => Ok(other.clone()),
        })
        .collect::<PyResult<Vec<_>>>()?;
    // A fixed duration moves the instants; a tz-aware index keeps its zone,
    // and the spacing - its freq - is unchanged (pandas keeps it; the
    // footer's 'Freq: 6h' was lost).
    Index::new(moved)
        .set_names(index.name())
        .with_tz(index.tz())
        .map(|shifted| shifted.with_freq(index.freq().map(str::to_owned)))
        .map_err(index_error_to_py)
}

/// Map a pandas dtype name to a FrankenPandas `DType` with pandas' meanings:
/// "Int64"/"Float64"/"boolean" are the nullable dtypes, "category" is
/// categorical (fp-types' `FromStr`); "i64"/"f64" are binding aliases.
fn parse_dtype(name: &str) -> PyResult<fp_types::DType> {
    use fp_types::DType;
    match name {
        "i64" => Ok(DType::Int64),
        "f64" => Ok(DType::Float64),
        other => other.parse::<DType>().map_err(|_| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "data type '{other}' not understood"
            ))
        }),
    }
}

/// pandas' dtype name for a column: numpy bool cannot hold a missing value,
/// so a bool column with one is pandas' object (it said bool; fvsao.13).
/// pandas' `nlargest` / `nsmallest` column check (SelectN's
/// `is_valid_dtype_n_method`): numbers (bools too), datetimes, timedeltas
/// and periods pass; any other column's pandas dtype name is returned, its
/// selection pandas' TypeError (text was sorted; k56su).
fn n_method_refused_dtype(column: &Column) -> Option<String> {
    let name = column_pandas_dtype_name(column);
    let selectable = column.categorical().is_none()
        && name != "object"
        && matches!(
            column.dtype(),
            DType::Int64
                | DType::Int64Nullable
                | DType::Float64
                | DType::Float64Nullable
                | DType::Bool
                | DType::BoolNullable
                | DType::Datetime64 { .. }
                | DType::Timedelta64
                | DType::Period
        );
    (!selectable).then_some(name)
}

fn column_pandas_dtype_name(column: &Column) -> String {
    let dtype = column.dtype();
    // A narrow numpy dtype, or its masked form (int32 / Int32; fvsao.23).
    if let Some(width) = column.width() {
        return width.name(dtype.is_nullable()).to_owned();
    }
    // pandas' `string` extension dtype (fvsao.59).
    if column.is_pandas_string() {
        return "string".to_owned();
    }
    if dtype == DType::Bool && column.has_any_missing() {
        return "object".to_owned();
    }
    // Periods name their frequency, as pandas' period[M] (it said period).
    if dtype == DType::Period
        && let Some(freq) = column_period_freq(column)
    {
        return format!("period[{}]", freq.alias());
    }
    pandas_dtype_name(&dtype)
}

/// pandas' IntervalDtype of an interval column: its subtype int64 only when
/// every value is an interval of int endpoints (a missing value makes it
/// float64, as numpy's NaN does), its closed side its intervals' (pandas'
/// default right with none). str() of it is interval[int64, right]; its
/// name, which a Series repr prints, stays interval. It was the text
/// 'interval' (br-frankenpandas-q69jo).
fn column_interval_dtype(column: &Column) -> PyIntervalDtype {
    let mut closed = None;
    let mut all_int = true;
    for value in column.values() {
        match value {
            Scalar::Interval(interval) => {
                closed.get_or_insert(interval.closed);
                all_int &= interval.subtype == fp_types::IntervalSubtype::Int64;
            }
            _ => all_int = false,
        }
    }
    let subtype = if closed.is_some() && all_int {
        "int64"
    } else {
        "float64"
    };
    PyIntervalDtype {
        subtype: Some(subtype.to_owned()),
        closed: Some(
            closed
                .unwrap_or(fp_types::IntervalClosed::Right)
                .to_string(),
        ),
    }
}

/// Whether every cell of a `dtype` column is its own typed scalar or
/// missing - a number, bool, datetime or duration column, which the casts
/// keep free of Period, Interval and Python-object cells. A scan for such
/// cells answers from the dtype: it read every value, building a column's
/// million-Scalar view (77% of `s + s`; br-frankenpandas-w1nrd).
fn holds_only_typed_cells(dtype: &DType) -> bool {
    dtype.is_numeric()
        || dtype.is_bool()
        || matches!(dtype, DType::Datetime64 { .. } | DType::Timedelta64)
}

/// The frequency of a Period column's values (None when none is a period).
fn column_period_freq(column: &Column) -> Option<PeriodFreq> {
    if holds_only_typed_cells(&column.dtype()) {
        return None;
    }
    column.values().iter().find_map(|value| match value {
        Scalar::Period(period) => Some(period.freq),
        _ => None,
    })
}

/// A Period column's values as the PeriodIndex pandas' `.dt` of periods
/// reads (a missing value NaT at the column's frequency).
fn column_period_index(column: &Column) -> fp_index::PeriodIndex {
    let freq = column_period_freq(column).unwrap_or(PeriodFreq::Daily);
    fp_index::PeriodIndex::new(
        column
            .values()
            .iter()
            .map(|value| match value {
                Scalar::Period(period) => *period,
                _ => Period::new(i64::MIN, freq),
            })
            .collect(),
    )
}

/// A Period column compared with one period - a Period, or its text read at
/// the column's frequency - as pandas compares them: by position on the
/// frequency axis (`holds` of the ordering), a NaT on either side `missing`
/// (False; True for `!=`); another frequency is pandas' IncompatibleFrequency
/// (a ValueError). It raised "non-numeric dtype Period". None when `series`
/// holds no periods or `other` is no period.
fn period_comparison(
    series: &Series,
    other: &Bound<'_, PyAny>,
    holds: fn(std::cmp::Ordering) -> bool,
    missing: bool,
) -> PyResult<Option<Series>> {
    let Some(freq) = column_period_freq(series.column()) else {
        return Ok(None);
    };
    let period = if let Ok(period) = other.extract::<PyRef<'_, PyPeriod>>() {
        period.inner
    } else if let Ok(text) = other.extract::<String>() {
        period_from_text(&text, Some(freq.alias()))?
    } else {
        return Ok(None);
    };
    if period.freq != freq && period.ordinal != i64::MIN {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "Invalid comparison between dtype=period[{}] and Period",
            freq.alias()
        )));
    }
    let flags = series
        .column()
        .values()
        .iter()
        .map(|value| match value {
            Scalar::Period(own) if own.ordinal != i64::MIN && period.ordinal != i64::MIN => {
                Scalar::Bool(holds(own.ordinal.cmp(&period.ordinal)))
            }
            _ => Scalar::Bool(missing),
        })
        .collect();
    let column = Column::from_values(flags).map_err(column_error_to_py)?;
    Series::new(series.name(), series.index().clone(), column)
        .map(Some)
        .map_err(frame_error_to_py)
}

/// `series + n` / `series - n` of a Period column: each period `n` steps
/// along its frequency (NaT stays NaT), as pandas (it raised "no compatible
/// common type"). None when `series` holds no periods or `n` is no int.
fn shifted_periods(series: &Series, n: &Bound<'_, PyAny>, sign: i64) -> PyResult<Option<Series>> {
    if series.column().dtype() != DType::Period || n.is_instance_of::<pyo3::types::PyBool>() {
        return Ok(None);
    }
    let Some(steps) = n.extract::<i64>().ok().and_then(|n| n.checked_mul(sign)) else {
        return Ok(None);
    };
    let values = series
        .column()
        .values()
        .iter()
        .map(|value| match value {
            Scalar::Period(period) if period.ordinal != i64::MIN => {
                Scalar::Period(period.shift(steps))
            }
            other => other.clone(),
        })
        .collect();
    let column = Column::from_values(values).map_err(column_error_to_py)?;
    Series::new(series.name(), series.index().clone(), column)
        .map(Some)
        .map_err(frame_error_to_py)
}

/// pandas' dtype OBJECT for a column (`Series.dtype`): numpy's dtype for
/// the numpy-backed types, so `s.dtype == np.float64`, `.kind` and `.name`
/// behave (it was the name as a str: `== np.float64` was False and `.kind`
/// raised); the extension dtype classes for the nullable, categorical and
/// tz-aware ones; the name for anything else.
fn column_pandas_dtype<'py>(py: Python<'py>, column: &Column) -> PyResult<Bound<'py, PyAny>> {
    let name = column_pandas_dtype_name(column);
    if let Some(width) = column.width() {
        return if column.dtype().is_nullable() {
            masked_width_dtype(py, width)
        } else {
            py.import("numpy")?.call_method1("dtype", (name,))
        };
    }
    if column.is_pandas_string() {
        return PyStringDtype::default().into_bound_py_any(py);
    }
    if matches!(
        name.as_str(),
        "int64" | "float64" | "bool" | "object" | "datetime64[ns]" | "timedelta64[ns]"
    ) {
        return py.import("numpy")?.call_method1("dtype", (name,));
    }
    match column.dtype() {
        DType::Int64Nullable => PyInt64Dtype.into_bound_py_any(py),
        DType::Float64Nullable => PyFloat64Dtype.into_bound_py_any(py),
        DType::BoolNullable => PyBooleanDtype.into_bound_py_any(py),
        DType::Categorical => {
            let (categories, ordered) = column.categorical().map_or((None, false), |meta| {
                (Some(meta.categories.clone()), meta.ordered)
            });
            PyCategoricalDtype {
                categories,
                ordered,
            }
            .into_bound_py_any(py)
        }
        DType::Datetime64 { tz: Some(tz) } => PyDatetimeTZDtype {
            unit: "ns".to_owned(),
            tz: tz.to_string(),
        }
        .into_bound_py_any(py),
        DType::Interval => column_interval_dtype(column).into_bound_py_any(py),
        // pandas' PeriodDtype, period[M] (it was the str; 45fzr).
        DType::Period => index_dtype_object(py, &name, None),
        _ => Ok(pyo3::types::PyString::new(py, &name).into_any()),
    }
}

/// pandas' masked extension dtype of a narrow width: `pd.Int8Dtype()` ...
/// `pd.Float32Dtype()`.
fn masked_width_dtype(py: Python<'_>, width: NumericWidth) -> PyResult<Bound<'_, PyAny>> {
    match width {
        NumericWidth::Int8 => PyInt8Dtype.into_bound_py_any(py),
        NumericWidth::Int16 => PyInt16Dtype.into_bound_py_any(py),
        NumericWidth::Int32 => PyInt32Dtype.into_bound_py_any(py),
        NumericWidth::UInt8 => PyUInt8Dtype.into_bound_py_any(py),
        NumericWidth::UInt16 => PyUInt16Dtype.into_bound_py_any(py),
        NumericWidth::UInt32 => PyUInt32Dtype.into_bound_py_any(py),
        NumericWidth::UInt64 => PyUInt64Dtype.into_bound_py_any(py),
        NumericWidth::Float32 => PyFloat32Dtype.into_bound_py_any(py),
    }
}

/// pandas' dtype object for an index's dtype `name` (as the index spells
/// it): numpy's for int64 / float64 / bool / object / datetime64[ns] /
/// timedelta64[ns], DatetimeTZDtype for a zoned one, PeriodDtype for
/// period[F], CategoricalDtype (of `categories`) for category; the name for
/// anything else. `Index.dtype` was the name as a str (`.kind` raised).
fn index_dtype_object<'py>(
    py: Python<'py>,
    name: &str,
    categories: Option<(Vec<Scalar>, bool)>,
) -> PyResult<Bound<'py, PyAny>> {
    if matches!(
        name,
        "int64" | "int32" | "float64" | "bool" | "object" | "datetime64[ns]" | "timedelta64[ns]"
    ) {
        return py.import("numpy")?.call_method1("dtype", (name,));
    }
    if let Some(zone) = name
        .strip_prefix("datetime64[ns, ")
        .and_then(|rest| rest.strip_suffix(']'))
    {
        return PyDatetimeTZDtype {
            unit: "ns".to_owned(),
            tz: zone.to_owned(),
        }
        .into_bound_py_any(py);
    }
    if let Some(freq) = name
        .strip_prefix("period[")
        .and_then(|rest| rest.strip_suffix(']'))
    {
        return PyPeriodDtype {
            freq: freq.to_owned(),
        }
        .into_bound_py_any(py);
    }
    if name == "category" {
        let (categories, ordered) = categories.unwrap_or_default();
        return PyCategoricalDtype {
            categories: Some(categories),
            ordered,
        }
        .into_bound_py_any(py);
    }
    Ok(pyo3::types::PyString::new(py, name).into_any())
}

/// pandas' `maybe_cast_pointwise_result` for `Series.combine`: the answers,
/// typed from what `func` returned, go back to the Series' dtype when no
/// value changes - an int Series' max(34, 120.0) is the int 120, a float
/// Series' int answers are floats, an int32 or nullable Int64 Series keeps
/// its dtype - and keep their own dtype otherwise: a fractional or missing
/// answer of a numpy int, bool answers of a number, text
/// (br-frankenpandas-s1pnw).
fn cast_pointwise_like(answers: Column, source: &Column) -> Column {
    // numpy's allclose(rtol=0, atol=1e-8) between the answers and their
    // integer cast (a truncation).
    let near_integral = |v: f64| v.is_finite() && (v - v.trunc()).abs() <= 1e-8;
    let floats = || -> Option<Vec<f64>> {
        answers
            .values()
            .iter()
            .map(|value| match value {
                Scalar::Float64(v) => Some(*v),
                Scalar::Int64(v) => Some(*v as f64),
                _ => None,
            })
            .collect()
    };
    let cast = match (source.dtype(), answers.dtype()) {
        (DType::Int64, DType::Int64) => Some(answers.clone().narrowed_like(source)),
        (DType::Int64, DType::Float64) => floats()
            .filter(|values| values.iter().all(|&v| near_integral(v)))
            .and_then(|values| {
                let ints = values
                    .iter()
                    .map(|&v| Scalar::Int64(v.trunc() as i64))
                    .collect();
                Column::new(DType::Int64, ints).ok()
            })
            .map(|column| column.narrowed_like(source)),
        (DType::Float64, DType::Int64 | DType::Float64) => {
            let column = answers.astype(DType::Float64).ok();
            // A float32 Series takes them when float32 holds each within
            // pandas' 5e-4.
            let fits_f32 = source.width().is_none_or(|_| {
                floats().is_some_and(|values| {
                    values
                        .iter()
                        .all(|&v| v.is_nan() || (f64::from(v as f32) - v).abs() <= 5e-4)
                })
            });
            column.map(|column| {
                if fits_f32 {
                    column.narrowed_like(source)
                } else {
                    column
                }
            })
        }
        (DType::Bool, DType::Int64 | DType::Float64) => floats()
            .filter(|values| values.iter().all(|&v| v == 0.0 || (v - 1.0).abs() <= 1e-8))
            .and_then(|values| {
                Column::new(
                    DType::Bool,
                    values.iter().map(|&v| Scalar::Bool(v != 0.0)).collect(),
                )
                .ok()
            }),
        // The extension dtypes' _from_sequence: integral numbers and missing
        // values make an Int64, any numbers a Float64.
        (DType::Int64Nullable | DType::Float64Nullable, _) => {
            let integer = source.dtype() == DType::Int64Nullable;
            answers
                .values()
                .iter()
                .map(|value| match value {
                    Scalar::Null(_) => Some(Scalar::Null(NullKind::Null)),
                    Scalar::Float64(v) if v.is_nan() => Some(Scalar::Null(NullKind::Null)),
                    Scalar::Int64(v) if integer => Some(Scalar::Int64(*v)),
                    Scalar::Float64(v) if integer && v.fract() == 0.0 && v.abs() < 9.2e18 => {
                        Some(Scalar::Int64(*v as i64))
                    }
                    Scalar::Int64(v) => Some(Scalar::Float64(*v as f64)),
                    Scalar::Float64(v) if !integer => Some(Scalar::Float64(*v)),
                    _ => None,
                })
                .collect::<Option<Vec<_>>>()
                .and_then(|values| Column::new(source.dtype(), values).ok())
                .map(|column| column.narrowed_like(source))
        }
        _ => None,
    };
    cast.unwrap_or(answers)
}

/// pandas' name for a dtype, as `Series.dtype` / `DataFrame.dtypes` print it.
fn pandas_dtype_name(dtype: &fp_types::DType) -> String {
    use fp_types::DType;
    match dtype {
        DType::Int64 => "int64".to_owned(),
        DType::Int64Nullable => "Int64".to_owned(),
        DType::Float64 => "float64".to_owned(),
        DType::Float64Nullable => "Float64".to_owned(),
        DType::Bool => "bool".to_owned(),
        DType::BoolNullable => "boolean".to_owned(),
        DType::Utf8 | DType::Null => "object".to_owned(),
        DType::Categorical => "category".to_owned(),
        DType::Datetime64 { tz: None } => "datetime64[ns]".to_owned(),
        DType::Datetime64 { tz: Some(tz) } => format!("datetime64[ns, {tz}]"),
        DType::Timedelta64 => "timedelta64[ns]".to_owned(),
        other => format!("{other:?}").to_ascii_lowercase(),
    }
}

// ── pandas' repr layout (fvsao.7) ───────────────────────────────────────
// pandas 2.2.3's formatters, measured on the pinned oracle: a Series joins
// its left-justified index and right-justified values with 3 spaces
// (SeriesFormatter, adjoin(3)); a DataFrame joins its columns with 1 space
// under right-justified headers (a numeric column's header takes a leading
// space); more than 60 rows show the first and last 5 around a dot row; the
// footer is "Name: ..., Length: ..., dtype: ..." / "[n rows x m columns]".

/// pandas' float cells (`None` = missing, shown NaN): `{: .6f}` with the
/// common trailing zeros trimmed (one decimal kept), or `{: .6e}` when a
/// value is below 1e-6 or the fixed form runs long with values above 1e6
/// (FloatArrayFormatter). The 6 is `display.precision` (it was fixed at 6);
/// a `display.float_format` callable renders every present value instead
/// (br-frankenpandas-fzfbp).
fn pandas_float_cells(values: &[Option<f64>]) -> Vec<String> {
    if let Some(format) = display_float_format() {
        let rendered = Python::attach(|py| {
            values
                .iter()
                .map(|value| match value {
                    None => Ok("NaN".to_owned()),
                    Some(value) => format
                        .0
                        .bind(py)
                        .call1((*value,))?
                        .str()?
                        .extract::<String>(),
                })
                .collect::<PyResult<Vec<_>>>()
        });
        if let Ok(cells) = rendered {
            return cells;
        }
    }
    let digits = display_limit("display.precision").flatten().unwrap_or(6);
    let signed = |body: String, value: f64| {
        if value.is_sign_negative() {
            format!("-{body}")
        } else {
            format!(" {body}")
        }
    };
    let fixed = |value: f64| signed(format!("{:.digits$}", value.abs()), value);
    let scientific = |value: f64| {
        // inf / NaN have no exponent: pandas shows them as the fixed form
        // does (they came out 'infe+00'; br-frankenpandas-pjww1).
        if !value.is_finite() {
            return fixed(value);
        }
        let text = format!("{:.digits$e}", value.abs());
        let (mantissa, exponent) = text.split_once('e').unwrap_or((text.as_str(), "0"));
        let exponent: i32 = exponent.parse().unwrap_or(0);
        let sign = if exponent < 0 { '-' } else { '+' };
        signed(format!("{mantissa}e{sign}{:02}", exponent.abs()), value)
    };
    let render = |format: &dyn Fn(f64) -> String| {
        trim_float_zeros(
            values
                .iter()
                .map(|value| value.map_or_else(|| "NaN".to_owned(), format))
                .collect(),
        )
    };
    let cells = render(&fixed);
    let magnitudes: Vec<f64> = values.iter().flatten().map(|value| value.abs()).collect();
    let too_long = cells.iter().map(text_width).max().unwrap_or(0) > digits + 6;
    let large = magnitudes.iter().any(|&value| value > 1e6);
    // pandas' has_small_values: below 10 ** -precision.
    let smallest = 10_f64.powi(-i32::try_from(digits).unwrap_or(6));
    let small = magnitudes
        .iter()
        .any(|&value| value > 0.0 && value < smallest);
    if small || (too_long && large) {
        render(&scientific)
    } else {
        cells
    }
}

/// pandas' `_trim_zeros_float`: while every decimal number ends in 0, drop
/// that 0 from all of them; a bare decimal point gets its 0 back.
fn trim_float_zeros(mut cells: Vec<String>) -> Vec<String> {
    let decimal = |cell: &str| {
        let text = cell.trim_start();
        let text = text.strip_prefix(['+', '-']).unwrap_or(text);
        text.split_once('.').is_some_and(|(whole, fraction)| {
            !whole.is_empty()
                && whole.bytes().all(|b| b.is_ascii_digit())
                && fraction.bytes().all(|b| b.is_ascii_digit())
        })
    };
    loop {
        let mut numbers = cells.iter().filter(|cell| decimal(cell)).peekable();
        if numbers.peek().is_none() || !numbers.all(|cell| cell.ends_with('0')) {
            break;
        }
        for cell in cells.iter_mut().filter(|cell| decimal(cell)) {
            cell.pop();
        }
    }
    for cell in cells
        .iter_mut()
        .filter(|cell| decimal(cell) && cell.ends_with('.'))
    {
        cell.push('0');
    }
    cells
}

/// pandas' datetime cells: a date when every instant is a midnight, else
/// the time too with one fraction width for all - 3, 6 or 9 digits in a
/// Series, 6 or 9 in an `index` (DatetimeIndex's repr) - and NaT.
fn pandas_datetime_cells(values: &[Option<i64>], index: bool) -> Vec<String> {
    const DAY: i64 = 86_400_000_000_000;
    let instants = || values.iter().flatten();
    let dates_only = instants().all(|&nanos| nanos.rem_euclid(DAY) == 0);
    let digits = if instants().any(|&nanos| nanos.rem_euclid(1_000) != 0) {
        9
    } else if instants().any(|&nanos| nanos.rem_euclid(1_000_000) != 0) {
        6
    } else if instants().any(|&nanos| nanos.rem_euclid(1_000_000_000) != 0) {
        if index { 6 } else { 3 }
    } else {
        0
    };
    values
        .iter()
        .map(|value| {
            let Some(nanos) = value else {
                return "NaT".to_owned();
            };
            let text = fp_index::format_datetime_ns(*nanos);
            let base = text.get(..19).unwrap_or(&text);
            if dates_only {
                return base.get(..10).unwrap_or(base).to_owned();
            }
            if digits == 0 {
                return base.to_owned();
            }
            let fraction = format!("{:09}", nanos.rem_euclid(1_000_000_000));
            format!("{base}.{}", &fraction[..digits])
        })
        .collect()
}

/// Instants of a tz-aware column or index as pandas prints them: each one's
/// wall clock in `zone` as `str(Timestamp)` does - its own fraction (none,
/// six digits, or nine for nanoseconds), then the `+HH:MM` offset, never a
/// bare date - and NaT (a non-UTC zone fell back to frankenpandas' own
/// Display; UTC dropped the fraction).
fn pandas_aware_datetime_texts(values: &[Option<i64>], zone: &str) -> Vec<String> {
    values
        .iter()
        .map(|value| match *value {
            Some(nanos) => fp_types::timestamp_text_in_zone(nanos, zone),
            None => "NaT".to_owned(),
        })
        .collect()
}

/// pandas' `Timedelta._repr_base`: "N days" when `long` is off and the
/// value is whole days, else "N days HH:MM:SS[.ffffff[fff]]" - milliseconds
/// and microseconds together whenever either is there (1.5 s is
/// '.500000'; it printed '.500'; br-frankenpandas-n33o4), nanoseconds
/// after them.
fn pandas_timedelta_text(nanos: i64, long: bool) -> String {
    const SECOND: i64 = 1_000_000_000;
    let days = nanos.div_euclid(86_400 * SECOND);
    let rest = nanos.rem_euclid(86_400 * SECOND);
    let (hours, minutes, seconds) = (
        rest / (3_600 * SECOND),
        rest / (60 * SECOND) % 60,
        rest / SECOND % 60,
    );
    let sub = rest % SECOND;
    let (ms, us, ns) = (sub / 1_000_000, sub / 1_000 % 1_000, sub % 1_000);
    let seconds = if ns != 0 {
        format!("{seconds:02}.{ms:03}{us:03}{ns:03}")
    } else if us != 0 || ms != 0 {
        format!("{seconds:02}.{ms:03}{us:03}")
    } else {
        format!("{seconds:02}")
    };
    if rest != 0 || long {
        let sign = if days < 0 { " +" } else { " " };
        format!("{days} days{sign}{hours:02}:{minutes:02}:{seconds}")
    } else {
        format!("{days} days")
    }
}

/// A masked (Float64) float as pandas prints it: `f"{x: .6f}"` - a sign
/// space before a positive - with its trailing zeros trimmed to one decimal
/// (1.414214, 2.0, -0.5). It printed each value's full repr
/// (1.4142135623730951).
fn masked_float_text(value: f64) -> String {
    if !value.is_finite() {
        let text = if value.is_nan() {
            "nan"
        } else if value > 0.0 {
            "inf"
        } else {
            "-inf"
        };
        return if text.starts_with('-') {
            text.to_owned()
        } else {
            format!(" {text}")
        };
    }
    let text = format!("{value:.6}");
    let trimmed = text.trim_end_matches('0');
    let trimmed = if trimmed.ends_with('.') {
        format!("{trimmed}0")
    } else {
        trimmed.to_owned()
    };
    if trimmed.starts_with('-') {
        trimmed
    } else {
        format!(" {trimmed}")
    }
}

/// A Python-`str()`-like text for one object cell.
fn pandas_object_text(value: &Scalar) -> String {
    match value {
        // pandas' pprint_thing escapes tabs and line breaks in a printed
        // cell or label ('a\nb' prints as a\nb; it broke the line).
        Scalar::Utf8(text) => text
            .replace('\t', "\\t")
            .replace('\n', "\\n")
            .replace('\r', "\\r"),
        Scalar::Null(NullKind::Null) => "None".to_owned(),
        Scalar::Null(NullKind::NaT) => "NaT".to_owned(),
        Scalar::Null(_) => "NaN".to_owned(),
        Scalar::Bool(flag) => if *flag { "True" } else { "False" }.to_owned(),
        Scalar::Float64(v) if v.fract() == 0.0 && v.abs() < 1e16 => format!("{v:.1}"),
        Scalar::Datetime64(nanos) => fp_index::format_datetime_ns(*nanos),
        Scalar::Timedelta64(nanos) => pandas_timedelta_text(*nanos, true),
        // pandas' pprint of an object cell: a list's strings unquoted.
        Scalar::Object(object) => object.pprint(),
        other => other.to_string(),
    }
}

/// pandas' dtype for a categorical's `categories` (the footer's
/// `Categories (3, int64)`, CategoricalDtype's `categories_dtype`): the one
/// kind they share, float64 for ints beside floats, object for text or a
/// mix, and for Intervals `interval[int64, right]` - their subtype (int64
/// only when every one is) and closed side; they printed 'interval'
/// (fvsao.54).
fn categories_dtype_name(categories: &[Scalar]) -> String {
    let all = |test: fn(&Scalar) -> bool| !categories.is_empty() && categories.iter().all(test);
    if let Some(Scalar::Interval(first)) = categories.first()
        && all(|category| matches!(category, Scalar::Interval(_)))
    {
        let int = all(|category| {
            matches!(category, Scalar::Interval(interval)
                if interval.subtype == fp_types::IntervalSubtype::Int64)
        });
        return fp_types::IntervalDtype {
            subtype: if int { DType::Int64 } else { DType::Float64 },
            closed: Some(first.closed),
        }
        .to_string();
    }
    if all(|category| matches!(category, Scalar::Int64(_) | Scalar::Float64(_)))
        && !all(|category| matches!(category, Scalar::Int64(_)))
    {
        return "float64".to_owned();
    }
    match categories.first() {
        Some(first)
            if !matches!(first, Scalar::Utf8(_))
                && categories
                    .iter()
                    .all(|category| category.dtype() == first.dtype()) =>
        {
            pandas_dtype_name(&first.dtype())
        }
        _ => "object".to_owned(),
    }
}

/// pandas' `format_array(values, quoting=QUOTE_NONNUMERIC)`, stripped, as a
/// Categorical prints its values and categories: text quoted, numbers at the
/// common precision their column prints ('1.25', '2.50'), a missing value
/// NaN, anything else as it prints.
fn pandas_quoted_texts(values: &[Scalar]) -> Vec<String> {
    let cells = Column::from_values(values.to_vec())
        .map(|column| pandas_cells(&column))
        .unwrap_or_default();
    values
        .iter()
        .enumerate()
        .map(|(position, value)| match value {
            Scalar::Utf8(text) => format!("'{text}'"),
            value if value.is_missing() => "NaN".to_owned(),
            other => cells
                .get(position)
                .map_or_else(|| pandas_object_text(other), |cell| cell.trim().to_owned()),
        })
        .collect()
}

/// pandas' `Categorical._repr_categories_info` at the default display.width
/// 80 and display.max_categories 8: `Categories (n, dtype): [...]`, the
/// first and last 4 around '...' past 8, joined by ' < ' when ordered, the
/// line broken under the bracket past 80 columns (with pandas' own column
/// count). It listed every category on one line.
fn pandas_categories_info(meta: &CategoricalMetadata) -> String {
    const MAX_WIDTH: usize = 80;
    const MAX_CATEGORIES: usize = 8;
    let categories = &meta.categories;
    let texts = if categories.len() > MAX_CATEGORIES {
        let num = MAX_CATEGORIES / 2;
        let mut texts = pandas_quoted_texts(&categories[..num]);
        texts.push("...".to_owned());
        texts.extend(pandas_quoted_texts(&categories[categories.len() - num..]));
        texts
    } else {
        pandas_quoted_texts(categories)
    };
    let header = format!(
        "Categories ({}, {}): ",
        categories.len(),
        categories_dtype_name(categories)
    );
    let header_len = header.chars().count();
    let (sep_len, sep) = if meta.ordered { (3, " < ") } else { (2, ", ") };
    let line_break = format!("{}\n{}", sep.trim_end(), " ".repeat(header_len + 1));
    let mut levels = String::new();
    let mut width = header_len;
    for (position, text) in texts.iter().enumerate() {
        let text_len = text.chars().count();
        if width + sep_len + text_len > MAX_WIDTH {
            levels.push_str(&line_break);
            width = header_len + 1;
        } else if position > 0 {
            levels.push_str(sep);
            width += text_len;
        }
        levels.push_str(text);
    }
    format!("{header}[{}]", levels.replace(" < ... < ", " ... "))
}

/// `categories` as pandas' Index repr lists them: text quoted (escaped),
/// an Interval as it prints, anything else as Python prints it.
fn category_repr_items(categories: &[Scalar]) -> Vec<String> {
    categories
        .iter()
        .map(|category| match category {
            Scalar::Utf8(text) => format!(
                "'{}'",
                text.replace('\t', "\\t")
                    .replace('\r', "\\r")
                    .replace('\n', "\\n")
            ),
            other => pandas_object_text(other),
        })
        .collect()
}

/// A categorical's categories as pandas' `.cat.categories` /
/// `CategoricalDtype.categories` give them: an IntervalIndex of Intervals
/// (cut / qcut bins; fvsao.54), else an Index.
fn categories_index(py: Python<'_>, categories: &[Scalar]) -> PyResult<Py<PyAny>> {
    if !categories.is_empty() && categories.iter().all(|c| matches!(c, Scalar::Interval(_))) {
        let intervals = categories
            .iter()
            .filter_map(|category| match category {
                Scalar::Interval(interval) => Some(PyInterval::of(interval)),
                _ => None,
            })
            .collect();
        return PyIntervalIndex {
            intervals,
            name: None,
        }
        .into_py_any(py);
    }
    PyIndex {
        inner: Index::new(
            categories
                .iter()
                .map(scalar_to_index_label_converter)
                .collect(),
        ),
    }
    .into_py_any(py)
}

/// A column's values as pandas materializes a run of them (repr cells,
/// tolist, iteration, `.values`): an interval categorical's go through
/// IntervalIndex.take, which makes `interval[int64]` float64 once any is
/// missing - '(10.0, 50.0]' beside NaN, where one value alone (`iloc`) or
/// `astype(str)` stays '(10, 50]' (fvsao.54).
fn materialized_values(column: &Column) -> std::borrow::Cow<'_, [Scalar]> {
    let values = column.values();
    let int_intervals = values.iter().any(|value| {
        matches!(value, Scalar::Interval(interval)
            if interval.subtype == fp_types::IntervalSubtype::Int64)
    });
    if int_intervals && values.iter().any(Scalar::is_missing) {
        std::borrow::Cow::Owned(
            values
                .iter()
                .map(|value| match value {
                    Scalar::Interval(interval) => Scalar::Interval(fp_types::Interval::new(
                        interval.left,
                        interval.right,
                        interval.closed,
                    )),
                    other => other.clone(),
                })
                .collect(),
        )
    } else {
        std::borrow::Cow::Borrowed(values)
    }
}

/// The cells pandas' formatter makes for `column` (before justification):
/// numbers, bools and objects take a leading space, datetimes and
/// timedeltas do not; a tz-aware column shows its wall clock and offset in
/// any zone.
#[allow(clippy::cast_precision_loss)] // pandas performs the same int64 -> float64 widening
fn pandas_cells(column: &Column) -> Vec<String> {
    let values = materialized_values(column);
    // pandas' `string` dtype prints its missing value as <NA>, and each cell
    // with the leading space of an extension array's formatter (fvsao.59).
    if column.is_pandas_string() {
        return values
            .iter()
            .map(|value| {
                if value.is_missing() {
                    " <NA>".to_owned()
                } else {
                    format!(" {}", pandas_object_text(value))
                }
            })
            .collect();
    }
    match column.dtype() {
        DType::Int64 if column.validity().all() => values
            .iter()
            .map(|value| match value {
                Scalar::Int64(v) if *v < 0 => v.to_string(),
                Scalar::Int64(v) => format!(" {v}"),
                other => format!(" {}", pandas_object_text(other)),
            })
            .collect(),
        DType::Int64 | DType::Float64 => pandas_float_cells(
            &values
                .iter()
                .map(|value| match value {
                    Scalar::Float64(v) if !v.is_nan() => Some(*v),
                    Scalar::Int64(v) => Some(*v as f64),
                    _ => None,
                })
                .collect::<Vec<_>>(),
        ),
        DType::Datetime64 { tz } => {
            let instants: Vec<Option<i64>> = values
                .iter()
                .map(|value| match value {
                    Scalar::Datetime64(nanos) if *nanos != i64::MIN => Some(*nanos),
                    _ => None,
                })
                .collect();
            match tz.as_deref() {
                None => pandas_datetime_cells(&instants, false),
                Some(zone) => pandas_aware_datetime_texts(&instants, zone),
            }
        }
        DType::Timedelta64 => {
            const DAY: i64 = 86_400_000_000_000;
            let durations: Vec<Option<i64>> = values
                .iter()
                .map(|value| match value {
                    Scalar::Timedelta64(nanos) if *nanos != i64::MIN => Some(*nanos),
                    _ => None,
                })
                .collect();
            let long = durations.iter().flatten().any(|nanos| nanos % DAY != 0);
            durations
                .iter()
                .map(|nanos| {
                    nanos.map_or_else(
                        || "NaT".to_owned(),
                        |nanos| pandas_timedelta_text(nanos, long),
                    )
                })
                .collect()
        }
        DType::Int64Nullable | DType::Float64Nullable | DType::BoolNullable => values
            .iter()
            .map(|value| match value {
                value if value.is_missing() => " <NA>".to_owned(),
                Scalar::Float64(v) => masked_float_text(*v),
                value => format!(" {}", pandas_object_text(value)),
            })
            .collect(),
        // A numeric categorical prints as pandas formats its values' array
        // (Categorical._internal_get_values): floats at one precision
        // ('2.50'), ints with a sign space only beside a negative - ints
        // beside a NaN are the object array they become, printed below.
        // They printed each on its own ('2.5', ' -1'; ba9pc).
        DType::Categorical
            if column.categorical().is_some_and(|meta| {
                let all = |test: fn(&Scalar) -> bool| {
                    !meta.categories.is_empty() && meta.categories.iter().all(test)
                };
                all(|c| matches!(c, Scalar::Int64(_) | Scalar::Float64(_)))
                    && !(all(|c| matches!(c, Scalar::Int64(_))) && !column.validity().all())
            }) =>
        {
            Column::from_values(values.to_vec()).map_or_else(
                |_| {
                    values
                        .iter()
                        .map(|value| format!(" {}", pandas_object_text(value)))
                        .collect()
                },
                |plain| pandas_cells(&plain),
            )
        }
        _ => values
            .iter()
            .map(|value| format!(" {}", pandas_object_text(value)))
            .collect(),
    }
}

/// The cells pandas' `format_array` makes for `column` under `to_string`'s
/// `formatter` (the column's own), `float_format`, `na_rep` and `decimal`,
/// as printed (`leading_space` is pandas' `index`), or None when they change
/// nothing ([`pandas_cells`]). A float column: a formatter or a callable
/// float_format gives each value's text (NaN as `na_rep`; no sign space, no
/// decimal swap), a '%' float_format each value's `%` text with its decimal
/// point swapped, else pandas' own cells with `na_rep` and the decimal
/// point. An int or datetime column takes only a formatter (each value's
/// text, NaT's too). Any other column is pandas' generic formatter: a space
/// and each value's text (the formatter's; a float's float_format text
/// without the space), None / NaT / <NA> as they print, NaN as `na_rep`.
#[allow(clippy::cast_precision_loss)] // an int column with a NaN is pandas' float64
fn styled_cells(
    py: Python<'_>,
    column: &Column,
    formatter: Option<&Bound<'_, PyAny>>,
    float_format: Option<&Bound<'_, PyAny>>,
    na_rep: &str,
    decimal: &str,
    leading_space: bool,
) -> PyResult<Option<Vec<String>>> {
    let called = |callable: &Bound<'_, PyAny>, value: Py<PyAny>| -> PyResult<String> {
        Ok(callable.call1((value,))?.str()?.to_string())
    };
    let missing =
        |value: &Scalar| value.is_missing() || matches!(value, Scalar::Float64(v) if v.is_nan());
    let as_float = |value: &Scalar| match value {
        Scalar::Int64(v) => *v as f64,
        Scalar::Float64(v) => *v,
        _ => f64::NAN,
    };
    let values = materialized_values(column);
    let dtype = column.dtype();
    if dtype == DType::Float64 || (dtype == DType::Int64 && !column.validity().all()) {
        let callable = formatter.or(float_format.filter(|format| format.is_callable()));
        if let Some(callable) = callable {
            return values
                .iter()
                .map(|value| {
                    if missing(value) {
                        Ok(na_rep.to_owned())
                    } else {
                        called(callable, as_float(value).into_py_any(py)?)
                    }
                })
                .collect::<PyResult<Vec<_>>>()
                .map(Some);
        }
        if let Some(pattern) = float_format {
            return values
                .iter()
                .map(|value| {
                    if missing(value) {
                        return Ok(na_rep.to_owned());
                    }
                    let text = pattern.rem(as_float(value))?.str()?.to_string();
                    Ok(text.replacen('.', decimal, 1))
                })
                .collect::<PyResult<Vec<_>>>()
                .map(Some);
        }
        if na_rep == "NaN" && decimal == "." {
            return Ok(None);
        }
        return Ok(Some(
            values
                .iter()
                .zip(pandas_cells(column))
                .map(|(value, cell)| {
                    if missing(value) {
                        na_rep.to_owned()
                    } else if leading_space {
                        cell.replacen('.', decimal, 1)
                    } else {
                        without_leading_space(cell).replacen('.', decimal, 1)
                    }
                })
                .collect(),
        ));
    }
    match dtype {
        DType::Int64 | DType::Datetime64 { .. } | DType::Timedelta64 => {
            let Some(formatter) = formatter else {
                return Ok(None);
            };
            values
                .iter()
                .map(|value| called(formatter, scalar_to_py(py, value)?))
                .collect::<PyResult<Vec<_>>>()
                .map(Some)
        }
        // A categorical prints its values' own array; only a formatter is
        // taken for it.
        DType::Categorical if formatter.is_none() => Ok(None),
        _ if formatter.is_none() && float_format.is_none() && na_rep == "NaN" => Ok(None),
        _ => {
            let lead = if leading_space { " " } else { "" };
            let nullable = matches!(
                dtype,
                DType::Int64Nullable | DType::Float64Nullable | DType::BoolNullable
            );
            values
                .iter()
                .map(|value| {
                    Ok(match value {
                        value if nullable && value.is_missing() => format!("{lead}<NA>"),
                        Scalar::Null(NullKind::Null) => format!("{lead}None"),
                        Scalar::Null(NullKind::NaT) => format!("{lead}NaT"),
                        value if missing(value) => format!("{lead}{na_rep}"),
                        value => match (formatter, float_format, value) {
                            (Some(formatter), _, value) => {
                                format!("{lead}{}", called(formatter, scalar_to_py(py, value)?)?)
                            }
                            (None, Some(format), Scalar::Float64(v)) => {
                                called(format, v.into_py_any(py)?)?
                            }
                            _ => format!("{lead}{}", pandas_object_text(value)),
                        },
                    })
                })
                .collect::<PyResult<Vec<_>>>()
                .map(Some)
        }
    }
}

/// `DataFrame.to_string`'s keywords that shape its layout (see
/// [`TextKeywords::style`]).
struct TextKeywords<'a, 'py> {
    col_space: Option<&'a Bound<'py, PyAny>>,
    header: Option<&'a Bound<'py, PyAny>>,
    formatters: Option<&'a Bound<'py, PyAny>>,
    float_format: Option<&'a Bound<'py, PyAny>>,
    na_rep: &'a str,
    decimal: &'a str,
    justify: Option<&'a str>,
    index_names: bool,
    sparsify: Option<bool>,
}

impl TextKeywords<'_, '_> {
    /// The [`FrameTextStyle`] of `frame`'s layout over `rows`, as pandas'
    /// DataFrameFormatter reads the keywords: `header` False hides the
    /// header, a list names the columns (one a column, text); `formatters`
    /// is a mapping by column label ('__index__' formats a flat index) or a
    /// list by position (one a column); `col_space` an int for the index and
    /// every column, a mapping by label ('' the index; only columns), or a
    /// list by position (one a column). pandas' errors for each.
    fn style(
        &self,
        py: Python<'_>,
        frame: &DataFrame,
        rows: &[usize],
        show_index: bool,
    ) -> PyResult<FrameTextStyle> {
        let value_error =
            |message: String| PyErr::new::<pyo3::exceptions::PyValueError, _>(message);
        let width = frame.shape().1;
        let labels: Vec<Bound<'_, PyAny>> = match frame.column_labels() {
            labels if labels.len() == width => labels
                .iter()
                .map(|label| index_label_to_py(py, label).map(|label| label.into_bound(py)))
                .collect::<PyResult<_>>()?,
            _ => (0..width)
                .filter_map(|position| frame.column_name_at(position))
                .map(|name| name.into_bound_py_any(py))
                .collect::<PyResult<_>>()?,
        };
        let mut style = FrameTextStyle {
            justify: self.justify.map_or(Justify::Right, Justify::of),
            hide_names: !self.index_names,
            dense: !self.sparsify.unwrap_or(true),
            ..FrameTextStyle::default()
        };
        if let Some(header) = self.header {
            if is_list_like_impl(header) {
                let aliases = header
                    .try_iter()?
                    .map(|alias| {
                        let alias = alias?;
                        alias.extract::<String>().map_err(|_| {
                            PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                                "object of type '{}' has no len()",
                                alias
                                    .get_type()
                                    .name()
                                    .map_or_else(|_| "object".into(), |n| n.to_string())
                            ))
                        })
                    })
                    .collect::<PyResult<Vec<String>>>()?;
                if aliases.len() != width {
                    return Err(value_error(format!(
                        "Writing {width} cols but got {} aliases",
                        aliases.len()
                    )));
                }
                style.aliases = Some(aliases);
            } else {
                style.hide_header = !header.is_truthy()?;
            }
        }
        let mut formatter_of: Vec<Option<Bound<'_, PyAny>>> = vec![None; width];
        if let Some(formatters) = self.formatters {
            if let Ok(mapping) = formatters.cast::<PyDict>() {
                for (position, label) in labels.iter().enumerate() {
                    formatter_of[position] = mapping.get_item(label)?.filter(|f| !f.is_none());
                }
                let index_formatter = mapping.get_item("__index__")?.filter(|f| !f.is_none());
                if let Some(formatter) =
                    index_formatter.filter(|_| frame.row_multiindex().is_none())
                {
                    let texts = rows
                        .iter()
                        .map(|&row| {
                            let label = index_label_to_py(py, &frame.index().labels()[row])?;
                            Ok(formatter.call1((label,))?.str()?.to_string())
                        })
                        .collect::<PyResult<Vec<String>>>()?;
                    style.index_cells = Some(texts);
                }
            } else {
                let count = formatters.len()?;
                if count != width {
                    return Err(value_error(format!(
                        "Formatters length({count}) should match DataFrame number of columns({width})"
                    )));
                }
                for (position, slot) in formatter_of.iter_mut().enumerate() {
                    *slot = Some(formatters.get_item(position)?).filter(|f| !f.is_none());
                }
            }
        }
        style.formatted = formatter_of.iter().map(Option::is_some).collect();
        style.cells = (0..width)
            .map(|position| {
                let Some(column) = frame.column_at(position) else {
                    return Ok(None);
                };
                styled_cells(
                    py,
                    &column.take_positions(rows),
                    formatter_of[position].as_ref(),
                    self.float_format,
                    self.na_rep,
                    self.decimal,
                    show_index,
                )
            })
            .collect::<PyResult<_>>()?;
        if let Some(space) = self.col_space {
            // pandas reads each entry with int() ('8' is 8).
            let int_of = |value: &Bound<'_, PyAny>| -> PyResult<usize> {
                let count = py
                    .get_type::<pyo3::types::PyInt>()
                    .call1((value,))?
                    .extract::<i64>()?;
                Ok(usize::try_from(count).unwrap_or(0))
            };
            if space.is_instance_of::<pyo3::types::PyInt>()
                || space.is_instance_of::<pyo3::types::PyString>()
            {
                let count = int_of(space)?;
                style.index_space = count;
                style.col_space = vec![count; width];
            } else if let Ok(mapping) = space.cast::<PyDict>() {
                for key in mapping.keys() {
                    let index_key = key.extract::<String>().is_ok_and(|key| key.is_empty());
                    if !index_key && !labels.iter().any(|label| label.eq(&key).unwrap_or(false)) {
                        return Err(value_error(format!(
                            "Col_space is defined for an unknown column: {key}"
                        )));
                    }
                }
                if let Some(count) = mapping.get_item("")? {
                    style.index_space = int_of(&count)?;
                }
                style.col_space = labels
                    .iter()
                    .map(|label| {
                        mapping
                            .get_item(label)?
                            .map_or(Ok(0), |count| int_of(&count))
                    })
                    .collect::<PyResult<_>>()?;
            } else {
                let count = space.len()?;
                if count != width {
                    return Err(value_error(format!(
                        "Col_space length({count}) should match DataFrame number of columns({width})"
                    )));
                }
                style.col_space = (0..width)
                    .map(|position| int_of(&space.get_item(position)?))
                    .collect::<PyResult<_>>()?;
            }
        }
        Ok(style)
    }
}

/// The header texts pandas prints for flat column `labels` (before a
/// numeric column's leading space): a numeric (int / float / bool) column
/// Index is formatted as one block ([`pandas_label_texts`]) with every text
/// left-justified to the widest, as pandas' `_format_flat`; a datetime one
/// as one block unjustified; any other Index prints each label as it is. The labels printed each at
/// its own width, so every frame with 11+ default columns differed
/// (br-frankenpandas-0jg0l).
fn pandas_column_label_texts(labels: &[IndexLabel]) -> Vec<String> {
    let all = |test: fn(&IndexLabel) -> bool| !labels.is_empty() && labels.iter().all(test);
    // A DatetimeIndex's header texts share one resolution but are not
    // justified (pandas' _format_with_header): a NaT label prints 'NaT' at
    // its own width - it was padded to the dates', and a NaT held as a null
    // label printed every date with its '00:00:00'.
    if labels
        .iter()
        .any(|label| matches!(label, IndexLabel::Datetime64(_)))
        && all(|label| {
            matches!(
                label,
                IndexLabel::Datetime64(_) | IndexLabel::Null(NullKind::NaT)
            )
        })
    {
        let instants: Vec<IndexLabel> = labels
            .iter()
            .map(|label| match label {
                IndexLabel::Null(_) => IndexLabel::Datetime64(i64::MIN),
                other => other.clone(),
            })
            .collect();
        return pandas_label_texts(&instants, None);
    }
    // A NaN among numbers is one of pandas' float labels ('NaN' in the
    // block; it printed 'nan' on its own; br-frankenpandas-qacqs).
    let numeric = |label: &IndexLabel| {
        matches!(
            label,
            IndexLabel::Int64(_) | IndexLabel::Float64(_) | IndexLabel::Null(NullKind::NaN)
        )
    };
    let numbers = labels.iter().all(numeric)
        && labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Int64(_) | IndexLabel::Float64(_)));
    if !(numbers || all(|label| matches!(label, IndexLabel::Bool(_)))) {
        return labels.iter().map(fp_frame::column_key).collect();
    }
    let texts = pandas_label_texts(labels, None);
    let width = texts.iter().map(text_width).max().unwrap_or(0);
    texts
        .into_iter()
        .map(|text| format!("{text:<width$}"))
        .collect()
}

/// The texts of index `labels`, as pandas' index formatter prints them
/// (left-justified by the caller): datetimes at their common resolution;
/// ints with a sign space on the others when any is negative; ints and
/// floats together as floats at one common precision ('1.50', '10.25';
/// they printed each at its own, and ints beside floats as ints -
/// br-frankenpandas-0jg0l); anything else label by label.
#[allow(clippy::cast_precision_loss)] // pandas' float Index holds the ints as floats
fn pandas_label_texts(labels: &[IndexLabel], zone: Option<&str>) -> Vec<String> {
    let all = |test: fn(&IndexLabel) -> bool| !labels.is_empty() && labels.iter().all(test);
    if all(|label| matches!(label, IndexLabel::Int64(_))) {
        let negative = labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Int64(v) if *v < 0));
        return labels
            .iter()
            .map(|label| match label {
                IndexLabel::Int64(v) if negative && *v >= 0 => format!(" {v}"),
                other => other.to_string(),
            })
            .collect();
    }
    if all(|label| {
        matches!(
            label,
            IndexLabel::Int64(_) | IndexLabel::Float64(_) | IndexLabel::Null(NullKind::NaN)
        )
    }) {
        let values: Vec<Option<f64>> = labels
            .iter()
            .map(|label| match label {
                IndexLabel::Int64(v) => Some(*v as f64),
                IndexLabel::Float64(v) => (!v.0.is_nan()).then_some(v.0),
                _ => None,
            })
            .collect();
        let cells = pandas_float_cells(&values);
        // The cells carry a sign space; labels keep it only beside a
        // negative one - a NaN label too (' NaN'; it had none, qacqs).
        return if cells.iter().any(|cell| cell.starts_with('-')) {
            cells
                .into_iter()
                .map(|cell| {
                    if cell.starts_with(['-', ' ']) {
                        cell
                    } else {
                        format!(" {cell}")
                    }
                })
                .collect()
        } else {
            cells
                .into_iter()
                .map(|cell| cell.strip_prefix(' ').map_or(cell.clone(), str::to_owned))
                .collect()
        };
    }
    // NaT beside datetimes is one of their labels: the dates keep their
    // shared resolution (a midnight-only index printed its times beside a
    // NaT; br-frankenpandas-l5jx6).
    if labels
        .iter()
        .any(|label| matches!(label, IndexLabel::Datetime64(_)))
        && all(|label| {
            matches!(
                label,
                IndexLabel::Datetime64(_) | IndexLabel::Null(NullKind::NaT)
            )
        })
    {
        let instants: Vec<Option<i64>> = labels
            .iter()
            .map(|label| match label {
                IndexLabel::Datetime64(nanos) if *nanos != i64::MIN => Some(*nanos),
                _ => None,
            })
            .collect();
        return match zone {
            Some(zone) => pandas_aware_datetime_texts(&instants, zone),
            None => pandas_datetime_cells(&instants, false),
        };
    }
    labels
        .iter()
        .map(|label| pandas_object_text(&index_label_to_scalar(label)))
        .collect()
}

/// pandas' `max_rows` / `min_rows` / `max_colwidth` for the text layouts:
/// the repr's are 60, 10 and 50; `to_string` shows every row and every
/// character unless given them.
#[derive(Clone, Copy)]
struct RowLimits {
    max_rows: Option<usize>,
    min_rows: Option<usize>,
    max_colwidth: Option<usize>,
    /// A frame wider than this wraps into blocks of columns (pandas'
    /// `expand_frame_repr` at `display.width`); None never wraps.
    wrap_width: Option<usize>,
}

impl RowLimits {
    /// The repr's limits: `display.max_rows` / `display.min_rows` /
    /// `display.max_colwidth` as set (pandas' 60 / 10 / 50 by default; the
    /// rows were fixed at those and no cell was cut), wrapping at
    /// `display.width` unless the columns fit the terminal instead.
    fn repr() -> Self {
        let wrap = display_flag("display.expand_frame_repr", true)
            && !matches!(ColumnLayout::repr(), ColumnLayout::Fit(_));
        Self {
            max_rows: display_limit("display.max_rows").unwrap_or(Some(60)),
            min_rows: display_limit("display.min_rows").unwrap_or(Some(10)),
            max_colwidth: display_limit("display.max_colwidth").unwrap_or(Some(50)),
            wrap_width: wrap
                .then(|| display_limit("display.width").flatten())
                .flatten(),
        }
    }

    /// `cells` as pandas cuts them to `max_colwidth`: past it (when it is
    /// over 3), a cell's first `max_colwidth - 3` characters and '...' (the
    /// sign space a text cell keeps counts).
    fn clip(self, cells: Vec<String>) -> Vec<String> {
        match self.max_colwidth {
            Some(max) if max > 3 && cells.iter().any(|cell| text_width(cell) > max) => cells
                .into_iter()
                .map(|cell| {
                    if text_width(&cell) > max {
                        let kept: String = cell.chars().take(max - 3).collect();
                        format!("{kept}...")
                    } else {
                        cell
                    }
                })
                .collect(),
            _ => cells,
        }
    }

    /// The rows shown of `len`: all of them, or, past `max_rows`, the first
    /// and last `min(min_rows, max_rows) / 2` (the first alone when that
    /// is 1), with where the '...' row goes.
    fn shown(self, len: usize) -> (Vec<usize>, Option<usize>) {
        match self.max_rows {
            Some(max_rows) if max_rows > 0 && len > max_rows => {
                let limit = match self.min_rows {
                    Some(min_rows) if min_rows > 0 => min_rows.min(max_rows),
                    _ => max_rows,
                };
                if limit == 1 {
                    (vec![0], Some(1))
                } else {
                    let half = limit / 2;
                    ((0..half).chain(len - half..len).collect(), Some(half))
                }
            }
            _ => ((0..len).collect(), None),
        }
    }
}

/// `cell` as pandas formats it without the leading space it keeps for a
/// sign, which `to_string(index=False)` drops.
fn without_leading_space(cell: String) -> String {
    match cell.strip_prefix(' ') {
        Some(rest) => rest.to_owned(),
        None => cell,
    }
}

/// `text` centered in `width` as Python's `str.center` places it (the odd
/// space goes left when `width` is odd).
fn python_center(text: &str, width: usize) -> String {
    let pad = width.saturating_sub(text.chars().count());
    let left = pad / 2 + (pad & width & 1);
    format!("{}{text}{}", " ".repeat(left), " ".repeat(pad - left))
}

/// pandas' `justify` for `to_string`'s headers (and the cells short of a
/// `col_space`): 'left' and 'center' as named, any other mode right.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
enum Justify {
    Left,
    Center,
    #[default]
    Right,
}

impl Justify {
    fn of(mode: &str) -> Self {
        match mode {
            "left" => Self::Left,
            "center" => Self::Center,
            _ => Self::Right,
        }
    }

    /// `text` in `width` characters, as pandas' `adj.justify` places it.
    fn place(self, text: &str, width: usize) -> String {
        match self {
            Self::Left => format!("{text:<width$}"),
            Self::Center => python_center(text, width),
            Self::Right => format!("{text:>width$}"),
        }
    }
}

/// What `DataFrame.to_string`'s keywords change in pandas' frame layout
/// (the repr takes the default). The per-column parts go by the frame's
/// column position; a missing entry changes nothing.
#[derive(Clone, Default)]
struct FrameTextStyle {
    /// header=False: no header lines.
    hide_header: bool,
    /// header=[...]: each column's header as given (no sign space).
    aliases: Option<Vec<String>>,
    /// A column's own cells for the rows shown (its formatter,
    /// float_format, na_rep or decimal; [`styled_cells`]), as printed.
    cells: Vec<Option<Vec<String>>>,
    /// The columns with a formatter: their header takes no sign space.
    formatted: Vec<bool>,
    /// A flat index's texts for the rows shown (formatters['__index__']).
    index_cells: Option<Vec<String>>,
    /// col_space: the least width of each index level, and of each column.
    index_space: usize,
    col_space: Vec<usize>,
    justify: Justify,
    /// index_names=False: neither the row index's names nor the column
    /// axis's print.
    hide_names: bool,
    /// sparsify=False: a MultiIndex prints every label.
    dense: bool,
}

impl FrameTextStyle {
    /// This style over the columns at `positions` (a truncated layout's).
    fn select(&self, positions: &[usize]) -> Self {
        Self {
            aliases: self.aliases.as_ref().map(|aliases| {
                positions
                    .iter()
                    .filter_map(|&position| aliases.get(position).cloned())
                    .collect()
            }),
            cells: positions
                .iter()
                .map(|&position| self.cells.get(position).cloned().flatten())
                .collect(),
            formatted: positions
                .iter()
                .map(|&position| self.formatted.get(position).copied().unwrap_or(false))
                .collect(),
            col_space: positions
                .iter()
                .map(|&position| self.col_space.get(position).copied().unwrap_or(0))
                .collect(),
            index_cells: self.index_cells.clone(),
            ..*self
        }
    }
}

/// A cell's display width in characters, which `{:>w$}` pads by (a byte
/// length misaligns non-ASCII text).
#[allow(clippy::ptr_arg)] // mapped over `&String` items: `.map(text_width)`
fn text_width(text: &String) -> usize {
    text.chars().count()
}

/// pandas' `sparsify_labels` over per-level label texts: a label equal to
/// the one before it, with every outer level equal too, prints blank; the
/// innermost level always prints.
fn sparsify_level_texts(levels: &mut [Vec<String>]) {
    let Some(inner) = levels.len().checked_sub(1) else {
        return;
    };
    let count = levels.first().map_or(0, Vec::len);
    // Bottom-up, so each row is compared with the unblanked row above it.
    for row in (1..count).rev() {
        for texts in levels.iter_mut().take(inner) {
            match (texts.get(row - 1), texts.get(row)) {
                (Some(above), Some(here)) if above == here => {}
                _ => break,
            }
            if let Some(here) = texts.get_mut(row) {
                here.clear();
            }
        }
    }
}

/// An index's printed texts, one list per level, and its level names (None
/// when no level is named).
type LevelTexts = (Vec<Vec<String>>, Option<Vec<String>>);

/// A frame's column axis as levels: one label list per level and each
/// level's name.
type ColumnLevels = (Vec<Vec<IndexLabel>>, Vec<Option<LabelName>>);

/// The texts pandas prints for a row MultiIndex at `rows`: one list per
/// level, sparsified unless `sparsify` is false (to_string's), and the level
/// names when any level is named ("" for an unnamed one).
fn pandas_multiindex_texts(
    multi: &fp_index::MultiIndex,
    rows: &[usize],
    sparsify: bool,
) -> Option<LevelTexts> {
    let mut levels = Vec::with_capacity(multi.nlevels());
    for level in 0..multi.nlevels() {
        let values = multi.get_level_values(level).ok()?;
        let shown: Vec<IndexLabel> = rows
            .iter()
            .map(|&row| values.labels().get(row).cloned())
            .collect::<Option<_>>()?;
        levels.push(pandas_label_texts(&shown, None));
    }
    if sparsify {
        sparsify_level_texts(&mut levels);
    }
    let names = multi.names().iter().any(Option::is_some).then(|| {
        multi
            .names()
            .iter()
            .map(|name| name.as_ref().map(ToString::to_string).unwrap_or_default())
            .collect()
    });
    Some((levels, names))
}

/// pandas' `adjoin(space, *lists)`: the lists side by side, each padded
/// left-justified to its widest text with `space` blanks after it (the last
/// only to its width).
fn adjoin_left(space: usize, lists: &[Vec<String>]) -> Vec<String> {
    let rows = lists.iter().map(Vec::len).max().unwrap_or(0);
    let widths: Vec<usize> = lists
        .iter()
        .enumerate()
        .map(|(position, list)| {
            let width = list.iter().map(text_width).max().unwrap_or(0);
            if position + 1 < lists.len() {
                width + space
            } else {
                width
            }
        })
        .collect();
    (0..rows)
        .map(|row| {
            lists
                .iter()
                .zip(&widths)
                .map(|(list, &width)| {
                    let text = list.get(row).map_or("", String::as_str);
                    format!("{text:<width$}")
                })
                .collect()
        })
        .collect()
}

/// Which footer parts pandas' Series layout prints: the repr prints the
/// name and dtype, and the length only when it truncates (`length: None`);
/// `to_string` prints none of them unless asked.
#[derive(Clone, Copy)]
struct SeriesFooter {
    name: bool,
    dtype: bool,
    length: Option<bool>,
}

impl SeriesFooter {
    const REPR: Self = Self {
        name: true,
        dtype: true,
        length: None,
    };
}

/// A Series name as pandas' footer prints it (`pprint_thing`): a tuple's
/// items unquoted in parentheses - (a, 1), (x,) - where it printed Python's
/// repr ('a', 1); any other name as its text.
fn pandas_name_text(name: &LabelName) -> String {
    let label = name.label();
    // A NaN name prints as Python's str(nan) (it printed the label's 'NaN';
    // br-frankenpandas-qacqs).
    if matches!(label, IndexLabel::Null(NullKind::NaN)) {
        return "nan".to_owned();
    }
    if !matches!(label, IndexLabel::Object(_)) {
        return name.to_string();
    }
    fn pprinted(value: &Bound<'_, PyAny>) -> PyResult<String> {
        match value.cast::<PyTuple>() {
            Ok(items) => {
                let parts = items
                    .iter()
                    .map(|item| pprinted(&item))
                    .collect::<PyResult<Vec<_>>>()?;
                Ok(match parts.as_slice() {
                    [only] => format!("({only},)"),
                    _ => format!("({})", parts.join(", ")),
                })
            }
            Err(_) => Ok(value.str()?.to_string()),
        }
    }
    Python::attach(|py| pprinted(index_label_to_py(py, &label)?.bind(py)))
        .unwrap_or_else(|_| name.to_string())
}

/// pandas' `repr(series)` (see [`pandas_series_text`]).
fn pandas_series_repr(series: &Series) -> String {
    pandas_series_text(
        series,
        RowLimits::repr(),
        true,
        true,
        SeriesFooter::REPR,
        None,
    )
}

/// pandas' Series text layout (`SeriesFormatter`), shared by the repr and
/// `to_string`: the index and the values three blanks apart, a row
/// MultiIndex as one sparsified column per level two blanks apart under a
/// line of the level names when any is named (`show_header`; printed even
/// without the index, as pandas does), `limits` rows, the chosen footer
/// parts. Without the index the values lose their sign space, as pandas'
/// `leading_space=index`. `own_cells` are the rows shown as `to_string`'s
/// na_rep / float_format print them ([`styled_cells`]). Every Series prints
/// this way (a Series it could not lay out printed frankenpandas' own
/// Display; fvsao.34).
fn pandas_series_text(
    series: &Series,
    limits: RowLimits,
    show_index: bool,
    show_header: bool,
    parts: SeriesFooter,
    own_cells: Option<Vec<String>>,
) -> String {
    let index = series.index();
    let column = series.column();
    let (rows, dots_at) = limits.shown(series.len());
    let mut footer = Vec::new();
    // An index with a freq leads the footer, whatever parts are asked for
    // (pandas' 'Freq: D', to_string's too) - a PeriodIndex's own (45fzr).
    if let Some(freq) = index.freq() {
        footer.push(format!("Freq: {freq}"));
    } else if matches!(index.labels().first(), Some(IndexLabel::Period(_)))
        && let Some(freq) = PeriodIndex::from_index(index).and_then(|periods| periods.freqstr())
    {
        footer.push(format!("Freq: {freq}"));
    }
    if parts.name && !series.name().is_empty() {
        footer.push(format!("Name: {}", pandas_name_text(series.name())));
    }
    if parts.length.unwrap_or(dots_at.is_some()) {
        footer.push(format!("Length: {}", series.len()));
    }
    if parts.dtype {
        footer.push(format!("dtype: {}", column_pandas_dtype_name(column)));
    }
    let mut footer = footer.join(", ");
    if let Some(meta) = column.categorical() {
        if !footer.is_empty() {
            footer.push('\n');
        }
        footer.push_str(&pandas_categories_info(meta));
    }
    if series.is_empty() {
        return format!("Series([], {footer})");
    }
    let mut cells = match own_cells {
        Some(cells) => limits.clip(cells),
        None => {
            let cells = limits.clip(pandas_cells(&column.take_positions(&rows)));
            if show_index {
                cells
            } else {
                cells.into_iter().map(without_leading_space).collect()
            }
        }
    };
    let width = cells.iter().map(text_width).max().unwrap_or(0);
    for cell in &mut cells {
        *cell = format!("{cell:>width$}");
    }
    // The header line: a flat index's name as is, or a MultiIndex's level
    // names laid out over its level columns (which the names widen).
    let multi_texts = index
        .row_multiindex()
        .and_then(|multi| pandas_multiindex_texts(multi, &rows, true));
    let (mut labels, header) = match multi_texts {
        Some((levels, names)) => {
            let lists: Vec<Vec<String>> = levels
                .into_iter()
                .enumerate()
                .map(|(level, mut texts)| {
                    let name = names.as_ref().map_or_else(String::new, |names| {
                        names.get(level).cloned().unwrap_or_default()
                    });
                    texts.insert(0, name);
                    texts
                })
                .collect();
            let mut lines = adjoin_left(2, &lists);
            let names_line = lines.remove(0);
            (lines, names.map(|_| names_line))
        }
        None => {
            let shown: Vec<IndexLabel> = rows
                .iter()
                .map(|&row| index.labels()[row].clone())
                .collect();
            (
                pandas_label_texts(&shown, index.tz()),
                index.name().map(String::from),
            )
        }
    };
    if let Some(at) = dots_at {
        let dots = if width > 3 { "..." } else { ".." };
        cells.insert(at, python_center(dots, width));
        labels.insert(at, String::new());
    }
    let body: Vec<String> = if show_index {
        let label_width = labels.iter().map(text_width).max().unwrap_or(0) + 3;
        labels
            .iter()
            .zip(&cells)
            .map(|(label, cell)| format!("{label:<label_width$}{cell}"))
            .collect()
    } else {
        cells
    };
    let mut text = String::new();
    if let Some(header) = header.filter(|_| show_header) {
        text.push_str(&header);
        text.push('\n');
    }
    text.push_str(&body.join("\n"));
    if !footer.is_empty() {
        text.push('\n');
        text.push_str(&footer);
    }
    text
}

/// The texts of a MultiIndex's entries as pandas lists them in an empty
/// frame's repr, "(a, 1)".
fn pandas_multiindex_tuples(multi: &fp_index::MultiIndex) -> Option<Vec<String>> {
    let levels: Vec<Vec<String>> = (0..multi.nlevels())
        .map(|level| {
            multi
                .get_level_values(level)
                .ok()
                .map(|values| pandas_label_texts(values.labels(), None))
        })
        .collect::<Option<_>>()?;
    Some(
        (0..multi.len())
            .map(|entry| {
                let parts: Vec<&str> = levels.iter().map(|texts| texts[entry].as_str()).collect();
                format!("({})", parts.join(", "))
            })
            .collect(),
    )
}

/// pandas' `repr(df)` (see [`pandas_frame_text`]): the display options'
/// rows and columns - fitted to the terminal's width by default, as pandas
/// in a terminal or a script (it printed every column).
fn pandas_frame_repr(frame: &DataFrame) -> String {
    pandas_frame_text(
        frame,
        RowLimits::repr(),
        true,
        None,
        ColumnLayout::repr(),
        &FrameTextStyle::default(),
    )
}

/// How many of a frame's columns its text lays out.
#[derive(Clone, Copy)]
enum ColumnLayout {
    /// Every column (`to_string`; `display.max_columns=None`).
    All,
    /// As many as fit this many characters, pandas' terminal fit
    /// (`display.max_columns=0`, its default in a terminal or a script).
    Fit(usize),
    /// At most this many (`display.max_columns=n`).
    Max(usize),
    /// Cut already: a '...' column after `after` columns, of `total`.
    Dots { after: usize, total: usize },
}

impl ColumnLayout {
    /// The repr's, from `display.max_columns`: 0 fits the terminal's width,
    /// n shows at most n, None every column.
    fn repr() -> Self {
        match display_limit("display.max_columns").unwrap_or(Some(0)) {
            Some(0) => Self::Fit(terminal_width()),
            Some(count) => Self::Max(count),
            None => Self::All,
        }
    }
}

/// The terminal's width as pandas reads it, Python's
/// `shutil.get_terminal_size()` (the COLUMNS variable, the terminal, else 80).
fn terminal_width() -> usize {
    Python::attach(|py| {
        py.import("shutil")
            .and_then(|shutil| shutil.call_method0("get_terminal_size"))
            .and_then(|size| size.getattr("columns"))
            .and_then(|columns| columns.extract::<usize>())
    })
    .unwrap_or(80)
}

/// pandas' `adjoin(space, *lists)`: each list left-justified to its widest
/// text, `space` blanks after every one but the last, line by line.
fn pandas_adjoin(space: usize, lists: &[Vec<String>]) -> String {
    let widths: Vec<usize> = lists
        .iter()
        .map(|list| list.iter().map(text_width).max().unwrap_or(0))
        .collect();
    let lines = lists.iter().map(Vec::len).max().unwrap_or(0);
    (0..lines)
        .map(|line| {
            lists
                .iter()
                .zip(&widths)
                .enumerate()
                .map(|(position, (list, &width))| {
                    let text = list.get(line).map_or("", String::as_str);
                    let width = if position + 1 < lists.len() {
                        width + space
                    } else {
                        width
                    };
                    format!("{text:<width$}")
                })
                .collect::<String>()
        })
        .collect::<Vec<_>>()
        .join("\n")
}

/// A frame's laid-out columns (the index column first when shown) wrapped
/// into blocks of `line_width` characters, as pandas' `expand_frame_repr`
/// wraps a repr it does not fit to the terminal: columns go to a block while
/// the running width (each column and its blank, one more for the last,
/// two otherwise) stays within the line; every block repeats the index,
/// the blocks end with a ' \' column but the last, and they are a blank
/// line apart.
fn pandas_join_multiline(
    mut strcols: Vec<Vec<String>>,
    show_index: bool,
    line_width: usize,
) -> String {
    let index = show_index.then(|| strcols.remove(0));
    let mut room = line_width as i64;
    if let Some(index) = &index {
        room -= index.iter().map(text_width).max().unwrap_or(0) as i64 + 1;
    }
    let widths: Vec<usize> = strcols
        .iter()
        .map(|column| column.iter().map(text_width).max().unwrap_or(0))
        .collect();
    let mut ends = Vec::new();
    let mut running = 0_i64;
    for (position, &width) in widths.iter().enumerate() {
        let adjoined = width as i64 + 1;
        running += adjoined;
        let reserve = if position + 1 == widths.len() { 1 } else { 2 };
        if running + reserve > room && position > 0 {
            ends.push(position);
            running = adjoined;
        }
    }
    ends.push(widths.len());
    let blocks = ends.len();
    let mut start = 0;
    let mut texts = Vec::with_capacity(blocks);
    for (block, &end) in ends.iter().enumerate() {
        let mut row: Vec<Vec<String>> = strcols[start..end].to_vec();
        if let Some(index) = &index {
            row.insert(0, index.clone());
        }
        if blocks > 1 {
            let lines = row.last().map_or(0, Vec::len);
            let marker = if block + 1 < blocks {
                let rest = std::iter::repeat_n("  ".to_owned(), lines.saturating_sub(1));
                std::iter::once(" \\".to_owned()).chain(rest).collect()
            } else {
                vec![" ".to_owned(); lines]
            };
            row.push(marker);
        }
        texts.push(pandas_adjoin(1, &row));
        start = end;
    }
    texts.join("\n\n")
}

/// How many of the laid-out columns `strcols` (the index column first when
/// shown) fit `terminal` characters, as pandas fits a repr: from the widest
/// line's excess over the width (+1), drop the middle column - Python's
/// `round(n / 2)`, half to even - until none remains; the columns left,
/// less the index, at least 2.
fn fitted_column_count(strcols: &[Vec<String>], terminal: usize, show_index: bool) -> usize {
    let mut widths: Vec<usize> = strcols
        .iter()
        .map(|column| column.iter().map(text_width).max().unwrap_or(0))
        .collect();
    let line = widths.iter().sum::<usize>() + widths.len().saturating_sub(1);
    let mut excess = line as i64 - terminal as i64 + 1;
    while excess > 0 && widths.len() > 1 {
        let half = widths.len() / 2;
        let middle = if widths.len() % 2 == 1 && half % 2 == 1 {
            half + 1
        } else {
            half
        };
        excess -= widths.remove(middle) as i64 + 1;
    }
    widths.len().saturating_sub(usize::from(show_index)).max(2)
}

/// One column-MultiIndex level's header texts as pandas' `_format_multi`
/// formats a level (`_format_flat`): an int, float or bool level as one
/// block left-justified to its widest ('-1 ', ' 10', ' 5 '; 'False',
/// 'True '), any other level label by label (they all printed unjustified,
/// which moved the columns a bool or int level heads; br-frankenpandas-wl75u).
fn multiindex_level_header_texts(labels: &[IndexLabel]) -> Vec<String> {
    let all = |test: fn(&IndexLabel) -> bool| !labels.is_empty() && labels.iter().all(test);
    let texts = pandas_label_texts(labels, None);
    if !(all(|label| matches!(label, IndexLabel::Int64(_) | IndexLabel::Float64(_)))
        || all(|label| matches!(label, IndexLabel::Bool(_))))
    {
        return texts;
    }
    let width = texts.iter().map(text_width).max().unwrap_or(0);
    texts
        .into_iter()
        .map(|text| format!("{text:<width$}"))
        .collect()
}

/// The header texts of a column MultiIndex over `width` columns, one per
/// level for each column, sparsified across the columns unless `sparsify`
/// is false, and the corner beside them (the column-axis level names, blank
/// when none is named); None when its levels do not cover the columns.
/// `numeric` flags the columns whose header takes pandas' leading space.
fn column_multiindex_headers(
    multi: &fp_index::MultiIndex,
    width: usize,
    sparsify: bool,
) -> Option<(Vec<Vec<String>>, Vec<String>)> {
    let mut levels: Vec<Vec<String>> = (0..multi.nlevels())
        .map(|level| {
            multi
                .get_level_values(level)
                .ok()
                .map(|values| multiindex_level_header_texts(values.labels()))
        })
        .collect::<Option<_>>()?;
    if levels.iter().any(|texts| texts.len() != width) {
        return None;
    }
    if sparsify {
        sparsify_level_texts(&mut levels);
    }
    let headers = (0..width)
        .map(|column| levels.iter().map(|texts| texts[column].clone()).collect())
        .collect();
    let corner = if multi.names().iter().any(Option::is_some) {
        multi
            .names()
            .iter()
            .map(|name| name.as_ref().map(ToString::to_string).unwrap_or_default())
            .collect()
    } else {
        vec![String::new(); multi.nlevels()]
    };
    Some((headers, corner))
}

/// pandas' DataFrame text layout (`DataFrameFormatter`), shared by the repr
/// and `to_string`. A row MultiIndex prints one sparsified column per
/// level, one blank apart, over a line of the level names when any is
/// named; a column MultiIndex prints one header line per level, sparsified
/// across the columns, with the column-axis level names at the left when
/// any is named. `limits` rows; the "[n rows x m columns]" line when
/// `show_dimensions` (None: when truncated, as the repr). Without the index
/// the cells lose their sign space, as pandas' `leading_space=index`.
/// `columns` says how many columns show: past those, the first and last
/// half are laid out again around a '...' column, as pandas truncates a
/// repr to the terminal's width (every column was shown). `style` is what
/// `to_string`'s keywords change (see [`FrameTextStyle`]): a column's
/// header and cells take at least its `col_space` and are justified by
/// `justify` in it (the cells right-justified among themselves first), each
/// index level takes at least the index's `col_space`, left-justified.
/// Every frame prints this way (a frame it could not lay out printed
/// frankenpandas' own Display; fvsao.34).
/// `DataFrame.to_html`'s layout keywords beside the cell ones
/// ([`TextKeywords`]), as pandas' HTMLFormatter reads them.
struct HtmlLayout<'a> {
    index: bool,
    header: bool,
    index_names: bool,
    bold_rows: bool,
    escape: bool,
    render_links: bool,
    justify: &'a str,
}

/// The URL schemes pandas' `is_url` accepts (`_VALID_URLS`: urllib's
/// uses_relative, uses_netloc and uses_params, the empty one left out).
const HTML_LINK_SCHEMES: [&str; 30] = [
    "file",
    "ftp",
    "git",
    "git+ssh",
    "gopher",
    "hdl",
    "http",
    "https",
    "imap",
    "itms-services",
    "mms",
    "nfs",
    "nntp",
    "prospero",
    "rsync",
    "rtsp",
    "rtsps",
    "rtspu",
    "sftp",
    "shttp",
    "sip",
    "sips",
    "snews",
    "svn",
    "svn+ssh",
    "tel",
    "telnet",
    "wais",
    "ws",
    "wss",
];

/// pandas' `HTMLFormatter` over a frame with a flat index and flat columns
/// (br-frankenpandas-ymbic): each column's `to_string` cells (formatters,
/// float_format, na_rep, decimal) stripped - fp printed every float on its
/// own (1.5, not pandas' 1.50 beside 2.25) - the index labels as `to_string`
/// shows them, the columns' name over the index and a row of the index's
/// name when it has one, `<th>` index cells unless `bold_rows` is off, `&`,
/// `<` and `>` escaped unless `escape` is off, and a URL in an `<a>` under
/// `render_links`. `tag` opens the table.
fn pandas_html(
    py: Python<'_>,
    frame: &DataFrame,
    tag: &str,
    text: &TextKeywords<'_, '_>,
    layout: &HtmlLayout<'_>,
) -> PyResult<String> {
    let (len, width) = frame.shape();
    let rows: Vec<usize> = (0..len).collect();
    let style = text.style(py, frame, &rows, layout.index)?;
    let urlparse = if layout.render_links {
        Some(py.import("urllib.parse")?.getattr("urlparse")?)
    } else {
        None
    };
    let cell = |kind: &str, raw: &str| -> PyResult<String> {
        let shown = if layout.escape {
            raw.replace('&', "&amp;")
                .replace('<', "&lt;")
                .replace('>', "&gt;")
        } else {
            raw.to_owned()
        };
        let shown = shown.trim();
        let link = match &urlparse {
            Some(urlparse) => {
                let scheme: String = urlparse.call1((shown,))?.getattr("scheme")?.extract()?;
                HTML_LINK_SCHEMES.contains(&scheme.as_str())
            }
            None => false,
        };
        Ok(if link {
            format!(
                "      <{kind}><a href=\"{}\" target=\"_blank\">{shown}</a></{kind}>\n",
                raw.trim()
            )
        } else {
            format!("      <{kind}>{shown}</{kind}>\n")
        })
    };
    // pandas' show_col_idx_names / show_row_idx_names: a named column axis
    // heads the index column (a blank one when the index is hidden), a named
    // index gets a row of its own.
    let column_axis_name = frame
        .columns_name()
        .map(String::from)
        .filter(|_| layout.index_names && layout.header);
    let row_name = frame
        .index()
        .name()
        .map(|name| name.to_string())
        .filter(|_| layout.index && layout.index_names);
    let lead_column = layout.index || column_axis_name.is_some();
    let lead_kind = if layout.bold_rows { "th" } else { "td" };
    let mut out = format!("{tag}\n");
    if layout.header || row_name.is_some() {
        out.push_str("  <thead>\n");
    }
    if layout.header {
        out.push_str(&format!(
            "    <tr style=\"text-align: {};\">\n",
            layout.justify
        ));
        if lead_column {
            out.push_str(&cell("th", column_axis_name.as_deref().unwrap_or(""))?);
        }
        let labels = frame.column_labels();
        let label_texts = if labels.len() == width {
            pandas_column_label_texts(&labels)
        } else {
            frame.column_names().into_iter().cloned().collect()
        };
        for label in &label_texts {
            out.push_str(&cell("th", label)?);
        }
        out.push_str("    </tr>\n");
    }
    if let Some(name) = &row_name {
        out.push_str("    <tr>\n");
        out.push_str(&cell("th", name)?);
        for _ in 0..width {
            out.push_str("      <th></th>\n");
        }
        out.push_str("    </tr>\n");
    }
    if layout.header || row_name.is_some() {
        out.push_str("  </thead>\n");
    }
    let index_texts = match style.index_cells.clone() {
        Some(texts) => texts,
        None => pandas_label_texts(frame.index().labels(), frame.index().tz()),
    };
    let columns: Vec<Vec<String>> = (0..width)
        .map(|position| {
            style
                .cells
                .get(position)
                .cloned()
                .flatten()
                .or_else(|| frame.column_at(position).map(pandas_cells))
                .unwrap_or_default()
        })
        .collect();
    out.push_str("  <tbody>\n");
    for row in 0..len {
        out.push_str("    <tr>\n");
        if layout.index {
            out.push_str(&cell(lead_kind, &index_texts[row])?);
        } else if lead_column {
            out.push_str(&cell(lead_kind, "")?);
        }
        for column in &columns {
            out.push_str(&cell("td", &column[row])?);
        }
        out.push_str("    </tr>\n");
    }
    out.push_str("  </tbody>\n</table>");
    Ok(out)
}

fn pandas_frame_text(
    frame: &DataFrame,
    limits: RowLimits,
    show_index: bool,
    show_dimensions: Option<bool>,
    columns_shown: ColumnLayout,
    style: &FrameTextStyle,
) -> String {
    let (len, width) = frame.shape();
    let columns: Vec<(String, &Column)> = (0..width)
        .filter_map(|position| Some((frame.column_name_at(position)?, frame.column_at(position)?)))
        .collect();
    let column_multi = frame.columns_multiindex();
    if len == 0 || width == 0 {
        let labels = frame
            .row_multiindex()
            .and_then(pandas_multiindex_tuples)
            .unwrap_or_else(|| pandas_label_texts(frame.index().labels(), frame.index().tz()));
        let names = column_multi
            .and_then(pandas_multiindex_tuples)
            .unwrap_or_else(|| columns.iter().map(|(name, _)| name.clone()).collect());
        return format!(
            "Empty DataFrame\nColumns: [{}]\nIndex: [{}]",
            names.join(", "),
            labels.join(", ")
        );
    }
    let (rows, dots_at) = limits.shown(len);
    // The column headers, one text per column-axis level for each column,
    // and what the index column shows beside them.
    let multi_headers = column_multi
        .filter(|_| style.aliases.is_none())
        .and_then(|multi| column_multiindex_headers(multi, columns.len(), !style.dense));
    let (headers, corner): (Vec<Vec<String>>, Vec<String>) = match multi_headers {
        Some(multi_headers) => multi_headers,
        None => {
            let label_texts = match &style.aliases {
                Some(aliases) => aliases.clone(),
                None => {
                    let labels = frame.column_labels();
                    if labels.len() == columns.len() {
                        pandas_column_label_texts(&labels)
                    } else {
                        columns.iter().map(|(name, _)| name.clone()).collect()
                    }
                }
            };
            let mut headers = Vec::with_capacity(columns.len());
            for (position, ((_, column), name)) in columns.iter().zip(&label_texts).enumerate() {
                let dtype = column.dtype();
                // A numeric column's header takes a sign space, unless it is
                // an alias or the column has a formatter.
                let numeric = matches!(
                    dtype,
                    DType::Int64
                        | DType::Float64
                        | DType::Bool
                        | DType::Int64Nullable
                        | DType::Float64Nullable
                        | DType::BoolNullable
                ) && !(dtype == DType::Bool && column.has_any_missing())
                    && style.aliases.is_none()
                    && !style.formatted.get(position).copied().unwrap_or(false);
                headers.push(vec![if numeric {
                    format!(" {name}")
                } else {
                    name.clone()
                }]);
            }
            // The column axis's name heads the index column, as pandas
            // prints it (pivot's 'c'; it was blank).
            (
                headers,
                vec![frame.columns_name().map(String::from).unwrap_or_default()],
            )
        }
    };
    let (headers, corner) = if style.hide_header {
        (vec![Vec::new(); columns.len()], Vec::new())
    } else if style.hide_names {
        let blank = vec![String::new(); corner.len()];
        (headers, blank)
    } else {
        (headers, corner)
    };
    let header_rows = corner.len();
    let multi_texts = frame
        .row_multiindex()
        .and_then(|multi| pandas_multiindex_texts(multi, &rows, !style.dense));
    let (index_levels, row_names) = match multi_texts {
        Some(texts) => texts,
        None => {
            let texts = style.index_cells.clone().unwrap_or_else(|| {
                let shown: Vec<IndexLabel> = rows
                    .iter()
                    .map(|&row| frame.index().labels()[row].clone())
                    .collect();
                pandas_label_texts(&shown, frame.index().tz())
            });
            (
                vec![texts],
                frame.index().name().map(|name| vec![name.to_string()]),
            )
        }
    };
    let row_names = row_names.filter(|_| !style.hide_names);
    let blank_rows = usize::from(show_index && row_names.is_some());
    let mut strcols: Vec<Vec<String>> = Vec::with_capacity(width + 1);
    if show_index {
        let space = style.index_space;
        let lists: Vec<Vec<String>> = index_levels
            .into_iter()
            .enumerate()
            .map(|(level, mut texts)| {
                if let Some(row_names) = &row_names {
                    texts.insert(0, row_names.get(level).cloned().unwrap_or_default());
                }
                if space > 0 {
                    texts = texts
                        .into_iter()
                        .map(|text| format!("{text:<space$}"))
                        .collect();
                }
                texts
            })
            .collect();
        let mut index_col = corner;
        index_col.extend(adjoin_left(1, &lists));
        let index_width = index_col.iter().map(text_width).max().unwrap_or(0);
        let mut index_col: Vec<String> = index_col
            .iter()
            .map(|cell| format!("{cell:<index_width$}"))
            .collect();
        if let Some(at) = dots_at {
            let dots = if index_width > 3 { "..." } else { ".." };
            index_col.insert(
                header_rows + blank_rows + at,
                format!("{dots:<index_width$}"),
            );
        }
        strcols.push(index_col);
    }
    for (position, ((_, column), header)) in columns.iter().zip(&headers).enumerate() {
        let cells = match style.cells.get(position).cloned().flatten() {
            Some(cells) => limits.clip(cells),
            None => {
                let cells = limits.clip(pandas_cells(&column.take_positions(&rows)));
                if show_index {
                    cells
                } else {
                    cells.into_iter().map(without_leading_space).collect()
                }
            }
        };
        let cells_width = cells.iter().map(text_width).max().unwrap_or(0);
        let col_width = header
            .iter()
            .map(text_width)
            .chain(style.col_space.get(position).copied())
            .fold(cells_width, usize::max);
        let justify = style.justify;
        let mut strcol: Vec<String> = header
            .iter()
            .map(|text| justify.place(text, col_width))
            .collect();
        if blank_rows == 1 {
            strcol.push(" ".repeat(col_width));
        }
        strcol.extend(cells.iter().map(|cell| match justify {
            Justify::Right => format!("{cell:>col_width$}"),
            _ => justify.place(&format!("{cell:>cells_width$}"), col_width),
        }));
        if let Some(at) = dots_at {
            let dots = if col_width > 3 { "..." } else { ".." };
            strcol.insert(header_rows + blank_rows + at, format!("{dots:>col_width$}"));
        }
        strcols.push(strcol);
    }
    // pandas' horizontal truncation: past the columns that fit, the first
    // and last half of them (the first `fitted` when that is 1) laid out
    // again around a '...' column.
    let fitted = match columns_shown {
        ColumnLayout::Fit(terminal) => Some(fitted_column_count(&strcols, terminal, show_index)),
        ColumnLayout::Max(count) => Some(count),
        ColumnLayout::All | ColumnLayout::Dots { .. } => None,
    };
    if let Some(fitted) = fitted
        && width > fitted
    {
        let keep = fitted / 2;
        let (positions, after): (Vec<usize>, usize) = if keep >= 1 {
            ((0..keep).chain(width - keep..width).collect(), keep)
        } else {
            ((0..fitted).collect(), fitted)
        };
        let mut seen = HashSet::new();
        let (kept_positions, kept): (Vec<usize>, Vec<String>) = positions
            .iter()
            .filter_map(|&position| Some((position, frame.column_name_at(position)?)))
            .filter(|(_, name)| seen.insert(name.clone()))
            .unzip();
        let refs: Vec<&str> = kept.iter().map(String::as_str).collect();
        if let Ok(cut) = frame.select_columns(&refs) {
            let dots = ColumnLayout::Dots {
                after,
                total: width,
            };
            return pandas_frame_text(
                &cut,
                limits,
                show_index,
                show_dimensions,
                dots,
                &style.select(&kept_positions),
            );
        }
    }
    let total_columns = match columns_shown {
        ColumnLayout::Dots { after, total } => {
            let lines = strcols.first().map_or(0, Vec::len);
            let dots = vec![" ...".to_owned(); lines];
            strcols.insert(usize::from(show_index) + after, dots);
            Some(total)
        }
        _ => None,
    };
    let mut text = match limits.wrap_width {
        Some(line_width) => pandas_join_multiline(strcols, show_index, line_width),
        None => {
            let last = strcols.len() - 1;
            let lines = strcols[0].len();
            let mut text = String::new();
            for line in 0..lines {
                if line > 0 {
                    text.push('\n');
                }
                for (position, strcol) in strcols.iter().enumerate() {
                    let cell = &strcol[line];
                    if position == last {
                        text.push_str(cell);
                    } else {
                        let pad = strcol.iter().map(text_width).max().unwrap_or(0) + 1;
                        text.push_str(&format!("{cell:<pad$}"));
                    }
                }
            }
            text
        }
    };
    if show_dimensions.unwrap_or(dots_at.is_some() || total_columns.is_some()) {
        let columns = total_columns.unwrap_or(width);
        text.push_str(&format!("\n\n[{len} rows x {columns} columns]"));
    }
    text
}

/// Convert a Python dict `{old: new}` into FrankenPandas `(Scalar, Scalar)` pairs.
fn py_dict_to_scalar_pairs(
    py: Python<'_>,
    mapping: &Bound<'_, PyDict>,
) -> PyResult<Vec<(Scalar, Scalar)>> {
    let mut pairs = Vec::with_capacity(mapping.len());
    for (k, v) in mapping.iter() {
        pairs.push((py_to_scalar(py, &k)?, py_to_scalar(py, &v)?));
    }
    Ok(pairs)
}

/// Nanoseconds of the naive wall time `fields` (year, month, day, hour,
/// minute, second, microsecond) plus `nanosecond`, checked as pandas'
/// Timestamp checks them: Python's datetime rejects a field out of its range
/// (month 13 is "month must be in 1..12") and a time past the nanosecond
/// range is OutOfBoundsDatetime (the arithmetic overflowed: a panic, or a
/// wrapped instant in a release build).
fn civil_nanos(py: Python<'_>, fields: [i64; 7], nanosecond: i64) -> PyResult<i64> {
    if !(0..=999).contains(&nanosecond) {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "nanosecond must be in 0..999",
        ));
    }
    let wall = py
        .import("datetime")?
        .getattr("datetime")?
        .call1(PyTuple::new(py, fields)?)?;
    let nanos = py_datetime_nanos(wall.cast::<PyDateTime>()?)?;
    nanos.checked_add(nanosecond).ok_or_else(|| {
        OutOfBoundsDatetime::new_err(format!("Out of bounds nanosecond timestamp: {wall}"))
    })
}

/// `text` read as pandas' Timestamp reads a string beyond the ISO forms
/// Timestamp::parse takes ('2024-01', 'Jan 5 2024', '2024/01/05',
/// '5 January 2024 10:00'): through to_datetime's parser, a zone the string
/// carries kept. Unreadable text is pandas' ValueError.
fn parsed_timestamp(text: &str) -> PyResult<Timestamp> {
    let unreadable = || {
        DateParseError::new_err(format!(
            "Unknown datetime string format, unable to parse: {text}"
        ))
    };
    let series = Series::from_values(
        "",
        vec![IndexLabel::Int64(0)],
        vec![Scalar::Utf8(text.to_owned())],
    )
    .map_err(frame_error_to_py)?;
    let parsed = fp_frame::to_datetime_with_options(
        &series,
        fp_frame::ToDatetimeOptions {
            errors: fp_frame::DatetimeErrors::Raise,
            ..Default::default()
        },
    )
    .map_err(|_| unreadable())?;
    let tz = match parsed.column().dtype() {
        DType::Datetime64 { tz } => tz,
        _ => None,
    };
    match parsed.values().first() {
        Some(Scalar::Datetime64(nanos)) => Ok(Timestamp { nanos: *nanos, tz }),
        _ => Err(unreadable()),
    }
}

/// Nanoseconds since the epoch of `value` counted in pandas' `unit` (a bare
/// number is nanoseconds, as pandas reads it: it was read as seconds below
/// 1e11, so Timestamp(1_700_000_000) was 2023 rather than 1970-01-01
/// 00:00:01.7); past the nanosecond range is OutOfBoundsDatetime.
fn epoch_nanos(value: f64, exact: Option<i64>, unit: Option<&str>) -> PyResult<i64> {
    let scale: i64 = match unit {
        None | Some("ns" | "nanosecond" | "nanoseconds" | "N") => 1,
        Some("us" | "microsecond" | "microseconds" | "U") => 1_000,
        Some("ms" | "millisecond" | "milliseconds" | "L") => 1_000_000,
        Some("s" | "second" | "seconds" | "S") => 1_000_000_000,
        Some("m" | "minute" | "minutes" | "min" | "T") => 60_000_000_000,
        Some("h" | "hour" | "hours" | "H") => 3_600_000_000_000,
        Some("D" | "d" | "day" | "days") => 86_400_000_000_000,
        Some(other) => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Unit {other} is not supported. Only unambiguous timedelta values durations are supported. Allowed units are 'W', 'D', 'h', 'm', 's', 'ms', 'us', 'ns'"
            )));
        }
    };
    let out_of_bounds = || {
        OutOfBoundsDatetime::new_err(format!(
            "cannot convert input {value} with the unit '{}'",
            unit.unwrap_or("ns")
        ))
    };
    if let Some(count) = exact {
        return count.checked_mul(scale).ok_or_else(out_of_bounds);
    }
    let nanos = (value * scale as f64).round();
    if nanos.is_finite() && nanos > i64::MIN as f64 && nanos < i64::MAX as f64 {
        Ok(nanos as i64)
    } else {
        Err(out_of_bounds())
    }
}

fn days_from_ymd(year: i64, month: i64, day: i64) -> i64 {
    let y = if month <= 2 { year - 1 } else { year };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let doy = (153 * (if month > 2 { month - 3 } else { month + 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

/// Missing value sentinel `NAType` (pandas `pd.NA`).
#[pyclass(name = "NAType", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyNAType;

static NA_OBJECT: pyo3::sync::PyOnceLock<Py<PyAny>> = pyo3::sync::PyOnceLock::new();

static FROZEN_LIST: pyo3::sync::PyOnceLock<Py<PyAny>> = pyo3::sync::PyOnceLock::new();

/// pandas' `FrozenList` (a MultiIndex's `levels` / `codes` / `names`): a
/// list that refuses mutation, hashes as its tuple, keeps its type through
/// `+`, `*` and slices, prints its items as pandas' `pprint_thing` does and
/// reprs as `FrozenList([...])`.
const FROZEN_LIST_SOURCE: &std::ffi::CStr = cr#"
def _pprint(item):
    if isinstance(item, str):
        return repr(item)
    if isinstance(item, tuple):
        return "(" + ", ".join(_pprint(value) for value in item) + ")"
    if isinstance(item, (bytes, dict)) or not hasattr(item, "__len__"):
        return str(item)
    try:
        values = list(iter(item))
    except TypeError:
        return str(item)
    return "[" + ", ".join(_pprint(value) for value in values) + "]"


class FrozenList(list):
    def _disabled(self, *args, **kwargs):
        raise TypeError(f"'{type(self).__name__}' does not support mutable operations.")

    __setitem__ = __delitem__ = __iadd__ = __imul__ = _disabled
    append = extend = insert = pop = remove = sort = reverse = clear = _disabled

    def __getitem__(self, key):
        if isinstance(key, slice):
            return type(self)(super().__getitem__(key))
        return super().__getitem__(key)

    def __add__(self, other):
        return type(self)(list(self) + list(other))

    def __radd__(self, other):
        return type(self)(list(other) + list(self))

    def __mul__(self, count):
        return type(self)(list(self) * count)

    __rmul__ = __mul__

    def __hash__(self):
        return hash(tuple(self))

    def __reduce__(self):
        return type(self), (list(self),)

    def union(self, other):
        return type(self)(list(self) + [item for item in other if item not in self])

    def difference(self, other):
        return type(self)([item for item in self if item not in set(other)])

    def __str__(self):
        return _pprint(self)

    def __repr__(self):
        return f"{type(self).__name__}({self})"
"#;

/// `items` as pandas' `FrozenList` (they came back a plain list, so
/// `mi.levels` printed Index reprs; rvqoi).
fn frozen_list(py: Python<'_>, items: Vec<Py<PyAny>>) -> PyResult<Py<PyAny>> {
    let class = FROZEN_LIST.get_or_try_init(py, || -> PyResult<Py<PyAny>> {
        let module = PyModule::from_code(
            py,
            FROZEN_LIST_SOURCE,
            c"frankenpandas/frozen_list.py",
            c"frankenpandas._frozen_list",
        )?;
        Ok(module.getattr("FrozenList")?.unbind())
    })?;
    class
        .bind(py)
        .call1((PyList::new(py, items)?,))
        .map(Bound::unbind)
}

/// pandas' `pd.NA` is one object, so `x is pd.NA` holds for every missing
/// cell; every NA the binding hands out is this one (each was a new
/// object, so `x is fpd.NA` was False).
fn na_object(py: Python<'_>) -> PyResult<Py<PyAny>> {
    NA_OBJECT
        .get_or_try_init(py, || Py::new(py, PyNAType).map(Py::into_any))
        .map(|na| na.clone_ref(py))
}

#[pymethods]
impl PyNAType {
    /// Pickles (and deep-copies) as the NA singleton ([`restore`]).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        restore_call(py, "NA", py.None().into_bound(py))
    }

    #[new]
    fn new() -> Self {
        PyNAType
    }

    fn __repr__(&self) -> &'static str {
        "<NA>"
    }

    fn __str__(&self) -> &'static str {
        "<NA>"
    }

    fn __bool__(&self) -> PyResult<bool> {
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "boolean value of NA is ambiguous",
        ))
    }

    fn __hash__(&self) -> isize {
        133742
    }

    fn __richcmp__<'py>(
        &self,
        py: Python<'py>,
        _other: &Bound<'py, PyAny>,
        _op: pyo3::class::basic::CompareOp,
    ) -> PyResult<Py<PyAny>> {
        na_object(py)
    }

    // pandas' NA propagates through arithmetic with a number, a string or NA
    // itself (an array: one NA per element), `+` / `-` with a duration and
    // `-` with a date; anything else is NotImplemented. Every operator raised
    // TypeError (br-frankenpandas-c5b7x).
    fn __add__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, true)
    }
    fn __radd__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, true)
    }
    fn __sub__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, true, true)
    }
    fn __rsub__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, true, true)
    }
    fn __mul__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __rmul__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __matmul__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __rmatmul__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __truediv__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __rtruediv__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __floordiv__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __rfloordiv__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __mod__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __rmod__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_propagated(py, other, false, false)
    }
    fn __divmod__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_divmod(py, other)
    }
    fn __rdivmod__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_divmod(py, other)
    }

    /// `NA ** 0` is 1 (of the exponent's type), any other number NA; an
    /// array is 1 where it is 0 and NA elsewhere.
    fn __pow__(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        _modulo: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        na_power(py, other, 0)
    }

    /// `1 ** NA` is 1, any other number NA; an array keeps its 1s and is NA
    /// elsewhere.
    fn __rpow__(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        _modulo: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        na_power(py, other, 1)
    }

    fn __neg__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        na_object(py)
    }
    fn __pos__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        na_object(py)
    }
    fn __abs__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        na_object(py)
    }
    fn __invert__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        na_object(py)
    }

    // Kleene logic, as pandas' NA: False & NA is False, True | NA is True,
    // every other bool / NA pairing NA (by identity: True / False only).
    fn __and__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, Some(false))
    }
    fn __rand__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, Some(false))
    }
    fn __or__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, Some(true))
    }
    fn __ror__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, Some(true))
    }
    fn __xor__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, None)
    }
    fn __rxor__(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        na_kleene(py, other, None)
    }
}

/// Whether `other` is a number as pandas' NA reads one (`numbers.Number`
/// or a numpy bool).
fn na_is_number(other: &Bound<'_, PyAny>) -> PyResult<bool> {
    let py = other.py();
    Ok(
        other.is_instance(&py.import("numbers")?.getattr("Number")?)?
            || other.is_instance(&py.import("numpy")?.getattr("bool_")?)?,
    )
}

/// pandas' NA arithmetic with `other`: NA for a number, str / bytes, NA or
/// a 0-d array, and for a date (Python's, or our Timestamp) when `dates`, a
/// duration (Python's, or our Timedelta) when `durations`; an object array
/// of NA for an n-d array; NotImplemented otherwise.
fn na_propagated(
    py: Python<'_>,
    other: &Bound<'_, PyAny>,
    dates: bool,
    durations: bool,
) -> PyResult<Py<PyAny>> {
    let numpy = py.import("numpy")?;
    let datetime = py.import("datetime")?;
    let scalar = other.is_instance_of::<PyNAType>()
        || other.is_instance_of::<pyo3::types::PyString>()
        || other.is_instance_of::<pyo3::types::PyBytes>()
        || na_is_number(other)?
        || (dates
            && (other.is_instance(&datetime.getattr("date")?)?
                || other.extract::<PyRef<'_, PyTimestamp>>().is_ok()))
        || (durations
            && (other.is_instance(&datetime.getattr("timedelta")?)?
                || other.extract::<PyRef<'_, PyTimedelta>>().is_ok()));
    let array = other.is_instance(&numpy.getattr("ndarray")?)?;
    if scalar || (array && other.getattr("ndim")?.extract::<usize>()? == 0) {
        return na_object(py);
    }
    if array {
        let filled = numpy.call_method1("empty", (other.getattr("shape")?, "object"))?;
        filled.call_method1("fill", (na_object(py)?,))?;
        return Ok(filled.unbind());
    }
    Ok(py.NotImplemented())
}

/// `divmod` with NA: a pair of [`na_propagated`] answers (two arrays for
/// an array).
fn na_divmod(py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
    let quotient = na_propagated(py, other, false, false)?;
    if quotient.is(py.NotImplemented()) {
        return Ok(quotient);
    }
    let remainder = na_propagated(py, other, false, false)?;
    Ok(PyTuple::new(py, [quotient, remainder])?.into_any().unbind())
}

/// NA `**` (`fixed` 0: NA is the base) or reflected `**` (`fixed` 1: NA is
/// the exponent) with `other`: `other` itself where it equals `fixed` - as
/// `type(other)(1)` for the exponent 0 - NA elsewhere; a number, NA or an
/// array only, NotImplemented otherwise.
fn na_power(py: Python<'_>, other: &Bound<'_, PyAny>, fixed: i64) -> PyResult<Py<PyAny>> {
    if other.is_instance_of::<PyNAType>() {
        return na_object(py);
    }
    if na_is_number(other)? {
        if !other.eq(fixed)? {
            return na_object(py);
        }
        return Ok(if fixed == 0 {
            other.get_type().call1((1,))?.unbind()
        } else {
            other.clone().unbind()
        });
    }
    let numpy = py.import("numpy")?;
    if other.is_instance(&numpy.getattr("ndarray")?)? {
        let kept = if fixed == 0 {
            other.getattr("dtype")?.getattr("type")?.call1((1,))?
        } else {
            other.clone()
        };
        let mask = other.call_method1("__eq__", (fixed,))?;
        return Ok(numpy
            .call_method1("where", (mask, kept, na_object(py)?))?
            .unbind());
    }
    Ok(py.NotImplemented())
}

/// NA `&` / `|` (`absorbing` the bool that decides the answer: False for
/// `&`, True for `|`; None for `^`, which is always NA) with `other` - by
/// identity with True / False, as pandas' NA; NotImplemented for anything
/// but a bool or NA.
fn na_kleene(
    py: Python<'_>,
    other: &Bound<'_, PyAny>,
    absorbing: Option<bool>,
) -> PyResult<Py<PyAny>> {
    let true_ = pyo3::types::PyBool::new(py, true);
    let false_ = pyo3::types::PyBool::new(py, false);
    let is_true = other.is(&*true_);
    let is_false = other.is(&*false_);
    if !(is_true || is_false || other.is_instance_of::<PyNAType>()) {
        return Ok(py.NotImplemented());
    }
    match absorbing {
        Some(true) if is_true => Ok(true_.to_owned().into_any().unbind()),
        Some(false) if is_false => Ok(false_.to_owned().into_any().unbind()),
        _ => na_object(py),
    }
}

/// Temporal missing value sentinel `NaTType` (pandas `pd.NaT`).
#[pyclass(name = "NaTType", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyNaTType;

static NAT_OBJECT: pyo3::sync::PyOnceLock<Py<PyAny>> = pyo3::sync::PyOnceLock::new();

/// pandas' `pd.NaT` is one object, so `x is pd.NaT` holds for every
/// missing instant or duration; every NaT the binding hands out is this one
/// (each was a new object, so `ts is fpd.NaT` was False).
fn nat_object(py: Python<'_>) -> PyResult<Py<PyAny>> {
    NAT_OBJECT
        .get_or_try_init(py, || Py::new(py, PyNaTType).map(Py::into_any))
        .map(|nat| nat.clone_ref(py))
}

