/// pandas' refusal of a datetime method NaT has no answer for.
fn nat_unsupported(name: &str) -> PyErr {
    PyErr::new::<pyo3::exceptions::PyValueError, _>(format!("NaTType does not support {name}"))
}

/// Components breakdown for `Timedelta` (pandas `Timedelta.components`),
/// named as pandas' namedtuple ('Components'; it was 'TimedeltaComponents').
#[pyclass(name = "Components", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyTimedeltaComponents {
    #[pyo3(get)]
    pub days: i64,
    #[pyo3(get)]
    pub hours: i64,
    #[pyo3(get)]
    pub minutes: i64,
    #[pyo3(get)]
    pub seconds: i64,
    #[pyo3(get)]
    pub milliseconds: i64,
    #[pyo3(get)]
    pub microseconds: i64,
    #[pyo3(get)]
    pub nanoseconds: i64,
}

impl PyTimedeltaComponents {
    fn fields(&self) -> [i64; 7] {
        [
            self.days,
            self.hours,
            self.minutes,
            self.seconds,
            self.milliseconds,
            self.microseconds,
            self.nanoseconds,
        ]
    }
}

/// pandas' Components is a namedtuple: it iterates, indexes and has a
/// length (tuple(c) raised "not iterable").
#[pymethods]
impl PyTimedeltaComponents {
    fn __len__(&self) -> usize {
        7
    }

    fn __getitem__(&self, index: isize) -> PyResult<i64> {
        let fields = self.fields();
        let position = if index < 0 { index + 7 } else { index };
        usize::try_from(position)
            .ok()
            .and_then(|position| fields.get(position).copied())
            .ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyIndexError, _>("tuple index out of range")
            })
    }

    fn __iter__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        Ok(PyTuple::new(py, self.fields())?
            .into_any()
            .try_iter()?
            .into_any()
            .unbind())
    }

    fn __repr__(&self) -> String {
        format!(
            "Components(days={}, hours={}, minutes={}, seconds={}, milliseconds={}, microseconds={}, nanoseconds={})",
            self.days,
            self.hours,
            self.minutes,
            self.seconds,
            self.milliseconds,
            self.microseconds,
            self.nanoseconds
        )
    }
}

/// Duration representation (pandas `pd.Timedelta`).
#[pyclass(name = "Timedelta", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyTimedelta {
    pub(crate) nanos: i64,
}

#[pymethods]
impl PyTimedelta {
    /// Pickles (and deep-copies) as this duration ([`restore`]; it could not
    /// be pickled, br-frankenpandas-uch5o).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        restore_call(py, "Timedelta", self.nanos.into_bound_py_any(py)?)
    }

    /// pandas' `Timedelta(value, unit=, **components)`: a string, int or
    /// float (in `unit`, rounded to whole nanoseconds; NaN is NaT), another
    /// Timedelta, a `datetime.timedelta` or numpy timedelta64, or the
    /// weeks..nanoseconds keywords (floats allowed). A `datetime.timedelta`
    /// and a float became 0 days; any other value now raises, as pandas. A
    /// missing duration ('NaT', None, NaN, NaT) is pandas' NaT singleton (it
    /// was a Timedelta holding NaT, so `Timedelta('NaT') is NaT` was False).
    #[new]
    #[pyo3(signature = (*args, **kwargs))]
    fn py_new(
        py: Python<'_>,
        args: &Bound<'_, PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        let made = |nanos: i64| -> PyResult<Py<PyAny>> {
            if nanos == Timedelta::NAT {
                return nat_object(py);
            }
            Ok(Py::new(py, PyTimedelta { nanos })?.into_any())
        };
        let mut value = args.iter().next();
        let mut unit = None;
        let mut components = Vec::new();
        for (key, item) in kwargs.into_iter().flat_map(|kwargs| kwargs.iter()) {
            match key.extract::<String>()?.as_str() {
                "value" => value = Some(item),
                "unit" => unit = Some(item.extract::<String>()?),
                name => {
                    let scale = match name {
                        "weeks" => 7 * 86_400_000_000_000_i64,
                        "days" => 86_400_000_000_000,
                        "hours" => 3_600_000_000_000,
                        "minutes" => 60_000_000_000,
                        "seconds" => 1_000_000_000,
                        "milliseconds" => 1_000_000,
                        "microseconds" => 1_000,
                        "nanoseconds" => 1,
                        _ => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                                "cannot construct a Timedelta from the passed arguments, allowed keywords are [weeks, days, hours, minutes, seconds, milliseconds, microseconds, nanoseconds]",
                            ));
                        }
                    };
                    components.push((item, scale));
                }
            }
        }
        let Some(value) = value else {
            let mut total = 0_i64;
            for (item, scale) in components {
                let nanos = match number_operand(&item) {
                    Some(Number::Int(count)) => {
                        count.checked_mul(scale).ok_or_else(duration_overflow)?
                    }
                    Some(Number::Float(count)) => float_nanos((count * scale as f64).round())?,
                    None => {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "unsupported type for timedelta component: {}",
                            item.get_type().name()?
                        )));
                    }
                };
                total = duration_sum(total, nanos)?;
            }
            return made(total);
        };
        if value.is_none() {
            return nat_object(py);
        }
        if let Ok(text) = value.extract::<String>() {
            if unit.is_some() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "unit must not be specified if the value is a str",
                ));
            }
            let nanos = Timedelta::parse(&text)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            return made(nanos);
        }
        if let Some(nanos) = duration_operand(&value)? {
            return made(nanos);
        }
        let scale = match unit.as_deref() {
            Some("W" | "w" | "weeks" | "week") => 7 * 86_400_000_000_000_i64,
            Some("D" | "d" | "days" | "day") => 86_400_000_000_000_i64,
            Some("h" | "H" | "hours" | "hour" | "hr") => 3_600_000_000_000_i64,
            Some("m" | "min" | "minutes" | "minute" | "T") => 60_000_000_000_i64,
            Some("s" | "S" | "seconds" | "second" | "sec") => 1_000_000_000_i64,
            Some("ms" | "L" | "milliseconds" | "millisecond" | "milli" | "millis") => 1_000_000_i64,
            Some("us" | "U" | "microseconds" | "microsecond" | "micro" | "micros") => 1_000_i64,
            Some("ns" | "N" | "nanoseconds" | "nanosecond" | "nano" | "nanos") | None => 1_i64,
            Some(other) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "invalid unit abbreviation: {other}"
                )));
            }
        };
        match number_operand(&value) {
            Some(Number::Int(count)) => {
                made(count.checked_mul(scale).ok_or_else(duration_overflow)?)
            }
            Some(Number::Float(count)) => made(float_nanos((count * scale as f64).round())?),
            None => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Value must be Timedelta, string, integer, float, timedelta or convertible, not {}",
                value.get_type().name()?
            ))),
        }
    }

    #[getter]
    fn value(&self) -> i64 {
        self.nanos
    }

    /// pandas' resolution of a Timedelta: nanoseconds (it was missing).
    #[getter]
    fn unit(&self) -> &'static str {
        "ns"
    }

    #[getter]
    fn days(&self) -> i64 {
        Timedelta::components(self.nanos).days
    }

    #[getter]
    fn seconds(&self) -> i64 {
        let c = Timedelta::components(self.nanos);
        c.hours * 3600 + c.minutes * 60 + c.seconds
    }

    #[getter]
    fn microseconds(&self) -> i64 {
        let c = Timedelta::components(self.nanos);
        c.milliseconds * 1000 + c.microseconds
    }

    #[getter]
    fn nanoseconds(&self) -> i64 {
        Timedelta::components(self.nanos).nanoseconds
    }

    #[getter]
    fn components(&self) -> PyTimedeltaComponents {
        let c = Timedelta::components(self.nanos);
        PyTimedeltaComponents {
            days: c.days,
            hours: c.hours,
            minutes: c.minutes,
            seconds: c.seconds,
            milliseconds: c.milliseconds,
            microseconds: c.microseconds,
            nanoseconds: c.nanoseconds,
        }
    }

    fn total_seconds(&self) -> f64 {
        self.nanos as f64 / 1_000_000_000.0
    }

    /// pandas' ISO 8601 duration from the components ('P1DT2H3M4.5S',
    /// 'P-1DT23H0M0S'; it printed the repr text).
    fn isoformat(&self) -> String {
        Timedelta::isoformat(self.nanos)
    }

    #[classattr]
    fn max() -> Self {
        PyTimedelta { nanos: i64::MAX }
    }

    #[classattr]
    fn min() -> Self {
        PyTimedelta {
            nanos: i64::MIN + 1,
        }
    }

    fn __repr__(&self) -> String {
        if self.nanos == Timedelta::NAT {
            "NaT".to_string()
        } else {
            format!("Timedelta('{}')", Timedelta::format(self.nanos))
        }
    }

    fn __str__(&self) -> String {
        if self.nanos == Timedelta::NAT {
            "NaT".to_string()
        } else {
            Timedelta::format(self.nanos)
        }
    }

    /// pandas' hash: the equal `datetime.timedelta`'s when the duration is
    /// whole microseconds (so either finds the other in a dict), else the
    /// nanoseconds'.
    fn __hash__(&self, py: Python<'_>) -> PyResult<isize> {
        if self.nanos != Timedelta::NAT && self.nanos.rem_euclid(1_000) == 0 {
            return py_delta_of_micros(py, self.nanos / 1_000)?.hash();
        }
        self.nanos.into_pyobject(py)?.hash()
    }

    fn __richcmp__(
        &self,
        other: &Bound<'_, PyAny>,
        op: pyo3::class::basic::CompareOp,
    ) -> PyResult<bool> {
        let other_nanos = if let Ok(other_td) = other.extract::<PyRef<'_, PyTimedelta>>() {
            other_td.nanos
        } else if other.is_instance_of::<PyNaTType>() {
            match op {
                pyo3::class::basic::CompareOp::Eq => return Ok(false),
                pyo3::class::basic::CompareOp::Ne => return Ok(true),
                _ => return Ok(false),
            }
        } else if let Ok(val) = other.getattr("value") {
            if let Ok(ns) = val.extract::<i64>() {
                ns
            } else {
                match op {
                    pyo3::class::basic::CompareOp::Eq => return Ok(false),
                    pyo3::class::basic::CompareOp::Ne => return Ok(true),
                    _ => {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                            "Cannot compare Timedelta with non-timedelta value",
                        ));
                    }
                }
            }
        } else if let Ok(sec) = other.call_method0("total_seconds") {
            if let Ok(s) = sec.extract::<f64>() {
                (s * 1_000_000_000.0).round() as i64
            } else {
                match op {
                    pyo3::class::basic::CompareOp::Eq => return Ok(false),
                    pyo3::class::basic::CompareOp::Ne => return Ok(true),
                    _ => {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                            "Cannot compare Timedelta with non-timedelta value",
                        ));
                    }
                }
            }
        } else if let Ok(s) = other.extract::<String>() {
            if let Ok(nanos) = Timedelta::parse(&s) {
                nanos
            } else {
                match op {
                    pyo3::class::basic::CompareOp::Eq => return Ok(false),
                    pyo3::class::basic::CompareOp::Ne => return Ok(true),
                    _ => {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                            "Cannot compare Timedelta with non-timedelta value",
                        ));
                    }
                }
            }
        } else {
            match op {
                pyo3::class::basic::CompareOp::Eq => return Ok(false),
                pyo3::class::basic::CompareOp::Ne => return Ok(true),
                _ => {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "Cannot compare Timedelta with non-timedelta value",
                    ));
                }
            }
        };

        if self.nanos == Timedelta::NAT || other_nanos == Timedelta::NAT {
            match op {
                pyo3::class::basic::CompareOp::Eq => Ok(false),
                pyo3::class::basic::CompareOp::Ne => Ok(true),
                _ => Ok(false),
            }
        } else {
            Ok(match op {
                pyo3::class::basic::CompareOp::Eq => self.nanos == other_nanos,
                pyo3::class::basic::CompareOp::Ne => self.nanos != other_nanos,
                pyo3::class::basic::CompareOp::Lt => self.nanos < other_nanos,
                pyo3::class::basic::CompareOp::Le => self.nanos <= other_nanos,
                pyo3::class::basic::CompareOp::Gt => self.nanos > other_nanos,
                pyo3::class::basic::CompareOp::Ge => self.nanos >= other_nanos,
            })
        }
    }

    /// `+` a duration (Timedelta, `datetime.timedelta`, numpy timedelta64,
    /// NaT), a Timestamp or a `datetime.datetime` (a Timestamp, its zone
    /// kept). Anything else is NotImplemented (Python's TypeError). A
    /// `datetime.timedelta` / datetime was refused.
    fn __add__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return duration_object(py, duration_sum(self.nanos, nanos)?);
        }
        let instant = if let Ok(ts) = other.extract::<PyRef<'_, PyTimestamp>>() {
            ts.inner.clone()
        } else if let Ok(dt) = other.cast::<PyDateTime>() {
            Timestamp {
                nanos: py_datetime_nanos(dt)?,
                tz: py_datetime_zone(dt)?,
            }
        } else {
            return Ok(py.NotImplemented());
        };
        if self.nanos == Timedelta::NAT || instant.is_nat() {
            return nat_object(py);
        }
        // A Timedelta is nanoseconds, so the sum is.
        PyTimestamp {
            inner: instant.add_timedelta(self.nanos),
            unit: StampUnit::Ns,
        }
        .into_py_any(py)
    }

    /// `duration + Timedelta`, and `datetime.datetime + Timedelta`, which
    /// is a `datetime.datetime` as pandas' (the nanoseconds dropped).
    fn __radd__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return duration_object(py, duration_sum(nanos, self.nanos)?);
        }
        match other.cast::<PyDateTime>() {
            Ok(dt) => self.shift_datetime(py, dt, 1),
            Err(_) => Ok(py.NotImplemented()),
        }
    }

    fn __sub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        match duration_operand(other)? {
            Some(nanos) => duration_object(py, duration_sum(self.nanos, duration_neg(nanos)?)?),
            None => Ok(py.NotImplemented()),
        }
    }

    /// `duration - Timedelta`, and `datetime.datetime - Timedelta` (a
    /// `datetime.datetime`, as pandas').
    fn __rsub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return duration_object(py, duration_sum(nanos, duration_neg(self.nanos)?)?);
        }
        match other.cast::<PyDateTime>() {
            Ok(dt) => self.shift_datetime(py, dt, -1),
            Err(_) => Ok(py.NotImplemented()),
        }
    }

    /// `*` an int or float (truncated to whole nanoseconds, as pandas; NaN
    /// is NaT); a bool or anything else is NotImplemented.
    fn __mul__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        let Some(factor) = number_operand(other) else {
            return Ok(py.NotImplemented());
        };
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        let nanos = match factor {
            Number::Int(factor) => self
                .nanos
                .checked_mul(factor)
                .ok_or_else(duration_overflow)?,
            Number::Float(factor) => float_nanos(self.nanos as f64 * factor)?,
        };
        duration_object(py, nanos)
    }

    fn __rmul__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        self.__mul__(py, other)
    }

    /// `/` a duration (a float; NaN when either is NaT) or a number (a
    /// Timedelta truncated to whole nanoseconds, NaN divisor NaT). Dividing
    /// by zero is ZeroDivisionError (an int zero PANICKED).
    fn __truediv__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return duration_ratio(self.nanos, nanos)?.into_py_any(py);
        }
        let Some(divisor) = number_operand(other) else {
            return Ok(py.NotImplemented());
        };
        if divisor.is_zero() {
            return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
                "division by zero",
            ));
        }
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        duration_object(py, float_nanos(self.nanos as f64 / divisor.as_f64())?)
    }

    fn __rtruediv__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        match duration_operand(other)? {
            Some(nanos) => duration_ratio(nanos, self.nanos)?.into_py_any(py),
            None => Ok(py.NotImplemented()),
        }
    }

    /// `//` a duration (the floored int count; NaN with NaT) or a number
    /// (a floored Timedelta). Dividing by zero is ZeroDivisionError. It was
    /// missing.
    fn __floordiv__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return match duration_floor_div(self.nanos, nanos)? {
                Some(count) => count.into_py_any(py),
                None => f64::NAN.into_py_any(py),
            };
        }
        let Some(divisor) = number_operand(other) else {
            return Ok(py.NotImplemented());
        };
        if divisor.is_zero() {
            return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
                "integer division or modulo by zero",
            ));
        }
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        let nanos = match divisor {
            Number::Int(divisor) => floor_div(self.nanos, divisor),
            Number::Float(divisor) => float_nanos((self.nanos as f64 / divisor).floor())?,
        };
        duration_object(py, nanos)
    }

    fn __rfloordiv__<'py>(
        &self,
        py: Python<'py>,
        other: &Bound<'py, PyAny>,
    ) -> PyResult<Py<PyAny>> {
        let Some(nanos) = duration_operand(other)? else {
            return Ok(py.NotImplemented());
        };
        match duration_floor_div(nanos, self.nanos)? {
            Some(count) => count.into_py_any(py),
            None => f64::NAN.into_py_any(py),
        }
    }

    /// `%` a duration or an int: Python's floored remainder, as a
    /// Timedelta. It was missing.
    fn __mod__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        let divisor = match duration_operand(other)? {
            Some(nanos) => nanos,
            None => match number_operand(other) {
                Some(Number::Int(divisor)) => divisor,
                _ => return Ok(py.NotImplemented()),
            },
        };
        if divisor == 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
                "integer division or modulo by zero",
            ));
        }
        if self.nanos == Timedelta::NAT || divisor == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        duration_object(py, self.nanos - floor_div(self.nanos, divisor) * divisor)
    }

    /// `divmod(Timedelta, duration)`: the floored count and the remainder.
    fn __divmod__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if duration_operand(other)?.is_none() {
            return Ok(py.NotImplemented());
        }
        let quotient = self.__floordiv__(py, other)?;
        let remainder = self.__mod__(py, other)?;
        Ok(PyTuple::new(py, [quotient, remainder])?.into_any().unbind())
    }

    fn __neg__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        duration_object(py, duration_neg(self.nanos)?)
    }

    fn __pos__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        duration_object(py, self.nanos)
    }

    fn __abs__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        if self.nanos < 0 {
            return duration_object(py, duration_neg(self.nanos)?);
        }
        duration_object(py, self.nanos)
    }

    fn __bool__(&self) -> bool {
        self.nanos != 0
    }

    /// The `datetime.timedelta` of this duration (Python's microseconds,
    /// the nanoseconds rounded half to even as pandas'); NaT for NaT. It
    /// was missing.
    fn to_pytimedelta(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        if self.nanos == Timedelta::NAT {
            return nat_object(py);
        }
        let (whole, rest) = (self.nanos.div_euclid(1_000), self.nanos.rem_euclid(1_000));
        let micros = if rest > 500 || (rest == 500 && whole % 2 != 0) {
            whole + 1
        } else {
            whole
        };
        py_delta_of_micros(py, micros).map(|delta| delta.into_any().unbind())
    }

    /// numpy's `timedelta64[ns]` of this duration (it was missing).
    fn to_timedelta64(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let numpy = py.import("numpy")?;
        if self.nanos == Timedelta::NAT {
            return Ok(numpy.call_method1("timedelta64", ("NaT", "ns"))?.unbind());
        }
        Ok(numpy
            .call_method1("timedelta64", (self.nanos, "ns"))?
            .unbind())
    }

    fn to_numpy(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.to_timedelta64(py)
    }

    /// The nearest multiple of the fixed `freq` (ties to even, as pandas);
    /// a calendar frequency is pandas' ValueError. round / floor / ceil
    /// were missing.
    fn round(&self, py: Python<'_>, freq: &str) -> PyResult<Py<PyAny>> {
        let step = duration_step(freq)?;
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        let low = floor_div(self.nanos, step);
        let rest = self.nanos - low * step;
        let up = match (rest * 2).cmp(&step) {
            std::cmp::Ordering::Greater => true,
            std::cmp::Ordering::Equal => low % 2 != 0,
            std::cmp::Ordering::Less => false,
        };
        let multiple = if up { low + 1 } else { low };
        duration_object(
            py,
            multiple.checked_mul(step).ok_or_else(duration_overflow)?,
        )
    }

    fn floor(&self, py: Python<'_>, freq: &str) -> PyResult<Py<PyAny>> {
        let step = duration_step(freq)?;
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        duration_object(py, floor_div(self.nanos, step) * step)
    }

    fn ceil(&self, py: Python<'_>, freq: &str) -> PyResult<Py<PyAny>> {
        let step = duration_step(freq)?;
        if self.nanos == Timedelta::NAT {
            return duration_object(py, Timedelta::NAT);
        }
        let multiple = -floor_div(-self.nanos, step);
        duration_object(
            py,
            multiple.checked_mul(step).ok_or_else(duration_overflow)?,
        )
    }
}

/// The period freq pandas reads an index's own offset freq as, for
/// `to_period()`: a month end or start ('ME', 'BME', 'MS', 'BMS') the month
/// 'M', a quarter or year end its 'Q-' / 'Y-' anchor, a quarter or year
/// start the anchor before it ('QS-JAN' is 'Q-DEC'); any other freq as it
/// is. The offset's own name was read as a period freq, so a date_range of
/// 'ME' could not become periods (br-frankenpandas-6kaxp).
fn offset_freq_as_period(freq: &str) -> String {
    const MONTHS: [&str; 12] = [
        "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC",
    ];
    let (base, anchor) = freq
        .split_once('-')
        .map_or((freq, None), |(base, anchor)| (base, Some(anchor)));
    let month_before = |anchor: Option<&str>| {
        let position = MONTHS
            .iter()
            .position(|month| Some(*month) == anchor.or(Some("JAN")))
            .unwrap_or(0);
        MONTHS[(position + 11) % 12]
    };
    match base {
        "ME" | "BME" | "MS" | "BMS" => "M".to_owned(),
        "QE" | "BQE" => format!("Q-{}", anchor.unwrap_or("DEC")),
        "YE" | "BYE" => format!("Y-{}", anchor.unwrap_or("DEC")),
        "QS" | "BQS" => format!("Q-{}", month_before(anchor)),
        "YS" | "BYS" => format!("Y-{}", month_before(anchor)),
        _ => freq.to_owned(),
    }
}

/// A fixed frequency's length for rounding: a calendar one is pandas'
/// ValueError naming the offset ('<MonthEnd> is a non-fixed frequency'),
/// anything else its invalid-frequency ValueError.
fn fixed_freq_nanos(freq: &str) -> PyResult<i64> {
    parse_freq_to_nanos(freq).map_err(|_| {
        // pandas' bare 'W' is W-SUN.
        let offset = offset_for_freqstr(freq).ok().flatten().or_else(|| {
            freq.ends_with('W')
                .then(|| offset_for_freqstr(&format!("{freq}-SUN")).ok().flatten())
                .flatten()
        });
        let message = match offset {
            Some(offset) => format!("{} is a non-fixed frequency", offset.__repr__()),
            None => format!("Invalid frequency: {freq}"),
        };
        PyErr::new::<pyo3::exceptions::PyValueError, _>(message)
    })
}

/// A fixed frequency's length for Timedelta rounding (see
/// [`fixed_freq_nanos`]); a zero one is pandas' ZeroDivisionError.
fn duration_step(freq: &str) -> PyResult<i64> {
    let step = fixed_freq_nanos(freq)?;
    if step == 0 {
        return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
            "integer division or modulo by zero",
        ));
    }
    Ok(step)
}

impl PyTimedelta {
    /// `dt` moved by this duration (`sign` 1 or -1) as Python's datetime
    /// arithmetic moves it (whole microseconds, its tzinfo kept); NaT for
    /// NaT.
    fn shift_datetime(
        &self,
        py: Python<'_>,
        dt: &Bound<'_, PyDateTime>,
        sign: i64,
    ) -> PyResult<Py<PyAny>> {
        if self.nanos == Timedelta::NAT {
            return nat_object(py);
        }
        let delta = py_delta_of_micros(py, self.nanos.div_euclid(1_000))?;
        let method = if sign < 0 { "__sub__" } else { "__add__" };
        Ok(dt.call_method1(method, (delta,))?.unbind())
    }
}

/// A duration operand as pandas' Timedelta arithmetic takes it - a
/// Timedelta, a `datetime.timedelta`, a numpy timedelta64 or NaT (as
/// `Timedelta::NAT`); None for anything else.
fn duration_operand(other: &Bound<'_, PyAny>) -> PyResult<Option<i64>> {
    if let Ok(td) = other.extract::<PyRef<'_, PyTimedelta>>() {
        return Ok(Some(td.nanos));
    }
    if other.is_instance_of::<PyNaTType>() {
        return Ok(Some(Timedelta::NAT));
    }
    if let Ok(delta) = other.cast::<PyDelta>() {
        return Ok(Some(py_delta_nanos(delta)?));
    }
    if other.get_type().name()?.to_cow()? == "timedelta64" {
        let nanos = other
            .call_method1("astype", ("timedelta64[ns]",))?
            .call_method1("astype", ("int64",))?
            .extract::<i64>()?;
        return Ok(Some(nanos));
    }
    Ok(None)
}

/// The resolution of a [`duration_operand`], which a Timestamp moved by it
/// takes when finer: a Timedelta is nanoseconds, a `datetime.timedelta`
/// microseconds, a numpy timedelta64 its own unit.
fn duration_unit(other: &Bound<'_, PyAny>) -> PyResult<StampUnit> {
    if other.cast::<PyDelta>().is_ok() {
        return Ok(StampUnit::Us);
    }
    if other.get_type().name()?.to_cow()? == "timedelta64" {
        let unit = other
            .py()
            .import("numpy")?
            .call_method1("datetime_data", (other.getattr("dtype")?,))?
            .get_item(0)?
            .extract::<String>()?;
        return Ok(StampUnit::of_unit(&unit));
    }
    Ok(StampUnit::Ns)
}

/// A number operand of Timedelta `*` / `/` / `//` (a bool is not one, as
/// pandas).
enum Number {
    Int(i64),
    Float(f64),
}

impl Number {
    fn is_zero(&self) -> bool {
        match self {
            Self::Int(value) => *value == 0,
            Self::Float(value) => value.classify() == std::num::FpCategory::Zero,
        }
    }

    fn as_f64(&self) -> f64 {
        match self {
            Self::Int(value) => *value as f64,
            Self::Float(value) => *value,
        }
    }
}

fn number_operand(other: &Bound<'_, PyAny>) -> Option<Number> {
    if other.is_instance_of::<pyo3::types::PyBool>() {
        return None;
    }
    if let Ok(value) = other.extract::<i64>() {
        return Some(Number::Int(value));
    }
    other.extract::<f64>().ok().map(Number::Float)
}

/// A duration result as pandas returns it: NaT for a missing one.
fn duration_object(py: Python<'_>, nanos: i64) -> PyResult<Py<PyAny>> {
    if nanos == Timedelta::NAT {
        return nat_object(py);
    }
    PyTimedelta { nanos }.into_py_any(py)
}

fn duration_overflow() -> PyErr {
    PyErr::new::<pyo3::exceptions::PyOverflowError, _>("Python int too large to convert to C long")
}

/// `a + b` for durations: NaT when either is, OverflowError past the
/// nanosecond range (it saturated).
fn duration_sum(a: i64, b: i64) -> PyResult<i64> {
    if a == Timedelta::NAT || b == Timedelta::NAT {
        return Ok(Timedelta::NAT);
    }
    match a.checked_add(b) {
        Some(Timedelta::NAT) | None => Err(duration_overflow()),
        Some(sum) => Ok(sum),
    }
}

fn duration_neg(nanos: i64) -> PyResult<i64> {
    if nanos == Timedelta::NAT {
        return Ok(Timedelta::NAT);
    }
    nanos.checked_neg().ok_or_else(duration_overflow)
}

/// A float count of nanoseconds truncated as pandas truncates it; NaN is
/// NaT.
fn float_nanos(value: f64) -> PyResult<i64> {
    if value.is_nan() {
        return Ok(Timedelta::NAT);
    }
    if !(value > i64::MIN as f64 && value < i64::MAX as f64) {
        return Err(duration_overflow());
    }
    Ok(value as i64)
}

/// `a / b` for durations: NaN when either is NaT; a zero divisor is
/// ZeroDivisionError.
fn duration_ratio(a: i64, b: i64) -> PyResult<f64> {
    if a == Timedelta::NAT || b == Timedelta::NAT {
        return Ok(f64::NAN);
    }
    if b == 0 {
        return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
            "float division by zero",
        ));
    }
    Ok(a as f64 / b as f64)
}

/// `a // b` for durations (floored, as Python's); None when either is NaT;
/// a zero divisor is ZeroDivisionError.
fn duration_floor_div(a: i64, b: i64) -> PyResult<Option<i64>> {
    if a == Timedelta::NAT || b == Timedelta::NAT {
        return Ok(None);
    }
    if b == 0 {
        return Err(PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(
            "integer division or modulo by zero",
        ));
    }
    Ok(Some(floor_div(a, b)))
}

/// Python's floored integer division (`b` nonzero).
fn floor_div(a: i64, b: i64) -> i64 {
    let quotient = a.wrapping_div(b);
    if a.wrapping_rem(b) != 0 && ((a < 0) != (b < 0)) {
        quotient - 1
    } else {
        quotient
    }
}

/// A `datetime.timedelta` of `micros` microseconds.
fn py_delta_of_micros(py: Python<'_>, micros: i64) -> PyResult<Bound<'_, PyDelta>> {
    const DAY: i64 = 86_400_000_000;
    let days = i32::try_from(micros.div_euclid(DAY)).map_err(|_| duration_overflow())?;
    let rest = micros.rem_euclid(DAY);
    let seconds = i32::try_from(rest / 1_000_000).unwrap_or(0);
    let micros = i32::try_from(rest % 1_000_000).unwrap_or(0);
    PyDelta::new(py, days, seconds, micros, true)
}

/// Instant representation (pandas `pd.Timestamp`).
#[pyclass(name = "Timestamp", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyTimestamp {
    pub(crate) inner: Timestamp,
    /// pandas' resolution, `Timestamp.unit`.
    pub(crate) unit: StampUnit,
}

/// pandas' resolution of a Timestamp (`Timestamp.unit`): the finest its
/// input carried - a string's fraction of a second, a `datetime`'s
/// microseconds, a numpy datetime64's own unit - kept by the operations on
/// it and made finer by a finer operand (it was always 'ns'; fvsao.35). The
/// instant itself is nanoseconds whatever the unit.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord)]
pub(crate) enum StampUnit {
    S,
    Ms,
    Us,
    #[default]
    Ns,
}

impl StampUnit {
    const fn name(self) -> &'static str {
        match self {
            Self::S => "s",
            Self::Ms => "ms",
            Self::Us => "us",
            Self::Ns => "ns",
        }
    }

    /// Nanoseconds in one tick.
    const fn nanos(self) -> i64 {
        match self {
            Self::S => 1_000_000_000,
            Self::Ms => 1_000_000,
            Self::Us => 1_000,
            Self::Ns => 1,
        }
    }

    /// The unit pandas stores a value given in numpy / epoch unit `unit` at:
    /// seconds and coarser ('D', 'h', 'm') are seconds.
    fn of_unit(unit: &str) -> Self {
        match unit {
            "ms" => Self::Ms,
            "us" | "μs" => Self::Us,
            "ns" => Self::Ns,
            _ => Self::S,
        }
    }

    /// The unit of a date string: the digits of its fraction of a second
    /// (after `:SS.`) - none is seconds, 1-3 ms, 4-6 us, more ns.
    fn of_text(text: &str) -> Self {
        let bytes = text.as_bytes();
        let digits = (3..bytes.len())
            .find(|&at| {
                bytes[at] == b'.'
                    && bytes[at - 3] == b':'
                    && bytes[at - 2].is_ascii_digit()
                    && bytes[at - 1].is_ascii_digit()
            })
            .map_or(0, |at| {
                bytes[at + 1..]
                    .iter()
                    .take_while(|byte| byte.is_ascii_digit())
                    .count()
            });
        match digits {
            0 => Self::S,
            1..=3 => Self::Ms,
            4..=6 => Self::Us,
            _ => Self::Ns,
        }
    }
}

/// A time zone argument as its name: a string as given, a tzinfo object
/// (`datetime.timezone.utc`, a `zoneinfo.ZoneInfo`, a pytz zone) by its
/// `str`. A zone neither the IANA database nor a fixed offset names is
/// pandas' (pytz) UnknownTimeZoneError, a KeyError.
fn tz_name(zone: &Bound<'_, PyAny>) -> PyResult<String> {
    let name = match zone.extract::<String>() {
        Ok(name) => name,
        Err(_) => zone.str()?.extract::<String>()?,
    };
    // pandas' own name for the zone ('+05:30' is UTC+05:30).
    fp_types::tz_canonical_name(&name).map_err(|err| tz_error_to_py(zone.py(), err))
}

/// A time-zone failure as pandas raises it: pytz's UnknownTimeZoneError (a
/// KeyError), NonExistentTimeError or AmbiguousTimeError, the classes
/// pandas' users catch - KeyError / ValueError when pytz is absent.
fn tz_error_to_py(py: Python<'_>, err: fp_types::TimeZoneError) -> PyErr {
    let (class, message) = match &err {
        fp_types::TimeZoneError::Unknown(name) => ("UnknownTimeZoneError", name.clone()),
        fp_types::TimeZoneError::NonExistent(_) => ("NonExistentTimeError", err.to_string()),
        fp_types::TimeZoneError::Ambiguous(_) => ("AmbiguousTimeError", err.to_string()),
    };
    match py
        .import("pytz.exceptions")
        .and_then(|module| module.getattr(class))
        .and_then(|class| class.call1((message.clone(),)))
    {
        Ok(exception) => PyErr::from_value(exception),
        Err(_) if matches!(err, fp_types::TimeZoneError::Unknown(_)) => {
            PyErr::new::<pyo3::exceptions::PyKeyError, _>(message)
        }
        Err(_) => PyErr::new::<pyo3::exceptions::PyValueError, _>(message),
    }
}

/// pandas' `tz_localize(ambiguous=, nonexistent=)` arguments as fp-frame's
/// options (they were refused unless 'raise'; br-frankenpandas-84w06):
/// `ambiguous` a bool (True: the DST occurrence), 'NaT', 'infer' or an
/// array of bools, one per value - any other string reads as 'raise', as
/// pandas'; `nonexistent` 'raise', 'NaT', 'shift_forward',
/// 'shift_backward' or a timedelta.
fn tz_localize_options(
    ambiguous: Option<&Bound<'_, PyAny>>,
    nonexistent: Option<&Bound<'_, PyAny>>,
) -> PyResult<fp_frame::TzLocalizeOptions> {
    use fp_frame::{TzAmbiguousPolicy, TzNonexistentPolicy};
    let ambiguous = match ambiguous.filter(|value| !value.is_none()) {
        None => TzAmbiguousPolicy::Raise,
        Some(value) if value.is_instance_of::<pyo3::types::PyBool>() => {
            TzAmbiguousPolicy::from_bool(value.is_truthy()?)
        }
        Some(value) => match value.extract::<String>() {
            Ok(text) if text == "NaT" => TzAmbiguousPolicy::NaT,
            Ok(text) if text == "infer" => TzAmbiguousPolicy::Infer,
            Ok(_) => TzAmbiguousPolicy::Raise,
            Err(_) => TzAmbiguousPolicy::Mask(
                value
                    .try_iter()?
                    .map(|item| item?.is_truthy())
                    .collect::<PyResult<Vec<_>>>()?,
            ),
        },
    };
    let nonexistent = match nonexistent.filter(|value| !value.is_none()) {
        None => TzNonexistentPolicy::Raise,
        Some(value) => match value.extract::<String>().ok().as_deref() {
            Some("raise") => TzNonexistentPolicy::Raise,
            Some("NaT") => TzNonexistentPolicy::NaT,
            Some("shift_forward") => TzNonexistentPolicy::ShiftForward,
            Some("shift_backward") => TzNonexistentPolicy::ShiftBackward,
            _ => match duration_operand(value)? {
                Some(nanos) if nanos != Timedelta::NAT => {
                    TzNonexistentPolicy::shift_by_nanos(nanos)
                }
                _ => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "The nonexistent argument must be one of 'raise', 'NaT', 'shift_forward', 'shift_backward' or a timedelta object",
                    ));
                }
            },
        },
    };
    Ok(fp_frame::TzLocalizeOptions {
        ambiguous,
        nonexistent,
    })
}

/// pandas' refusal of an `ambiguous` bool array whose length is not the
/// values' `len`.
fn check_ambiguous_mask(options: &fp_frame::TzLocalizeOptions, len: usize) -> PyResult<()> {
    match &options.ambiguous {
        fp_frame::TzAmbiguousPolicy::Mask(mask) if mask.len() != len => {
            Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Length of ambiguous bool-array must be the same size as vals",
            ))
        }
        _ => Ok(()),
    }
}

/// `values` (naive wall-clock nanoseconds, NaT `i64::MIN`) localized to
/// `zone` under `options` through fp-frame's Series path - the one that
/// reads `ambiguous='infer'` and per-value arrays - as UTC nanoseconds.
fn localized_nanos(
    values: &[i64],
    zone: &str,
    options: fp_frame::TzLocalizeOptions,
) -> PyResult<Vec<i64>> {
    check_ambiguous_mask(&options, values.len())?;
    let column = Column::new(
        DType::datetime64_naive(),
        values
            .iter()
            .map(|&nanos| Scalar::Datetime64(nanos))
            .collect(),
    )
    .map_err(column_error_to_py)?;
    let positions = Index::new_known_unique_int64_unit_range(0, values.len());
    let series = Series::new("", positions, column).map_err(frame_error_to_py)?;
    let localized = series
        .dt()
        .tz_localize_with_options(Some(zone), options)
        .map_err(frame_error_to_py)?;
    Ok(localized
        .values()
        .iter()
        .map(|value| match value {
            Scalar::Datetime64(nanos) => *nanos,
            _ => i64::MIN,
        })
        .collect())
}

/// `dti.tz_localize(zone, ambiguous=, nonexistent=)`: fp-index's path for
/// pandas' 'raise' defaults (and for dropping or refusing a zone), else the
/// wall times localized under `options` (see [`localized_nanos`]), the name
/// kept.
fn localize_datetime_index(
    dti: &DatetimeIndex,
    zone: Option<&str>,
    options: fp_frame::TzLocalizeOptions,
) -> PyResult<DatetimeIndex> {
    let Some(zone) = zone.filter(|_| {
        options != fp_frame::TzLocalizeOptions::default() && dti.as_index().tz().is_none()
    }) else {
        return dti.tz_localize(zone).map_err(index_error_to_py);
    };
    let wall: Vec<i64> = dti
        .values()
        .into_iter()
        .map(|nanos| nanos.unwrap_or(i64::MIN))
        .collect();
    let utc = localized_nanos(&wall, zone, options)?;
    let index = DatetimeIndex::new(utc)
        .into_index()
        .with_tz(Some(zone))
        .map_err(index_error_to_py)?
        .rename_index(dti.name().cloned());
    DatetimeIndex::from_index(index).map_err(index_error_to_py)
}

/// The tzinfo pandas 2.2 gives a zone: `datetime.timezone.utc` for UTC, a
/// fixed `datetime.timezone` for an offset, else pytz's zone (zoneinfo's
/// when pytz is absent).
fn zone_tzinfo<'py>(py: Python<'py>, zone: &str) -> PyResult<Bound<'py, PyAny>> {
    let timezone = py.import("datetime")?.getattr("timezone")?;
    // An offset a text carried ('+09:00') is the fixed zone 'UTC+09:00'.
    let zone = fp_types::tz_canonical_name(zone).map_err(|err| tz_error_to_py(py, err))?;
    let zone = zone.as_str();
    if zone == "UTC" {
        return timezone.getattr("utc");
    }
    if zone.starts_with("UTC+") || zone.starts_with("UTC-") {
        let seconds =
            fp_types::tz_offset_seconds(zone, 0).map_err(|err| tz_error_to_py(py, err))?;
        return timezone.call1((PyDelta::new(py, 0, seconds, 0, true)?,));
    }
    match py.import("pytz") {
        Ok(pytz) => pytz.call_method1("timezone", (zone,)),
        Err(_) => py.import("zoneinfo")?.call_method1("ZoneInfo", (zone,)),
    }
}

/// [`zone_tzinfo`] at the UTC instant `nanos`, as `Timestamp.tz` is: a pytz
/// zone localized to the offset it has then (`EST` / `EDT`, where an
/// index's or a dtype's zone is the zone itself, `LMT`); any other tzinfo
/// is itself.
fn instant_tzinfo<'py>(py: Python<'py>, zone: &str, nanos: i64) -> PyResult<Bound<'py, PyAny>> {
    let tzinfo = zone_tzinfo(py, zone)?;
    Ok(py
        .import("datetime")?
        .getattr("datetime")?
        .call_method1("fromtimestamp", (nanos.div_euclid(1_000_000_000), &tzinfo))
        .and_then(|stamp| stamp.getattr("tzinfo"))
        .unwrap_or(tzinfo))
}

impl PyTimestamp {
    /// This instant as a `datetime.datetime` - a tz-aware one's in its zone
    /// with the tzinfo pandas gives it (see [`zone_tzinfo`]); None for NaT.
    fn py_datetime<'py>(&self, py: Python<'py>) -> PyResult<Option<Bound<'py, PyAny>>> {
        let Some(zone) = &self.inner.tz else {
            return Ok(self.datetime_object(py)?.map(Bound::into_any));
        };
        let utc = PyTimestamp {
            inner: Timestamp::from_nanos(self.inner.nanos),
            unit: self.unit,
        };
        let Some((year, month, day, hour, minute, second, micro)) = utc.civil_fields() else {
            return Ok(None);
        };
        let datetime = py.import("datetime")?;
        let utc_zone = datetime.getattr("timezone")?.getattr("utc")?;
        let instant = datetime
            .getattr("datetime")?
            .call1((year, month, day, hour, minute, second, micro, utc_zone))?;
        instant
            .call_method1("astimezone", (zone_tzinfo(py, zone)?,))
            .map(Some)
    }

    /// This instant moved by `nanos` (its zone kept), in the finer of its
    /// unit and the duration's `unit`; NaT when either is, pandas'
    /// OutOfBoundsDatetime past the nanosecond range (it was a silent NaT).
    fn shifted(&self, py: Python<'_>, nanos: i64, unit: StampUnit) -> PyResult<Py<PyAny>> {
        if nanos == Timedelta::NAT || self.inner.is_nat() {
            return nat_object(py);
        }
        let inner = self.inner.try_add_timedelta(nanos).map_err(|_| {
            OutOfBoundsDatetime::new_err(format!(
                "Out of bounds nanosecond timestamp: {}",
                i128::from(self.inner.nanos) + i128::from(nanos)
            ))
        })?;
        PyTimestamp {
            inner,
            unit: self.unit.max(unit),
        }
        .into_py_any(py)
    }

    /// pandas' refusal to mix tz-naive and tz-aware instants in `-`.
    fn require_same_awareness(&self, other_zone: Option<&str>, other_nat: bool) -> PyResult<()> {
        if self.inner.is_nat() || other_nat || self.inner.tz.is_some() == other_zone.is_some() {
            return Ok(());
        }
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "Cannot subtract tz-naive and tz-aware datetime-like objects.",
        ))
    }
    /// The UTC offset, in seconds, of a tz-aware Timestamp's zone at its
    /// instant; 0 for a naive one or NaT.
    fn utc_offset_seconds(&self) -> i32 {
        match &self.inner.tz {
            Some(tz) if !self.inner.is_nat() => {
                fp_types::tz_offset_seconds(tz, self.inner.nanos).unwrap_or(0)
            }
            _ => 0,
        }
    }

    /// The wall clock this Timestamp shows, as a naive Timestamp: a tz-aware
    /// one's instant moved by its zone's offset (the fields read the UTC
    /// instant, so a Tokyo 23:30 said 14:30).
    fn wall(&self) -> Timestamp {
        if self.inner.tz.is_none() || self.inner.is_nat() {
            return Timestamp::from_nanos(self.inner.nanos);
        }
        Timestamp::from_nanos(
            self.inner
                .nanos
                .saturating_add(i64::from(self.utc_offset_seconds()) * 1_000_000_000),
        )
    }

    /// `self` moved by a DateOffset (`sign` 1 or -1) on its wall clock; a
    /// tz-aware result is back in its zone (it dropped the zone).
    fn offset_shift(&self, py: Python<'_>, offset: &PyDateOffset, sign: i64) -> PyResult<Self> {
        let shifted = Self {
            inner: Timestamp::from_nanos(offset.apply(py, self.wall().nanos, sign)?),
            unit: self.unit,
        };
        match &self.inner.tz {
            Some(zone) if !self.inner.is_nat() => shifted.localized(Some(zone)),
            _ => Ok(shifted),
        }
    }

    /// `op` applied to the wall clock; a tz-aware result is that wall time
    /// back in its zone.
    fn on_wall(&self, op: impl FnOnce(&Timestamp) -> Timestamp) -> PyResult<Self> {
        let wall = Self {
            inner: op(&self.wall()),
            unit: self.unit,
        };
        match &self.inner.tz {
            Some(zone) if !self.inner.is_nat() => wall.localized(Some(zone)),
            _ => Ok(wall),
        }
    }

    /// floor / ceil / round (`op`) to a multiple of the fixed `freq` on the
    /// wall clock: any multiple ('15min', '7D', '30s') - it read only a bare
    /// unit, so `round('15min')` was NaT - with pandas' ValueError for a
    /// calendar, unknown or zero frequency (they were NaT too) and its
    /// OutOfBoundsDatetime past the nanosecond range.
    fn rounded(&self, freq: &str, op: fn(&Timestamp, i64) -> Timestamp) -> PyResult<Self> {
        if self.inner.is_nat() {
            return Ok(self.clone());
        }
        let step = fixed_freq_nanos(freq)?;
        if step == 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Division by zero in rounding",
            ));
        }
        let rounded = self.on_wall(|wall| op(wall, step))?;
        if rounded.inner.is_nat() {
            let shown = match offset_for_freqstr(freq) {
                Ok(Some(offset)) => offset.__repr__(),
                _ => freq.to_owned(),
            };
            return Err(OutOfBoundsDatetime::new_err(format!(
                "Cannot round {} to freq={shown} without overflow",
                self.__str__()
            )));
        }
        Ok(rounded)
    }

    /// pandas' `+HH:MM` for a tz-aware Timestamp's offset (`colon`) or its
    /// `+HHMM` repr spelling; empty for a naive one.
    fn offset_text(&self, colon: bool) -> String {
        if self.inner.tz.is_none() || self.inner.is_nat() {
            return String::new();
        }
        let offset = self.utc_offset_seconds();
        let sign = if offset < 0 { '-' } else { '+' };
        let minutes = offset.unsigned_abs() / 60;
        let separator = if colon { ":" } else { "" };
        format!("{sign}{:02}{separator}{:02}", minutes / 60, minutes % 60)
    }

    /// pandas' `Timestamp.tz_localize`: a naive Timestamp's wall clock
    /// placed in `tz` (a wall time a DST change repeats or skips is an
    /// error), or a tz-aware one's wall clock kept without its zone (None).
    fn localized(&self, tz: Option<&str>) -> PyResult<Self> {
        self.localized_with(
            tz,
            fp_types::AmbiguousTime::Raise,
            fp_types::NonexistentTime::Raise,
        )
    }

    /// [`Self::localized`] under pandas' `ambiguous` / `nonexistent`
    /// policies for one value (a policy's NaT is a NaT Timestamp).
    fn localized_with(
        &self,
        tz: Option<&str>,
        ambiguous: fp_types::AmbiguousTime,
        nonexistent: fp_types::NonexistentTime,
    ) -> PyResult<Self> {
        match (tz, &self.inner.tz) {
            (Some(_), Some(_)) => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Cannot localize tz-aware Timestamp, use tz_convert for conversions",
            )),
            (None, _) => Ok(Self {
                inner: self.wall(),
                unit: self.unit,
            }),
            (Some(zone), None) => {
                if self.inner.is_nat() {
                    return Ok(self.clone());
                }
                let nanos = fp_types::tz_wall_to_utc_nanos_with(
                    zone,
                    self.inner.nanos,
                    ambiguous,
                    nonexistent,
                )
                .map_err(|err| Python::attach(|py| tz_error_to_py(py, err)))?;
                if nanos == i64::MIN {
                    return Ok(Self {
                        inner: Timestamp::nat(),
                        unit: self.unit,
                    });
                }
                Ok(Self {
                    inner: Timestamp {
                        nanos,
                        tz: Some(zone.to_owned()),
                    },
                    unit: self.unit,
                })
            }
        }
    }

    /// pandas' `Timestamp.tz_convert`: the same instant shown in `tz` (None:
    /// UTC, naive). A naive Timestamp raises.
    fn converted(&self, tz: Option<&str>) -> PyResult<Self> {
        if self.inner.tz.is_none() {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Cannot convert tz-naive Timestamp, use tz_localize to localize",
            ));
        }
        Ok(Self {
            inner: Timestamp {
                nanos: self.inner.nanos,
                tz: tz.map(str::to_owned),
            },
            unit: self.unit,
        })
    }

    /// The fields Python's datetime takes (microseconds, the nanoseconds
    /// dropped), on the wall clock; None for NaT.
    fn civil_fields(&self) -> Option<(i32, u8, u8, u8, u8, u8, u32)> {
        let wall = self.wall();
        Some((
            i32::try_from(wall.year()?).ok()?,
            u8::try_from(wall.month()?).ok()?,
            u8::try_from(wall.day()?).ok()?,
            u8::try_from(wall.hour()?).ok()?,
            u8::try_from(wall.minute()?).ok()?,
            u8::try_from(wall.second()?).ok()?,
            u32::try_from(wall.microsecond()?).ok()?,
        ))
    }

    /// This instant as a naive `datetime.datetime`; None for NaT.
    fn datetime_object<'py>(&self, py: Python<'py>) -> PyResult<Option<Bound<'py, PyDateTime>>> {
        let Some((year, month, day, hour, minute, second, micro)) = self.civil_fields() else {
            return Ok(None);
        };
        PyDateTime::new(py, year, month, day, hour, minute, second, micro, None).map(Some)
    }
}

#[pymethods]
impl PyTimestamp {
    /// Pickles (and deep-copies) as this instant - its nanoseconds, zone
    /// and unit ([`restore`]; it could not be pickled,
    /// br-frankenpandas-uch5o).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let payload =
            (self.inner.nanos, self.inner.tz.clone(), self.unit.name()).into_bound_py_any(py)?;
        restore_call(py, "Timestamp", payload)
    }

    /// A missing input (None, NaT, NaN, 'NaT', 'nan', '') is pandas' NaT
    /// singleton (it was a NaT-holding Timestamp or raised); a string
    /// pandas parses - '2024-01', 'Jan 5 2024', '2024/01/05' - is parsed as
    /// to_datetime parses it (only ISO forms were read).
    #[new]
    #[pyo3(signature = (*args, **kwargs))]
    fn py_new(
        py: Python<'_>,
        args: &Bound<'_, PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        // tz= / tzinfo= localizes the wall time the other arguments give
        // (it was refused).
        let mut zone = None;
        if let Some(kw) = kwargs {
            for key in ["tz", "tzinfo"] {
                if let Some(value) = kw.get_item(key)?.filter(|value| !value.is_none()) {
                    zone = Some(tz_name(&value)?);
                }
            }
        }
        let keyword = |name: &str| -> PyResult<Option<Bound<'_, PyAny>>> {
            Ok(kwargs.map(|kw| kw.get_item(name)).transpose()?.flatten())
        };
        let nanosecond = keyword("nanosecond")?.map_or(Ok(0), |v| v.extract::<i64>())?;
        // Each input sets the unit pandas gives it: a string its fraction of
        // a second, a datetime or fields microseconds (nanoseconds with
        // nanosecond=), a date seconds, numpy its own unit, an int
        // nanoseconds or its epoch unit=, a float nanoseconds.
        let stamp = |inner: Timestamp, unit: StampUnit| PyTimestamp { inner, unit };
        let fields_unit = if nanosecond == 0 {
            StampUnit::Us
        } else {
            StampUnit::Ns
        };
        let nat = || stamp(Timestamp::from_nanos(Timestamp::NAT), StampUnit::Ns);
        // The naive Timestamp the arguments describe.
        let naive = (|| -> PyResult<Self> {
            if args.len() >= 3 {
                let mut fields = [0_i64, 1, 1, 0, 0, 0, 0];
                for (position, field) in fields.iter_mut().enumerate().take(args.len()) {
                    *field = args.get_item(position)?.extract::<i64>()?;
                }
                let nanos = civil_nanos(py, fields, nanosecond)?;
                return Ok(stamp(Timestamp::from_nanos(nanos), fields_unit));
            }
            if args.len() == 1 {
                let arg = args.get_item(0)?;
                if arg.is_none() || arg.is_instance_of::<PyNaTType>() {
                    return Ok(nat());
                }
                if let Ok(ts) = arg.extract::<PyRef<'_, PyTimestamp>>() {
                    return Ok(ts.clone());
                }
                // datetime, date and numpy datetime64 inputs (each fell through
                // to Timestamp.now(), a silently wrong value; fvsao.35).
                if let Ok(dt) = arg.cast::<PyDateTime>() {
                    // A tz-aware datetime keeps its instant and zone.
                    let inner = Timestamp {
                        nanos: py_datetime_nanos(dt)?,
                        tz: py_datetime_zone(dt)?,
                    };
                    return Ok(stamp(inner, StampUnit::Us));
                }
                if let Ok(date) = arg.cast::<pyo3::types::PyDate>() {
                    let days = days_from_ymd(
                        i64::from(date.get_year()),
                        i64::from(date.get_month()),
                        i64::from(date.get_day()),
                    );
                    let inner = Timestamp::from_nanos(days * 86_400_000_000_000);
                    return Ok(stamp(inner, StampUnit::S));
                }
                if arg.get_type().name()?.to_str()? == "datetime64" {
                    let nanos =
                        numpy_temporal_nanos(&arg, "datetime64[ns]")?.unwrap_or(Timestamp::NAT);
                    let unit = py
                        .import("numpy")?
                        .call_method1("datetime_data", (arg.getattr("dtype")?,))?
                        .get_item(0)?
                        .extract::<String>()?;
                    return Ok(stamp(
                        Timestamp::from_nanos(nanos),
                        StampUnit::of_unit(&unit),
                    ));
                }
                if let Ok(s) = arg.extract::<String>() {
                    if s == "now" {
                        return Ok(stamp(Timestamp::now(), StampUnit::Us));
                    }
                    if s == "today" {
                        return Ok(stamp(Timestamp::today(), StampUnit::Us));
                    }
                    if matches!(s.trim().to_ascii_lowercase().as_str(), "" | "nat" | "nan") {
                        return Ok(nat());
                    }
                    let unit = StampUnit::of_text(&s);
                    if let Ok(ts) = Timestamp::parse(&s) {
                        return Ok(stamp(ts, unit));
                    }
                    return parsed_timestamp(&s).map(|inner| stamp(inner, unit));
                }
                let unit = keyword("unit")?
                    .map(|u| u.extract::<String>())
                    .transpose()?;
                let number = !arg.is_instance_of::<pyo3::types::PyBool>();
                if number && let Ok(val) = arg.extract::<i64>() {
                    let nanos = epoch_nanos(val as f64, Some(val), unit.as_deref())?;
                    let unit = unit.as_deref().map_or(StampUnit::Ns, StampUnit::of_unit);
                    return Ok(stamp(Timestamp::from_nanos(nanos), unit));
                }
                if number && let Ok(val) = arg.extract::<f64>() {
                    if val.is_nan() {
                        return Ok(nat());
                    }
                    let nanos = epoch_nanos(val, None, unit.as_deref())?;
                    return Ok(stamp(Timestamp::from_nanos(nanos), StampUnit::Ns));
                }
            }
            if let Some(kw) = kwargs {
                if let Some(ts_val) = kw.get_item("ts_input")?.or(kw.get_item("value")?) {
                    let s = ts_val.extract::<String>()?;
                    let ts = match Timestamp::parse(&s) {
                        Ok(ts) => ts,
                        Err(_) => parsed_timestamp(&s)?,
                    };
                    return Ok(stamp(ts, StampUnit::of_text(&s)));
                }
                if let Some(y) = kw.get_item("year")? {
                    let mut fields = [y.extract::<i64>()?, 1, 1, 0, 0, 0, 0];
                    let names = ["month", "day", "hour", "minute", "second", "microsecond"];
                    for (field, name) in fields.iter_mut().skip(1).zip(names) {
                        if let Some(value) = kw.get_item(name)? {
                            *field = value.extract::<i64>()?;
                        }
                    }
                    let nanos = civil_nanos(py, fields, nanosecond)?;
                    return Ok(stamp(Timestamp::from_nanos(nanos), fields_unit));
                }
            }
            // Anything else was Timestamp.now() - no argument, a list, an
            // unknown type - where pandas raises (fvsao.35).
            match args.iter().next() {
                Some(arg) => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "Cannot convert input [{}] of type {} to Timestamp",
                    arg.repr()?,
                    arg.get_type().repr()?
                ))),
                None => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "function missing required argument 'year' (pos 1)",
                )),
            }
        })()?;
        if naive.inner.is_nat() {
            return nat_object(py);
        }
        // A zone a text carried is named as pandas names it ('+09:00' is
        // 'UTC+09:00'; it kept the text's spelling).
        let naive = match naive.inner.tz.as_deref().map(fp_types::tz_canonical_name) {
            Some(Ok(canonical)) => PyTimestamp {
                inner: Timestamp {
                    nanos: naive.inner.nanos,
                    tz: Some(canonical),
                },
                unit: naive.unit,
            },
            _ => naive,
        };
        let stamp = match zone {
            None => naive,
            // A tz-aware input is converted to the zone, a naive one localized.
            Some(zone) if naive.inner.tz.is_some() => naive.converted(Some(zone.as_str()))?,
            Some(zone) => naive.localized(Some(zone.as_str()))?,
        };
        Ok(Py::new(py, stamp)?.into_any())
    }

    #[getter]
    fn value(&self) -> i64 {
        self.inner.value()
    }

    // The calendar and clock fields read the wall clock (see `wall`).
    #[getter]
    fn year(&self) -> Option<i64> {
        self.wall().year()
    }

    #[getter]
    fn month(&self) -> Option<i64> {
        self.wall().month()
    }

    #[getter]
    fn day(&self) -> Option<i64> {
        self.wall().day()
    }

    #[getter]
    fn hour(&self) -> Option<i64> {
        self.wall().hour()
    }

    #[getter]
    fn minute(&self) -> Option<i64> {
        self.wall().minute()
    }

    #[getter]
    fn second(&self) -> Option<i64> {
        self.wall().second()
    }

    #[getter]
    fn microsecond(&self) -> Option<i64> {
        self.wall().microsecond()
    }

    #[getter]
    fn nanosecond(&self) -> Option<i64> {
        self.wall().nanosecond()
    }

    #[getter]
    fn dayofweek(&self) -> Option<i64> {
        self.wall().dayofweek()
    }

    #[getter]
    fn day_of_week(&self) -> Option<i64> {
        self.wall().day_of_week()
    }

    /// pandas' `Timestamp.weekday()` is a method (Monday 0); it was a
    /// property, so the call raised "'int' object is not callable".
    fn weekday(&self) -> Option<i64> {
        self.wall().weekday()
    }

    /// Monday 1 .. Sunday 7.
    fn isoweekday(&self) -> Option<i64> {
        self.wall().day_of_week().map(|day| day + 1)
    }

    /// `datetime.date(...).isocalendar()`: (ISO year, week, weekday).
    fn isocalendar(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        Ok(self
            .date(py)?
            .bind(py)
            .call_method0("isocalendar")?
            .unbind())
    }

    /// The ISO week number, pandas' `week` / `weekofyear` (they were
    /// missing; br-frankenpandas-b9lc7).
    #[getter]
    fn week(&self, py: Python<'_>) -> PyResult<Option<i64>> {
        if self.civil_fields().is_none() {
            return Ok(None);
        }
        self.isocalendar(py)?
            .bind(py)
            .get_item(1)?
            .extract()
            .map(Some)
    }

    #[getter]
    fn weekofyear(&self, py: Python<'_>) -> PyResult<Option<i64>> {
        self.week(py)
    }

    /// The zone's UTC offset, `datetime.utcoffset()` (None when naive; it
    /// was missing, as were tzname and dst - br-frankenpandas-b9lc7).
    fn utcoffset(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.py_datetime(py)? {
            Some(dt) => Ok(dt.call_method0("utcoffset")?.unbind()),
            None => nat_object(py),
        }
    }

    /// The zone's abbreviation (`EST`), `datetime.tzname()`.
    fn tzname(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.py_datetime(py)? {
            Some(dt) => Ok(dt.call_method0("tzname")?.unbind()),
            None => nat_object(py),
        }
    }

    /// The zone's daylight-saving adjustment, `datetime.dst()`.
    fn dst(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.py_datetime(py)? {
            Some(dt) => Ok(dt.call_method0("dst")?.unbind()),
            None => nat_object(py),
        }
    }

    /// The calendar date as a `datetime.date`; NaT for NaT.
    fn date(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let Some((year, month, day, ..)) = self.civil_fields() else {
            return nat_object(py);
        };
        Ok(pyo3::types::PyDate::new(py, year, month, day)?
            .into_any()
            .unbind())
    }

    /// The wall-clock time as a `datetime.time` (microseconds; the
    /// nanoseconds are dropped, as pandas); NaT for NaT.
    fn time(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let Some((_, _, _, hour, minute, second, micro)) = self.civil_fields() else {
            return nat_object(py);
        };
        Ok(
            pyo3::types::PyTime::new(py, hour, minute, second, micro, None)?
                .into_any()
                .unbind(),
        )
    }

    /// The wall-clock time with the zone's tzinfo (`time()` for a naive
    /// Timestamp); NaT for NaT. It was missing.
    fn timetz(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.py_datetime(py)? {
            Some(dt) => Ok(dt.call_method0("timetz")?.unbind()),
            None => nat_object(py),
        }
    }

    /// A `datetime.datetime` - a tz-aware one in its zone (it dropped the
    /// zone) - warning as pandas when nonzero nanoseconds are dropped; NaT
    /// for NaT.
    #[pyo3(signature = (warn=true))]
    fn to_pydatetime(&self, py: Python<'_>, warn: bool) -> PyResult<Py<PyAny>> {
        if warn && self.civil_fields().is_some() && self.inner.nanos.rem_euclid(1_000) != 0 {
            PyErr::warn(
                py,
                &py.get_type::<pyo3::exceptions::PyUserWarning>(),
                c"Discarding nonzero nanoseconds in conversion.",
                1,
            )?;
        }
        match self.py_datetime(py)? {
            Some(dt) => Ok(dt.unbind()),
            None => nat_object(py),
        }
    }

    /// numpy's datetime64 of the instant in this Timestamp's unit (UTC for
    /// a tz-aware one, as numpy has no zones; it was always `[ns]`).
    fn to_datetime64(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let numpy = py.import("numpy")?;
        if self.inner.is_nat() {
            return Ok(numpy.call_method1("datetime64", ("NaT", "ns"))?.unbind());
        }
        let ticks = self.inner.nanos.div_euclid(self.unit.nanos());
        Ok(numpy
            .call_method1("datetime64", (ticks, self.unit.name()))?
            .unbind())
    }

    /// pandas' `asm8`, [`Self::to_datetime64`] (it was missing).
    #[getter]
    fn asm8(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.to_datetime64(py)
    }

    /// pandas' `to_numpy`, [`Self::to_datetime64`]; a dtype or copy is
    /// pandas' ValueError (it was missing).
    #[pyo3(signature = (dtype=None, copy=false))]
    fn to_numpy(
        &self,
        py: Python<'_>,
        dtype: Option<&Bound<'_, PyAny>>,
        copy: bool,
    ) -> PyResult<Py<PyAny>> {
        if dtype.is_some_and(|dtype| !dtype.is_none()) || copy {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Timestamp.to_numpy dtype and copy arguments are ignored.",
            ));
        }
        self.to_datetime64(py)
    }

    /// Python's `ctime` of the wall clock (it was missing).
    fn ctime(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.datetime_object(py)? {
            Some(dt) => Ok(dt.call_method0("ctime")?.unbind()),
            None => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "NaTType does not support ctime",
            )),
        }
    }

    /// pandas' `Timestamp.replace`: the given fields replaced, each checked
    /// by Python's datetime (pandas' own messages, "month must be in
    /// 1..12"); `nanosecond` replaces the sub-microsecond part. The fields
    /// are the wall clock; `tzinfo=` puts that wall clock in another zone
    /// (None: naive), as pandas (it was refused).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (year=None, month=None, day=None, hour=None, minute=None, second=None, microsecond=None, nanosecond=None, **kwargs))]
    fn replace(
        &self,
        py: Python<'_>,
        year: Option<i32>,
        month: Option<u8>,
        day: Option<u8>,
        hour: Option<u8>,
        minute: Option<u8>,
        second: Option<u8>,
        microsecond: Option<u32>,
        nanosecond: Option<i64>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Self> {
        // `tzinfo=None` removes the zone, so a given None differs from an
        // absent tzinfo; `fold` only disambiguates a repeated wall time.
        let mut zone = self.inner.tz.clone();
        for (key, value) in kwargs.into_iter().flat_map(|kwargs| kwargs.iter()) {
            match key.extract::<String>()?.as_str() {
                "tzinfo" if value.is_none() => zone = None,
                "tzinfo" => zone = Some(tz_name(&value)?),
                "fold" => {}
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                        "replace() got an unexpected keyword argument '{other}'"
                    )));
                }
            }
        }
        let Some((y, mo, d, h, mi, s, us)) = self.civil_fields() else {
            return Ok(self.clone());
        };
        let dt = PyDateTime::new(
            py,
            year.unwrap_or(y),
            month.unwrap_or(mo),
            day.unwrap_or(d),
            hour.unwrap_or(h),
            minute.unwrap_or(mi),
            second.unwrap_or(s),
            microsecond.unwrap_or(us),
            None,
        )?;
        let nanosecond = nanosecond.unwrap_or_else(|| self.inner.nanos.rem_euclid(1_000));
        if !(0..1_000).contains(&nanosecond) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "nanosecond must be in 0..999",
            ));
        }
        let wall = PyTimestamp {
            inner: Timestamp::from_nanos(py_datetime_nanos(&dt)? + nanosecond),
            unit: self.unit,
        };
        // A tz-aware Timestamp's fields are its wall clock; the result keeps
        // the zone (or takes tzinfo=).
        match &zone {
            Some(zone) => wall.localized(Some(zone)),
            None => Ok(wall),
        }
    }

    /// The Period of `freq` holding this instant.
    #[pyo3(signature = (freq=None))]
    fn to_period(&self, freq: Option<&str>) -> PyResult<PyPeriod> {
        let Some(freq) = freq else {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Must supply freq for datetime value",
            ));
        };
        let periods = DatetimeIndex::new(vec![self.wall().nanos])
            .to_period(freq)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        let inner = periods.values().first().cloned().ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>("to_period: no period")
        })?;
        Ok(PyPeriod { inner })
    }

    #[getter]
    fn is_month_start(&self) -> Option<bool> {
        Some(self.wall().day()? == 1)
    }

    #[getter]
    fn is_month_end(&self) -> Option<bool> {
        let wall = self.wall();
        Some(wall.day()? == wall.days_in_month()?)
    }

    #[getter]
    fn is_quarter_start(&self) -> Option<bool> {
        let wall = self.wall();
        Some(wall.day()? == 1 && wall.month()? % 3 == 1)
    }

    #[getter]
    fn is_quarter_end(&self) -> Option<bool> {
        Some(self.wall().month()? % 3 == 0 && self.is_month_end()?)
    }

    #[getter]
    fn is_year_start(&self) -> Option<bool> {
        let wall = self.wall();
        Some(wall.month()? == 1 && wall.day()? == 1)
    }

    #[getter]
    fn is_year_end(&self) -> Option<bool> {
        let wall = self.wall();
        Some(wall.month()? == 12 && wall.day()? == 31)
    }

    #[getter]
    fn dayofyear(&self) -> Option<i64> {
        self.wall().dayofyear()
    }

    #[getter]
    fn day_of_year(&self) -> Option<i64> {
        self.wall().day_of_year()
    }

    #[getter]
    fn quarter(&self) -> Option<i64> {
        self.wall().quarter()
    }

    #[getter]
    fn is_leap_year(&self) -> Option<bool> {
        self.wall().is_leap_year()
    }

    #[getter]
    fn days_in_month(&self) -> Option<i64> {
        self.wall().days_in_month()
    }

    #[getter]
    fn daysinmonth(&self) -> Option<i64> {
        self.wall().daysinmonth()
    }

    /// The zone as pandas' tzinfo object, localized to this instant (see
    /// [`instant_tzinfo`]; it was the name, a str); None when naive.
    #[getter]
    fn tz<'py>(&self, py: Python<'py>) -> PyResult<Option<Bound<'py, PyAny>>> {
        self.inner
            .tz
            .as_deref()
            .map(|name| instant_tzinfo(py, name, self.inner.nanos))
            .transpose()
    }

    /// datetime's name for [`Self::tz`] (it was missing).
    #[getter]
    fn tzinfo<'py>(&self, py: Python<'py>) -> PyResult<Option<Bound<'py, PyAny>>> {
        self.tz(py)
    }

    /// pandas' resolution (see [`StampUnit`]; it was always 'ns').
    #[getter]
    fn unit(&self) -> Option<&'static str> {
        (!self.inner.is_nat()).then(|| self.unit.name())
    }

    /// This Timestamp in `unit` ('s', 'ms', 'us', 'ns'): a finer instant is
    /// floored to it, as pandas' `as_unit` (it was missing); with
    /// `round_ok=False` a lossy one is pandas' ValueError.
    #[pyo3(signature = (unit, round_ok=true))]
    fn as_unit(&self, unit: &str, round_ok: bool) -> PyResult<Self> {
        let target = match unit {
            "s" | "ms" | "us" | "ns" => StampUnit::of_unit(unit),
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(
                    "Only resolutions 's', 'ms', 'us', 'ns' are supported.",
                ));
            }
        };
        let tick = target.nanos();
        let nanos = self.inner.nanos;
        let floored = nanos.div_euclid(tick) * tick;
        if floored != nanos && !round_ok {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Cannot losslessly convert units",
            ));
        }
        Ok(Self {
            inner: Timestamp {
                nanos: if self.inner.is_nat() { nanos } else { floored },
                tz: self.inner.tz.clone(),
            },
            unit: target,
        })
    }

    #[staticmethod]
    fn now() -> Self {
        PyTimestamp {
            inner: Timestamp::now(),
            unit: StampUnit::Us,
        }
    }

    #[staticmethod]
    fn utcnow() -> Self {
        PyTimestamp {
            inner: Timestamp::utcnow(),
            unit: StampUnit::Us,
        }
    }

    #[staticmethod]
    fn today() -> Self {
        PyTimestamp {
            inner: Timestamp::today(),
            unit: StampUnit::Us,
        }
    }

    #[classattr]
    fn max() -> Self {
        PyTimestamp {
            inner: Timestamp::from_nanos(i64::MAX),
            unit: StampUnit::Ns,
        }
    }

    #[classattr]
    fn min() -> Self {
        PyTimestamp {
            inner: Timestamp::from_nanos(i64::MIN + 1),
            unit: StampUnit::Ns,
        }
    }

    /// The wall clock, with a tz-aware Timestamp's offset ('+09:00').
    fn isoformat(&self) -> String {
        format!("{}{}", self.wall().isoformat(), self.offset_text(true))
    }

    /// Python's strftime on the wall clock; a tz-aware Timestamp's `%z` /
    /// `%Z` are its offset and abbreviation (they printed empty).
    fn strftime(&self, fmt: &str) -> String {
        self.inner.strftime(fmt)
    }

    /// pandas' `Timestamp.tz_localize(tz, ambiguous='raise',
    /// nonexistent='raise')` (it was missing): see [`Self::localized`]. The
    /// policies are pandas' for one value (see [`tz_localize_options`]; only
    /// 'raise' was supported); 'infer' and arrays are its ValueError, and a
    /// policy's NaT is pandas' NaT.
    #[pyo3(signature = (tz, ambiguous=None, nonexistent=None))]
    fn tz_localize(
        &self,
        py: Python<'_>,
        tz: Option<&Bound<'_, PyAny>>,
        ambiguous: Option<&Bound<'_, PyAny>>,
        nonexistent: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        use fp_frame::{TzAmbiguousPolicy, TzNonexistentPolicy};
        use fp_types::{AmbiguousTime, NonexistentTime};
        let options = tz_localize_options(ambiguous, nonexistent)?;
        let ambiguous = match options.ambiguous {
            TzAmbiguousPolicy::Raise => AmbiguousTime::Raise,
            TzAmbiguousPolicy::Earliest => AmbiguousTime::Earliest,
            TzAmbiguousPolicy::Latest => AmbiguousTime::Latest,
            TzAmbiguousPolicy::NaT => AmbiguousTime::NaT,
            TzAmbiguousPolicy::Infer | TzAmbiguousPolicy::Mask(_) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "'ambiguous' parameter must be one of: True, False, 'NaT', 'raise' (default)",
                ));
            }
        };
        let nonexistent = match options.nonexistent {
            TzNonexistentPolicy::Raise => NonexistentTime::Raise,
            TzNonexistentPolicy::NaT => NonexistentTime::NaT,
            TzNonexistentPolicy::ShiftForward => NonexistentTime::ShiftForward,
            TzNonexistentPolicy::ShiftBackward => NonexistentTime::ShiftBackward,
            TzNonexistentPolicy::ShiftBy(shift) => {
                NonexistentTime::Shift(shift.num_nanoseconds().unwrap_or(i64::MAX))
            }
        };
        let zone = tz.filter(|tz| !tz.is_none()).map(tz_name).transpose()?;
        let mut localized = self.localized_with(zone.as_deref(), ambiguous, nonexistent)?;
        if localized.inner.is_nat() && !self.inner.is_nat() {
            return nat_object(py);
        }
        // pandas' shift_backward steps ONE OF THE TIMESTAMP'S OWN UNITS back
        // from the gap - a second for Timestamp('2024-03-10 02:30'), where a
        // datetime64[ns] array steps a nanosecond.
        if nonexistent == NonexistentTime::ShiftBackward && !localized.inner.is_nat() {
            let forward =
                self.localized_with(zone.as_deref(), ambiguous, NonexistentTime::ShiftForward)?;
            if forward.inner.nanos == localized.inner.nanos + 1 {
                localized.inner.nanos = forward.inner.nanos - self.unit.nanos();
            }
        }
        localized.into_py_any(py)
    }

    /// pandas' `Timestamp.tz_convert(tz)` (it was missing): see
    /// [`Self::converted`].
    fn tz_convert(&self, tz: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let zone = tz.filter(|tz| !tz.is_none()).map(tz_name).transpose()?;
        self.converted(zone.as_deref())
    }

    fn day_name(&self) -> Option<&'static str> {
        match self.day_of_week()? {
            0 => Some("Monday"),
            1 => Some("Tuesday"),
            2 => Some("Wednesday"),
            3 => Some("Thursday"),
            4 => Some("Friday"),
            5 => Some("Saturday"),
            6 => Some("Sunday"),
            _ => None,
        }
    }

    fn month_name(&self) -> Option<&'static str> {
        match self.month()? {
            1 => Some("January"),
            2 => Some("February"),
            3 => Some("March"),
            4 => Some("April"),
            5 => Some("May"),
            6 => Some("June"),
            7 => Some("July"),
            8 => Some("August"),
            9 => Some("September"),
            10 => Some("October"),
            11 => Some("November"),
            12 => Some("December"),
            _ => None,
        }
    }

    fn timestamp(&self) -> PyResult<f64> {
        self.inner
            .timestamp()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))
    }

    // floor / ceil / round / normalize work on the wall clock; a tz-aware
    // result is that wall time back in its zone.
    fn floor(&self, freq: &str) -> PyResult<Self> {
        self.rounded(freq, Timestamp::floor_to)
    }

    fn ceil(&self, freq: &str) -> PyResult<Self> {
        self.rounded(freq, Timestamp::ceil_to)
    }

    fn round(&self, freq: &str) -> PyResult<Self> {
        self.rounded(freq, Timestamp::round_to)
    }

    fn normalize(&self) -> PyResult<Self> {
        self.on_wall(Timestamp::normalize)
    }

    /// pandas' repr: a tz-aware Timestamp shows its wall clock, its '+HHMM'
    /// offset and its zone.
    fn __repr__(&self) -> String {
        if self.inner.is_nat() {
            return "NaT".to_string();
        }
        let wall = self.wall().isoformat().replace('T', " ");
        match &self.inner.tz {
            Some(zone) => format!(
                "Timestamp('{wall}{}', tz='{zone}')",
                self.offset_text(false)
            ),
            None => format!("Timestamp('{wall}')"),
        }
    }

    fn __str__(&self) -> String {
        if self.inner.is_nat() {
            "NaT".to_string()
        } else {
            self.isoformat().replace('T', " ")
        }
    }

    /// pandas hashes a Timestamp without nanoseconds as the equal
    /// `datetime`, so either finds the other in a dict or set; a tz-aware
    /// one as its UTC instant, as Python hashes an aware datetime.
    fn __hash__(&self, py: Python<'_>) -> PyResult<isize> {
        let utc = PyTimestamp {
            inner: Timestamp::from_nanos(self.inner.nanos),
            unit: self.unit,
        };
        if self.inner.nanos.rem_euclid(1_000) == 0
            && let Some(dt) = utc.datetime_object(py)?
        {
            return dt.hash();
        }
        Ok(self.inner.nanos as isize)
    }

    /// Against a Timestamp, NaT, a date string, a `datetime` or a numpy
    /// datetime64. A `datetime.date` is unequal and unordered (pandas'
    /// TypeError); anything else is Python's NotImplemented, so == is False
    /// and ordering raises (it raised for == too).
    fn __richcmp__(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        op: pyo3::class::basic::CompareOp,
    ) -> PyResult<Py<PyAny>> {
        use pyo3::class::basic::CompareOp;
        let unequal = |op: CompareOp| -> PyResult<Py<PyAny>> {
            Ok(pyo3::types::PyBool::new(py, matches!(op, CompareOp::Ne))
                .to_owned()
                .into_any()
                .unbind())
        };
        let other_nanos = if let Ok(other_ts) = other.extract::<PyRef<'_, PyTimestamp>>() {
            other_ts.inner.nanos
        } else if other.is_instance_of::<PyNaTType>() {
            return unequal(op);
        } else if let Ok(dt) = other.cast::<PyDateTime>() {
            py_datetime_nanos(dt)?
        } else if other.cast::<pyo3::types::PyDate>().is_ok() {
            if matches!(op, CompareOp::Eq | CompareOp::Ne) {
                return unequal(op);
            }
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Cannot compare Timestamp with datetime.date. Use ts == pd.Timestamp(date) or ts.date() == date instead.",
            ));
        } else if other.get_type().name()?.to_str()? == "datetime64" {
            numpy_temporal_nanos(other, "datetime64[ns]")?.unwrap_or(Timestamp::NAT)
        } else if let Ok(s) = other.extract::<String>() {
            if s.eq_ignore_ascii_case("nat") {
                return unequal(op);
            }
            Timestamp::parse(&s)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
                .nanos
        } else {
            return Ok(py.NotImplemented());
        };
        if self.inner.is_nat() || other_nanos == Timestamp::NAT {
            return unequal(op);
        }
        let result = match op {
            CompareOp::Eq => self.inner.nanos == other_nanos,
            CompareOp::Ne => self.inner.nanos != other_nanos,
            CompareOp::Lt => self.inner.nanos < other_nanos,
            CompareOp::Le => self.inner.nanos <= other_nanos,
            CompareOp::Gt => self.inner.nanos > other_nanos,
            CompareOp::Ge => self.inner.nanos >= other_nanos,
        };
        Ok(pyo3::types::PyBool::new(py, result)
            .to_owned()
            .into_any()
            .unbind())
    }

    /// `+` a Timedelta, a DateOffset or a `datetime.timedelta`; anything else
    /// is NotImplemented, so the other operand's reflected op runs (it
    /// raised before `Series.__radd__` could).
    fn __add__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(offset) = other.extract::<PyRef<'_, PyDateOffset>>() {
            return self.offset_shift(py, &offset, 1)?.into_py_any(py);
        }
        match duration_operand(other)? {
            Some(nanos) => self.shifted(py, nanos, duration_unit(other)?),
            None => Ok(py.NotImplemented()),
        }
    }

    /// `duration + Timestamp`.
    fn __radd__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        match duration_operand(other)? {
            Some(nanos) => self.shifted(py, nanos, duration_unit(other)?),
            None => Ok(py.NotImplemented()),
        }
    }

    /// `-` a duration or a DateOffset (a Timestamp), or a Timestamp /
    /// `datetime` (a Timedelta); anything else is NotImplemented. NaT on
    /// either side is NaT (a NaT duration moved the instant by i64::MIN).
    fn __sub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Some(nanos) = duration_operand(other)? {
            return self.shifted(py, duration_neg(nanos)?, duration_unit(other)?);
        }
        if let Ok(offset) = other.extract::<PyRef<'_, PyDateOffset>>() {
            self.offset_shift(py, &offset, -1)?.into_py_any(py)
        } else if let Ok(other_ts) = other.extract::<PyRef<'_, PyTimestamp>>() {
            // Tz-naive against tz-aware is pandas' TypeError (it subtracted
            // the wall clock from the instant).
            self.require_same_awareness(other_ts.inner.tz.as_deref(), other_ts.inner.is_nat())?;
            if self.inner.is_nat() || other_ts.inner.is_nat() {
                return duration_object(py, Timedelta::NAT);
            }
            let diff_nanos = self.inner.sub_timestamp(&other_ts.inner);
            PyTimedelta { nanos: diff_nanos }.into_py_any(py)
        } else if let Ok(dt) = other.cast::<PyDateTime>() {
            self.require_same_awareness(py_datetime_zone(dt)?.as_deref(), false)?;
            let other = Timestamp::from_nanos(py_datetime_nanos(dt)?);
            duration_object(py, self.inner.sub_timestamp(&other))
        } else {
            Ok(py.NotImplemented())
        }
    }

    /// `datetime - Timestamp`, a Timedelta.
    fn __rsub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        match other.cast::<PyDateTime>() {
            Ok(dt) => {
                self.require_same_awareness(py_datetime_zone(dt)?.as_deref(), false)?;
                let other = Timestamp::from_nanos(py_datetime_nanos(dt)?);
                PyTimedelta {
                    nanos: other.sub_timestamp(&self.inner),
                }
                .into_py_any(py)
            }
            Err(_) => Ok(py.NotImplemented()),
        }
    }
}

fn convert_period_freq(p: Period, target_freq: &str, how: &str) -> PyResult<Period> {
    if p.ordinal == i64::MIN {
        return Ok(p);
    }
    let pidx = fp_index::PeriodIndex::new(vec![p]);
    let res = pidx
        .asfreq_with_how(target_freq, how)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
    Ok(res.values().first().copied().unwrap_or(p))
}

/// A Period from its text, as pandas' `Period(text, freq)` reads it: period
/// text ('2024Q1', '2024-01', '2024-12-30') converted to `freq` at its
/// start, else - with a `freq` - the period of the instant the text names
/// ('2024-01-01 22:00' at 'h', which raised "cannot parse").
fn period_from_text(text: &str, freq: Option<&str>) -> PyResult<Period> {
    let unreadable = |err: String| PyErr::new::<pyo3::exceptions::PyValueError, _>(err);
    match (Period::parse(text), freq) {
        (Ok(period), Some(freq)) => match (period.freq, PeriodFreq::parse(freq)) {
            // A quarter label names the fiscal quarter of an anchored
            // frequency (pandas' quarter_to_myear): Period('2024Q1', 'Q-JAN')
            // is fiscal 2024Q1, starting 2023-02 (it read the calendar
            // quarter and became 2024Q4).
            (PeriodFreq::QUARTERLY, Some(target @ PeriodFreq::Quarterly(_))) => {
                Ok(Period::new(period.ordinal, target))
            }
            _ => convert_period_freq(period, freq, "start"),
        },
        (Ok(period), None) => Ok(period),
        (Err(err), None) => Err(unreadable(err.to_string())),
        (Err(err), Some(freq)) => {
            let target = PeriodFreq::parse(freq)
                .ok_or_else(|| unreadable(format!("unsupported frequency '{freq}'")))?;
            let instant = parsed_timestamp(text).map_err(|_| unreadable(err.to_string()))?;
            fp_index::datetime_nanos_to_period(instant.nanos, target).map_err(index_error_to_py)
        }
    }
}

/// Period representation (pandas `pd.Period`).
#[pyclass(name = "Period", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyPeriod {
    pub(crate) inner: Period,
}

impl PyPeriod {
    /// The period's first instant, pandas' `start_time` (a week, a business
    /// day and the freqs finer than a day were read as days).
    fn start_nanos(&self) -> Option<i64> {
        if self.inner.is_nat() {
            return None;
        }
        fp_index::period_start_nanos(self.inner).ok()
    }

    /// The period's last instant, pandas' `end_time`: a business day's own
    /// day's last nanosecond, any other the one before the next period.
    fn end_nanos(&self) -> Option<i64> {
        if self.inner.freq == PeriodFreq::Business {
            return self.start_nanos()?.checked_add(86_399_999_999_999);
        }
        if self.inner.is_nat() {
            return None;
        }
        fp_index::period_start_nanos(self.inner.shift(1))
            .ok()?
            .checked_sub(1)
    }

    /// The instant pandas reads the period's fields at (get_date_info): a
    /// period of a day or longer its last day at midnight (2024Q1's month is
    /// 3 and its day 31), a business day or a finer period its start
    /// (br-frankenpandas-3x4e7).
    fn field_stamp(&self) -> Option<Timestamp> {
        let nanos = match self.inner.freq {
            PeriodFreq::Business
            | PeriodFreq::Hourly
            | PeriodFreq::Minutely
            | PeriodFreq::Secondly
            | PeriodFreq::Milliseconds
            | PeriodFreq::Microseconds
            | PeriodFreq::Nanoseconds => self.start_nanos()?,
            _ => {
                let last = self.end_nanos()?;
                last - last.rem_euclid(86_400_000_000_000)
            }
        };
        Some(Timestamp::from_nanos(nanos))
    }

    fn stamp(nanos: Option<i64>) -> PyTimestamp {
        PyTimestamp {
            inner: nanos.map_or_else(Timestamp::nat, Timestamp::from_nanos),
            unit: StampUnit::Ns,
        }
    }
}

/// The offset `n` periods of `freq` span, as pandas' Period - Period gives
/// it (`<3 * MonthEnds>`; it was the int 3; br-frankenpandas-3x4e7).
fn period_freq_offset(freq: PeriodFreq, n: i64) -> PyResult<PyDateOffset> {
    // An anchored frequency's offset carries its anchor (<2 * YearEnds:
    // month=6> for Y-JUN, QuarterEnd startingMonth=1 for Q-JAN).
    Ok(match freq {
        PeriodFreq::Annual(month) => offset_year_end(n, false, i64::from(month))?,
        PeriodFreq::Quarterly(month) => offset_quarter_end(n, false, i64::from(month))?,
        PeriodFreq::Monthly => offset_month_end(n, false),
        PeriodFreq::Weekly(day) => offset_week(n, false, Some(i64::from(day)))?,
        PeriodFreq::Daily => offset_day(n),
        PeriodFreq::Business => offset_business_day(n, false),
        PeriodFreq::Hourly => offset_hour(n),
        PeriodFreq::Minutely => offset_minute(n),
        PeriodFreq::Secondly => offset_second(n),
        PeriodFreq::Milliseconds => offset_milli(n),
        PeriodFreq::Microseconds => offset_micro(n),
        PeriodFreq::Nanoseconds => offset_nano(n),
        _ => return Err(not_implemented("Period - Period at this freq")),
    })
}

#[pymethods]
impl PyPeriod {
    /// Pickles (and deep-copies) as `Period(str(self), freq=freqstr)`
    /// ([`restore`]; it could not be pickled, br-frankenpandas-uch5o).
    fn __reduce__<'py>(
        slf: &Bound<'py, Self>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let py = slf.py();
        let payload = constructor_payload(
            py,
            vec![slf.str()?.into_any()],
            &[("freq", slf.getattr("freqstr")?)],
        )?;
        restore_call(py, "Period", payload)
    }

    #[new]
    #[pyo3(signature = (*args, **kwargs))]
    fn new(args: &Bound<'_, PyTuple>, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<Self> {
        let mut value_arg: Option<Bound<'_, PyAny>> = args.get_item(0).ok();
        let mut freq_arg: Option<String> = args
            .get_item(1)
            .ok()
            .and_then(|a1| a1.extract::<String>().ok());

        if let Some(kw) = kwargs {
            if value_arg.is_none() {
                value_arg = kw.get_item("value")?;
            }
            if freq_arg.is_none() {
                freq_arg = kw
                    .get_item("freq")?
                    .and_then(|f| f.extract::<String>().ok());
            }
            if value_arg.is_none() {
                let year_item = kw.get_item("year")?;
                if let Some(y) = year_item {
                    let year = y.extract::<i64>()?;
                    let freq_str = freq_arg.as_deref().unwrap_or("Y");
                    let parsed = PeriodFreq::parse(freq_str);
                    let inner = match freq_str.to_ascii_uppercase().as_str() {
                        // A fiscal year / quarter names the period itself:
                        // Period(year=2024, quarter=1, freq='Q-JAN') is
                        // 2024Q1 (pandas' quarter_to_myear).
                        _ if matches!(parsed, Some(PeriodFreq::Quarterly(_))) => {
                            let quarter = kw
                                .get_item("quarter")?
                                .map_or(Ok(1), |v| v.extract::<i64>())?;
                            let ord = (year - 1970) * 4 + quarter - 1;
                            Period::new(ord, parsed.unwrap_or(PeriodFreq::QUARTERLY))
                        }
                        "M" => {
                            let month = kw
                                .get_item("month")?
                                .map_or(Ok(1), |v| v.extract::<i64>())?;
                            let ord = (year - 1970) * 12 + month - 1;
                            Period::new(ord, PeriodFreq::Monthly)
                        }
                        "D" => {
                            let month = kw
                                .get_item("month")?
                                .map_or(Ok(1), |v| v.extract::<i64>())?;
                            let day = kw.get_item("day")?.map_or(Ok(1), |v| v.extract::<i64>())?;
                            let ord = days_from_ymd(year, month, day);
                            Period::new(ord, PeriodFreq::Daily)
                        }
                        _ => {
                            let ord = year - 1970;
                            let annual = match parsed {
                                Some(freq @ PeriodFreq::Annual(_)) => freq,
                                _ => PeriodFreq::ANNUAL,
                            };
                            Period::new(ord, annual)
                        }
                    };
                    return Ok(PyPeriod { inner });
                }
            }
        }

        if let Some(val) = value_arg {
            if let Ok(p) = val.extract::<PyRef<'_, PyPeriod>>() {
                let mut inner = p.inner;
                if let Some(target_freq) = freq_arg.as_deref() {
                    inner = convert_period_freq(inner, target_freq, "start")?;
                }
                return Ok(PyPeriod { inner });
            }
            if let Ok(yr) = val.extract::<i64>() {
                let mut p = Period::new(yr - 1970, PeriodFreq::ANNUAL);
                if let Some(target_freq) = freq_arg.as_deref() {
                    p = convert_period_freq(p, target_freq, "start")?;
                }
                return Ok(PyPeriod { inner: p });
            }
            if let Ok(s) = val.extract::<String>() {
                let inner = period_from_text(&s, freq_arg.as_deref())?;
                return Ok(PyPeriod { inner });
            }
        }

        Ok(PyPeriod {
            inner: Period::new(0, PeriodFreq::ANNUAL),
        })
    }

    #[getter]
    fn ordinal(&self) -> i64 {
        self.inner.ordinal()
    }

    #[getter]
    fn freqstr(&self) -> &'static str {
        self.inner.freqstr()
    }

    /// pandas' `freq`: the period's offset (`<QuarterEnd: startingMonth=1>`
    /// for Q-JAN, `<Week: weekday=3>` for W-THU) as `PeriodIndex.freq` gives
    /// it; it was the alias text.
    #[getter]
    fn freq(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let offset = fp_index::canonical_freq(self.inner.freqstr())
            .map(|freqstr| offset_for_freqstr(&freqstr))
            .transpose()?
            .flatten();
        match offset {
            Some(offset) => offset.into_py_any(py),
            None => self.inner.freqstr().into_py_any(py),
        }
    }

    // The date and time fields, read where pandas reads them (see
    // `field_stamp`; week, business-day and sub-daily periods had none, a
    // quarter's weekday was its first day's, and days_in_month, dayofyear,
    // hour, minute, second, qyear, week, weekday, is_leap_year were missing;
    // br-frankenpandas-3x4e7).
    #[getter]
    fn year(&self) -> Option<i64> {
        self.field_stamp()?.year()
    }

    #[getter]
    fn month(&self) -> Option<i64> {
        self.field_stamp()?.month()
    }

    #[getter]
    fn day(&self) -> Option<i64> {
        self.field_stamp()?.day()
    }

    #[getter]
    fn hour(&self) -> Option<i64> {
        self.field_stamp()?.hour()
    }

    #[getter]
    fn minute(&self) -> Option<i64> {
        self.field_stamp()?.minute()
    }

    #[getter]
    fn second(&self) -> Option<i64> {
        self.field_stamp()?.second()
    }

    #[getter]
    fn quarter(&self) -> Option<i64> {
        self.field_stamp()?.quarter()
    }

    /// The fiscal year of the quarter (a Q-DEC year is the calendar one).
    #[getter]
    fn qyear(&self) -> Option<i64> {
        self.year()
    }

    #[getter]
    fn day_of_week(&self) -> Option<i64> {
        self.field_stamp()?.dayofweek()
    }

    #[getter]
    fn dayofweek(&self) -> Option<i64> {
        self.day_of_week()
    }

    #[getter]
    fn weekday(&self) -> Option<i64> {
        self.day_of_week()
    }

    #[getter]
    fn day_of_year(&self) -> Option<i64> {
        self.field_stamp()?.dayofyear()
    }

    #[getter]
    fn dayofyear(&self) -> Option<i64> {
        self.day_of_year()
    }

    #[getter]
    fn week(&self) -> Option<i64> {
        self.field_stamp()?.week()
    }

    #[getter]
    fn weekofyear(&self) -> Option<i64> {
        self.week()
    }

    #[getter]
    fn days_in_month(&self) -> Option<i64> {
        self.field_stamp()?.days_in_month()
    }

    #[getter]
    fn daysinmonth(&self) -> Option<i64> {
        self.days_in_month()
    }

    #[getter]
    fn is_leap_year(&self) -> Option<bool> {
        self.field_stamp()?.is_leap_year()
    }

    /// pandas' `Period.strftime`: Python's directives read at the period's
    /// fields, and pandas' own - %q the quarter, %F the fiscal year, %f its
    /// last two digits, %l / %u / %n the milli-, micro- and nanoseconds (it
    /// was missing).
    fn strftime(&self, fmt: &str) -> String {
        let Some(stamp) = self.field_stamp() else {
            return "NaT".to_owned();
        };
        let within = stamp.value().rem_euclid(1_000_000_000);
        let year = stamp.year().unwrap_or_default();
        let mut own = String::with_capacity(fmt.len());
        let mut chars = fmt.chars();
        while let Some(c) = chars.next() {
            if c != '%' {
                own.push(c);
                continue;
            }
            match chars.next() {
                Some('q') => own.push_str(&stamp.quarter().unwrap_or_default().to_string()),
                Some('F') => own.push_str(&year.to_string()),
                Some('f') => own.push_str(&format!("{:02}", year.rem_euclid(100))),
                Some('l') => own.push_str(&format!("{:03}", within / 1_000_000)),
                Some('u') => own.push_str(&format!("{:06}", within / 1_000)),
                Some('n') => own.push_str(&format!("{within:09}")),
                Some(other) => {
                    own.push('%');
                    own.push(other);
                }
                None => own.push('%'),
            }
        }
        stamp.strftime(&own)
    }

    #[getter]
    fn start_time(&self) -> PyTimestamp {
        Self::stamp(self.start_nanos())
    }

    #[getter]
    fn end_time(&self) -> PyTimestamp {
        Self::stamp(self.end_nanos())
    }

    #[pyo3(signature = (freq, how="end"))]
    fn asfreq(&self, freq: &str, how: &str) -> PyResult<Self> {
        let p = convert_period_freq(self.inner, freq, how)?;
        Ok(Self { inner: p })
    }

    fn to_timestamp(&self) -> PyTimestamp {
        self.start_time()
    }

    fn __repr__(&self) -> String {
        format!(
            "Period('{}', '{}')",
            self.inner.calendar_string(),
            self.inner.freqstr()
        )
    }

    fn __str__(&self) -> String {
        self.inner.calendar_string()
    }

    fn __hash__(&self) -> isize {
        self.inner.ordinal as isize
    }

    fn __richcmp__(
        &self,
        other: &Bound<'_, PyAny>,
        op: pyo3::class::basic::CompareOp,
    ) -> PyResult<bool> {
        if let Ok(other_p) = other.extract::<PyRef<'_, PyPeriod>>() {
            if self.inner.ordinal == i64::MIN || other_p.inner.ordinal == i64::MIN {
                match op {
                    pyo3::class::basic::CompareOp::Eq => Ok(false),
                    pyo3::class::basic::CompareOp::Ne => Ok(true),
                    _ => Ok(false),
                }
            } else if self.inner.freq != other_p.inner.freq {
                match op {
                    pyo3::class::basic::CompareOp::Eq => Ok(false),
                    pyo3::class::basic::CompareOp::Ne => Ok(true),
                    _ => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Cannot compare Periods with different frequencies",
                    )),
                }
            } else {
                Ok(match op {
                    pyo3::class::basic::CompareOp::Eq => {
                        self.inner.ordinal == other_p.inner.ordinal
                    }
                    pyo3::class::basic::CompareOp::Ne => {
                        self.inner.ordinal != other_p.inner.ordinal
                    }
                    pyo3::class::basic::CompareOp::Lt => self.inner.ordinal < other_p.inner.ordinal,
                    pyo3::class::basic::CompareOp::Le => {
                        self.inner.ordinal <= other_p.inner.ordinal
                    }
                    pyo3::class::basic::CompareOp::Gt => self.inner.ordinal > other_p.inner.ordinal,
                    pyo3::class::basic::CompareOp::Ge => {
                        self.inner.ordinal >= other_p.inner.ordinal
                    }
                })
            }
        } else {
            match op {
                pyo3::class::basic::CompareOp::Eq => Ok(false),
                pyo3::class::basic::CompareOp::Ne => Ok(true),
                _ => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "Cannot compare Period with non-Period",
                )),
            }
        }
    }

    fn __add__(&self, other: i64) -> PyPeriod {
        PyPeriod {
            inner: self.inner.shift(other),
        }
    }

    fn __sub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(i) = other.extract::<i64>() {
            PyPeriod {
                inner: self.inner.shift(-i),
            }
            .into_py_any(py)
        } else if let Ok(other_p) = other.extract::<PyRef<'_, PyPeriod>>() {
            if let Some(diff) = self.inner.diff(&other_p.inner) {
                period_freq_offset(self.inner.freq, diff)?.into_py_any(py)
            } else {
                Err(IncompatibleFrequency::new_err(format!(
                    "Input has different freq={} from Period(freq={})",
                    other_p.inner.freqstr(),
                    self.inner.freqstr()
                )))
            }
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Can only subtract int or Period from Period",
            ))
        }
    }
}

/// Nanoseconds since the epoch of a `datetime.datetime`, as pandas reads one
/// into a datetime64[ns] column: a naive one's wall clock, a tz-aware one's
/// UTC instant (its wall clock less `utcoffset()`; its zone is
/// [`py_datetime_zone`]). A tz-aware one was refused.
fn py_datetime_nanos(dt: &Bound<'_, PyDateTime>) -> PyResult<i64> {
    // Outside the nanosecond range (years ~1677-2262) is pandas'
    // OutOfBoundsDatetime (the arithmetic overflowed: a panic, or a wrapped
    // instant in a release build).
    let out_of_bounds = || {
        OutOfBoundsDatetime::new_err(format!(
            "Out of bounds nanosecond timestamp: {}-{:02}-{:02} {:02}:{:02}:{:02}",
            dt.get_year(),
            dt.get_month(),
            dt.get_day(),
            dt.get_hour(),
            dt.get_minute(),
            dt.get_second()
        ))
    };
    let days = days_from_ymd(
        i64::from(dt.get_year()),
        i64::from(dt.get_month()),
        i64::from(dt.get_day()),
    );
    let clock = i64::from(dt.get_hour()) * 3_600_000_000_000
        + i64::from(dt.get_minute()) * 60_000_000_000
        + i64::from(dt.get_second()) * 1_000_000_000
        + i64::from(dt.get_microsecond()) * 1_000;
    let wall = days
        .checked_mul(86_400_000_000_000)
        .and_then(|nanos| nanos.checked_add(clock))
        .ok_or_else(out_of_bounds)?;
    if dt.get_tzinfo().is_none() {
        return Ok(wall);
    }
    let offset = dt.call_method0("utcoffset")?;
    match offset.cast::<PyDelta>() {
        Ok(delta) => wall
            .checked_sub(py_delta_nanos(delta)?)
            .ok_or_else(out_of_bounds),
        Err(_) => Ok(wall),
    }
}

/// The zone of a tz-aware `datetime.datetime` as pandas names it: an IANA
/// key (`zoneinfo.ZoneInfo`, pytz), `datetime.timezone`'s own name ('UTC',
/// 'UTC+05:30'), else its fixed offset at that value; None for a naive one.
fn py_datetime_zone(dt: &Bound<'_, PyDateTime>) -> PyResult<Option<String>> {
    let Some(tzinfo) = dt.get_tzinfo() else {
        return Ok(None);
    };
    for attr in ["key", "zone"] {
        if let Ok(name) = tzinfo
            .getattr(attr)
            .and_then(|name| name.extract::<String>())
            && let Ok(name) = fp_types::tz_canonical_name(&name)
        {
            return Ok(Some(name));
        }
    }
    if let Ok(name) = fp_types::tz_canonical_name(&tzinfo.str()?.extract::<String>()?) {
        return Ok(Some(name));
    }
    let offset = dt.call_method0("utcoffset")?;
    let Ok(delta) = offset.cast::<PyDelta>() else {
        return Ok(None);
    };
    let seconds = py_delta_nanos(delta)? / 1_000_000_000;
    let sign = if seconds < 0 { '-' } else { '+' };
    let minutes = seconds.unsigned_abs() / 60;
    Ok(fp_types::tz_canonical_name(&format!("{sign}{:02}:{:02}", minutes / 60, minutes % 60)).ok())
}

/// The one time zone every datetime in a list or tuple carries - tz-aware
/// Timestamps or `datetime.datetime`s, NaT and None allowed - which the
/// column built from it keeps (pandas' datetime64[ns, tz]; it came back
/// naive). None when any value is naive or the zones differ (pandas makes
/// an object column).
fn sequence_zone(data: &Bound<'_, PyAny>) -> Option<String> {
    if !(data.is_instance_of::<PyList>() || data.is_instance_of::<PyTuple>()) {
        return None;
    }
    // Every value's zone must equal the first one's (owned once).
    let mut zone: Option<String> = None;
    let mut agrees = |this: &str| match &zone {
        Some(seen) => seen == this,
        None => {
            zone = Some(this.to_owned());
            true
        }
    };
    for item in data.try_iter().ok()? {
        let item = item.ok()?;
        let same = if item.is_none() || item.is_instance_of::<PyNaTType>() {
            continue;
        } else if let Ok(ts) = item.extract::<PyRef<'_, PyTimestamp>>() {
            if ts.inner.is_nat() {
                continue;
            }
            agrees(ts.inner.tz.as_deref()?)
        } else if let Ok(dt) = item.cast::<PyDateTime>() {
            agrees(&py_datetime_zone(dt).ok()??)
        } else {
            return None;
        };
        if !same {
            return None;
        }
    }
    zone
}

/// A list / tuple of datetimes in more than one zone (or aware beside
/// naive), as pandas holds it: an object column of each value as it is, an
/// aware one a host object keeping its zone. None for any other data. They
/// became naive UTC instants, blending UTC with naive wall times (fvsao.60).
fn mixed_zone_cells(py: Python<'_>, data: &Bound<'_, PyAny>) -> PyResult<Option<Column>> {
    let Some(aware) = mixed_zone_flags(data)? else {
        return Ok(None);
    };
    let cells = data
        .try_iter()?
        .zip(aware)
        .map(|(item, aware)| {
            let item = item?;
            if aware {
                Ok(Scalar::Object(fp_types::ObjectValue::Host(
                    fp_types::HostValue::new(PyHost(item.unbind())),
                )))
            } else {
                py_to_cell(py, &item)
            }
        })
        .collect::<PyResult<Vec<_>>>()?;
    Ok(Some(Column::from_object_values(cells)))
}

/// [`mixed_zone_cells`]' Index: pandas' object Index of each datetime as the
/// Python object it is (an aware one keeping its zone). None for any other
/// data. They became one naive datetime64 index, and a NaT among them
/// raised OutOfBoundsDatetime (ewrvf).
fn mixed_zone_object_index(data: &Bound<'_, PyAny>) -> PyResult<Option<PyIndex>> {
    if mixed_zone_flags(data)?.is_none() {
        return Ok(None);
    }
    host_object_index(data).map(Some)
}

/// An object Index of `items` as Python has them: each a host object, None
/// or NaT the missing label.
fn host_object_index(items: &Bound<'_, PyAny>) -> PyResult<PyIndex> {
    let labels = items
        .try_iter()?
        .map(|item| {
            let item = item?;
            if item.is_none() || item.is_instance_of::<PyNaTType>() {
                py_to_index_label(&item)
            } else {
                Ok(IndexLabel::Object(fp_types::ObjectValue::Host(
                    fp_types::HostValue::new(PyHost(item.unbind())),
                )))
            }
        })
        .collect::<PyResult<Vec<_>>>()?;
    Ok(PyIndex {
        inner: Index::new(labels),
    })
}

/// Each item's awareness when a list / tuple holds datetimes (NaT / None
/// among them) in more than one zone, aware beside naive counting as two.
/// None for any other data: not such a sequence, an item that is not a
/// datetime, one zone or none.
fn mixed_zone_flags(data: &Bound<'_, PyAny>) -> PyResult<Option<Vec<bool>>> {
    if !(data.is_instance_of::<PyList>() || data.is_instance_of::<PyTuple>()) {
        return Ok(None);
    }
    let mut zones: Vec<Option<String>> = Vec::new();
    let mut aware = Vec::new();
    for item in data.try_iter()? {
        let item = item?;
        let zone = if item.is_none() || item.is_instance_of::<PyNaTType>() {
            aware.push(false);
            continue;
        } else if let Ok(ts) = item.extract::<PyRef<'_, PyTimestamp>>() {
            if ts.inner.is_nat() {
                aware.push(false);
                continue;
            }
            ts.inner.tz.clone()
        } else if let Ok(dt) = item.cast::<PyDateTime>() {
            py_datetime_zone(dt)?
        } else {
            return Ok(None);
        };
        aware.push(zone.is_some());
        if !zones.contains(&zone) {
            zones.push(zone);
        }
    }
    Ok((zones.len() >= 2).then_some(aware))
}

/// Whether `item` is a datetime in a zone: a Timestamp or a
/// `datetime.datetime` with one.
fn is_aware_datetime(item: &Bound<'_, PyAny>) -> PyResult<bool> {
    if let Ok(ts) = item.extract::<PyRef<'_, PyTimestamp>>() {
        return Ok(!ts.inner.is_nat() && ts.inner.tz.is_some());
    }
    match item.cast::<PyDateTime>() {
        Ok(dt) => Ok(py_datetime_zone(dt)?.is_some()),
        Err(_) => Ok(false),
    }
}

/// `series` with the zone its source list carried (see [`sequence_zone`]):
/// a naive datetime column's instants shown in it.
fn with_sequence_zone(series: Series, data: Option<&Bound<'_, PyAny>>) -> PyResult<Series> {
    match (data.and_then(sequence_zone), series.dtype()) {
        (Some(zone), DType::Datetime64 { tz: None }) => {
            let column = series.column().with_dtype(DType::datetime64_tz(zone));
            Series::new(series.name(), series.index().clone(), column).map_err(frame_error_to_py)
        }
        _ => Ok(series),
    }
}

/// Nanoseconds of a `datetime.timedelta`.
fn py_delta_nanos(delta: &Bound<'_, PyDelta>) -> PyResult<i64> {
    // A span past ~292 years is pandas' OutOfBoundsTimedelta (the
    // arithmetic overflowed).
    (i64::from(delta.get_days()) * 86_400 + i64::from(delta.get_seconds()))
        .checked_mul(1_000_000_000)
        .and_then(|nanos| nanos.checked_add(i64::from(delta.get_microseconds()) * 1_000))
        .ok_or_else(|| {
            OutOfBoundsTimedelta::new_err(format!(
                "Cannot cast {} to unit='ns' without overflow.",
                delta
                    .str()
                    .map_or_else(|_| "the timedelta".to_owned(), |text| text.to_string())
            ))
        })
}

/// A numpy datetime64/timedelta64 scalar or array cast to `ns_dtype` and read
/// as int64 nanoseconds; `None` for NaT.
fn numpy_temporal_nanos(obj: &Bound<'_, PyAny>, ns_dtype: &str) -> PyResult<Option<i64>> {
    let nanos = obj
        .call_method1("astype", (ns_dtype,))?
        .call_method1("astype", ("int64",))?
        .extract::<i64>()?;
    Ok((nanos != i64::MIN).then_some(nanos))
}

/// Convert a Python value to a FrankenPandas Scalar.
#[allow(clippy::only_used_in_recursion)]
fn py_to_scalar(py: Python<'_>, obj: &Bound<'_, PyAny>) -> PyResult<Scalar> {
    // The everyday cells by exact type first, as the checks below read them:
    // a float or a str reached its extraction through a dozen failed ones,
    // raising and formatting a TypeError on the way (a million floats from a
    // list took ~0.3 s; br-frankenpandas-1ze1o). An int past int64 goes on.
    // A float subclass (numpy's float64 scalar) reads as its float, where the
    // checks below led it too (a list of them; br-frankenpandas-mf3tj).
    if obj.is_instance_of::<pyo3::types::PyFloat>() {
        let value = obj.extract::<f64>()?;
        return Ok(if value.is_nan() {
            Scalar::Null(fp_types::NullKind::NaN)
        } else {
            Scalar::Float64(value)
        });
    }
    if obj.is_exact_instance_of::<pyo3::types::PyString>() {
        return Ok(Scalar::Utf8(obj.extract::<String>()?));
    }
    if obj.is_exact_instance_of::<pyo3::types::PyBool>() {
        return Ok(Scalar::Bool(obj.extract::<bool>()?));
    }
    if obj.is_exact_instance_of::<pyo3::types::PyInt>()
        && let Ok(value) = obj.extract::<i64>()
    {
        return Ok(Scalar::Int64(value));
    }
    if obj.is_none() {
        return Ok(Scalar::Null(fp_types::NullKind::Null));
    }
    if obj.is_instance_of::<PyNAType>() {
        return Ok(Scalar::Null(fp_types::NullKind::Null));
    }
    if obj.is_instance_of::<PyNaTType>() {
        return Ok(Scalar::Null(fp_types::NullKind::NaT));
    }
    if let Ok(ts) = obj.extract::<PyRef<'_, PyTimestamp>>() {
        return Ok(Scalar::Datetime64(ts.inner.nanos));
    }
    if let Ok(td) = obj.extract::<PyRef<'_, PyTimedelta>>() {
        return Ok(Scalar::Timedelta64(td.nanos));
    }
    // An Interval cell (Series([Interval(0, 1), ...]) raised "Cannot convert
    // Interval to Scalar").
    if let Ok(interval) = obj.extract::<PyRef<'_, PyInterval>>() {
        return Ok(Scalar::Interval(interval.core()));
    }
    if let Ok(type_name) = obj.get_type().name() {
        if type_name == "Timedelta"
            && let Ok(val) = obj.getattr("value")
            && let Ok(ns) = val.extract::<i64>()
        {
            return Ok(Scalar::Timedelta64(ns));
        }
        if type_name == "Timestamp"
            && let Ok(val) = obj.getattr("value")
            && let Ok(ns) = val.extract::<i64>()
        {
            return Ok(Scalar::Datetime64(ns));
        }
        // numpy's datetime64/timedelta64 scalars converted as float
        // nanoseconds (or raised for a date unit); pandas reads them as
        // instants and durations (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.15).
        if type_name == "datetime64" {
            return Ok(numpy_temporal_nanos(obj, "datetime64[ns]")?
                .map_or(Scalar::Null(NullKind::NaT), Scalar::Datetime64));
        }
        if type_name == "timedelta64" {
            return Ok(numpy_temporal_nanos(obj, "timedelta64[ns]")?
                .map_or(Scalar::Null(NullKind::NaT), Scalar::Timedelta64));
        }
    }
    if let Ok(dt) = obj.cast::<PyDateTime>() {
        return py_datetime_nanos(dt).map(Scalar::Datetime64);
    }
    if let Ok(delta) = obj.cast::<PyDelta>() {
        return Ok(Scalar::Timedelta64(py_delta_nanos(delta)?));
    }
    if let Ok(p) = obj.extract::<PyRef<'_, PyPeriod>>() {
        return Ok(Scalar::Period(p.inner));
    }
    if let Ok(b) = obj.extract::<bool>() {
        return Ok(Scalar::Bool(b));
    }
    if let Ok(i) = obj.extract::<i64>() {
        return Ok(Scalar::Int64(i));
    }
    if let Ok(f) = obj.extract::<f64>() {
        if f.is_nan() {
            return Ok(Scalar::Null(fp_types::NullKind::NaN));
        }
        return Ok(Scalar::Float64(f));
    }
    if let Ok(s) = obj.extract::<String>() {
        return Ok(Scalar::Utf8(s));
    }
    if let Ok(item_fn) = obj.getattr("item")
        && let Ok(val) = item_fn.call0()
    {
        return py_to_scalar(py, &val);
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
        "Cannot convert {} to Scalar",
        obj.get_type().name()?
    )))
}

/// Convert a FrankenPandas Scalar to a Python object.
/// A cell of `column` as Python, as `tolist()` / iteration give it: a
/// tz-aware datetime column's instant is a Timestamp in that zone (it came
/// back naive, showing the UTC wall clock), and a nullable extension
/// column's missing cell is `pd.NA` (it was None).
fn cell_to_py(py: Python<'_>, column: &Column, value: &Scalar) -> PyResult<Py<PyAny>> {
    if let (DType::Datetime64 { tz: Some(zone) }, Scalar::Datetime64(nanos)) =
        (column.dtype(), value)
        && *nanos != Timestamp::NAT
    {
        return PyTimestamp {
            inner: Timestamp {
                nanos: *nanos,
                tz: Some(zone),
            },
            unit: StampUnit::Ns,
        }
        .into_py_any(py);
    }
    // A nullable extension column's missing value is pd.NA - pandas'
    // `string` dtype's too (fvsao.59; it read back None).
    if value.is_missing() && (is_nullable_extension(&column.dtype()) || column.is_pandas_string()) {
        return na_object(py);
    }
    scalar_to_py(py, value)
}

/// A cell as pandas' `to_dict` boxes it: a tz-aware instant a Timestamp in
/// its zone (it was the naive UTC wall clock; br-frankenpandas-wuize), any
/// other value its Python scalar - a masked or `string` column's missing
/// value None, as pandas' to_dict gives it.
fn to_dict_cell(py: Python<'_>, column: &Column, value: &Scalar) -> PyResult<Py<PyAny>> {
    if column.timezone().is_some() && !value.is_missing() {
        return cell_to_py(py, column, value);
    }
    scalar_to_py(py, value)
}

/// A row the core read from `frame` (iloc_row / loc_row), each tz-aware
/// column's instant a tz-aware Timestamp in its zone, as pandas' object
/// row holds it: the core's interleaved cell is the naive UTC instant
/// (df.iloc[0]['t'], iterrows, df.loc[k] gave 15:30 for 10:30-05:00;
/// br-frankenpandas-wuize). A row that kept a tz-aware dtype is as it is.
fn zoned_row(py: Python<'_>, frame: &DataFrame, row: Series) -> PyResult<Series> {
    let columns: Vec<Option<&Column>> = (0..frame.num_columns())
        .map(|position| frame.column_at(position))
        .collect();
    let zoned = |column: &Option<&Column>| column.is_some_and(|c| c.timezone().is_some());
    if row.len() != columns.len() || row.column().timezone().is_some() || !columns.iter().any(zoned)
    {
        return Ok(row);
    }
    // Every column in one zone: the row is that tz-aware dtype, as pandas'.
    let first_zone = columns
        .first()
        .copied()
        .flatten()
        .and_then(Column::timezone);
    if let Some(zone) = first_zone
        && columns
            .iter()
            .all(|column| column.and_then(Column::timezone) == Some(zone))
    {
        let column = Column::new(DType::datetime64_tz(zone), row.values().to_vec())
            .map_err(column_error_to_py)?;
        return Series::new(row.name(), row.index().clone(), column).map_err(frame_error_to_py);
    }
    let cells = row
        .values()
        .iter()
        .zip(&columns)
        .map(|(cell, column)| match column {
            Some(column) if column.timezone().is_some() && !cell.is_missing() => {
                Ok(Scalar::Object(fp_types::ObjectValue::Host(
                    fp_types::HostValue::new(PyHost(cell_to_py(py, column, cell)?)),
                )))
            }
            _ => Ok(cell.clone()),
        })
        .collect::<PyResult<Vec<Scalar>>>()?;
    Series::new(
        row.name(),
        row.index().clone(),
        Column::from_object_values(cells),
    )
    .map_err(frame_error_to_py)
}

/// An empty column of `source`'s pandas dtype: its width, `string` mark,
/// categories and zone kept.
fn empty_column_like(source: &Column) -> PyResult<Column> {
    let column = Column::new(source.dtype(), Vec::new())
        .map_err(column_error_to_py)?
        .keeping_dtype_of(source);
    Ok(match source.categorical() {
        Some(meta) => column.with_categorical(Some(meta.clone())),
        None => column,
    })
}

/// An empty Series' `map` / `apply` of a function, without calling it, in
/// pandas' dtype: the Series' own, a masked one's numpy dtype under `map`
/// (`numpy_masked`; Int64 -> int64, boolean -> bool) - the answers inferred
/// object from no values (br-frankenpandas-4ohjc). None when not empty.
fn empty_mapped(series: &Series, numpy_masked: bool) -> PyResult<Option<Series>> {
    if !series.is_empty() {
        return Ok(None);
    }
    let source = series.column();
    let column = match source.dtype() {
        DType::Int64Nullable if numpy_masked => Column::from_i64_values(Vec::new()),
        DType::Float64Nullable if numpy_masked => Column::from_f64_values(Vec::new()),
        DType::BoolNullable if numpy_masked => {
            Column::new(DType::Bool, Vec::new()).map_err(column_error_to_py)?
        }
        _ => empty_column_like(source)?,
    };
    Series::new(series.name(), series.index().clone(), column)
        .map(Some)
        .map_err(frame_error_to_py)
}

/// The column a groupby `op` over `source` gives when there are no groups,
/// in pandas' dtype for it - counts int64 (a masked source's Int64), sums
/// and products the source's (bools int64, boolean Int64), means and the
/// moments float64 for ints and bools (masked Float64, a datetime's spread a
/// timedelta), extremes and first / last the source's - where the core's
/// reductions inferred object from no values (br-frankenpandas-4ohjc). None
/// for an op this does not know or one pandas refuses over `source` (a
/// datetime sum, a timedelta product or variance), which keeps its path.
fn empty_group_reduction(source: &Column, op: &str) -> PyResult<Option<Column>> {
    let dtype = source.dtype();
    let empty = |dtype: DType| Column::new(dtype, Vec::new()).map_err(column_error_to_py);
    let own = || empty_column_like(source);
    let op = op.trim_end_matches("(min_count)");
    let column = match op {
        "size" | "count" if is_nullable_extension(&dtype) => empty(DType::Int64Nullable)?,
        "size" | "count" | "nunique" => Column::from_i64_values(Vec::new()),
        "sum" | "prod" => match dtype {
            DType::Bool => Column::from_i64_values(Vec::new()),
            DType::BoolNullable => empty(DType::Int64Nullable)?,
            DType::Datetime64 { .. } => return Ok(None),
            DType::Timedelta64 if op == "prod" => return Ok(None),
            _ => own()?,
        },
        "mean" | "median" | "std" | "var" | "sem" => match dtype {
            DType::Datetime64 { .. } | DType::Timedelta64 if op == "var" => return Ok(None),
            DType::Int64 | DType::Bool => Column::from_f64_values(Vec::new()),
            DType::Int64Nullable | DType::BoolNullable => empty(DType::Float64Nullable)?,
            DType::Datetime64 { .. } if matches!(op, "std" | "sem") => empty(DType::Timedelta64)?,
            DType::Utf8 if !source.is_pandas_string() && matches!(op, "std" | "sem") => {
                Column::from_f64_values(Vec::new())
            }
            _ => own()?,
        },
        "min" | "max" | "first" | "last" => own()?,
        _ => return Ok(None),
    };
    Ok(Some(column))
}

/// A `string` column's groupby sums as pandas gives them: `string`, a group
/// holding no text the text '0' (pandas sums the objects - 0 for nothing -
/// and casts back; the core's object sums hold the int 0; ttzzq).
fn string_group_sums(column: &Column) -> Column {
    let values = column
        .values()
        .iter()
        .map(|value| match value {
            Scalar::Int64(0) => Scalar::Utf8("0".to_owned()),
            other => other.clone(),
        })
        .collect();
    Column::from_object_values(values).as_pandas_string()
}

/// A cell of `column` as pandas' `map` / `apply` hands it to a function:
/// a masked Int64 / Float64 column holding a missing value goes through
/// `to_numpy()`'s float64, so its numbers are floats and the gap NaN
/// (`float_gaps`; they were ints and pd.NA, `map(str)` '1' / '<NA>' where
/// pandas gives '1.0' / 'nan'; br-frankenpandas-l5jx6); any other as the
/// column holds it.
#[allow(clippy::cast_precision_loss)] // numpy's int64 -> float64
fn mapped_cell(
    py: Python<'_>,
    column: &Column,
    value: &Scalar,
    float_gaps: bool,
) -> PyResult<Py<PyAny>> {
    if float_gaps {
        if value.is_missing() {
            return f64::NAN.into_py_any(py);
        }
        if let Scalar::Int64(number) = value {
            return (*number as f64).into_py_any(py);
        }
    }
    cell_to_py(py, column, value)
}

/// Whether `map` / `apply` hand `column`'s cells over as numpy's float64
/// (see [`mapped_cell`]).
fn maps_through_float(column: &Column) -> bool {
    matches!(
        column.dtype(),
        DType::Int64Nullable | DType::Float64Nullable
    ) && column.has_any_missing()
}

/// pandas' `fillna(value)` of a datetime / timedelta `series` with a value
/// not of its kind: an object Series of its instants / durations (in their
/// zone) and `value` where they were missing (at most `limit` of them) - 0
/// filled the epoch and 'x' raised (br-frankenpandas-l5jx6). None when the
/// value is of the kind (a datetime / timedelta, numpy's, a string parsing
/// as one) or missing, or the Series is neither, for the caller's own fill.
fn temporal_object_fill(
    py: Python<'_>,
    series: &Series,
    value: &Bound<'_, PyAny>,
    limit: Option<usize>,
) -> PyResult<Option<Series>> {
    let column = series.column();
    let datetime = matches!(column.dtype(), DType::Datetime64 { .. });
    // Nothing missing, nothing filled: the dtype stays (pandas' no-op).
    if !(datetime || column.dtype() == DType::Timedelta64)
        || !column.has_any_missing()
        || isna(py, value)?.bind(py).is_truthy()?
    {
        return Ok(None);
    }
    let (python_kind, numpy_kind, parser) = if datetime {
        ("datetime", "datetime64", "Timestamp")
    } else {
        ("timedelta", "timedelta64", "Timedelta")
    };
    let own_class = if datetime {
        value.extract::<PyRef<'_, PyTimestamp>>().is_ok()
    } else {
        value.extract::<PyRef<'_, PyTimedelta>>().is_ok()
    };
    let of_kind = own_class
        || value.is_instance(&py.import("datetime")?.getattr(python_kind)?)?
        || value.get_type().name()?.to_str()? == numpy_kind
        || (value.is_instance_of::<pyo3::types::PyString>()
            && py
                .import("frankenpandas")?
                .getattr(parser)?
                .call1((value,))
                .is_ok());
    if of_kind {
        return Ok(None);
    }
    let fill = py_to_cell(py, value)?;
    let mut left = limit.unwrap_or(usize::MAX);
    let cells = column
        .values()
        .iter()
        .map(|cell| {
            if cell.is_missing() {
                if left == 0 {
                    return Ok(Scalar::Null(NullKind::NaT));
                }
                left -= 1;
                return Ok(fill.clone());
            }
            if column.timezone().is_some() {
                return Ok(Scalar::Object(fp_types::ObjectValue::Host(
                    fp_types::HostValue::new(PyHost(cell_to_py(py, column, cell)?)),
                )));
            }
            Ok(cell.clone())
        })
        .collect::<PyResult<Vec<_>>>()?;
    Series::new(
        series.name(),
        series.index().clone(),
        Column::from_object_values(cells),
    )
    .map(Some)
    .map_err(frame_error_to_py)
}

/// Whether `dtype` is one of pandas' nullable extension dtypes (Int64 /
/// Float64 / boolean), whose missing value is `pd.NA`.
fn is_nullable_extension(dtype: &DType) -> bool {
    matches!(
        dtype,
        DType::Int64Nullable | DType::Float64Nullable | DType::BoolNullable
    )
}

/// A number as pandas returns it from a reduction or a scalar element: a
/// numpy scalar (np.int64 / np.float64 / np.bool_) - they came back as
/// Python int / float / bool; anything else as `scalar_to_py`.
fn numpy_scalar(py: Python<'_>, scalar: &Scalar) -> PyResult<Py<PyAny>> {
    numpy_scalar_of(py, scalar, None)
}

/// [`numpy_scalar`] of a column of `width`: an int32 column's element is
/// np.int32, a float32 column's np.float32 (fvsao.23).
fn numpy_scalar_of(
    py: Python<'_>,
    scalar: &Scalar,
    width: Option<NumericWidth>,
) -> PyResult<Py<PyAny>> {
    let (name, value) = match scalar {
        Scalar::Int64(v) => ("int64", v.into_py_any(py)?),
        Scalar::Float64(v) => ("float64", v.into_py_any(py)?),
        Scalar::Null(NullKind::NaN) => ("float64", f64::NAN.into_py_any(py)?),
        Scalar::Bool(b) => ("bool_", b.into_py_any(py)?),
        _ => return scalar_to_py(py, scalar),
    };
    let name = match (width, name) {
        (Some(width), "float64") if width.is_float() => width.name(false),
        (Some(width), "int64") if !width.is_float() => width.name(false),
        _ => name,
    };
    Ok(py.import("numpy")?.getattr(name)?.call1((value,))?.unbind())
}

/// A frame's cell in the column at `position` (negative from the end) as
/// an element (see [`element_to_py`]).
fn frame_element_at(
    py: Python<'_>,
    frame: &DataFrame,
    position: i64,
    value: &Scalar,
) -> PyResult<Py<PyAny>> {
    let columns = i64::try_from(frame.num_columns()).unwrap_or(i64::MAX);
    let position = if position < 0 {
        position + columns
    } else {
        position
    };
    match usize::try_from(position)
        .ok()
        .and_then(|position| frame.column_at(position))
    {
        Some(column) => element_to_py(py, column, value),
        None => scalar_to_py(py, value),
    }
}

/// A frame's cell in the column `name` as an element (see [`element_to_py`]).
fn frame_element_named(
    py: Python<'_>,
    frame: &DataFrame,
    name: &str,
    value: &Scalar,
) -> PyResult<Py<PyAny>> {
    match frame.column(name) {
        Some(column) => element_to_py(py, column, value),
        None => scalar_to_py(py, value),
    }
}

/// One element of `column` as pandas' `s[i]` / `.iloc` / `.at` /
/// `df.iat[r, c]` give it: a numeric column's value is a numpy scalar (a
/// missing float NaN too), a nullable column's missing value `pd.NA`, and
/// any other column's cell as `cell_to_py` (text, None, a Timestamp).
fn element_to_py(py: Python<'_>, column: &Column, value: &Scalar) -> PyResult<Py<PyAny>> {
    match column.dtype() {
        DType::Int64 | DType::Float64 if value.is_missing() => {
            numpy_scalar_of(py, &Scalar::Float64(f64::NAN), column.width())
        }
        DType::Int64 | DType::Float64 => numpy_scalar_of(py, value, column.width()),
        DType::Bool if !value.is_missing() => numpy_scalar(py, value),
        dtype if is_nullable_extension(&dtype) && !value.is_missing() => {
            numpy_scalar_of(py, value, column.width())
        }
        _ => cell_to_py(py, column, value),
    }
}

/// One value of `column` as iterating a Series (`for v in s`, `s.items()`)
/// yields it: a numpy dtype's value as the Python scalar `tolist()` gives,
/// a nullable extension dtype's as its element - np.int64 / np.float64 /
/// np.bool_, or `pd.NA` - since pandas iterates the masked array itself
/// (measured, pandas 2.2.3).
fn iterated_to_py(py: Python<'_>, column: &Column, value: &Scalar) -> PyResult<Py<PyAny>> {
    if is_nullable_extension(&column.dtype()) {
        element_to_py(py, column, value)
    } else {
        cell_to_py(py, column, value)
    }
}

/// A reduction of `series` as pandas returns it: a missing result of a
/// nullable extension dtype (Int64 / Float64 / boolean) is `pd.NA`, not NaN.
///
/// A number is a numpy scalar (np.int64 / np.float64 / np.bool_), as
/// pandas' reductions return (they were Python scalars; fvsao.25) - except a
/// NaN that pandas' nanops hands back as the Python float: `mean` of no
/// values, and `min` / `max` / `std` / `var` / `median` of an empty Series
/// (measured, pandas 2.2.3). `op` is the reduction's name.
/// Whether `column` is pandas' object dtype: text or mixed cells (not its
/// `string` dtype), or no dtype at all (an empty column's).
fn is_object_column(column: &Column) -> bool {
    matches!(column.dtype(), DType::Utf8 | DType::Null) && !column.is_pandas_string()
}

/// An object column's sum / prod as pandas answers it through Python's
/// arithmetic: `result` (its numbers' reduction) as a Python number, and
/// over no values the op's `identity` - NaN when `min_count` asks for more
/// (br-frankenpandas-qymo3).
fn object_total(
    py: Python<'_>,
    result: Py<PyAny>,
    count: usize,
    min_count: usize,
    identity: i64,
) -> PyResult<Py<PyAny>> {
    if count == 0 {
        return if min_count > 0 {
            f64::NAN.into_py_any(py)
        } else {
            identity.into_py_any(py)
        };
    }
    let result = result.into_bound(py);
    if result.hasattr("item")? {
        return Ok(result.call_method0("item")?.unbind());
    }
    Ok(result.unbind())
}

fn reduction_to_py(
    py: Python<'_>,
    series: &Series,
    op: &str,
    result: &Scalar,
) -> PyResult<Py<PyAny>> {
    if result.is_missing() && is_nullable_extension(&series.dtype()) {
        return na_object(py);
    }
    // pandas' masked reductions keep their kind: an Int64 prod is np.int64,
    // and so is an Int64 quantile when the column holds a missing value and
    // the quantile is a whole number (only then does pandas' masked quantile
    // cast back); a boolean min / max is np.bool_. They were np.float64
    // (br-frankenpandas-1t4kg).
    match (series.dtype(), result) {
        (DType::Int64Nullable, Scalar::Float64(value))
            if value.fract() == 0.0
                && value.abs() < 9.2e18
                && (op == "prod" || (op == "quantile" && series.column().has_any_missing())) =>
        {
            return numpy_scalar(py, &Scalar::Int64(*value as i64));
        }
        (DType::BoolNullable, Scalar::Float64(value)) if matches!(op, "min" | "max") => {
            return numpy_scalar(py, &Scalar::Bool(*value != 0.0));
        }
        _ => {}
    }
    // A tz-aware column's instant is a Timestamp in its zone (min / max /
    // median / quantile came back naive UTC).
    if let (DType::Datetime64 { tz: Some(zone) }, Scalar::Datetime64(nanos)) =
        (series.dtype(), result)
        && *nanos != Timestamp::NAT
    {
        return PyTimestamp {
            inner: Timestamp {
                nanos: *nanos,
                tz: Some(zone),
            },
            unit: StampUnit::Ns,
        }
        .into_py_any(py);
    }
    let nan = matches!(result, Scalar::Float64(v) if v.is_nan())
        || matches!(result, Scalar::Null(NullKind::NaN));
    if nan
        && (op == "mean"
            || (series.is_empty() && matches!(op, "min" | "max" | "std" | "var" | "median")))
    {
        return f64::NAN.into_py_any(py);
    }
    numpy_scalar_of(py, result, reduction_width(series.column().width(), op))
}

/// A skew / kurtosis as pandas' nanops returns it: np.float64, except
/// `np.nan` - a plain float - when there are too few values (fewer than 3
/// for skew, 4 for kurt; `enough` false). They were plain floats.
fn moment_to_py(py: Python<'_>, value: f64, enough: bool) -> PyResult<Py<PyAny>> {
    if enough {
        numpy_scalar(py, &Scalar::Float64(value))
    } else {
        f64::NAN.into_py_any(py)
    }
}

/// The numpy width of a reduction of a column of `width`, as pandas'
/// nanops give it (live pandas 2.2.3, fvsao.23): min / max / first / last
/// keep the column's dtype (an int32 max is np.int32); a float32 column's
/// sum, mean, median, std, var, prod and quantile are float32 too; an integer
/// column's sum and prod widen to int64, or uint64 when unsigned (a uint8
/// sum is np.uint64); anything else of an integer column is float64.
fn reduction_width(width: Option<NumericWidth>, op: &str) -> Option<NumericWidth> {
    let width = width?;
    match op {
        "min" | "max" | "first" | "last" => Some(width),
        "sum" | "mean" | "median" | "std" | "var" | "prod" | "quantile" if width.is_float() => {
            Some(width)
        }
        "sum" | "prod" if width.is_unsigned() => Some(NumericWidth::UInt64),
        _ => None,
    }
}

fn scalar_to_py(py: Python<'_>, scalar: &Scalar) -> PyResult<Py<PyAny>> {
    match scalar {
        Scalar::Null(NullKind::NaT) => nat_object(py),
        Scalar::Null(NullKind::NaN) => f64::NAN.into_py_any(py),
        Scalar::Null(NullKind::Null) => Ok(py.None()),
        Scalar::Bool(b) => b.into_py_any(py),
        Scalar::Int64(i) => i.into_py_any(py),
        Scalar::Float64(f) => f.into_py_any(py),
        Scalar::Utf8(s) => s.into_py_any(py),
        Scalar::Datetime64(ns) => {
            if *ns == Timestamp::NAT {
                nat_object(py)
            } else {
                PyTimestamp {
                    inner: Timestamp::from_nanos(*ns),
                    unit: StampUnit::Ns,
                }
                .into_py_any(py)
            }
        }
        Scalar::Timedelta64(ns) => {
            if *ns == Timedelta::NAT {
                nat_object(py)
            } else {
                PyTimedelta { nanos: *ns }.into_py_any(py)
            }
        }
        // A NaT period is pandas' NaT (it was Period('NaT', 'M');
        // fvsao.62).
        Scalar::Period(p) if p.is_nat() => nat_object(py),
        Scalar::Period(p) => PyPeriod { inner: *p }.into_py_any(py),
        // An Interval cell is an Interval (it came back None).
        Scalar::Interval(interval) => PyInterval::of(interval).into_py_any(py),
        // An object cell: a list cell is a Python list, a host cell the very
        // Python object it carries (fvsao.33).
        Scalar::Object(fp_types::ObjectValue::List(items)) => {
            let items = items
                .iter()
                .map(|item| scalar_to_py(py, item))
                .collect::<PyResult<Vec<_>>>()?;
            PyList::new(py, items)?.into_py_any(py)
        }
        Scalar::Object(fp_types::ObjectValue::Bytes(data)) => {
            pyo3::types::PyBytes::new(py, data).into_py_any(py)
        }
        Scalar::Object(fp_types::ObjectValue::Host(value)) => {
            match value.object().as_any().downcast_ref::<PyHost>() {
                Some(host) => Ok(host.0.clone_ref(py)),
                None => value.object().host_repr().into_py_any(py),
            }
        }
    }
}

/// A Python value as a cell of object data holds it (fvsao.33): a scalar as
/// [`py_to_scalar`] reads it, a list as a list cell (its items cells too),
/// and any other object - a tuple, dict, set, `datetime.date`, an array - as
/// itself. For DATA (a Series' values, a frame's cells, apply results) and
/// operands (a date to compare with or fill); an argument that must not be
/// a list refuses it itself (`fillna([1, 2])` raises as pandas does). They
/// raised "Cannot convert list to Scalar".
fn py_to_cell(py: Python<'_>, obj: &Bound<'_, PyAny>) -> PyResult<Scalar> {
    py_to_cell_with_ancestors(py, obj, &mut Vec::new())
}

const MAX_LIST_CELL_DEPTH: usize = 128;

/// List cells are copied recursively, so reject cycles by identity on the
/// active path and bound its depth. A shared acyclic sublist remains valid.
fn py_to_cell_with_ancestors<'py>(
    py: Python<'_>,
    obj: &Bound<'py, PyAny>,
    ancestors: &mut Vec<Bound<'py, PyAny>>,
) -> PyResult<Scalar> {
    if let Ok(list) = obj.cast::<PyList>() {
        if ancestors.iter().any(|ancestor| ancestor.is(obj)) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "cyclic list cells are not supported",
            ));
        }
        if ancestors.len() >= MAX_LIST_CELL_DEPTH {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "list cell nesting exceeds {MAX_LIST_CELL_DEPTH} levels"
            )));
        }
        ancestors.push(obj.clone());
        let items = list
            .iter()
            .map(|item| py_to_cell_with_ancestors(py, &item, ancestors))
            .collect::<PyResult<Vec<_>>>();
        // Restore the path before propagating a child conversion error.
        ancestors.pop();
        return Ok(Scalar::Object(fp_types::ObjectValue::list(items?)));
    }
    // bytes are a bytes cell the core reads (they were a host object, so
    // every kernel over them ran single-threaded under the GIL; 4qg5w.8).
    if let Ok(data) = obj.cast::<pyo3::types::PyBytes>() {
        return Ok(Scalar::Object(fp_types::ObjectValue::bytes(
            data.as_bytes().to_vec(),
        )));
    }
    // A numpy array is an object cell as it is, as pandas keeps it (a
    // one-element array became its float through numpy's deprecated
    // conversion; fvsao.69). A float, str, bool or int skips the check,
    // which built its type's name as a new str (30% of a Series of a
    // million strings; br-frankenpandas-1ze1o).
    let everyday = obj.is_instance_of::<pyo3::types::PyFloat>()
        || obj.is_exact_instance_of::<pyo3::types::PyString>()
        || obj.is_exact_instance_of::<pyo3::types::PyBool>()
        || obj.is_exact_instance_of::<pyo3::types::PyInt>();
    if !everyday && obj.get_type().name().is_ok_and(|name| name == "ndarray") {
        return Ok(Scalar::Object(fp_types::ObjectValue::Host(
            fp_types::HostValue::new(PyHost(obj.clone().unbind())),
        )));
    }
    match py_to_scalar(py, obj) {
        Ok(scalar) => Ok(scalar),
        Err(_) => Ok(Scalar::Object(fp_types::ObjectValue::Host(
            fp_types::HostValue::new(PyHost(obj.clone().unbind())),
        ))),
    }
}

/// pandas' min / max (`position: false`) or argmin / argmax over an object
/// column holding non-text cells (dates, a mix of ints and strings): numpy's
/// object reduction with Python's own comparisons, a missing cell standing
/// in as +inf (min) / -inf (max) under skipna - so a date beside a missing
/// value or a string beside an int is pandas' TypeError. The winning row and
/// cell; None when every cell is missing. fp-frame read such cells as NaN
/// (fvsao.67). A text-only column keeps fp-frame's path, as pandas' `string`
/// dtype (which the binding does not tell from object) answers.
fn object_extreme(
    py: Python<'_>,
    series: &Series,
    maximum: bool,
    position: bool,
    skipna: bool,
) -> PyResult<Option<(usize, Py<PyAny>)>> {
    let column = series.column();
    let fill = if maximum {
        f64::NEG_INFINITY
    } else {
        f64::INFINITY
    };
    let mut best: Option<(usize, Bound<'_, PyAny>)> = None;
    let mut any_present = false;
    for (row, value) in column.values().iter().enumerate() {
        let cell = if value.is_missing() && skipna {
            fill.into_bound_py_any(py)?
        } else {
            any_present |= !value.is_missing();
            cell_to_py(py, column, value)?.into_bound(py)
        };
        best = Some(match best {
            None => (row, cell),
            // numpy: minimum keeps the running value while it is <= the
            // next; argmin moves only on a strictly smaller one.
            Some((at, current)) => {
                let keep = match (maximum, position) {
                    (false, false) => current.le(&cell)?,
                    (true, false) => current.ge(&cell)?,
                    (false, true) => !cell.lt(&current)?,
                    (true, true) => !cell.gt(&current)?,
                };
                if keep { (at, current) } else { (row, cell) }
            }
        });
    }
    Ok(best
        .filter(|_| any_present)
        .map(|(row, cell)| (row, cell.unbind())))
}

/// `series` with each `datetime.date` / naive `datetime.datetime` object
/// cell as the instant it names (a date its midnight, as pandas' Timestamp
/// reads it) and every other cell as it is: how `to_datetime` and `to_json`
/// read a column of dates (they gave NaT / the date's text; fvsao.67). An
/// aware datetime stays an object.
fn object_instants(py: Python<'_>, series: &Series) -> PyResult<Series> {
    if !series.column().holds_non_text() {
        return Ok(series.clone());
    }
    let values = series
        .values()
        .iter()
        .map(|value| {
            if !matches!(value, Scalar::Object(fp_types::ObjectValue::Host(_))) {
                return Ok(value.clone());
            }
            let object = scalar_to_py(py, value)?;
            let object = object.bind(py);
            let naive = match object.cast::<PyDateTime>() {
                Ok(instant) => instant.get_tzinfo().is_none(),
                Err(_) => object.cast::<pyo3::types::PyDate>().is_ok(),
            };
            if !naive {
                return Ok(value.clone());
            }
            let stamp = py.get_type::<PyTimestamp>().call1((object,))?;
            py_to_scalar(py, &stamp)
        })
        .collect::<PyResult<Vec<_>>>()?;
    Series::new(
        series.name(),
        series.index().clone(),
        Column::from_object_values(values),
    )
    .map_err(frame_error_to_py)
}

/// `frame` with each column of dates as their instants, as `to_json` reads
/// them ([`json_instants`]).
fn frame_object_instants(py: Python<'_>, frame: &DataFrame, iso: bool) -> PyResult<DataFrame> {
    let mut out = frame.clone();
    for position in 0..frame.shape().1 {
        let Some(column) = frame.column_at(position) else {
            continue;
        };
        if !column.holds_non_text() {
            continue;
        }
        let series =
            Series::new("", frame.index().clone(), column.clone()).map_err(frame_error_to_py)?;
        let instants = json_instants(py, &series, iso)?;
        out = out
            .isetitem(position, instants.column().clone())
            .map_err(frame_error_to_py)?;
    }
    Ok(out)
}

/// [`object_instants`] as `to_json` reads a column: one of zoned datetimes
/// ([`zoned_cells`]) is their instants, which pandas writes as epoch
/// milliseconds - in UTC, ISO text ending "Z", when none is naive (each
/// Timestamp's own text was written; br-frankenpandas-an1xe). Naive beside
/// aware under date_format='iso' stay cells, which [`json_dates`] writes
/// each as its kind does.
fn json_instants(py: Python<'_>, series: &Series, iso: bool) -> PyResult<Series> {
    let Some(cells) = zoned_cells(py, series.column())? else {
        return object_instants(py, series);
    };
    let naive = cells.iter().any(|cell| matches!(cell, ZonedCell::Naive(_)));
    if naive && iso {
        return object_instants(py, series);
    }
    let column = if naive {
        Column::from_object_values(
            cells
                .iter()
                .map(|cell| match cell {
                    ZonedCell::Aware(nanos, _) | ZonedCell::Naive(nanos) => {
                        Scalar::Datetime64(*nanos)
                    }
                    ZonedCell::Missing => Scalar::Null(NullKind::NaT),
                })
                .collect(),
        )
    } else {
        zoned_to_datetime(&cells, true, false)?
    };
    Series::new(series.name(), series.index().clone(), column).map_err(frame_error_to_py)
}

/// A present cell of an object column of datetimes ([`zoned_cells`]): an
/// aware one's UTC nanoseconds and zone, a naive one's wall clock.
enum ZonedCell {
    Missing,
    Aware(i64, String),
    Naive(i64),
}

/// The cells of an object column of datetimes holding at least one aware
/// one - Timestamps each in its zone, as astype(object), a concat of pieces
/// in different zones and a list of zoned Timestamps hold them. None for
/// any other column (a present cell that is no datetime, or no aware one).
/// to_datetime, astype, to_json and isin read such a column through it
/// (they gave NaT, raised, wrote each Timestamp's text and matched nothing;
/// br-frankenpandas-an1xe).
fn zoned_cells(py: Python<'_>, column: &Column) -> PyResult<Option<Vec<ZonedCell>>> {
    if !column.holds_non_text() {
        return Ok(None);
    }
    let mut cells = Vec::with_capacity(column.len());
    for value in column.values() {
        let cell = match value {
            missing if missing.is_missing() => ZonedCell::Missing,
            Scalar::Datetime64(nanos) => ZonedCell::Naive(*nanos),
            Scalar::Object(fp_types::ObjectValue::Host(_)) => {
                let object = scalar_to_py(py, value)?;
                match zoned_cell(py, object.bind(py))? {
                    Some(cell) => cell,
                    None => return Ok(None),
                }
            }
            _ => return Ok(None),
        };
        cells.push(cell);
    }
    Ok(cells
        .iter()
        .any(|cell| matches!(cell, ZonedCell::Aware(..)))
        .then_some(cells))
}

/// A Timestamp, `datetime.datetime` or NaT as a [`ZonedCell`]; None for any
/// other object.
fn zoned_cell(py: Python<'_>, object: &Bound<'_, PyAny>) -> PyResult<Option<ZonedCell>> {
    if object.is_instance_of::<PyNaTType>() {
        return Ok(Some(ZonedCell::Missing));
    }
    let stamp = if object.is_instance_of::<PyTimestamp>() {
        object.clone()
    } else if object.cast::<PyDateTime>().is_ok() {
        py.get_type::<PyTimestamp>().call1((object,))?
    } else {
        return Ok(None);
    };
    let stamp = stamp.extract::<PyRef<'_, PyTimestamp>>()?;
    Ok(Some(match &stamp.inner.tz {
        _ if stamp.inner.nanos == Timestamp::NAT => ZonedCell::Missing,
        Some(zone) => ZonedCell::Aware(stamp.inner.nanos, zone.clone()),
        None => ZonedCell::Naive(stamp.inner.nanos),
    }))
}

/// pandas' `to_datetime` of [`zoned_cells`]: utc=True each instant in UTC (a
/// naive cell's wall clock read as UTC); otherwise the first present cell
/// decides - aware in a zone, a column in that zone; naive, a naive one -
/// and a cell in another zone or of the other kind is pandas' ValueError,
/// NaT under errors='coerce'.
fn zoned_to_datetime(cells: &[ZonedCell], utc: bool, coerce: bool) -> PyResult<Column> {
    let zone = if utc {
        Some("UTC")
    } else {
        match cells
            .iter()
            .find(|cell| !matches!(cell, ZonedCell::Missing))
        {
            Some(ZonedCell::Aware(_, zone)) => Some(zone.as_str()),
            _ => None,
        }
    };
    let mut values = Vec::with_capacity(cells.len());
    for (position, cell) in cells.iter().enumerate() {
        let nanos = match cell {
            ZonedCell::Missing => None,
            ZonedCell::Naive(nanos) if utc || zone.is_none() => Some(*nanos),
            ZonedCell::Aware(nanos, own) if utc || zone == Some(own.as_str()) => Some(*nanos),
            _ if coerce => None,
            ZonedCell::Naive(_) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Cannot mix tz-aware with tz-naive values, at position {position}"
                )));
            }
            ZonedCell::Aware(..) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Tz-aware datetime.datetime cannot be converted to datetime64 unless \
                     utc=True, at position {position}"
                )));
            }
        };
        values.push(nanos.map_or(Scalar::Null(NullKind::NaT), Scalar::Datetime64));
    }
    let dtype = zone.map_or_else(DType::datetime64_naive, DType::datetime64_tz);
    Column::new(dtype, values).map_err(column_error_to_py)
}

/// pandas' `astype` of [`zoned_cells`] to a datetime dtype: to one in a
/// zone, each aware instant in it and each naive wall clock localized to it;
/// to a naive one, pandas' ValueError. None when `column` holds no zoned
/// datetimes or `target` is no datetime dtype (the cast raised "cannot cast
/// scalar of dtype Utf8"; br-frankenpandas-an1xe).
fn zoned_astype(column: &Column, target: &DType) -> PyResult<Option<Column>> {
    if !target.is_datetime() {
        return Ok(None);
    }
    let Some(cells) = Python::attach(|py| zoned_cells(py, column))? else {
        return Ok(None);
    };
    let Some(zone) = target.timezone() else {
        let one_zone = cells
            .iter()
            .filter_map(|cell| match cell {
                ZonedCell::Aware(_, zone) => Some(Some(zone)),
                ZonedCell::Naive(_) => Some(None),
                ZonedCell::Missing => None,
            })
            .collect::<Vec<_>>()
            .windows(2)
            .all(|pair| pair[0] == pair[1]);
        if one_zone {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "cannot supply both a tz and a timezone-naive dtype (i.e. {})",
                pandas_dtype_name(target)
            )));
        }
        return zoned_to_datetime(&cells, false, false).map(Some);
    };
    // The naive wall clocks localized to the zone, as tz_localize does.
    let walls = cells
        .iter()
        .map(|cell| match cell {
            ZonedCell::Naive(nanos) => Scalar::Datetime64(*nanos),
            _ => Scalar::Null(NullKind::NaT),
        })
        .collect::<Vec<_>>();
    let walls = Column::new(DType::datetime64_naive(), walls).map_err(column_error_to_py)?;
    let localized = Series::new("", Index::default_range(cells.len()), walls)
        .and_then(|walls| walls.dt().tz_localize(Some(zone)))
        .map_err(frame_error_to_py)?;
    let values = cells
        .iter()
        .zip(localized.column().values())
        .map(|(cell, local)| match cell {
            ZonedCell::Aware(nanos, _) => Scalar::Datetime64(*nanos),
            ZonedCell::Naive(_) => local.clone(),
            ZonedCell::Missing => Scalar::Null(NullKind::NaT),
        })
        .collect::<Vec<_>>();
    Column::new(DType::datetime64_tz(zone), values)
        .map(Some)
        .map_err(column_error_to_py)
}

/// pandas' TypeError for a group key column holding an unhashable cell (a
/// list, a dict): grouping hashes the keys. A list column grouped into
/// nothing (fvsao.66).
fn refuse_unhashable_keys(py: Python<'_>, column: &Column) -> PyResult<()> {
    if column.dtype() != DType::Utf8 {
        return Ok(());
    }
    for value in column.values() {
        let Scalar::Object(object) = value else {
            continue;
        };
        let unhashable = match object {
            fp_types::ObjectValue::List(_) => Some("list".to_owned()),
            fp_types::ObjectValue::Bytes(_) => None,
            fp_types::ObjectValue::Host(host) => host
                .object()
                .as_any()
                .downcast_ref::<PyHost>()
                .map(|host| host.0.bind(py))
                .filter(|object| object.hash().is_err())
                .map(|object| {
                    object
                        .get_type()
                        .name()
                        .map_or_else(|_| "object".to_owned(), |name| name.to_string())
                }),
        };
        if let Some(kind) = unhashable {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "unhashable type: '{kind}'"
            )));
        }
    }
    Ok(())
}

/// pandas' `pprint_thing` of a value in a repr: a sequence as its items
/// pprinted one level deeper - `[1, 2]` for one that takes item assignment
/// (a list, an array), `{1}` for a set, else `(a, 1)` (a one-item tuple
/// `(a,)`), `, ...` past display.max_seq_items - and a dict as `{k: v}` with
/// its text quoted; `quote` quotes text (unescaped quotes, as pandas);
/// `escape` spells tabs and line breaks out; past display.pprint_nest_depth,
/// or for anything else, the value's `str`. An array cell printed numpy's
/// `['x' 'y']`, a tuple `('a', 1)`.
fn pandas_pprint(
    value: &Bound<'_, PyAny>,
    depth: usize,
    quote: bool,
    escape: bool,
) -> PyResult<String> {
    const NEST_DEPTH: usize = 3;
    const MAX_SEQ_ITEMS: usize = 100;
    let escaped = |text: String| {
        if escape {
            text.replace('\t', "\\t")
                .replace('\n', "\\n")
                .replace('\r', "\\r")
        } else {
            text
        }
    };
    if value.hasattr("__next__")? {
        return Ok(escaped(value.str()?.to_string()));
    }
    if depth < NEST_DEPTH {
        if let Ok(dict) = value.cast::<PyDict>() {
            let mut pairs = Vec::new();
            for (key, item) in dict.iter().take(MAX_SEQ_ITEMS) {
                pairs.push(format!(
                    "{}: {}",
                    pandas_pprint(&key, depth + 1, true, false)?,
                    pandas_pprint(&item, depth + 1, true, false)?
                ));
            }
            let more = if dict.len() > MAX_SEQ_ITEMS {
                ", ..."
            } else {
                ""
            };
            return Ok(format!("{{{}{more}}}", pairs.join(", ")));
        }
        let text = value.is_instance_of::<pyo3::types::PyString>()
            || value.is_instance_of::<pyo3::types::PyBytes>();
        if !text
            && let Ok(items) = value.try_iter()
            && let Ok(len) = value.len()
        {
            let mut parts = Vec::with_capacity(len.min(MAX_SEQ_ITEMS));
            for item in items.take(len.min(MAX_SEQ_ITEMS)) {
                parts.push(pandas_pprint(&item?, depth + 1, quote, escape)?);
            }
            let mut body = parts.join(", ");
            if len > MAX_SEQ_ITEMS {
                body.push_str(", ...");
            } else if len == 1 && value.is_instance_of::<PyTuple>() {
                body.push(',');
            }
            return Ok(if value.is_instance_of::<PySet>() {
                format!("{{{body}}}")
            } else if value.hasattr("__setitem__")? {
                format!("[{body}]")
            } else {
                format!("({body})")
            });
        }
    }
    let shown = escaped(value.str()?.to_string());
    Ok(
        if quote && value.is_instance_of::<pyo3::types::PyString>() {
            format!("'{shown}'")
        } else {
            shown
        },
    )
}

/// A Python object an object cell carries (fvsao.33): the core compares,
/// prints and hashes it through Python.
struct PyHost(Py<PyAny>);

impl fp_types::HostObject for PyHost {
    fn host_eq(&self, other: &dyn fp_types::HostObject) -> bool {
        let Some(other) = other.as_any().downcast_ref::<PyHost>() else {
            return false;
        };
        Python::attach(|py| self.0.bind(py).eq(other.0.bind(py)).unwrap_or(false))
    }

    fn host_repr(&self) -> String {
        Python::attach(|py| {
            self.0
                .bind(py)
                .repr()
                .map(|text| text.to_string())
                .unwrap_or_default()
        })
    }

    fn host_str(&self) -> String {
        Python::attach(|py| {
            self.0
                .bind(py)
                .str()
                .map(|text| text.to_string())
                .unwrap_or_default()
        })
    }

    // pandas displays a pandas object in a cell by its str, anything else
    // by pprint_thing.
    fn host_pprint(&self) -> String {
        Python::attach(|py| {
            let value = self.0.bind(py);
            // pandas' array formatter prints a StringDtype cell by its repr,
            // string[python] (df.dtypes printed 'string'; vzoct).
            if value.is_instance_of::<PyStringDtype>() {
                return Ok(value.repr()?.to_string());
            }
            let module = value.get_type().module()?.to_string();
            if module.starts_with("pandas") || module.starts_with("frankenpandas") {
                return Ok(value.str()?.to_string());
            }
            pandas_pprint(value, 0, false, true)
        })
        .unwrap_or_else(|_: PyErr| self.host_str())
    }

    fn host_hash(&self) -> Option<u64> {
        Python::attach(|py| {
            self.0
                .bind(py)
                .hash()
                .ok()
                .map(|hash| u64::from_ne_bytes(hash.to_ne_bytes()))
        })
    }

    // Python's own == against the value as Python has it.
    fn host_eq_scalar(&self, other: &Scalar) -> bool {
        Python::attach(|py| {
            scalar_to_py(py, other)
                .and_then(|other| self.0.bind(py).eq(other.bind(py)))
                .unwrap_or(false)
        })
    }

    // Python's own < / > / ==; a TypeError (a date against a time) is None.
    fn host_cmp(&self, other: &dyn fp_types::HostObject) -> Option<std::cmp::Ordering> {
        let other = other.as_any().downcast_ref::<PyHost>()?;
        Python::attach(|py| {
            let (left, right) = (self.0.bind(py), other.0.bind(py));
            if left.lt(right).ok()? {
                Some(std::cmp::Ordering::Less)
            } else if left.gt(right).ok()? {
                Some(std::cmp::Ordering::Greater)
            } else {
                left.eq(right).ok()?.then_some(std::cmp::Ordering::Equal)
            }
        })
    }

    // Python's own `tp_name`: a class defined in Python by its bare name, a
    // builtin by its name, any other built type as `module.name`
    // (`datetime.date`), as Python's TypeErrors print it.
    fn host_type_name(&self) -> String {
        const HEAP_TYPE: u64 = 1 << 9;
        Python::attach(|py| {
            let kind = self.0.bind(py).get_type();
            let Ok(name) = kind.name().map(|name| name.to_string()) else {
                return "object".to_owned();
            };
            let heap_type = kind
                .getattr("__flags__")
                .and_then(|flags| flags.extract::<u64>())
                .is_ok_and(|flags| flags & HEAP_TYPE != 0);
            match kind.module().map(|module| module.to_string()) {
                Ok(module) if !heap_type && module != "builtins" => format!("{module}.{name}"),
                _ => name,
            }
        })
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }
}

/// Parse `keep` parameter for duplicate row/value detection.
/// The positions a `duplicated` mask leaves: what `drop_duplicates(keep=)`
/// keeps.
fn unduplicated_positions(duplicated: &[bool]) -> Vec<usize> {
    duplicated
        .iter()
        .enumerate()
        .filter_map(|(position, &repeated)| (!repeated).then_some(position))
        .collect()
}

/// The positions an Index `delete(loc)` drops: one position (negative
/// counts from the end) or a list / array of them, with numpy's
/// IndexError for one out of bounds (br-frankenpandas-b9lc7).
fn delete_positions(loc: &Bound<'_, PyAny>, len: usize) -> PyResult<HashSet<usize>> {
    let positions: Vec<i64> = match loc.extract::<i64>() {
        Ok(position) => vec![position],
        Err(_) => loc.extract::<Vec<i64>>()?,
    };
    let mut dropped = HashSet::with_capacity(positions.len());
    for position in positions {
        let resolved = if position < 0 {
            position + len as i64
        } else {
            position
        };
        match usize::try_from(resolved) {
            Ok(at) if at < len => {
                dropped.insert(at);
            }
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(format!(
                    "index {position} is out of bounds for axis 0 with size {len}"
                )));
            }
        }
    }
    Ok(dropped)
}

/// pandas' `keep=` of duplicated / drop_duplicates: 'first', 'last' or
/// False; anything else is pandas' ValueError (it also read 'First',
/// 'false' and 'none', and raised texts of its own; br-frankenpandas-k2bwx).
fn parse_duplicate_keep(keep: Option<&Bound<'_, PyAny>>) -> PyResult<DuplicateKeep> {
    let Some(keep) = keep else {
        return Ok(DuplicateKeep::First);
    };
    if keep.is_instance_of::<pyo3::types::PyBool>() && !keep.is_truthy()? {
        return Ok(DuplicateKeep::None);
    }
    match keep.extract::<String>().as_deref() {
        Ok("first") => Ok(DuplicateKeep::First),
        Ok("last") => Ok(DuplicateKeep::Last),
        _ => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            r#"keep must be either "first", "last" or False"#,
        )),
    }
}

/// The values of an array-like argument as one column, the way pandas'
/// Series and DataFrame constructors, `df[col] = ...` and `assign` take them:
/// an Index keeps its typed values (a DatetimeIndex gives datetime64 with
/// NaT, a TimedeltaIndex timedelta64), a 1-D numpy array its elements
/// (datetime64/timedelta64 as nanoseconds), a `range` its ints. `None` for
/// anything else. These raised "Cannot convert ndarray to Scalar" in the
/// DataFrame paths, and a DatetimeIndex became its formatted strings with NaT
/// as 1970-01-01 (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.15).
/// The labels a CategoricalIndex (or its categories) is built from: any
/// collection - a list, an array, an Index, a Series, a Categorical - read
/// item by item as index labels. Text or a scalar is pandas' TypeError.
fn categorical_labels_of(data: &Bound<'_, PyAny>) -> PyResult<Vec<IndexLabel>> {
    if data.is_instance_of::<pyo3::types::PyString>() || data.try_iter().is_err() {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "CategoricalIndex(...) must be called with a collection of some kind, {} was passed",
            data.repr()?
        )));
    }
    data.try_iter()?
        .map(|item| py_to_index_label(&item?))
        .collect()
}

/// A CategoricalIndex construction's refusal as pandas' ValueError of its
/// message ("Categorical categories must be unique").
fn categorical_error(err: fp_index::IndexError) -> PyErr {
    let message = match err {
        fp_index::IndexError::InvalidArgument(message) => message,
        other => other.to_string(),
    };
    PyErr::new::<pyo3::exceptions::PyValueError, _>(message)
}

/// A category argument (`add_categories('d')`, `remove_categories(['a'])`):
/// one label, or each item of a list-like.
fn category_items(obj: &Bound<'_, PyAny>) -> PyResult<Vec<IndexLabel>> {
    if obj.is_instance_of::<pyo3::types::PyString>() || obj.try_iter().is_err() {
        return Ok(vec![py_to_index_label(obj)?]);
    }
    categorical_labels_of(obj)
}

/// A CategoricalIndex's labels as a categorical column of its categories and
/// ordering, a missing label code -1.
fn categorical_index_column(index: &CategoricalIndex) -> PyResult<Column> {
    let categories = index.categories();
    let codes = index
        .labels()
        .iter()
        .zip(index.isna())
        .map(|(label, missing)| {
            categories
                .iter()
                .position(|category| !missing && category == label)
                .map_or(-1, |position| position as i64)
        })
        .collect();
    let categories = categories.iter().map(index_label_to_scalar).collect();
    Series::from_categorical_codes("", codes, categories, index.ordered())
        .map(|series| series.column().clone())
        .map_err(frame_error_to_py)
}

/// `items` as one Utf8 column when each is an exact `str`: their UTF-8 bytes
/// end to end, the column `Column::from_values` makes of them without a
/// String and a Scalar per cell (a million strings from a list took ~70 ms;
/// br-frankenpandas-mf3tj). None for any other item - a str with lone
/// surrogates too - or no items: the caller's path decides those.
fn contiguous_text_column<'py>(
    items: impl IntoIterator<Item = Bound<'py, PyAny>>,
) -> Option<Column> {
    let mut bytes = Vec::new();
    let mut offsets = vec![0];
    for item in items {
        let text = item
            .cast_exact::<pyo3::types::PyString>()
            .ok()?
            .to_str()
            .ok()?;
        bytes.extend_from_slice(text.as_bytes());
        offsets.push(bytes.len());
    }
    (offsets.len() > 1).then(|| Column::from_utf8_contiguous(bytes, offsets))
}

/// A list of narrow numpy number scalars (np.float32, np.int8, np.uint16:
/// widths the engine tags) as numpy's array of them, in the dtype numpy
/// promotes them to while that stays narrow (int8 with int16 is int16), as
/// pandas infers it (each item was read through py_to_scalar into a 64-bit
/// column; br-frankenpandas-mwuhp). None for any other list, and for signed
/// with unsigned ints among them, which pandas keeps as objects.
fn narrow_numpy_list_column(py: Python<'_>, list: &Bound<'_, PyList>) -> PyResult<Option<Column>> {
    // The numpy kind ('i', 'u', 'f') of a narrow numpy number scalar.
    let narrow_kind = |item: &Bound<'_, PyAny>| -> PyResult<Option<String>> {
        if item.get_type().module()?.to_str()? != "numpy" {
            return Ok(None);
        }
        let Ok(dtype) = item.getattr("dtype") else {
            return Ok(None);
        };
        if NumericWidth::parse(&dtype.getattr("name")?.extract::<String>()?).is_none() {
            return Ok(None);
        }
        Ok(Some(dtype.getattr("kind")?.extract::<String>()?))
    };
    if list.is_empty() {
        return Ok(None);
    }
    let (mut signed, mut unsigned) = (false, false);
    for item in list.iter() {
        match narrow_kind(&item)?.as_deref() {
            Some("i") => signed = true,
            Some("u") => unsigned = true,
            Some(_) => {}
            None => return Ok(None),
        }
    }
    if signed && unsigned {
        return Ok(None);
    }
    let array = py.import("numpy")?.call_method1("array", (list,))?;
    let name = array
        .getattr("dtype")?
        .getattr("name")?
        .extract::<String>()?;
    if NumericWidth::parse(&name).is_none() {
        return Ok(None);
    }
    py_array_like_column(py, &array)
}

/// A native-order numpy array's elements through the buffer protocol: one
/// copy, a strided view gathered by `PyBuffer_ToContiguous`. The caller
/// checks the byte order (see [`py_array_like_column`]).
fn ndarray_elements<T: pyo3::buffer::Element>(
    py: Python<'_>,
    array: &Bound<'_, PyAny>,
) -> PyResult<Vec<T>> {
    pyo3::buffer::PyBuffer::<T>::get(array)?.to_vec(py)
}

/// A native-order array of a numpy dtype narrower than 64 bits, or of
/// uint64, in the engine's 64-bit storage (the caller tags the width); a
/// uint64 value at or above 2**63 is refused, as the largest one.
fn narrow_ndarray_column(
    py: Python<'_>,
    array: &Bound<'_, PyAny>,
    width: NumericWidth,
) -> PyResult<Column> {
    fn ints<T: pyo3::buffer::Element + Into<i64>>(
        py: Python<'_>,
        array: &Bound<'_, PyAny>,
    ) -> PyResult<Column> {
        let values = ndarray_elements::<T>(py, array)?;
        Ok(Column::from_i64_values(
            values.into_iter().map(Into::into).collect(),
        ))
    }
    match width {
        NumericWidth::Int8 => ints::<i8>(py, array),
        NumericWidth::Int16 => ints::<i16>(py, array),
        NumericWidth::Int32 => ints::<i32>(py, array),
        NumericWidth::UInt8 => ints::<u8>(py, array),
        NumericWidth::UInt16 => ints::<u16>(py, array),
        NumericWidth::UInt32 => ints::<u32>(py, array),
        NumericWidth::UInt64 => {
            let values = ndarray_elements::<u64>(py, array)?;
            match values
                .iter()
                .map(|&value| i64::try_from(value))
                .collect::<Result<Vec<_>, _>>()
            {
                Ok(values) => Ok(Column::from_i64_values(values)),
                Err(_) => Err(column_error_to_py(
                    fp_columnar::ColumnError::UInt64OutOfRange {
                        value: values.iter().copied().max().unwrap_or_default(),
                    },
                )),
            }
        }
        NumericWidth::Float32 => Ok(Column::from_f64_values(
            ndarray_elements::<f32>(py, array)?
                .into_iter()
                .map(f64::from)
                .collect(),
        )),
    }
}

fn py_array_like_column(py: Python<'_>, obj: &Bound<'_, PyAny>) -> PyResult<Option<Column>> {
    // An array is its column, dtype and all.
    if let Ok(array) = obj.extract::<PyRef<'_, PyExtensionArray>>() {
        return Ok(Some(array.inner.column().clone()));
    }
    // A CategoricalIndex is a categorical column of its categories and
    // ordering (it was an object column of its labels; 5y62q).
    if let Ok(categorical) = obj.extract::<PyRef<'_, PyCategoricalIndex>>() {
        return categorical_index_column(&categorical.inner).map(Some);
    }
    // A Categorical (pd.cut's answer) is its categorical column; a groupby
    // keyed by one read it as one value ("Cannot convert Categorical to
    // Scalar"; 4qg5w.7).
    if let Ok(categorical) = obj.extract::<PyRef<'_, PyCategorical>>() {
        return Ok(Some(categorical.inner.column().clone()));
    }
    let temporal = |dtype: DType, nanos: Vec<Option<i64>>, wrap: fn(i64) -> Scalar| {
        let values = nanos
            .into_iter()
            .map(|ns| ns.map_or(Scalar::Null(NullKind::NaT), wrap))
            .collect();
        Column::new(dtype, values).map_err(column_error_to_py)
    };
    if let Ok(dti) = obj.extract::<PyRef<'_, PyDatetimeIndex>>() {
        // Its instants typed while none is NaT (their Scalar cells were
        // built and read back; br-frankenpandas-so0mr).
        let instants = dti.inner.asi8();
        let column = if instants.contains(&i64::MIN) {
            temporal(
                DType::Datetime64 { tz: None },
                dti.inner.nanos(),
                Scalar::Datetime64,
            )?
        } else {
            Column::from_datetime64_values(instants)
        };
        // A tz-aware index gives a column of its dtype (datetime64[ns, tz]).
        return Ok(Some(match dti.inner.tz() {
            Some(zone) => column.with_dtype(DType::datetime64_tz(zone)),
            None => column,
        }));
    }
    if let Ok(tdi) = obj.extract::<PyRef<'_, PyTimedeltaIndex>>() {
        let column = temporal(DType::Timedelta64, tdi.inner.nanos(), Scalar::Timedelta64)?;
        return Ok(Some(column));
    }
    // A RangeIndex is an Index.
    let labels = plain_index_ref(obj)
        .ok()
        .map(|idx| idx.inner.labels().to_vec());
    if let Some(labels) = labels {
        let values = labels.iter().map(index_label_to_scalar).collect();
        return Column::from_values(values)
            .map(Some)
            .map_err(column_error_to_py);
    }
    if let Ok(range) = obj.cast::<pyo3::types::PyRange>() {
        let values = range
            .try_iter()?
            .map(|v| v.and_then(|v| v.extract::<i64>()))
            .collect::<PyResult<Vec<_>>>()?;
        return Ok(Some(Column::from_i64_values(values)));
    }
    if obj.get_type().name()? != "ndarray" {
        return Ok(None);
    }
    if obj.getattr("ndim")?.extract::<usize>()? != 1 {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "Data must be 1-dimensional, got ndarray of shape {} instead",
            obj.getattr("shape")?.str()?
        )));
    }
    let dtype = obj.getattr("dtype")?;
    let kind = dtype.getattr("kind")?.extract::<String>()?;
    let name = dtype.getattr("name")?.extract::<String>()?;
    // A native-order array of numbers or bools is read through its buffer,
    // one copy of its bytes: tolist() made a Python object of every element
    // and converted each (a million floats took ~0.3 s;
    // br-frankenpandas-1ze1o). numpy's isnative decides - pyo3's PyBuffer
    // reads a big-endian ('>') format as native on a little-endian machine -
    // and any other array keeps tolist().
    let native = dtype.getattr("isnative")?.extract::<bool>()?;
    // An array of a numpy dtype narrower than 64 bits keeps it, as pandas'
    // Series(np.array([1, 2], dtype=np.int32)) is int32 (it widened to
    // int64 / float64; fvsao.23).
    if matches!(kind.as_str(), "i" | "u" | "f")
        && let Some((width, _)) = NumericWidth::parse(&name)
    {
        let column = if native {
            narrow_ndarray_column(py, obj, width)?
        } else if width.is_float() {
            Column::from_f64_values(obj.call_method0("tolist")?.extract::<Vec<f64>>()?)
        } else {
            let values = obj.call_method0("tolist")?;
            match values.extract::<Vec<i64>>() {
                Ok(values) => Column::from_i64_values(values),
                // A uint64 value at or above 2**63.
                Err(_) => {
                    let largest = py
                        .import("builtins")?
                        .getattr("max")?
                        .call1((values,))?
                        .extract::<u64>()?;
                    return Err(column_error_to_py(
                        fp_columnar::ColumnError::UInt64OutOfRange { value: largest },
                    ));
                }
            }
        };
        return column
            .cast_to_width(width, false)
            .map(Some)
            .map_err(column_error_to_py);
    }
    let temporal_array = |ns_dtype: &str| -> PyResult<Vec<Option<i64>>> {
        let nanos = obj
            .call_method1("astype", (ns_dtype,))?
            .call_method1("astype", ("int64",))?;
        Ok(ndarray_elements::<i64>(py, &nanos)?
            .into_iter()
            .map(|ns| (ns != i64::MIN).then_some(ns))
            .collect())
    };
    let column = match kind.as_str() {
        "M" => temporal(
            DType::Datetime64 { tz: None },
            temporal_array("datetime64[ns]")?,
            Scalar::Datetime64,
        )?,
        "m" => temporal(
            DType::Timedelta64,
            temporal_array("timedelta64[ns]")?,
            Scalar::Timedelta64,
        )?,
        "i" if native => Column::from_i64_values(ndarray_elements::<i64>(py, obj)?),
        "i" => Column::from_i64_values(obj.call_method0("tolist")?.extract::<Vec<i64>>()?),
        "f" if native && name == "float64" => {
            Column::from_f64_values(ndarray_elements::<f64>(py, obj)?)
        }
        // A numpy bool is one byte, zero or not.
        "b" => Column::from_bool_values(
            ndarray_elements::<u8>(py, &obj.call_method1("view", ("uint8",))?)?
                .into_iter()
                .map(|byte| byte != 0)
                .collect(),
        ),
        _ => {
            let items = obj
                .call_method0("tolist")?
                .try_iter()?
                .collect::<PyResult<Vec<_>>>()?;
            // Text (numpy's unicode kind, or an object array holding only
            // str; br-frankenpandas-djbjt) laid out contiguously.
            let text = matches!(kind.as_str(), "U" | "O")
                .then(|| contiguous_text_column(items.iter().cloned()));
            match text.flatten() {
                Some(column) => column,
                None => {
                    let values = items
                        .iter()
                        .map(|v| py_to_scalar(py, v))
                        .collect::<PyResult<Vec<_>>>()?;
                    Column::from_values(values).map_err(column_error_to_py)?
                }
            }
        }
    };
    Ok(Some(column))
}

/// pandas refuses a set as column data: its order is arbitrary.
fn refuse_unordered_set(obj: &Bound<'_, PyAny>) -> PyResult<()> {
    if obj.is_instance_of::<PySet>() || obj.is_instance_of::<PyFrozenSet>() {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "'set' type is unordered",
        ));
    }
    Ok(())
}

/// The time zone an `index=` argument carries: a tz-aware DatetimeIndex's,
/// or a tz-aware datetime Series' (its values are the labels).
/// `Index.append`'s argument as pandas takes it: an index, or a list /
/// tuple of them. A lone index given where a list was expected was read as
/// the list of its elements, and each dropped (fvsao.60).
fn append_pieces<'py>(other: &Bound<'py, PyAny>) -> PyResult<Vec<Bound<'py, PyAny>>> {
    if other.is_instance_of::<PyList>() || other.is_instance_of::<PyTuple>() {
        other.try_iter()?.collect()
    } else {
        Ok(vec![other.clone()])
    }
}

/// pandas' object Index of every element of `first` then `pieces`, as
/// `append` builds one from indexes of different kinds: each element as
/// Python has it, an aware Timestamp kept whole with its zone.
fn object_index_of<'py>(
    first: Bound<'py, PyAny>,
    pieces: Vec<Bound<'py, PyAny>>,
) -> PyResult<PyIndex> {
    let mut labels = Vec::new();
    for piece in std::iter::once(first).chain(pieces) {
        for item in piece.try_iter()? {
            let item = item?;
            let aware = item.getattr("tz").is_ok_and(|tz| !tz.is_none());
            labels.push(if aware {
                IndexLabel::Object(fp_types::ObjectValue::Host(fp_types::HostValue::new(
                    PyHost(item.unbind()),
                )))
            } else {
                py_to_index_label(&item)?
            });
        }
    }
    Ok(PyIndex {
        inner: Index::new(labels),
    })
}

/// pandas' row axis for pieces stacked by `concat` whose indexes are in
/// different zones (or aware beside naive, or aware beside other labels):
/// an object Index of every piece's elements as Python has them, each
/// Timestamp in its own zone. None when every non-empty piece shares one
/// zone or none is aware - fp's concat keeps that index. The bare instants
/// came back naive UTC (fvsao.60).
fn mixed_zone_rows(py: Python<'_>, indexes: &[&Index]) -> PyResult<Option<Index>> {
    let zones: Vec<Option<&str>> = indexes
        .iter()
        .filter(|index| !index.is_empty())
        .map(|index| index.tz())
        .collect();
    if zones.iter().all(Option::is_none) || zones.windows(2).all(|pair| pair[0] == pair[1]) {
        return Ok(None);
    }
    let mut pieces = indexes
        .iter()
        .map(|index| Ok(row_index_to_py(py, index)?.into_bound(py)))
        .collect::<PyResult<Vec<_>>>()?;
    if pieces.is_empty() {
        return Ok(None);
    }
    let first = pieces.remove(0);
    Ok(Some(object_index_of(first, pieces)?.inner))
}

/// pandas' TypeError for a quantile over values it cannot interpolate: a
/// bool / boolean column (numpy refuses `-` on booleans; along axis=1 only
/// a frame of nothing but booleans, whose rows stay boolean) or a text
/// column (Python refuses `-` on str; object cells that subtract, dates,
/// pandas interpolates). They were dropped, or a bool read as 0.5 (o46uo).
fn quantile_refusal(columns: &[&Column], axis: usize) -> PyResult<()> {
    let refuse_bool = if axis == 0 {
        columns.iter().any(|column| column.dtype().is_bool())
    } else {
        !columns.is_empty() && columns.iter().all(|column| column.dtype().is_bool())
    };
    if refuse_bool {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            fp_frame::NUMPY_BOOL_SUBTRACT,
        ));
    }
    let unsubtractable = columns
        .iter()
        .filter(|column| column.dtype() == DType::Utf8)
        .find_map(|column| column.values().iter().find(|value| !value.is_missing()))
        .filter(|value| matches!(value, Scalar::Utf8(_)));
    if let Some(value) = unsubtractable {
        let kind = value.python_type_name();
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "unsupported operand type(s) for -: '{kind}' and '{kind}'"
        )));
    }
    Ok(())
}

/// A column pandas' corr / corrwith / quantile read as numbers: ints and
/// floats, nullable or not, and booleans. The nullable Int64 / Float64 /
/// boolean columns were left out - dropped from the result, or refused
/// (4qg5w.5).
fn corr_numeric(dtype: &DType) -> bool {
    dtype.is_numeric() || dtype.is_bool()
}

/// The zone of a tz-aware datetime column (a groupby key's); None for any
/// other column.
fn column_zone(column: &Column) -> Option<String> {
    match column.dtype() {
        DType::Datetime64 { tz } => tz,
        _ => None,
    }
}

/// `index` shown in `zone` while its labels are all datetimes, unchanged
/// otherwise (a groupby result keyed by an aware column's instants).
fn index_in_zone(index: Index, zone: &str) -> Index {
    index.clone().with_tz(Some(zone)).unwrap_or(index)
}

/// `series` with its index shown in `zone` (None: as it is) - for results
/// whose rows are another index's labels, taken as bare UTC instants.
fn series_index_in_zone(series: Series, zone: Option<&str>) -> PyResult<Series> {
    let Some(zone) = zone else {
        return Ok(series);
    };
    let index = series
        .index()
        .clone()
        .with_tz(Some(zone))
        .map_err(index_error_to_py)?;
    Series::new(series.name(), index, series.column().clone()).map_err(frame_error_to_py)
}

fn index_arg_zone(obj: &Bound<'_, PyAny>) -> Option<String> {
    if let Ok(dti) = obj.extract::<PyRef<'_, PyDatetimeIndex>>() {
        dti.inner.tz()
    } else if let Ok(series) = obj.extract::<PyRef<'_, PySeries>>() {
        match series.inner.dtype() {
            DType::Datetime64 { tz } => tz,
            _ => None,
        }
    } else {
        None
    }
}

/// The name of `frame`'s column the Python label `key` selects, as pandas
/// matches labels: a string names a string-labelled column, any other label
/// (0, 1.5, True, a Timestamp) the column carrying exactly that typed label -
/// so `df[0]` finds `DataFrame([[1, 2]])`'s first column and `df['0']` does
/// not (fvsao.32). None when no column carries it.
#[allow(clippy::cast_precision_loss, clippy::cast_possible_truncation)] // whole numbers below 2^63
fn frame_column_name_for(frame: &DataFrame, key: &Bound<'_, PyAny>) -> Option<String> {
    let label = if key.is_instance_of::<pyo3::types::PyString>() {
        IndexLabel::Utf8(key.extract::<String>().ok()?)
    } else {
        py_to_index_label(key).ok()?
    };
    let found = |label: &IndexLabel| {
        let name = fp_frame::column_key(label);
        (frame.column(&name).is_some() && frame.column_label(&name) == *label).then_some(name)
    };
    // A number finds the equal number of the other kind, as pandas' Index
    // lookup: df[1] the column 1.0, df[2.0] the column 2 (a KeyError;
    // br-frankenpandas-qacqs). A bool is not a number here.
    found(&label).or_else(|| match &label {
        IndexLabel::Int64(value) => {
            found(&IndexLabel::Float64(fp_index::OrderedF64(*value as f64)))
        }
        IndexLabel::Float64(value) if value.0.fract() == 0.0 && value.0.abs() < 9.2e18 => {
            found(&IndexLabel::Int64(value.0 as i64))
        }
        _ => None,
    })
}

/// The column names a `by=` / `columns=` / `keys=` / `.loc` column argument
/// names when it holds a typed label - one (`by=0`) or a list with one
/// (`by=[0, 'a']`) - each matched as [`frame_column_name_for`] does; None
/// for strings alone and anything else, which the caller reads as before
/// (fvsao.32).
fn frame_column_names_arg(frame: &DataFrame, obj: &Bound<'_, PyAny>) -> Option<Vec<String>> {
    let typed = |item: &Bound<'_, PyAny>| {
        !item.is_instance_of::<pyo3::types::PyString>()
            && !item.is_instance_of::<PyList>()
            && !item.is_instance_of::<PyTuple>()
            && item.extract::<PyRef<'_, PySeries>>().is_err()
    };
    if typed(obj) {
        return (!obj.hasattr("__len__").unwrap_or(true))
            .then(|| frame_column_name_for(frame, obj))
            .flatten()
            .map(|name| vec![name]);
    }
    let items: Vec<Bound<'_, PyAny>> = obj.cast::<PyList>().ok()?.iter().collect();
    if !items.iter().any(typed) {
        return None;
    }
    items
        .iter()
        .map(|item| frame_column_name_for(frame, item))
        .collect()
}

/// A column argument - a `.loc` column key, `subset=`, `on=`, `keys=`,
/// `items=`, ... - with its typed labels read as the names they select
/// (`loc[:, 0]` / `subset=[0]` name the column '0' of `DataFrame([[1,
/// 2]])`, a list likewise); any other argument as given, for the caller to
/// read as before (fvsao.32).
fn column_arg<'py>(
    py: Python<'py>,
    frame: &DataFrame,
    key: Bound<'py, PyAny>,
) -> PyResult<Bound<'py, PyAny>> {
    Ok(match frame_column_names_arg(frame, &key) {
        Some(names) if key.is_instance_of::<PyList>() => PyList::new(py, names)?.into_any(),
        Some(names) => match names.into_iter().next() {
            Some(name) => pyo3::types::PyString::new(py, &name).into_any(),
            None => key,
        },
        None => key,
    })
}

/// Refuse a write of the column labelled `label` (keyed `name`) where
/// `frame` already has a column keyed `name` under another label - the
/// integer 0 and the string '0' are both keyed "0", and writing one would
/// silently overwrite the other (pandas keeps both columns; fvsao.32).
fn refuse_label_clash(frame: &DataFrame, name: &str, label: &IndexLabel) -> PyResult<()> {
    if frame.column(name).is_none() {
        return Ok(());
    }
    let existing = frame.column_label(name);
    if existing == *label {
        return Ok(());
    }
    let shown = |label: &IndexLabel| match label {
        IndexLabel::Utf8(text) => format!("'{text}'"),
        other => other.to_string(),
    };
    Err(not_implemented(&format!(
        "a frame holding both the column labels {} and {} (they are keyed by the same text)",
        shown(&existing),
        shown(label)
    )))
}

/// Refuse column labels two of which share a key text - `{0: .., '0': ..}`,
/// `columns=[0, '0']`: one column would silently replace the other (pandas
/// keeps both; fvsao.32).
fn refuse_labels_keyed_alike<'py>(
    items: impl IntoIterator<Item = Bound<'py, PyAny>>,
) -> PyResult<()> {
    let mut seen: HashMap<String, IndexLabel> = HashMap::new();
    for item in items {
        let label = match typed_column_label(&item) {
            Some(label) => label,
            None => match item.extract::<String>() {
                Ok(text) => IndexLabel::Utf8(text),
                Err(_) => continue,
            },
        };
        let key = fp_frame::column_key(&label);
        match seen.get(&key) {
            Some(previous) if *previous != label => {
                return Err(not_implemented(&format!(
                    "a frame holding both the column labels {previous:?} and {label:?} (they are \
                     keyed by the same text)"
                )));
            }
            Some(_) => {}
            None => {
                seen.insert(key, label);
            }
        }
    }
    Ok(())
}

/// Whether `data` is a (non-empty) list of Series - pandas' rows-of-Series
/// frame, which labels its own rows and columns ([`frame_from_series_rows`]).
fn is_series_list(data: &Bound<'_, PyAny>) -> bool {
    data.cast::<PyList>().is_ok_and(|list| {
        !list.is_empty()
            && list
                .iter()
                .all(|item| item.extract::<PyRef<'_, PySeries>>().is_ok())
    })
}

/// pandas' `DataFrame([s1, s2, ...])`: each Series a ROW, labelled by its
/// name (typed; `'Unnamed <k>'` counting the unnamed ones when some are
/// named, pandas' RangeIndex when none is), the columns the union of the
/// Series' indexes in the order their labels first appear (a RangeIndex
/// when every Series shares one), a label a Series lacks NaN; `columns`
/// (`columns=`) are the columns instead, selected before the dtypes are
/// read. It raised TypeError (fvsao.63).
fn frame_from_series_rows(
    rows: &[Series],
    columns: Option<&[IndexLabel]>,
    promote: impl Fn(Vec<Scalar>) -> Vec<Scalar>,
) -> PyResult<DataFrame> {
    let mut labels: Vec<IndexLabel> = Vec::new();
    let mut seen: HashSet<&IndexLabel> = HashSet::new();
    let mut positions: Vec<HashMap<&IndexLabel, usize>> = Vec::with_capacity(rows.len());
    for row in rows {
        if row.index().has_duplicates() {
            return Err(not_implemented(
                "DataFrame of Series whose index repeats a label",
            ));
        }
        let mut at = HashMap::with_capacity(row.len());
        for (position, label) in row.index().labels().iter().enumerate() {
            if seen.insert(label) {
                labels.push(label.clone());
            }
            at.insert(label, position);
        }
        positions.push(at);
    }
    let selected = columns.is_some();
    if let Some(columns) = columns {
        labels = columns.to_vec();
    }
    let cells: Vec<Vec<Scalar>> = labels
        .iter()
        .map(|label| {
            rows.iter()
                .zip(&positions)
                .map(|(row, at)| match at.get(label) {
                    Some(&position) => row.column().values()[position].clone(),
                    None => Scalar::Null(NullKind::NaN),
                })
                .collect()
        })
        .collect();
    // pandas stacks the rows into one 2-D array: all-numeric cells with a
    // float or a missing one anywhere make EVERY column float64; any other
    // mix is read column by column.
    let numeric = cells.iter().flatten().all(|cell| {
        matches!(
            cell,
            Scalar::Int64(_) | Scalar::Float64(_) | Scalar::Null(NullKind::NaN | NullKind::Null)
        )
    });
    let floats = numeric
        && cells
            .iter()
            .flatten()
            .any(|cell| matches!(cell, Scalar::Float64(_) | Scalar::Null(_)));
    let mut columns = BTreeMap::new();
    let mut order = Vec::with_capacity(labels.len());
    for (label, values) in labels.iter().zip(cells) {
        let column = if floats {
            Column::new(DType::Float64, values)
        } else {
            Column::from_values(promote(values))
        }
        .map_err(column_error_to_py)?;
        let name = fp_frame::column_key(label);
        columns.insert(name.clone(), column);
        order.push(name);
    }
    let unnamed = rows.iter().filter(|row| row.name().is_empty()).count();
    let index = if unnamed == rows.len() {
        Index::default_range(rows.len())
    } else {
        let mut next_unnamed = 0;
        Index::new(
            rows.iter()
                .map(|row| {
                    if row.name().is_empty() {
                        next_unnamed += 1;
                        IndexLabel::Utf8(format!("Unnamed {}", next_unnamed - 1))
                    } else {
                        row.name().label()
                    }
                })
                .collect(),
        )
    };
    let span = rows
        .first()
        .and_then(|first| first.index().range_span())
        .filter(|span| {
            !selected
                && rows
                    .iter()
                    .all(|row| row.index().range_span() == Some(*span))
        });
    let frame = DataFrame::new_with_column_order(index, columns, order)
        .map_err(frame_error_to_py)?
        .with_recorded_column_labels(labels);
    Ok(match span {
        Some(span) => frame.with_column_range(span),
        None => frame,
    })
}

/// [`column_arg`] for an optional argument.
fn column_arg_opt<'py>(
    frame: &DataFrame,
    key: Option<&Bound<'py, PyAny>>,
) -> PyResult<Option<Bound<'py, PyAny>>> {
    key.map(|key| column_arg(key.py(), frame, key.clone()))
        .transpose()
}

/// A dict keyed by columns (`astype({0: float})`, `fillna({0: 1})`,
/// `agg({0: 'sum'})`, ...) with each typed key that labels a column
/// replaced by that column's name; other keys, and the values, as given
/// (fvsao.32).
fn column_dict_arg<'py>(
    frame: &DataFrame,
    dict: &Bound<'py, PyDict>,
) -> PyResult<Bound<'py, PyDict>> {
    let out = PyDict::new(dict.py());
    for (key, value) in dict.iter() {
        // A full tuple names its MultiIndex column (7m8bq).
        let tupled = frame_multi_column_position(frame, &key)
            .and_then(|position| frame.column_name_at(position));
        match tupled.or_else(|| {
            frame_column_name_for(frame, &key)
                .filter(|_| !key.is_instance_of::<pyo3::types::PyString>())
        }) {
            Some(name) => out.set_item(name, value)?,
            None => out.set_item(key, value)?,
        }
    }
    Ok(out)
}

/// The position of the column a full-depth tuple names under `frame`'s
/// MultiIndex columns; None over flat columns, for a non-tuple, or a tuple
/// naming no single column.
fn frame_multi_column_position(frame: &DataFrame, key: &Bound<'_, PyAny>) -> Option<usize> {
    let multi = frame.columns_multiindex()?;
    let wanted = key
        .cast::<PyTuple>()
        .ok()?
        .iter()
        .map(|level| py_to_index_label(&level).ok())
        .collect::<Option<Vec<IndexLabel>>>()?;
    let mut positions = (0..multi.len()).filter(|&position| {
        multi.get_tuple(position).is_some_and(|levels| {
            levels.len() == wanted.len()
                && levels.iter().zip(&wanted).all(|(have, want)| *have == want)
        })
    });
    let position = positions.next()?;
    if positions.next().is_some() {
        return None;
    }
    Some(position)
}

/// A Python column label's typed label: None for a string (a string names
/// its column as itself).
fn typed_column_label(obj: &Bound<'_, PyAny>) -> Option<IndexLabel> {
    if obj.is_instance_of::<pyo3::types::PyString>() {
        return None;
    }
    py_to_index_label(obj).ok()
}

/// `frame` with the typed column labels its constructor was given - the
/// items of `columns=`, the keys of a dict or of the records - or, for a
/// matrix given no `columns=` (a list of lists, a 2-D array, a flat list),
/// pandas' default RangeIndex columns 0..n. They were their text: the columns
/// of `DataFrame([[1, 2]])` were the strings '0' and '1' (fvsao.32).
fn constructor_column_labels(
    data: Option<&Bound<'_, PyAny>>,
    columns: Option<&Bound<'_, PyAny>>,
    frame: DataFrame,
) -> PyResult<DataFrame> {
    if frame.columns_multiindex().is_some() {
        return Ok(frame);
    }
    let width = frame.num_columns();
    let default_names = frame
        .column_names()
        .iter()
        .enumerate()
        .all(|(at, name)| **name == at.to_string());
    let range = || i64::try_from(width).ok().map(|stop| (0, stop, 1));
    if let Some(columns) = columns.filter(|columns| !columns.is_none()) {
        // A range (or RangeIndex) given as columns= stays one.
        let ranged = columns.is_instance_of::<pyo3::types::PyRange>()
            || columns.extract::<PyRef<'_, PyRangeIndex>>().is_ok();
        if ranged
            && default_names
            && let Some(span) = range()
        {
            return Ok(frame.with_column_range(span));
        }
        refuse_labels_keyed_alike(columns.try_iter()?.filter_map(Result::ok))?;
        // A list / tuple is pandas' Index of its labels (see
        // `columns_arg_labels`), as `extract_columns_names` named them.
        if columns.is_instance_of::<PyList>() || columns.is_instance_of::<PyTuple>() {
            let items: Vec<Bound<'_, PyAny>> = columns.try_iter()?.collect::<PyResult<_>>()?;
            let labels = columns_arg_labels(&items)?
                .into_iter()
                .filter(|label| !matches!(label, IndexLabel::Utf8(_)));
            return Ok(frame.with_recorded_column_labels(labels));
        }
        let labels = columns
            .try_iter()?
            .filter_map(|item| item.ok().and_then(|item| typed_column_label(&item)));
        return Ok(frame.with_recorded_column_labels(labels));
    }
    let Some(data) = data.filter(|data| !data.is_none()) else {
        return Ok(frame);
    };
    // Rows of Series label their own columns.
    if is_series_list(data) {
        return Ok(frame);
    }
    if let Ok(dict) = data.cast::<PyDict>() {
        refuse_labels_keyed_alike(dict.keys().iter())?;
        let labels = dict
            .keys()
            .iter()
            .filter_map(|key| typed_column_label(&key));
        return Ok(frame.with_recorded_column_labels(labels));
    }
    let records = data.cast::<PyList>().ok().filter(|list| {
        list.iter()
            .next()
            .is_some_and(|first| first.is_instance_of::<PyDict>())
    });
    if let Some(records) = records {
        refuse_labels_keyed_alike(
            records
                .iter()
                .filter_map(|record| record.cast_into::<PyDict>().ok())
                .flat_map(|record| record.keys()),
        )?;
        let labels = records
            .iter()
            .filter_map(|record| record.cast_into::<PyDict>().ok())
            .flat_map(|record| record.keys())
            .filter_map(|key| typed_column_label(&key));
        return Ok(frame.with_recorded_column_labels(labels));
    }
    // A matrix's columns are the positions 0..n, pandas' RangeIndex.
    let matrix = data.is_instance_of::<PyList>()
        || data.is_instance_of::<PyTuple>()
        || data.get_type().name()?.to_str()? == "ndarray";
    match range().filter(|_| matrix && default_names && width > 0) {
        Some(span) => Ok(frame.with_column_range(span)),
        None => Ok(frame),
    }
}

/// The pandas RangeIndex a constructor's `rows` are, if any: the RangeIndex
/// or `range` given as `index=` (its own stop); with no index, the one
/// `data` brings (a Series' or DataFrame's, or the one every Series of a
/// mapping for a DataFrame shares), none for a mapping for a Series (its
/// keys), and otherwise the default one.
fn constructor_range_span(
    data: Option<&Bound<'_, PyAny>>,
    index: Option<&Bound<'_, PyAny>>,
    for_frame: bool,
    rows: &Index,
) -> Option<(i64, i64, i64)> {
    if let Some(index) = index.filter(|index| !index.is_none()) {
        if let Ok(range) = index.extract::<PyRef<'_, PyRangeIndex>>() {
            return range.as_super().inner.range_span();
        }
        let range = index.cast::<pyo3::types::PyRange>().ok()?;
        let part = |name: &str| range.getattr(name).ok()?.extract::<i64>().ok();
        return Some((part("start")?, part("stop")?, part("step")?));
    }
    // The rows a Series or DataFrame brings: Some(its RangeIndex or None).
    let own_rows = |value: &Bound<'_, PyAny>| {
        if let Ok(series) = value.extract::<PyRef<'_, PySeries>>() {
            return Some(series.inner.index().range_span());
        }
        let frame = value.extract::<PyRef<'_, PyDataFrame>>().ok()?;
        Some(frame.inner.index().range_span())
    };
    let Some(data) = data.filter(|data| !data.is_none()) else {
        return rows.int64_range_span();
    };
    if let Some(span) = own_rows(data) {
        return span;
    }
    // Rows of Series are labelled by their names: a RangeIndex only when
    // none is named, as the rows already say.
    if is_series_list(data) {
        return rows.range_span();
    }
    match data.cast::<PyDict>() {
        Ok(mapping) if for_frame => {
            let spans: Vec<Option<(i64, i64, i64)>> = mapping
                .values()
                .iter()
                .filter_map(|value| own_rows(&value))
                .collect();
            match spans.split_first() {
                None => rows.int64_range_span(),
                Some((first, rest)) => first.filter(|_| rest.iter().all(|span| span == first)),
            }
        }
        Ok(_) => None,
        Err(_) => rows.int64_range_span(),
    }
}

/// The freq an `index=` DatetimeIndex carries (a date_range's): the rows
/// built on its labels keep it, as pandas' (`Series(x, index=dr).index.freq`
/// is `<Day>`; it was dropped).
fn index_arg_freq(obj: &Bound<'_, PyAny>) -> Option<String> {
    if let Ok(tdi) = obj.extract::<PyRef<'_, PyTimedeltaIndex>>() {
        return tdi.inner.freq();
    }
    obj.extract::<PyRef<'_, PyDatetimeIndex>>()
        .ok()
        .and_then(|dti| dti.inner.freq())
}

/// The dtype an `index=` Index is declared with where its labels read
/// another (see [`fp_index::DeclaredDtype`]): the rows built on its labels
/// keep it, as pandas'.
fn index_arg_declared(obj: &Bound<'_, PyAny>) -> Option<fp_index::DeclaredDtype> {
    plain_index_ref(obj)
        .ok()
        .and_then(|index| index.inner.declared_dtype())
}

/// The categories an index argument carries when it is a CategoricalIndex
/// (a Series / frame built on it keeps them; br-frankenpandas-cld41).
fn index_arg_categories(obj: &Bound<'_, PyAny>) -> Option<fp_index::IndexCategories> {
    let categorical = obj.extract::<PyRef<'_, PyCategoricalIndex>>().ok()?;
    Some(fp_index::IndexCategories {
        categories: categorical.inner.categories().to_vec(),
        ordered: categorical.inner.ordered(),
    })
}

/// The name an Index argument gives the Series built from it, as pandas'
/// `Series(Index([1, 2], name='a')).name == 'a'`.
fn py_index_arg_name(obj: &Bound<'_, PyAny>) -> Option<LabelName> {
    if let Ok(idx) = plain_index_ref(obj) {
        idx.inner.name().cloned()
    } else if let Ok(dti) = obj.extract::<PyRef<'_, PyDatetimeIndex>>() {
        dti.inner.name().cloned()
    } else if let Ok(tdi) = obj.extract::<PyRef<'_, PyTimedeltaIndex>>() {
        tdi.inner.name().cloned()
    } else if let Ok(categorical) = obj.extract::<PyRef<'_, PyCategoricalIndex>>() {
        // A CategoricalIndex's name too (it was dropped; cld41).
        categorical.inner.name().cloned()
    } else if let Ok(series) = obj.extract::<PyRef<'_, PySeries>>() {
        let name = series.inner.name();
        (!name.is_empty()).then(|| name.clone())
    } else {
        None
    }
}

/// Convert an arbitrary Python value (Series, list, tuple, or scalar) into a Column.
fn py_value_to_column(
    py: Python<'_>,
    val: &Bound<'_, PyAny>,
    expected_len: usize,
) -> PyResult<Column> {
    if let Ok(s) = val.extract::<PyRef<'_, PySeries>>() {
        if s.inner.len() != expected_len {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of values ({}) does not match length of index ({})",
                s.inner.len(),
                expected_len
            )));
        }
        return Ok(s.inner.column().clone());
    }
    if let Some(column) = py_array_like_column(py, val)? {
        if column.len() != expected_len {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of values ({}) does not match length of index ({})",
                column.len(),
                expected_len
            )));
        }
        return Ok(column);
    }
    if let Ok(list) = val.cast::<PyList>() {
        let scalars: Vec<Scalar> = pandas_promote_int_with_missing(
            list.iter()
                .map(|v| py_to_scalar(py, &v))
                .collect::<PyResult<Vec<_>>>()?,
        );
        if scalars.len() != expected_len {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of values ({}) does not match length of index ({})",
                scalars.len(),
                expected_len
            )));
        }
        let column = Column::from_values(scalars)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        // Aware datetimes of one zone make an aware column (assign's came
        // back naive).
        return Ok(match (sequence_zone(val), column.dtype()) {
            (Some(zone), DType::Datetime64 { tz: None }) => {
                column.with_dtype(DType::datetime64_tz(zone))
            }
            _ => column,
        });
    }
    if let Ok(tuple) = val.cast::<pyo3::types::PyTuple>() {
        let scalars: Vec<Scalar> = pandas_promote_int_with_missing(
            tuple
                .iter()
                .map(|v| py_to_scalar(py, &v))
                .collect::<PyResult<Vec<_>>>()?,
        );
        if scalars.len() != expected_len {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of values ({}) does not match length of index ({})",
                scalars.len(),
                expected_len
            )));
        }
        return Column::from_values(scalars)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()));
    }
    if let Ok(s) = py_to_scalar(py, val) {
        return Column::from_values(vec![s; expected_len])
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()));
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
        "Cannot convert value to DataFrame column",
    ))
}

/// A Series name given from Python: None leaves it unnamed, a string is its
/// text, and any other label (0, 1.5, a Timestamp) keeps its type, as
/// pandas' (fvsao.32; `Series(name=0).name` was the string '0'). A name no
/// label holds (a tuple) is its `str`.
fn py_series_name(value: &Bound<'_, PyAny>) -> PyResult<LabelName> {
    if value.is_none() {
        return Ok(LabelName::default());
    }
    match py_to_index_label(value) {
        Ok(label) => Ok(LabelName::typed(label)),
        Err(_) => Ok(value.str()?.to_string().into()),
    }
}

/// A Series name as pandas reports it: None when unnamed, else its typed
/// label.
fn series_name_to_py(py: Python<'_>, name: &LabelName) -> PyResult<Option<Py<PyAny>>> {
    if name.is_empty() {
        return Ok(None);
    }
    index_label_to_py(py, &name.label()).map(Some)
}

/// An axis name (an index's, the columns') as pandas reports it: None when
/// unnamed, else its typed label - `set_index(0).index.name` is the integer
/// 0 (fvsao.64; it was the string '0').
fn axis_name_to_py(py: Python<'_>, name: Option<&LabelName>) -> PyResult<Option<Py<PyAny>>> {
    name.map(|name| index_label_to_py(py, &name.label()))
        .transpose()
}

/// An axis name given from Python: None unnames the axis; a string is its
/// text, and any other label (0, 1.5, a Timestamp) keeps its type
/// (`pd.Index([5, 6], name=7)` raised TypeError; fvsao.64).
fn py_axis_name(value: &Bound<'_, PyAny>) -> PyResult<Option<LabelName>> {
    if value.is_none() {
        return Ok(None);
    }
    py_series_name(value).map(Some)
}

/// The name a `reindex` target gives its axis: an index-like target's (an
/// Index or Series - anything with a `.name`, pandas' `preserve_names`
/// test), None among them; nothing for a list, an array or a MultiIndex,
/// which keep the axis' own names (br-frankenpandas-hnu53).
fn reindex_target_name(target: Option<&Bound<'_, PyAny>>) -> PyResult<Option<Option<LabelName>>> {
    let Some(target) = target.filter(|target| !target.is_instance_of::<PyMultiIndex>()) else {
        return Ok(None);
    };
    if !target.hasattr("name")? {
        return Ok(None);
    }
    py_axis_name(&target.getattr("name")?).map(Some)
}

/// The MultiIndex `pd.Index([(1, 2), (3, 4)])` builds from a list (or
/// tuple) of tuples - only the Index constructor does; `index=`, `set_axis`
/// and the setters keep tuple labels (r0hk0). None for anything else.
fn tuple_labels_multiindex(obj: &Bound<'_, PyAny>) -> PyResult<Option<MultiIndex>> {
    let items: Vec<Bound<'_, PyAny>> = if let Ok(list) = obj.cast::<PyList>() {
        list.iter().collect()
    } else if let Ok(tuple) = obj.cast::<PyTuple>() {
        tuple.iter().collect()
    } else {
        return Ok(None);
    };
    if items.is_empty() || !items.iter().all(|item| item.is_instance_of::<PyTuple>()) {
        return Ok(None);
    }
    let tuples = items
        .iter()
        .map(|item| {
            item.try_iter()?
                .map(|label| py_to_index_label(&label?))
                .collect()
        })
        .collect::<PyResult<Vec<Vec<IndexLabel>>>>()?;
    MultiIndex::from_tuples(tuples)
        .map(Some)
        .map_err(index_error_to_py)
}

/// pandas' TypeError for a label bound (truncate's before / after) that
/// cannot be ordered against `index`'s labels: an object against
/// non-objects, or objects Python cannot order. truncate(after=object())
/// compared nothing and kept every row (r0hk0).
fn require_orderable_bound(index: &Index, bound: &IndexLabel) -> PyResult<()> {
    let Some(first) = index.labels().iter().find(|label| !label.is_missing()) else {
        return Ok(());
    };
    let orderable = match (first, bound) {
        (IndexLabel::Object(label), IndexLabel::Object(bound)) => label.python_cmp(bound).is_some(),
        (IndexLabel::Object(_), _) | (_, IndexLabel::Object(_)) => false,
        _ => true,
    };
    if orderable {
        Ok(())
    } else {
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "'<' not supported between the index labels and {bound}"
        )))
    }
}

/// The label an Index's `where` / `putmask` puts in place of its labels:
/// `value`'s, and for a missing one (left out, None, NaN, NaT) the index's
/// own missing value, as pandas' - NaT among datetimes or durations, the
/// value given (None when left out) in an object index, else NaN (an int
/// index then turns float64). It was NaN for every index (a DatetimeIndex
/// showed nan, an object Index nan for None; br-frankenpandas-oq1df).
fn index_fill_label(index: &Index, value: Option<&Bound<'_, PyAny>>) -> PyResult<IndexLabel> {
    let label = match value {
        Some(value) => py_to_index_label(value)?,
        None => IndexLabel::Null(NullKind::Null),
    };
    if !label.is_missing() {
        return Ok(label);
    }
    let mut present = index
        .labels()
        .iter()
        .filter(|label| !label.is_missing())
        .peekable();
    let temporal = present.peek().is_some()
        && present.clone().all(|label| {
            matches!(
                label,
                IndexLabel::Datetime64(_) | IndexLabel::Timedelta64(_)
            )
        });
    if temporal {
        return Ok(IndexLabel::Null(NullKind::NaT));
    }
    if present.any(|label| matches!(label, IndexLabel::Utf8(_) | IndexLabel::Object(_))) {
        return Ok(label);
    }
    Ok(IndexLabel::Null(NullKind::NaN))
}

/// Convert a Python value to an IndexLabel.
fn py_to_index_label(obj: &Bound<'_, PyAny>) -> PyResult<IndexLabel> {
    if obj.is_none() {
        return Ok(IndexLabel::Null(NullKind::Null));
    }
    if obj.is_instance_of::<PyNAType>() {
        return Ok(IndexLabel::Null(NullKind::Null));
    }
    if obj.is_instance_of::<PyNaTType>() {
        return Ok(IndexLabel::Null(NullKind::NaT));
    }
    if let Ok(ts) = obj.extract::<PyRef<'_, PyTimestamp>>() {
        return Ok(IndexLabel::Datetime64(ts.inner.nanos));
    }
    if let Ok(td) = obj.extract::<PyRef<'_, PyTimedelta>>() {
        return Ok(IndexLabel::Timedelta64(td.nanos));
    }
    // A Period is the period label (a PeriodIndex's; 45fzr).
    if let Ok(period) = obj.extract::<PyRef<'_, PyPeriod>>() {
        return Ok(IndexLabel::Period(period.inner));
    }
    // An Interval is the interval label (an IntervalIndex's; c27hq), a
    // missing one NaN.
    if let Ok(interval) = obj.extract::<PyRef<'_, PyInterval>>() {
        return Ok(if interval.is_missing() {
            IndexLabel::Null(NullKind::NaN)
        } else {
            IndexLabel::Interval(interval.core())
        });
    }
    // A naive datetime.datetime / a datetime.timedelta is the instant /
    // duration it names, as a Timestamp is (they became their text, so
    // Index([datetime(2024, 1, 1)]) was an object Index of strings).
    if let Ok(instant) = obj.cast::<PyDateTime>()
        && instant.get_tzinfo().is_none()
    {
        return Ok(IndexLabel::Datetime64(py_datetime_nanos(instant)?));
    }
    if let Ok(delta) = obj.cast::<PyDelta>() {
        return Ok(IndexLabel::Timedelta64(py_delta_nanos(delta)?));
    }
    if let Ok(b) = obj.extract::<bool>() {
        Ok(IndexLabel::Bool(b))
    } else if let Ok(i) = obj.extract::<i64>() {
        Ok(IndexLabel::Int64(i))
    } else if let Ok(f) = obj.extract::<f64>() {
        if f.is_nan() {
            Ok(IndexLabel::Null(NullKind::NaN))
        } else {
            Ok(IndexLabel::Float64(fp_index::OrderedF64(f)))
        }
    } else if let Ok(s) = obj.extract::<String>() {
        Ok(IndexLabel::Utf8(s))
    } else if let Ok(item_fn) = obj.getattr("item") {
        if let Ok(val) = item_fn.call0() {
            py_to_index_label(&val)
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "Cannot convert {} to IndexLabel",
                obj.get_type().name()?
            )))
        }
    } else {
        // Any other object (a datetime.date, a tuple) is its own label, as
        // pandas' object Index holds it; it became its text, so
        // Index([date(...)]) held strings, .loc[date(...)] missed (fvsao.66)
        // and a tuple label was the string "(1, 2)" (r0hk0).
        match py_to_cell(obj.py(), obj)? {
            Scalar::Object(object) => Ok(IndexLabel::Object(object)),
            scalar => Ok(scalar_to_index_label_converter(&scalar)),
        }
    }
}

/// One label read out of `index` as pandas returns it (`index[0]`,
/// `index.max()`, `s.idxmax()`, `first_valid_index`): an int or float label
/// of an Int64 / Float64 index is a numpy scalar - np.int64(10), not 10 - and
/// a RangeIndex's a Python int; any other as [`row_label_to_py`]
/// (br-frankenpandas-x8ql1). Iteration and `tolist` stay Python scalars.
/// The name `set_names(names)` gives a flat index: a name (any hashable,
/// typed) or a list / tuple of one - another length is pandas' ValueError.
fn flat_index_name(names: &Bound<'_, PyAny>) -> PyResult<Option<LabelName>> {
    if names.is_instance_of::<PyList>() || names.is_instance_of::<PyTuple>() {
        let items = names.try_iter()?.collect::<PyResult<Vec<_>>>()?;
        if items.len() != 1 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of new names must be 1, got {}",
                items.len()
            )));
        }
        return py_axis_name(&items[0]);
    }
    py_axis_name(names)
}

/// numpy's axis check for a 1-D reduction (pandas' validate_minmax_axis):
/// None, 0 or -1, anything else its ValueError.
fn one_dim_axis(axis: Option<i64>) -> PyResult<()> {
    match axis {
        None | Some(0 | -1) => Ok(()),
        Some(_) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "`axis` must be fewer than the number of dimensions (1)",
        )),
    }
}

/// pandas' `Index.min` / `max` (`largest`) with `axis` / `skipna`: the least
/// or greatest present label; NaN when the index is empty, all missing, or
/// holds a missing label with skipna=False; a missing label beside text is
/// Python's TypeError comparing str with float, as pandas' object reduction
/// raises. A null label sorts after every concrete one, so the max of a
/// float index holding NaN was the NaN (br-frankenpandas-zvn7a).
fn index_extreme(
    py: Python<'_>,
    index: &Index,
    largest: bool,
    axis: Option<i64>,
    skipna: bool,
) -> PyResult<Py<PyAny>> {
    one_dim_axis(axis)?;
    let labels = index.labels();
    let present: Vec<&IndexLabel> = labels.iter().filter(|label| !label.is_missing()).collect();
    let nan = || pyo3::types::PyFloat::new(py, f64::NAN).into_any().unbind();
    if present.is_empty() || (!skipna && present.len() < labels.len()) {
        return Ok(nan());
    }
    if present.len() < labels.len()
        && present
            .iter()
            .any(|label| matches!(label, IndexLabel::Utf8(_)))
    {
        let symbol = if largest { ">=" } else { "<=" };
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "'{symbol}' not supported between instances of 'str' and 'float'"
        )));
    }
    let best = present
        .iter()
        .copied()
        .reduce(|best, label| {
            if (largest && label > best) || (!largest && label < best) {
                label
            } else {
                best
            }
        })
        .expect("a present label");
    index_scalar_to_py(py, index, best)
}

/// pandas' `Index.argmin` / `argmax` (`largest`) with `axis` / `skipna`: the
/// first position of the least / greatest present label; an empty index is
/// numpy's ValueError; a missing label with skipna=False, or every label
/// missing, is -1 with pandas' FutureWarning (`owner` names the class); a
/// missing label beside text is Python's TypeError. argmax found the NaN,
/// which sorts last (br-frankenpandas-zvn7a).
fn index_arg_extreme(
    py: Python<'_>,
    index: &Index,
    owner: &str,
    largest: bool,
    axis: Option<i64>,
    skipna: bool,
) -> PyResult<Py<PyAny>> {
    one_dim_axis(axis)?;
    let labels = index.labels();
    if labels.is_empty() {
        let op = if largest { "argmax" } else { "argmin" };
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "attempt to get {op} of an empty sequence"
        )));
    }
    let missing = labels.iter().filter(|label| label.is_missing()).count();
    if missing > 0 && (!skipna || missing == labels.len()) {
        let message = std::ffi::CString::new(format!(
            "The behavior of {owner}.argmax/argmin with skipna=False and NAs, or with all-NAs \
             is deprecated. In a future version this will raise ValueError."
        ))
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        PyErr::warn(
            py,
            &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
            &message,
            1,
        )?;
        return (-1_i64).into_py_any(py);
    }
    if missing > 0
        && labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Utf8(_)))
    {
        let symbol = if largest { ">" } else { "<" };
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "'{symbol}' not supported between instances of 'float' and 'str'"
        )));
    }
    let mut best: Option<usize> = None;
    for (position, label) in labels.iter().enumerate() {
        if label.is_missing() {
            continue;
        }
        let better = best.is_none_or(|at| {
            let current = &labels[at];
            (largest && label > current) || (!largest && label < current)
        });
        if better {
            best = Some(position);
        }
    }
    NumpyInt64::from(best.unwrap_or(0)).into_py_any(py)
}

fn index_scalar_to_py(py: Python<'_>, index: &Index, label: &IndexLabel) -> PyResult<Py<PyAny>> {
    let numeric = |label: &IndexLabel| match label {
        IndexLabel::Int64(value) => Some(Scalar::Int64(*value)),
        IndexLabel::Float64(value) => Some(Scalar::Float64(value.0)),
        _ => None,
    };
    // A MultiIndex row is the tuple of its levels' values, each numeric one
    // a numpy scalar too ((np.int64(2), 'b')).
    if let Some(multi) = index.row_multiindex() {
        let Some(row) = index
            .labels()
            .iter()
            .position(|candidate| candidate == label)
        else {
            return row_label_to_py(py, index, label);
        };
        let parts = (0..multi.nlevels())
            .map(|level| {
                let values = multi.get_level_values(level).map_err(index_error_to_py)?;
                let value = &values.labels()[row];
                match numeric(value) {
                    Some(scalar) => numpy_scalar(py, &scalar),
                    None => index_label_to_py(py, value),
                }
            })
            .collect::<PyResult<Vec<_>>>()?;
        return Ok(PyTuple::new(py, parts)?.into_any().unbind());
    }
    match numeric(label) {
        Some(Scalar::Int64(_)) if index.range_span().is_some() => row_label_to_py(py, index, label),
        Some(scalar) => numpy_scalar(py, &scalar),
        None => row_label_to_py(py, index, label),
    }
}

/// Convert an IndexLabel to a Python object.
fn index_label_to_py(py: Python<'_>, label: &IndexLabel) -> PyResult<Py<PyAny>> {
    match label {
        IndexLabel::Int64(i) => i.into_py_any(py),
        IndexLabel::Utf8(s) => s.into_py_any(py),
        IndexLabel::Timedelta64(ns) => {
            if *ns == Timedelta::NAT {
                nat_object(py)
            } else {
                PyTimedelta { nanos: *ns }.into_py_any(py)
            }
        }
        IndexLabel::Datetime64(ns) => {
            if *ns == Timestamp::NAT {
                nat_object(py)
            } else {
                PyTimestamp {
                    inner: Timestamp::from_nanos(*ns),
                    unit: StampUnit::Ns,
                }
                .into_py_any(py)
            }
        }
        IndexLabel::Float64(f) => {
            if f.0.is_nan() {
                f64::NAN.into_py_any(py)
            } else {
                f.0.into_py_any(py)
            }
        }
        IndexLabel::Bool(b) => b.into_py_any(py),
        // An object label is the Python object (fvsao.66).
        IndexLabel::Object(object) => scalar_to_py(py, &Scalar::Object(object.clone())),
        // A period label is a Period (NaT for its NaT; 45fzr).
        IndexLabel::Period(period) => scalar_to_py(py, &Scalar::Period(*period)),
        // An interval label is an Interval (c27hq).
        IndexLabel::Interval(interval) => PyInterval::of(interval).into_py_any(py),
        IndexLabel::Null(NullKind::NaT) => nat_object(py),
        IndexLabel::Null(NullKind::NaN) => f64::NAN.into_py_any(py),
        IndexLabel::Null(NullKind::Null) => Ok(py.None()),
    }
}

/// The Python key of every row of `index`: a tuple per row when the flat
/// labels carry row MultiIndex levels, as pandas keys a MultiIndex Series,
/// else the label itself (br-frankenpandas-rc0923-epic-rust-parity-bugs-4qg5w.9).
fn row_keys_to_py(py: Python<'_>, index: &Index) -> PyResult<Vec<Py<PyAny>>> {
    let Some(levels) = index.row_multiindex() else {
        // A tz-aware index's keys are Timestamps in its zone.
        return index
            .labels()
            .iter()
            .map(|label| row_label_to_py(py, index, label))
            .collect();
    };
    multiindex_row_keys(py, levels)
}

/// The Python key of every row of `frame`: the tuple of its row MultiIndex
/// (the frame's own, or its index's), else [`row_keys_to_py`]'s. to_dict,
/// iterrows and itertuples read the flat storage labels ('a|1' for a
/// groupby([k, j]) result, naive UTC instants for a tz-aware index;
/// br-frankenpandas-h06ox).
fn frame_row_keys_to_py(py: Python<'_>, frame: &DataFrame) -> PyResult<Vec<Py<PyAny>>> {
    match frame.row_multiindex() {
        Some(levels) => multiindex_row_keys(py, levels),
        None => row_keys_to_py(py, frame.index()),
    }
}

/// The index to_json keys rows by under row MultiIndex `levels`: each row's
/// tuple as Python prints it ("('a', 1)"), as pandas' (the flat storage
/// label 'a, 1' / 'a|1' was written; br-frankenpandas-h06ox).
fn json_tuple_keyed_index(py: Python<'_>, levels: &MultiIndex) -> PyResult<Index> {
    let keys = multiindex_row_keys(py, levels)?
        .into_iter()
        .map(|key| Ok(IndexLabel::Utf8(key.bind(py).str()?.to_string())))
        .collect::<PyResult<Vec<_>>>()?;
    Ok(Index::new(keys))
}

/// A tuple of `levels`' labels per row.
fn multiindex_row_keys(py: Python<'_>, levels: &MultiIndex) -> PyResult<Vec<Py<PyAny>>> {
    (0..levels.len())
        .map(|row| {
            let parts = levels
                .get_tuple(row)
                .unwrap_or_default()
                .into_iter()
                .map(|label| index_label_to_py(py, label))
                .collect::<PyResult<Vec<_>>>()?;
            Ok(pyo3::types::PyTuple::new(py, parts)?.into_any().unbind())
        })
        .collect()
}

/// `index` as the pandas object: a MultiIndex when its labels carry row
/// MultiIndex levels, else a flat Index.
/// A DatetimeIndex field (year, month, dayofweek, ...) as pandas returns it:
/// an Index of numpy's int32 (it was int64; br-frankenpandas-pqjzo), float64
/// with NaN when a NaT is present (it was a list holding None;
/// br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.18).
fn datetime_field_index<T: Into<i64>>(values: Vec<Option<T>>) -> PyIndex {
    let any_nat = values.iter().any(Option::is_none);
    let labels = values
        .into_iter()
        .map(|value| match value {
            Some(value) if any_nat => IndexLabel::Float64(OrderedF64(value.into() as f64)),
            Some(value) => IndexLabel::Int64(value.into()),
            None => IndexLabel::Null(NullKind::NaN),
        })
        .collect();
    let declared = (!any_nat).then_some(fp_index::DeclaredDtype::Int32);
    PyIndex {
        inner: Index::new(labels).with_declared_dtype(declared),
    }
}

/// A DatetimeIndex boolean field (is_month_start, is_leap_year, ...) as pandas
/// returns it: NaT reads as False (it was None; fvsao.18).
fn nat_as_false(flags: Vec<Option<bool>>) -> Vec<bool> {
    flags
        .into_iter()
        .map(|flag| flag.unwrap_or(false))
        .collect()
}

/// A DatetimeIndex text field (day_name, month_name, strftime) as pandas
/// returns it: an object Index with NaN for NaT (fvsao.18).
fn datetime_text_index(values: Vec<Option<String>>) -> PyIndex {
    let labels = values
        .into_iter()
        .map(|value| value.map_or(IndexLabel::Null(NullKind::NaN), IndexLabel::Utf8))
        .collect();
    PyIndex {
        inner: Index::new(labels),
    }
}

fn row_index_to_py(py: Python<'_>, index: &Index) -> PyResult<Py<PyAny>> {
    if let Some(levels) = index.row_multiindex() {
        return Ok(Py::new(
            py,
            PyMultiIndex {
                inner: levels.clone(),
            },
        )?
        .into_any());
    }
    // A default index - a Series or DataFrame built without one,
    // reset_index, a slice of one - comes back as pandas' RangeIndex (it
    // was a plain Index of 0..n; fvsao.18).
    if index.range_span().is_some() {
        return Ok(Py::new(py, PyRangeIndex::initializer(index.clone()))?.into_any());
    }
    // A categorical index (a CategoricalIndex given, set_index of a
    // category column, a categorical groupby key) is pandas'
    // CategoricalIndex (it was a plain Index; br-frankenpandas-cld41).
    if let Some(categorical) = categorical_index_of(index) {
        return Ok(Py::new(py, PyCategoricalIndex { inner: categorical })?.into_any());
    }
    flat_index_to_py(py, index)
}

/// `index` as the CategoricalIndex its category metadata describes - any
/// labels and categories (pd.cut's intervals as Interval objects), a
/// missing label NaN; None for any other index. Only text was held, and
/// intervals went in as their text (br-frankenpandas-lztvp).
fn categorical_index_of(index: &Index) -> Option<CategoricalIndex> {
    let categories = index.categories()?;
    let categorical = CategoricalIndex::with_categories(
        index.labels().to_vec(),
        categories.categories.clone(),
        categories.ordered,
    )
    .ok()?;
    Some(categorical.set_names(index.name().cloned()))
}

/// pandas' refusal of a container's truth value - `bool(s)`, `if df:`,
/// `a and b` over Series - naming the class (each was its length's, so a
/// wrong branch ran silently; br-frankenpandas-99npt).
fn ambiguous_truth_value(object: &Bound<'_, PyAny>) -> PyErr {
    let name = object
        .get_type()
        .name()
        .map_or_else(|_| "object".to_owned(), |name| name.to_string());
    PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
        "The truth value of a {name} is ambiguous. Use a.empty, a.bool(), a.item(), a.any() or a.all()."
    ))
}

/// pandas' DataFrameGroupBy.filter verdict on a group: the result squeezed,
/// then a bool (a missing value drops the group); anything else is pandas'
/// TypeError (a number was read by its truthiness and a one-row Series by
/// its length; br-frankenpandas-99npt).
fn frame_filter_verdict(py: Python<'_>, result: &Bound<'_, PyAny>) -> PyResult<bool> {
    let result = if result.hasattr("squeeze")? {
        result.call_method0("squeeze")?
    } else {
        result.clone()
    };
    let type_name = result.get_type().name()?.to_string();
    if result.is_instance_of::<pyo3::types::PyBool>()
        || matches!(type_name.as_str(), "bool" | "bool_")
    {
        return result.is_truthy();
    }
    if api_is_scalar(&result) && isna(py, &result)?.bind(py).is_truthy()? {
        return Ok(false);
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
        "filter function returned a {type_name}, but expected a scalar bool"
    )))
}

/// pandas' SeriesGroupBy.filter verdict on a group: `notna(b) and b`, a
/// result without a truth value (a Series) pandas' TypeError.
fn series_filter_verdict(py: Python<'_>, result: &Bound<'_, PyAny>) -> PyResult<bool> {
    let verdict = if api_is_scalar(result) && isna(py, result)?.bind(py).is_truthy()? {
        Ok(false)
    } else {
        result.is_truthy()
    };
    verdict.map_err(|err| {
        if err.is_instance_of::<pyo3::exceptions::PyValueError>(py)
            || err.is_instance_of::<pyo3::exceptions::PyTypeError>(py)
        {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "the filter must return a boolean result",
            )
        } else {
            err
        }
    })
}

/// `slice(start, stop)` with numpy int64 bounds, as pandas' searched slices
/// come back (`slice(np.int64(0), np.int64(2), None)`).
fn numpy_slice(py: Python<'_>, start: usize, stop: usize) -> PyResult<Py<PyAny>> {
    py.import("builtins")?
        .getattr("slice")?
        .call1((NumpyInt64::from(start), NumpyInt64::from(stop)))
        .map(Bound::unbind)
}

/// The rows of a datetime-like index inside the period a date string names,
/// `first..=last` (`instants` each row's instant - a DatetimeIndex's wall
/// clock, a PeriodIndex's start - None for NaT), as pandas' partial-string
/// `get_loc` gives them: over a monotonic index the slice of them (empty
/// where the period falls between two rows; a KeyError only past either
/// end), else their positions.
fn partial_date_rows(
    py: Python<'_>,
    key: &Bound<'_, PyAny>,
    monotonic: bool,
    instants: &[Option<i64>],
    (first, last): (i64, i64),
) -> PyResult<Py<PyAny>> {
    if monotonic {
        if let (Some(Some(low)), Some(Some(high))) = (instants.first(), instants.last())
            && (last < *low || first > *high)
        {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                key.clone().unbind(),
            ));
        }
        let start = instants.partition_point(|at| at.is_some_and(|at| at < first));
        let stop = instants.partition_point(|at| at.is_some_and(|at| at <= last));
        return numpy_slice(py, start, stop);
    }
    instants
        .iter()
        .enumerate()
        .filter(|(_, at)| at.is_some_and(|at| (first..=last).contains(&at)))
        .map(|(position, _)| i64::try_from(position).unwrap_or(i64::MAX))
        .collect::<IndexerArray>()
        .into_py_any(py)
}

/// `iter(index)`: its elements as `index[i]` gives them. The Datetime /
/// Timedelta / Period / Interval / Categorical / MultiIndex classes had no
/// `__iter__` - `for` reached them through the `__getitem__` fallback - so
/// they were not `collections.abc.Iterable`, as pandas' are
/// (br-frankenpandas-84w06).
fn iter_by_position(index: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
    let items = (0..index.len()?)
        .map(|position| index.get_item(position))
        .collect::<PyResult<Vec<_>>>()?;
    Ok(PyList::new(index.py(), items)?
        .as_any()
        .try_iter()?
        .into_any()
        .unbind())
}

/// pandas' `to_period` of a row index: a DatetimeIndex as the PeriodIndex
/// of `freq` (its own freq by default), its name kept; any other index is
/// pandas' TypeError "unsupported Type ..." (45fzr).
fn index_to_period(py: Python<'_>, index: &Index, freq: Option<&str>) -> PyResult<Index> {
    let object = row_index_to_py(py, index)?;
    let object = object.bind(py);
    let Ok(datetimes) = object.extract::<PyRef<'_, PyDatetimeIndex>>() else {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "unsupported Type {}",
            object.get_type().name()?
        )));
    };
    Ok(datetimes.to_period(freq)?.inner.to_index())
}

/// pandas' `to_timestamp` of a row index: a PeriodIndex as the
/// DatetimeIndex of its periods' start (or end) instants - the starts with
/// the freq they follow inferred, as pandas; its end instants (the next
/// start less a nanosecond there) carry none - and any other index pandas'
/// TypeError "unsupported Type ..." (45fzr). A target `freq` is refused.
fn index_to_timestamp(
    py: Python<'_>,
    index: &Index,
    freq: Option<&str>,
    how: &str,
) -> PyResult<Index> {
    unsupported_params("to_timestamp", &[("freq", freq.is_none())])?;
    let Some(periods) = PeriodIndex::from_index(index).filter(|_| !index.is_empty()) else {
        let object = row_index_to_py(py, index)?;
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "unsupported Type {}",
            object.bind(py).get_type().name()?
        )));
    };
    let stamps = PyPeriodIndex { inner: periods }.to_timestamp(how)?.inner;
    let inferred = if how.starts_with(['s', 'S']) {
        stamps.inferred_freq()
    } else {
        None
    };
    Ok(stamps.with_freq(inferred).into_index())
}

/// A flat index as pandas' class for its labels: instants and durations
/// come back as pandas' DatetimeIndex / TimedeltaIndex, with their
/// accessors (df.index.year, .month_name(), .normalize();
/// groupby(df.index.month)); every index was a plain Index
/// (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.18) - a
/// MultiIndex level too (br-frankenpandas-stofr).
fn flat_index_to_py(py: Python<'_>, index: &Index) -> PyResult<Py<PyAny>> {
    let labels = index.labels();
    // An empty index keeps its source's class (pandas' empty slice of a
    // DatetimeIndex is one; dwyud); one declared object is a plain Index
    // whatever it holds (pandas' astype(object); i20vm).
    match index.declared_dtype() {
        Some(fp_index::DeclaredDtype::Object) => {
            return Ok(Py::new(
                py,
                PyIndex {
                    inner: index.clone(),
                },
            )?
            .into_any());
        }
        Some(fp_index::DeclaredDtype::Datetime64) if labels.is_empty() => {
            if let Ok(inner) = DatetimeIndex::from_index(index.clone()) {
                return Ok(Py::new(py, PyDatetimeIndex { inner })?.into_any());
            }
        }
        Some(fp_index::DeclaredDtype::Timedelta64) if labels.is_empty() => {
            if let Ok(inner) = TimedeltaIndex::from_index(index.clone()) {
                return Ok(Py::new(py, PyTimedeltaIndex { inner })?.into_any());
            }
        }
        _ => {}
    }
    if !labels.is_empty() {
        if labels
            .iter()
            .all(|label| matches!(label, IndexLabel::Datetime64(_)))
            && let Ok(inner) = DatetimeIndex::from_index(index.clone())
        {
            return Ok(Py::new(py, PyDatetimeIndex { inner })?.into_any());
        }
        // NaT labels (alone, or beside instants) are a DatetimeIndex too,
        // as pandas' Index([NaT, NaT]) (br-frankenpandas-mzes1).
        if labels.iter().all(|label| {
            matches!(
                label,
                IndexLabel::Datetime64(_) | IndexLabel::Null(NullKind::NaT)
            )
        }) {
            let instants = labels
                .iter()
                .map(|label| match label {
                    IndexLabel::Null(_) => IndexLabel::Datetime64(i64::MIN),
                    other => other.clone(),
                })
                .collect();
            if let Ok(inner) =
                DatetimeIndex::from_index(Index::new(instants).rename_index(index.name()))
            {
                return Ok(Py::new(py, PyDatetimeIndex { inner })?.into_any());
            }
        }
        if labels
            .iter()
            .all(|label| matches!(label, IndexLabel::Timedelta64(_)))
            && let Ok(inner) = TimedeltaIndex::from_index(index.clone())
        {
            return Ok(Py::new(py, PyTimedeltaIndex { inner })?.into_any());
        }
        // Durations beside missing labels (NaT, NaN, None) are a
        // TimedeltaIndex with NaT, as pandas infers one (a plain Index of
        // durations and nan; br-frankenpandas-a2t82).
        if labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Timedelta64(_)))
            && labels
                .iter()
                .all(|label| matches!(label, IndexLabel::Timedelta64(_) | IndexLabel::Null(_)))
        {
            let durations = labels
                .iter()
                .map(|label| match label {
                    IndexLabel::Null(_) => IndexLabel::Timedelta64(fp_types::Timedelta::NAT),
                    other => other.clone(),
                })
                .collect();
            if let Ok(inner) =
                TimedeltaIndex::from_index(Index::new(durations).rename_index(index.name()))
            {
                return Ok(Py::new(py, PyTimedeltaIndex { inner })?.into_any());
            }
        }
        // Periods of one freq are a PeriodIndex (they were text; 45fzr).
        if let Some(inner) = PeriodIndex::from_index(index) {
            return Ok(Py::new(py, PyPeriodIndex { inner })?.into_any());
        }
        // Intervals are an IntervalIndex (they were text; c27hq), a missing
        // label beside them a missing interval on their closed side (a
        // where / reindex over one; tjfdd).
        let closed = labels.iter().find_map(|label| match label {
            IndexLabel::Interval(interval) => Some(interval.closed.to_string()),
            _ => None,
        });
        if let Some(closed) = closed
            && labels
                .iter()
                .all(|label| matches!(label, IndexLabel::Interval(_) | IndexLabel::Null(_)))
        {
            // A missing one makes the subtype float64, as pandas' (int
            // endpoints print as floats then).
            let gap = labels.iter().any(IndexLabel::is_missing);
            let intervals = labels
                .iter()
                .map(|label| match label {
                    IndexLabel::Interval(interval) => {
                        let mut interval = PyInterval::of(interval);
                        interval.int_endpoints &= !gap;
                        interval
                    }
                    _ => PyInterval::missing(&closed),
                })
                .collect();
            return Ok(Py::new(
                py,
                PyIntervalIndex {
                    intervals,
                    name: index.name().map(ToString::to_string),
                },
            )?
            .into_any());
        }
    }
    Ok(Py::new(
        py,
        PyIndex {
            inner: index.clone(),
        },
    )?
    .into_any())
}

/// Labels as pandas' Index holds numbers beside a missing one or ints beside
/// floats: float64, the missing label NaN - `Index([2.0, None, 1.0])`,
/// `Index([1, None])` and `Index([1.5, 2])`, whose ints become floats. The
/// None stayed (printed None where pandas prints NaN). Any other mix is left
/// as it is (an object Index keeps None).
#[allow(clippy::cast_precision_loss)] // pandas widens the ints the same way
fn float_index_labels(labels: Vec<IndexLabel>) -> Vec<IndexLabel> {
    let numeric =
        |label: &IndexLabel| matches!(label, IndexLabel::Int64(_) | IndexLabel::Float64(_));
    let missing = |label: &IndexLabel| matches!(label, IndexLabel::Null(_));
    // Ints beside a float are float64 too (Index([1.5, 2]) was object;
    // br-frankenpandas-u6p7i).
    let mixed = labels
        .iter()
        .any(|label| matches!(label, IndexLabel::Int64(_)))
        && labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Float64(_)));
    if !(mixed || labels.iter().any(missing))
        || !labels.iter().any(numeric)
        || !labels.iter().all(|label| numeric(label) || missing(label))
    {
        return labels;
    }
    labels
        .into_iter()
        .map(|label| match label {
            IndexLabel::Int64(value) => IndexLabel::Float64(fp_index::OrderedF64(value as f64)),
            IndexLabel::Null(_) => IndexLabel::Null(NullKind::NaN),
            other => other,
        })
        .collect()
}

/// `index` with [`float_index_labels`] applied when they change it (a
/// missing label, or ints beside floats), its name kept. Aware instants
/// are left as they are (rebuilding them dropped the zone when a NaT was
/// among them; br-frankenpandas-wtu8e).
fn float_labelled(index: Index) -> Index {
    let labels = index.labels();
    let mixed = labels
        .iter()
        .any(|label| matches!(label, IndexLabel::Int64(_)))
        && labels
            .iter()
            .any(|label| matches!(label, IndexLabel::Float64(_)));
    if index.tz().is_some() || (!mixed && !index.hasnans()) {
        return index;
    }
    Index::new(float_index_labels(labels.to_vec())).rename_index(index.name())
}

/// The rows an `index=` argument gives `len` values: a DatetimeIndex is its
/// own index - an O(1) clone sharing its labels, a date_range's lazy range
/// kept, where its million labels were copied out
/// (br-frankenpandas-so0mr) - anything else its extracted labels.
fn index_arg_rows(index: &Bound<'_, PyAny>, len: usize) -> PyResult<Index> {
    let rows = match index.extract::<PyRef<'_, PyDatetimeIndex>>() {
        Ok(dti) => dti.inner.as_index().clone(),
        Err(_) => Index::new(extract_index_labels(Some(index), len)?),
    };
    if rows.len() != len {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "Length of values ({len}) does not match length of index ({})",
            rows.len()
        )));
    }
    Ok(rows)
}

/// Extract index labels from an optional Python object (Index, list, tuple, sequence, or None).
fn extract_index_labels(
    index: Option<&Bound<'_, PyAny>>,
    default_len: usize,
) -> PyResult<Vec<IndexLabel>> {
    if let Some(index) = index {
        if let Ok(py_idx) = plain_index_ref(index) {
            Ok(py_idx.inner.labels().to_vec())
        } else if let Ok(dti) = index.extract::<PyRef<'_, PyDatetimeIndex>>() {
            Ok(dti.inner.clone().into_index().labels().to_vec())
        } else if let Ok(tdi) = index.extract::<PyRef<'_, PyTimedeltaIndex>>() {
            Ok(tdi.inner.clone().into_index().labels().to_vec())
        } else if let Ok(ci) = index.extract::<PyRef<'_, PyCategoricalIndex>>() {
            Ok(ci.inner.to_index().labels().to_vec())
        } else if let Ok(pi) = index.extract::<PyRef<'_, PyPeriodIndex>>() {
            Ok(pi.inner.to_index().labels().to_vec())
        } else if let Ok(mi) = index.extract::<PyRef<'_, PyMultiIndex>>() {
            Ok(mi.inner.to_flat_index(", ").labels().to_vec())
        } else if let Ok(s) = index.extract::<PyRef<'_, PySeries>>() {
            // A Series given as an index is its VALUES, as pandas (its own
            // index was taken, so `index=pd.to_datetime(series)` lost the
            // dates).
            Ok(s.inner
                .column()
                .values()
                .iter()
                .map(scalar_to_index_label_converter)
                .collect())
        } else if let Ok(list) = index.cast::<PyList>() {
            list.iter()
                .map(|item| py_to_index_label(&item))
                .collect::<PyResult<Vec<_>>>()
                .map(float_index_labels)
        } else if let Ok(tuple) = index.cast::<PyTuple>() {
            tuple
                .iter()
                .map(|item| py_to_index_label(&item))
                .collect::<PyResult<Vec<_>>>()
                .map(float_index_labels)
        } else if let Ok(iter) = index.try_iter() {
            let mut labels = Vec::new();
            for item in iter {
                labels.push(py_to_index_label(&item?)?);
            }
            Ok(float_index_labels(labels))
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Index must be a sequence or Index",
            ))
        }
    } else {
        Ok((0..default_len)
            .map(|i| IndexLabel::Int64(i as i64))
            .collect())
    }
}

/// A FrameError from replacing an axis, in pandas' words for a wrong length.
fn axis_length_error_to_py(err: FrameError) -> PyErr {
    match err {
        FrameError::LengthMismatch {
            index_len,
            column_len,
        } => PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "Length mismatch: Expected axis has {column_len} elements, new values have \
             {index_len} elements"
        )),
        other => frame_error_to_py(other),
    }
}

/// `frame` with `multi` as its column axis; the storage keys join each
/// column's levels with '_'.
fn frame_with_column_multiindex(
    frame: &DataFrame,
    multi: fp_index::MultiIndex,
) -> PyResult<DataFrame> {
    let keys = (0..multi.len())
        .map(|position| {
            let labels = multi.get_tuple(position).unwrap_or_default();
            IndexLabel::Utf8(
                labels
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>()
                    .join("_"),
            )
        })
        .collect();
    frame
        .set_axis(keys, 1)
        .and_then(|frame| frame.with_columns_multiindex(Some(multi)))
        .map_err(axis_length_error_to_py)
}

/// The row axis `obj.index = value` sets, as pandas builds it: an Index
/// keeps its labels and name, a Series gives its values and name, a list or
/// other iterable its items, unnamed.
fn index_from_axis_value(value: &Bound<'_, PyAny>) -> PyResult<Index> {
    if value.is_instance_of::<pyo3::types::PyString>() {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "Index(...) must be called with a collection of some kind, {} was passed",
            value.repr()?
        )));
    }
    // A MultiIndex stays one: its flat labels with the levels attached, as
    // the constructors keep one (it was refused; r0hk0). A list of tuples is
    // a flat Index of tuple labels, as pandas' (not a MultiIndex).
    if let Ok(multi) = value.extract::<PyRef<'_, PyMultiIndex>>() {
        return multi
            .inner
            .to_flat_index(", ")
            .with_row_multiindex(multi.inner.clone())
            .map_err(index_error_to_py);
    }
    // A tz-aware DatetimeIndex or datetime Series keeps its zone (it was
    // taken as naive UTC labels).
    let zone = index_arg_zone(value);
    if let Ok(series) = value.extract::<PyRef<'_, PySeries>>() {
        let labels = series
            .inner
            .column()
            .values()
            .iter()
            .map(scalar_to_index_label_converter)
            .collect();
        let name = series.inner.name();
        return Index::new(labels)
            .rename_index((!name.is_empty()).then_some(name))
            .with_tz(zone.as_deref())
            .map_err(index_error_to_py);
    }
    let name = value
        .getattr("name")
        .ok()
        .and_then(|name| name.extract::<String>().ok());
    let labels = extract_index_labels(Some(value), 0)?;
    // A DatetimeIndex / TimedeltaIndex keeps its freq, as the constructors'
    // index= does (`s.index = dr` dropped it).
    Index::new(labels)
        .rename_index(name.as_deref())
        .with_tz(zone.as_deref())
        .map(|index| index.with_freq(index_arg_freq(value)))
        .map_err(index_error_to_py)
}

/// The name a Python column label keys its column under: a string itself,
/// any other label its typed label's [`fp_frame::column_key`] - the key its
/// recorded label carries (`str(nan)` is 'nan' where the key is 'NaN', so a
/// NaN column label stayed the text 'nan'; br-frankenpandas-qacqs) - and
/// `str()` for one with no typed form.
fn column_name_of(item: &Bound<'_, PyAny>) -> PyResult<String> {
    if let Ok(text) = item.extract::<String>() {
        return Ok(text);
    }
    match py_to_index_label(item) {
        Ok(label) => Ok(fp_frame::column_key(&label)),
        Err(_) => Ok(item.str()?.to_str()?.to_string()),
    }
}

/// The labels of a `columns=` list or tuple as pandas' Index of them: a
/// string itself, any other item its typed label (its text where it has
/// none), and numbers beside a missing label float64 with NaN, as
/// `Index([1, 2, None])` is [1.0, 2.0, nan] (they were 1, 2, None;
/// br-frankenpandas-qacqs).
#[allow(clippy::cast_precision_loss)] // pandas' int64 -> float64 widening
fn columns_arg_labels(items: &[Bound<'_, PyAny>]) -> PyResult<Vec<IndexLabel>> {
    let mut labels = items
        .iter()
        .map(|item| {
            if let Ok(text) = item.extract::<String>() {
                return Ok(IndexLabel::Utf8(text));
            }
            match py_to_index_label(item) {
                Ok(label) => Ok(label),
                Err(_) => Ok(IndexLabel::Utf8(item.str()?.to_str()?.to_string())),
            }
        })
        .collect::<PyResult<Vec<_>>>()?;
    let number =
        |label: &IndexLabel| matches!(label, IndexLabel::Int64(_) | IndexLabel::Float64(_));
    let missing = |label: &IndexLabel| matches!(label, IndexLabel::Null(_));
    if labels.iter().all(|label| number(label) || missing(label))
        && labels.iter().any(number)
        && labels.iter().any(missing)
    {
        for label in &mut labels {
            *label = match &*label {
                IndexLabel::Int64(value) => {
                    IndexLabel::Float64(fp_index::OrderedF64(*value as f64))
                }
                IndexLabel::Null(_) => IndexLabel::Null(NullKind::NaN),
                other => other.clone(),
            };
        }
    }
    Ok(labels)
}

/// Extract column names from an optional Python object (Index, list, tuple, sequence, or None).
fn extract_columns_names(columns: Option<&Bound<'_, PyAny>>) -> PyResult<Option<Vec<String>>> {
    let Some(cols) = columns else {
        return Ok(None);
    };
    if let Ok(idx) = plain_index_ref(cols) {
        let names = idx.inner.labels().iter().map(|l| l.to_string()).collect();
        return Ok(Some(names));
    }
    if cols.is_instance_of::<PyList>() || cols.is_instance_of::<PyTuple>() {
        let items: Vec<Bound<'_, PyAny>> = cols.try_iter()?.collect::<PyResult<_>>()?;
        let names = columns_arg_labels(&items)?
            .iter()
            .map(fp_frame::column_key)
            .collect();
        return Ok(Some(names));
    }
    if let Ok(iter) = cols.try_iter() {
        let mut names = Vec::new();
        for item in iter {
            names.push(column_name_of(&item?)?);
        }
        return Ok(Some(names));
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
        "columns must be an iterable",
    ))
}

/// Convert an IndexLabel to a Scalar.
fn index_label_to_scalar(label: &IndexLabel) -> Scalar {
    match label {
        IndexLabel::Int64(i) => Scalar::Int64(*i),
        IndexLabel::Utf8(s) => Scalar::Utf8(s.clone()),
        IndexLabel::Timedelta64(ns) => Scalar::Timedelta64(*ns),
        IndexLabel::Datetime64(ns) => Scalar::Datetime64(*ns),
        IndexLabel::Float64(f) => Scalar::Float64(f.0),
        IndexLabel::Bool(b) => Scalar::Bool(*b),
        IndexLabel::Object(object) => Scalar::Object(object.clone()),
        IndexLabel::Period(period) => Scalar::Period(*period),
        IndexLabel::Interval(interval) => Scalar::Interval(*interval),
        IndexLabel::Null(k) => Scalar::Null(*k),
    }
}

/// Python wrapper for Index string accessor methods.
#[pyclass(name = "IndexStringMethods", from_py_object)]
#[derive(Clone)]
pub struct PyIndexStringMethods {
    pub(crate) inner: Index,
}

/// pandas' `Index.str`: every method is the Series accessor's over the
/// labels, its result wrapped as pandas' Index accessor wraps it (see
/// [`PyIndexStrMethod`]). It had eight methods of its own - lower, upper,
/// strip, len, contains, startswith, endswith, replace - with no regex (a
/// pattern like r'\d' was looked for literally), no case= / na=, lists for
/// numpy arrays, and the Index name dropped.
#[pymethods]
impl PyIndexStringMethods {
    fn __getattr__(&self, py: Python<'_>, name: &str) -> PyResult<PyIndexStrMethod> {
        // Only what the Series accessor has (anything else raises its
        // AttributeError).
        let probe = PySeries {
            inner: Series::from_values("", Vec::new(), Vec::new()).map_err(frame_error_to_py)?,
        }
        .into_bound_py_any(py)?;
        probe.getattr("str")?.getattr(name)?;
        Ok(PyIndexStrMethod {
            index: self.inner.clone(),
            name: name.to_owned(),
        })
    }
}

/// One `Index.str` method, bound to the index (see [`PyIndexStringMethods`]).
#[pyclass(name = "IndexStrMethod")]
pub struct PyIndexStrMethod {
    index: Index,
    name: String,
}

#[pymethods]
impl PyIndexStrMethod {
    /// The Series accessor's method over the labels; its result as pandas'
    /// Index accessor gives it: a bool Series with every value present is a
    /// numpy array, any other Series an Index under this index's name, a
    /// frame (expand=True) a MultiIndex (extract's stays a frame), anything
    /// else (str.cat's string) itself.
    #[pyo3(signature = (*args, **kwargs))]
    fn __call__(
        &self,
        py: Python<'_>,
        args: &Bound<'_, PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        let values: Vec<Scalar> = self
            .index
            .labels()
            .iter()
            .map(index_label_to_scalar)
            .collect();
        let positions = (0..values.len())
            .map(|position| IndexLabel::Int64(i64::try_from(position).unwrap_or(i64::MAX)))
            .collect();
        let series = PySeries {
            inner: Series::from_values("", positions, values).map_err(frame_error_to_py)?,
        }
        .into_bound_py_any(py)?;
        let result = series
            .getattr("str")?
            .call_method(self.name.as_str(), args, kwargs)?;
        if let Ok(frame) = result.extract::<PyRef<'_, PyDataFrame>>() {
            // extract's frame stays one; get_dummies' levels are named after
            // its columns, the rest (split, partition) unnamed.
            if matches!(self.name.as_str(), "extract" | "extractall") {
                return Ok(result.unbind());
            }
            // A split's short row is padded with NaN over an Index (None
            // over a Series; it was None; br-frankenpandas-fvwrq).
            let mut inner = frame.inner.clone();
            if matches!(self.name.as_str(), "split" | "rsplit") {
                for name in frame.inner.column_names() {
                    let Some(column) = frame.inner.column(name) else {
                        continue;
                    };
                    let cells = column
                        .values()
                        .iter()
                        .map(|cell| match cell {
                            Scalar::Null(NullKind::Null) => Scalar::Null(NullKind::NaN),
                            other => other.clone(),
                        })
                        .collect();
                    let padded = Column::from_values(cells).map_err(column_error_to_py)?;
                    inner = inner
                        .with_column(name.clone(), padded)
                        .map_err(frame_error_to_py)?;
                }
            }
            let frame = PyDataFrame { inner };
            let mut multi = py
                .get_type::<PyMultiIndex>()
                .call_method1("from_frame", (frame,))?
                .extract::<PyMultiIndex>()?;
            let nlevels = multi.inner.nlevels();
            if self.name != "get_dummies" {
                multi.inner = multi.inner.set_names(vec![None; nlevels]);
            }
            let multi = multi.into_bound_py_any(py)?;
            // One level is its Index, as pandas'.
            if nlevels == 1 {
                return Ok(multi.call_method1("get_level_values", (0,))?.unbind());
            }
            return Ok(multi.unbind());
        }
        let Ok(result) = result.extract::<PyRef<'_, PySeries>>() else {
            return Ok(result.unbind());
        };
        let column = result.inner.column();
        if column.dtype() == DType::Bool && column.validity().all() {
            return Ok(column_ndarray(py, column)?.unbind());
        }
        let labels = column
            .values()
            .iter()
            .map(scalar_to_index_label_converter)
            .collect();
        PyIndex {
            inner: Index::new(labels).rename_index(self.index.name()),
        }
        .into_py_any(py)
    }
}

/// pandas' result dtype for a groupby reduction `op` over a nullable (masked)
/// column: sum / prod of ints or bools Int64, of floats Float64; min / max /
/// first / last the column's own; mean / median / std / var / sem / skew
/// Float64; count / size Int64; any / all boolean. None for a numpy column
/// or an op that stays numpy (nunique, idxmax). They came back numpy
/// (float64 / int64 / object).
fn masked_reduction_dtype(source: &DType, op: &str) -> Option<DType> {
    if !source.is_nullable() {
        return None;
    }
    let numeric = if *source == DType::Float64Nullable {
        DType::Float64Nullable
    } else {
        DType::Int64Nullable
    };
    Some(match op.split('(').next().unwrap_or(op) {
        "sum" | "prod" | "cumsum" | "cumprod" => numeric,
        "min" | "max" | "first" | "last" | "cummin" | "cummax" => source.clone(),
        "mean" | "median" | "std" | "var" | "sem" | "skew" => DType::Float64Nullable,
        "count" | "size" => DType::Int64Nullable,
        "any" | "all" => DType::BoolNullable,
        _ => return None,
    })
}

/// A column numeric_only reduces: int64 / float64, a bool column without a
/// missing value (with one it is pandas' object column; ildvj), and pandas'
/// masked Int64 / Float64 / boolean (they were left out;
/// br-frankenpandas-8u5eh).
fn numeric_only_column(column: &Column) -> bool {
    match column.dtype() {
        DType::Bool => !column.has_any_missing(),
        dtype => matches!(
            dtype,
            DType::Int64
                | DType::Float64
                | DType::Int64Nullable
                | DType::Float64Nullable
                | DType::BoolNullable
        ),
    }
}

/// pandas' dtype for a frame reduction `op`'s answer over one column of
/// `dtype`: sum / prod make bools ints, min / max keep the dtype, anything
/// else is a float - each masked for a masked column. None for any other
/// column (object, text, temporal), which is answered as it was
/// (br-frankenpandas-8u5eh).
fn column_answer_dtype(op: &str, dtype: &DType) -> Option<DType> {
    let (int, float) = if dtype.is_nullable() {
        (DType::Int64Nullable, DType::Float64Nullable)
    } else {
        (DType::Int64, DType::Float64)
    };
    match dtype {
        DType::Float64 | DType::Float64Nullable => Some(float),
        DType::Int64 | DType::Int64Nullable | DType::Bool | DType::BoolNullable => Some(match op {
            "sum" | "prod" => int,
            "min" | "max" => dtype.clone(),
            _ => float,
        }),
        _ => None,
    }
}

/// pandas' common dtype of a frame reduction's per-column answers: one
/// dtype stays itself, a bool beside a number is object (None), bools are
/// bool, numbers int or - any float among them - float, masked when any
/// answer is (br-frankenpandas-8u5eh).
fn common_answer_dtype(answers: &[DType]) -> Option<DType> {
    let first = answers.first()?;
    if answers.iter().all(|answer| answer == first) {
        return Some(first.clone());
    }
    let boolish = |answer: &DType| matches!(answer, DType::Bool | DType::BoolNullable);
    let masked = answers.iter().any(DType::is_nullable);
    if answers.iter().any(boolish) {
        if !answers.iter().all(boolish) {
            return None;
        }
        return Some(if masked {
            DType::BoolNullable
        } else {
            DType::Bool
        });
    }
    let float = answers
        .iter()
        .any(|answer| matches!(answer, DType::Float64 | DType::Float64Nullable));
    Some(match (float, masked) {
        (true, true) => DType::Float64Nullable,
        (true, false) => DType::Float64,
        (false, true) => DType::Int64Nullable,
        (false, false) => DType::Int64,
    })
}

/// A reduction's value as an answer of `dtype`: a bool's 0.0 / 1.0 back to
/// the bool, a whole float an int, an int a float, a missing value that
/// dtype's own missing value (pd.NA for a masked one; 8u5eh).
fn as_answer(value: &Scalar, dtype: &DType) -> Scalar {
    if value.is_missing() {
        return Scalar::missing_for_dtype(dtype.clone());
    }
    match (dtype, value) {
        (DType::Bool | DType::BoolNullable, Scalar::Float64(v)) => Scalar::Bool(*v != 0.0),
        (DType::Bool | DType::BoolNullable, Scalar::Int64(v)) => Scalar::Bool(*v != 0),
        // Whole and within i64: the cast is exact.
        (DType::Int64 | DType::Int64Nullable, Scalar::Float64(v))
            if v.fract() == 0.0 && v.abs() < 9.0e18 =>
        {
            Scalar::Int64(*v as i64)
        }
        (DType::Int64 | DType::Int64Nullable, Scalar::Bool(v)) => Scalar::Int64(i64::from(*v)),
        (DType::Float64 | DType::Float64Nullable, Scalar::Int64(v)) => Scalar::Float64(*v as f64),
        (DType::Float64 | DType::Float64Nullable, Scalar::Bool(v)) => {
            Scalar::Float64(f64::from(u8::from(*v)))
        }
        _ => value.clone(),
    }
}

/// A groupby reduction's Series in its masked dtype (see
/// [`masked_reduction_dtype`]).
fn masked_reduction(source: &DType, op: &str, result: Series) -> PyResult<Series> {
    let Some(target) = masked_reduction_dtype(source, op) else {
        return Ok(result);
    };
    if result.column().dtype() == target {
        return Ok(result);
    }
    let column = result.column().astype(target).map_err(column_error_to_py)?;
    Series::new(result.name(), result.index().clone(), column).map_err(frame_error_to_py)
}

/// pandas' `limit_area=` of ffill / bfill: Some(true) for 'inside' (fill only
/// between a column's first and last values), Some(false) for 'outside'
/// (only before the first or after the last), None for every gap.
fn fill_limit_area(limit_area: Option<&Bound<'_, PyAny>>) -> PyResult<Option<bool>> {
    let Some(area) = limit_area.filter(|area| !area.is_none()) else {
        return Ok(None);
    };
    match area.extract::<String>()?.as_str() {
        "inside" => Ok(Some(true)),
        "outside" => Ok(Some(false)),
        other => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "Invalid limit_area: expecting one of ['inside', 'outside'], got {other}."
        ))),
    }
}

/// `filled` with the fills `limit_area` forbids undone: a value missing in
/// `original` stays missing where it lies outside (for 'inside') or inside
/// (for 'outside') the span from `original`'s first value to its last.
fn restrict_fill_area(
    original: &Column,
    filled: &Column,
    inside: bool,
) -> Result<Column, fp_columnar::ColumnError> {
    let values = original.values();
    let first = values.iter().position(|value| !value.is_missing());
    let last = values.iter().rposition(|value| !value.is_missing());
    let (Some(first), Some(last)) = (first, last) else {
        return Ok(filled.clone());
    };
    let mut out = filled.values().to_vec();
    for (position, value) in values.iter().enumerate() {
        if value.is_missing() && (first < position && position < last) != inside {
            out[position] = value.clone();
        }
    }
    Column::new(filled.dtype(), out)
}

/// A Series fill restricted to its `limit_area` (see [`fill_limit_area`]).
fn series_fill_area(original: &Series, filled: Series, inside: Option<bool>) -> PyResult<Series> {
    let Some(inside) = inside else {
        return Ok(filled);
    };
    let column = restrict_fill_area(original.column(), filled.column(), inside)
        .map_err(column_error_to_py)?;
    Series::new(filled.name(), filled.index().clone(), column).map_err(frame_error_to_py)
}

/// A frame fill down its columns restricted to its `limit_area`.
fn frame_fill_area(
    original: &DataFrame,
    filled: DataFrame,
    inside: Option<bool>,
) -> PyResult<DataFrame> {
    let Some(inside) = inside else {
        return Ok(filled);
    };
    let mut out = filled.clone();
    for name in filled.column_names() {
        let (Some(before), Some(after)) = (original.column(name), filled.column(name)) else {
            continue;
        };
        let column = restrict_fill_area(before, after, inside).map_err(column_error_to_py)?;
        out = out
            .with_column(name.clone(), column)
            .map_err(frame_error_to_py)?;
    }
    Ok(out)
}

/// The positions ordering `index` as pandas' nargsort does: its present
/// labels ascending, or descending with tied labels in index order, and the
/// missing ones after (or before) them in index order.
fn nargsort(index: &Index, ascending: bool, na_first: bool) -> Vec<usize> {
    let labels = index.labels();
    let order = if ascending {
        index.argsort()
    } else {
        let mut order: Vec<usize> = (0..labels.len()).collect();
        order.sort_by(|&a, &b| labels[b].cmp(&labels[a]));
        order
    };
    let (mut missing, present): (Vec<usize>, Vec<usize>) = order
        .into_iter()
        .partition(|&position| labels[position].is_missing());
    missing.sort_unstable();
    if na_first {
        [missing, present].concat()
    } else {
        [present, missing].concat()
    }
}

/// pandas' `Index.get_loc(key)`: the position of a label that occurs once;
/// where it repeats, `slice(first, last + 1)` over a monotonic-increasing
/// index, else a bool mask over the index (it gave the first position). A
/// missing label is pandas' `KeyError(key)`.
fn pandas_get_loc(
    py: Python<'_>,
    index: &Index,
    label: &IndexLabel,
    key: &Bound<'_, PyAny>,
) -> PyResult<Py<PyAny>> {
    let missing = || PyErr::new::<pyo3::exceptions::PyKeyError, _>(key.clone().unbind());
    if index.is_unique() {
        return index.get_loc(label).ok_or_else(missing)?.into_py_any(py);
    }
    let mut positions = index.get_loc_all(label);
    // An int key finds its float label, as the unique lookup does.
    if positions.is_empty()
        && let IndexLabel::Int64(value) = label
    {
        positions = index.get_loc_all(&IndexLabel::Float64(OrderedF64(*value as f64)));
    }
    match positions.as_slice() {
        [] => Err(missing()),
        [only] => only.into_py_any(py),
        [first, .., last] if index.is_monotonic_increasing() => {
            // slice(first, stop): its step None, as pandas'.
            py.get_type::<pyo3::types::PySlice>()
                .call1((*first, *last + 1))?
                .into_py_any(py)
        }
        _ => {
            let mut mask = vec![false; index.len()];
            for position in positions {
                mask[position] = true;
            }
            BoolArray::from(mask).into_py_any(py)
        }
    }
}

/// pandas' `Index.__repr__` (format_object_summary + _format_attrs at the
/// default display.width 80 and display.max_seq_items 100): labels wrapped
/// at 80 columns under `Index([`, the first and last 10 around `...` past
/// 100 labels, non-string labels right-justified once the labels wrap,
/// then `dtype=` / `name=` / `length=`. It printed every label on one line
/// with no dtype.
fn pandas_index_repr(py: Python<'_>, index: &Index) -> PyResult<String> {
    let dtype = index.dtype();
    let items = index
        .labels()
        .iter()
        .map(|label| -> PyResult<String> {
            Ok(match label {
                IndexLabel::Utf8(s) => format!(
                    "'{}'",
                    s.replace('\t', "\\t")
                        .replace('\r', "\\r")
                        .replace('\n', "\\n")
                ),
                // An object Index prints its missing label as it is (None,
                // NaT or nan); the NaN printed None.
                IndexLabel::Null(NullKind::Null) if dtype == "object" => "None".to_owned(),
                IndexLabel::Null(NullKind::NaT) if dtype == "object" => "NaT".to_owned(),
                IndexLabel::Null(_) => "nan".to_owned(),
                other => index_label_to_py(py, other)?.bind(py).str()?.to_string(),
            })
        })
        .collect::<PyResult<Vec<String>>>()?;
    let mut attrs = vec![format!("dtype='{dtype}'")];
    attrs.extend(index.name().map(|name| format!("name='{name}'")));
    Ok(pandas_index_text(
        "Index",
        &items,
        index.inferred_type() != "string",
        attrs,
    ))
}

/// pandas' `<Class>(<summary>, <attrs>)` for an index of `items` (each
/// already formatted as pandas prints it): format_object_summary at the
/// default display.width 80 and display.max_seq_items 100, then `attrs`
/// with `length=` inserted after them (before a trailing `freq=`) once the
/// items are truncated. `justify` right-aligns the items when they wrap.
fn pandas_index_text(
    class: &str,
    items: &[String],
    justify: bool,
    mut attrs: Vec<String>,
) -> String {
    let data = pandas_object_summary(Some(class), items, justify);
    let n = items.len();
    if n > PANDAS_MAX_SEQ_ITEMS {
        let at = if attrs.last().is_some_and(|attr| attr.starts_with("freq=")) {
            attrs.len() - 1
        } else {
            attrs.len()
        };
        attrs.insert(at, format!("length={n}"));
    }
    format!("{class}({data}{})", attrs.join(", "))
}

/// pandas' display.max_seq_items default: past it a summary shows the
/// first and last 10 around `...`.
const PANDAS_MAX_SEQ_ITEMS: usize = 100;

/// pandas' `format_object_summary(items, name=class)` at the default
/// display.width 80: `[a, b, ...], ` wrapped under the class name's width
/// (and `],` then a line break once it wraps); without a class, pandas'
/// `indent_for_name=False` (an array's repr), under the `[` alone.
fn pandas_object_summary(class: Option<&str>, items: &[String], justify: bool) -> String {
    const WIDTH: usize = 80;
    const MAX_SEQ_ITEMS: usize = PANDAS_MAX_SEQ_ITEMS;
    let indent = class.map_or(0, |class| class.len() + 1);
    let space1 = format!("\n{}", " ".repeat(indent));
    let space2 = format!("\n{}", " ".repeat(indent + 1));
    let n = items.len();
    let truncated = n > MAX_SEQ_ITEMS;
    let width_of = |text: &str| text.chars().count();
    match n {
        0 => "[], ".to_owned(),
        1 => format!("[{}], ", items[0]),
        2 => format!("[{}, {}], ", items[0], items[1]),
        _ => {
            let (mut head, mut tail) = if truncated {
                let shown = (MAX_SEQ_ITEMS / 2).min(10);
                (items[..shown].to_vec(), items[n - shown..].to_vec())
            } else {
                (Vec::new(), items.to_vec())
            };
            let one_line = width_of(&head.join(", ")) < WIDTH && width_of(&tail.join(", ")) < WIDTH;
            if justify && (truncated || !one_line) {
                let widest = head
                    .iter()
                    .chain(&tail)
                    .map(|s| width_of(s))
                    .max()
                    .unwrap_or(0);
                for text in head.iter_mut().chain(tail.iter_mut()) {
                    *text = format!("{text:>widest$}");
                }
            }
            let extend = |summary: &mut String, line: &mut String, value: &str, width: usize| {
                if width_of(line.trim_end()) + width_of(value.trim_end()) >= width {
                    summary.push_str(line.trim_end());
                    line.clone_from(&space2);
                }
                line.push_str(value);
            };
            let mut summary = String::new();
            let mut line = space2.clone();
            for value in &head {
                extend(&mut summary, &mut line, &format!("{value}, "), WIDTH);
            }
            if truncated {
                summary.push_str(line.trim_end());
                summary.push_str(&space2);
                summary.push_str("...");
                line.clone_from(&space2);
            }
            if let Some((last, rest)) = tail.split_last() {
                for value in rest {
                    extend(&mut summary, &mut line, &format!("{value}, "), WIDTH);
                }
                extend(&mut summary, &mut line, last, WIDTH - 2);
            }
            summary.push_str(&line);
            summary.push_str("],");
            if width_of(&summary) > WIDTH {
                summary.push_str(&space1);
            } else {
                summary.push(' ');
            }
            format!("[{}", &summary[space2.len()..])
        }
    }
}

/// Python wrapper for FrankenPandas Index.
#[pyclass(name = "Index", module = "frankenpandas", from_py_object, subclass)]
#[derive(Clone)]
pub struct PyIndex {
    pub(crate) inner: Index,
}

/// An index-like argument. pandas' set operations, append, get_indexer and
/// asof_locs take any array-like (`df.columns.difference(['id'])`); they
/// raised TypeError unless handed an Index. An Index is taken as is,
/// anything else through `Index(obj)`.
pub struct IndexArg(PyIndex);

/// Whether `obj` is one of the typed index classes - DatetimeIndex,
/// TimedeltaIndex, PeriodIndex, CategoricalIndex, MultiIndex - which are
/// Index subclasses (br-frankenpandas-myyy1) whose base labels are not what
/// a plain Index's reader expects (a MultiIndex's are its joined labels).
fn typed_index_object(obj: &Bound<'_, PyAny>) -> bool {
    obj.is_instance_of::<PyDatetimeIndex>()
        || obj.is_instance_of::<PyTimedeltaIndex>()
        || obj.is_instance_of::<PyPeriodIndex>()
        || obj.is_instance_of::<PyCategoricalIndex>()
        || obj.is_instance_of::<PyMultiIndex>()
}

/// Whether `obj` is a DatetimeIndex, TimedeltaIndex or PeriodIndex, whose
/// arithmetic is its values' (see [`datetimelike_index_arithmetic`]).
fn datetimelike_index_object(obj: &Bound<'_, PyAny>) -> bool {
    obj.is_instance_of::<PyDatetimeIndex>()
        || obj.is_instance_of::<PyTimedeltaIndex>()
        || obj.is_instance_of::<PyPeriodIndex>()
}

/// pandas' arithmetic of a datetime-like `index` with `other` (an operator
/// `op` it inherits from Index): its values' Series arithmetic - instants
/// minus instants are durations, durations over a duration floats, periods
/// plus ints periods - as an Index of the results, named as pandas'
/// `get_op_result_name` (the name both share, else none; a scalar keeps
/// this one). Another index is read by position; a Series or frame answers
/// itself. Each raised TypeError (br-frankenpandas-a2t82).
fn datetimelike_index_arithmetic(
    index: &Bound<'_, PyAny>,
    other: &Bound<'_, PyAny>,
    op: &str,
) -> PyResult<Py<PyAny>> {
    let py = index.py();
    if other.is_instance_of::<PySeries>() || other.is_instance_of::<PyDataFrame>() {
        return Ok(py.NotImplemented());
    }
    // Instants and periods do not multiply, divide or raise (pandas'
    // make_invalid_op).
    let scaling = matches!(
        op,
        "__mul__"
            | "__rmul__"
            | "__truediv__"
            | "__rtruediv__"
            | "__floordiv__"
            | "__rfloordiv__"
            | "__mod__"
            | "__rmod__"
            | "__pow__"
            | "__rpow__"
    );
    if scaling && !index.is_instance_of::<PyTimedeltaIndex>() {
        let array = if index.is_instance_of::<PyPeriodIndex>() {
            "PeriodArray"
        } else {
            "DatetimeArray"
        };
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "cannot perform {op} with this index type: {array}"
        )));
    }
    let module = py.import("frankenpandas")?;
    let series = module.getattr("Series")?;
    let other_index = is_index_object(other);
    let right = if other_index {
        series.call1((other,))?
    } else {
        other.clone()
    };
    let values = series.call1((index,))?.call_method1(op, (right,))?;
    if values.is(py.NotImplemented()) {
        return Ok(values.unbind());
    }
    let name = index.getattr("name")?;
    let name = if other_index && !name.eq(other.getattr("name")?)? {
        py.None().into_bound(py)
    } else {
        name
    };
    let named = PyDict::new(py);
    named.set_item("name", name)?;
    Ok(module
        .getattr("Index")?
        .call((values,), Some(&named))?
        .unbind())
}

/// `obj` as a plain Index object (an Index, a RangeIndex, a Series' or
/// frame's `.index`), for the readers of index-like arguments: a typed
/// index class is refused here, as before it was an Index subclass, so each
/// reader keeps its own handling of those.
fn plain_index_ref<'py>(obj: &Bound<'py, PyAny>) -> PyResult<PyRef<'py, PyIndex>> {
    if typed_index_object(obj) {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "a typed index is not a plain Index here",
        ));
    }
    obj.extract::<PyRef<'py, PyIndex>>().map_err(Into::into)
}

impl<'a, 'py> FromPyObject<'a, 'py> for IndexArg {
    type Error = PyErr;

    fn extract(obj: pyo3::Borrowed<'a, 'py, PyAny>) -> PyResult<Self> {
        if let Ok(index) = plain_index_ref(&obj) {
            return Ok(Self(index.clone()));
        }
        // The typed index classes carry their labels directly.
        let typed = if let Ok(instants) = obj.extract::<PyRef<'_, PyDatetimeIndex>>() {
            Some(instants.inner.clone().into_index())
        } else {
            obj.extract::<PyRef<'_, PyTimedeltaIndex>>()
                .ok()
                .map(|durations| durations.inner.clone().into_index())
        };
        if let Some(inner) = typed {
            return Ok(Self(PyIndex { inner }));
        }
        // A list is the Index pandas' constructor makes of it: numbers
        // beside a missing one float64 ([None, 1] kept None, which a float
        // index's NaN did not match; l5sed).
        let index = PyIndex::new(Some(&obj), None)?;
        Ok(Self(PyIndex {
            inner: float_labelled(index.inner),
        }))
    }
}

impl std::ops::Deref for IndexArg {
    type Target = PyIndex;

    fn deref(&self) -> &PyIndex {
        &self.0
    }
}

/// pandas' `sort=` for union / difference / symmetric_difference: None (the
/// default) sorts the result unless the two indexes are equal, either is
/// empty, or the labels are of mixed kinds (left in first-seen order); False
/// keeps first-seen order; True sorts. fp-index keeps first-seen order, so
/// `df.columns.union(['c'])` came back unsorted.
#[allow(clippy::cast_precision_loss)] // an order, as Python compares them
fn setop_sorted(result: Index, left: &Index, right: &Index, sort: Option<bool>) -> Index {
    // Bools beside numbers compare as numbers (Python's False < 1), so
    // pandas sorts them; other mixes stay as they came.
    let number = |label: &IndexLabel| match label {
        IndexLabel::Bool(flag) => Some(f64::from(u8::from(*flag))),
        IndexLabel::Int64(value) => Some(*value as f64),
        IndexLabel::Float64(value) => Some(value.0),
        _ => None,
    };
    let numbers: Option<Vec<f64>> = result.labels().iter().map(number).collect();
    let mixed = result.inferred_type() == "mixed";
    let sorts = match sort {
        Some(sort) => sort,
        None => {
            !(left.is_empty()
                || right.is_empty()
                || left.equals(right)
                || (mixed && numbers.is_none()))
        }
    };
    match numbers {
        Some(numbers) if sorts && mixed => {
            let mut order: Vec<usize> = (0..numbers.len()).collect();
            order.sort_by(|&a, &b| numbers[a].total_cmp(&numbers[b]));
            result.take(&order)
        }
        _ if sorts => result.sort_values(),
        _ => result,
    }
}

/// pandas' dtype for an index operation joining indexes of dtypes `left`
/// and `right` (its `_find_common_type_compat`): one dtype stays, ints
/// meet floats at float64, and anything else - a bool beside a number,
/// text, an object index, an empty list - meets at object.
fn index_common_dtype(left: &'static str, right: &'static str) -> &'static str {
    let number = |dtype: &str| matches!(dtype, "int64" | "int32" | "float64");
    match (left, right) {
        _ if left == right => left,
        ("float64", other) | (other, "float64") if number(other) => "float64",
        (one, other) if number(one) && number(other) => "int64",
        _ => "object",
    }
}

/// `index` held as pandas holds an operation's result of `dtype`: float64
/// turns its int labels (and missing ones) into floats, object declares it
/// (its labels kept); any other dtype leaves it. Set operations kept the
/// labels' own dtype (Index([1, 2]).union([2.5]) was object, .union([None])
/// int64 holding a None; br-frankenpandas-jnw2b).
#[allow(clippy::cast_precision_loss)] // pandas widens the ints the same way
fn index_in_dtype(index: Index, dtype: &str) -> Index {
    if index.dtype() == dtype {
        return index;
    }
    match dtype {
        "float64" => {
            let labels = index
                .labels()
                .iter()
                .map(|label| match label {
                    IndexLabel::Int64(value) => IndexLabel::Float64(OrderedF64(*value as f64)),
                    IndexLabel::Null(_) => IndexLabel::Null(NullKind::NaN),
                    other => other.clone(),
                })
                .collect();
            Index::new(labels).rename_index(index.name())
        }
        "object" => index.with_declared_dtype(Some(fp_index::DeclaredDtype::Object)),
        _ => index,
    }
}

/// `get_indexer`'s positions (-1 where a label is absent) as pandas returns
/// them: an int64 numpy array (they came back as a list).
pub struct IndexerArray(Vec<i64>);

impl FromIterator<i64> for IndexerArray {
    fn from_iter<I: IntoIterator<Item = i64>>(positions: I) -> Self {
        Self(positions.into_iter().collect())
    }
}

impl<'py> IntoPyObject<'py> for IndexerArray {
    type Target = PyAny;
    type Output = Bound<'py, PyAny>;
    type Error = PyErr;

    fn into_pyobject(self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        column_ndarray(py, &Column::from_i64_values_owned(self.0))
    }
}

/// One position as pandas returns it (`argmax`, `argmin`): a numpy int64
/// (it was a Python int).
pub struct NumpyInt64(i64);

impl From<usize> for NumpyInt64 {
    fn from(position: usize) -> Self {
        Self(i64::try_from(position).unwrap_or(i64::MAX))
    }
}

impl<'py> IntoPyObject<'py> for NumpyInt64 {
    type Target = PyAny;
    type Output = Bound<'py, PyAny>;
    type Error = PyErr;

    fn into_pyobject(self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        py.import("numpy")?.getattr("int64")?.call1((self.0,))
    }
}

/// Positions (`argsort`) as pandas returns them: an int64 numpy array.
impl From<Vec<usize>> for IndexerArray {
    fn from(positions: Vec<usize>) -> Self {
        positions
            .into_iter()
            .map(|position| i64::try_from(position).unwrap_or(i64::MAX))
            .collect()
    }
}

/// An Index's per-label flags (`isin`, `duplicated`, `isna`) as pandas
/// returns them: a bool numpy array, so `.any()` / `.sum()` work (they were
/// lists: `df.index.duplicated().any()` raised AttributeError).
pub struct BoolArray(Vec<bool>);

impl From<Vec<bool>> for BoolArray {
    fn from(flags: Vec<bool>) -> Self {
        Self(flags)
    }
}

impl<'py> IntoPyObject<'py> for BoolArray {
    type Target = PyAny;
    type Output = Bound<'py, PyAny>;
    type Error = PyErr;

    fn into_pyobject(self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        let kwargs = PyDict::new(py);
        kwargs.set_item("dtype", "bool")?;
        py.import("numpy")?
            .call_method("array", (self.0,), Some(&kwargs))
    }
}

/// The Index a Series' or DataFrame's `.index` returns: an `Index` that
/// also writes its `name` back to the object it came from, as pandas'
/// shared Index does - `df.index.name = 'k'` renamed a copy.
#[pyclass(extends = PyIndex, name = "Index", module = "frankenpandas")]
pub struct PyOwnedIndex {
    owner: Py<PyAny>,
    /// Whether this is the owner's column axis (`df.columns`), not its rows.
    columns: bool,
}

#[pymethods]
impl PyOwnedIndex {
    #[getter]
    fn name(slf: PyRef<'_, Self>) -> PyResult<Option<Py<PyAny>>> {
        axis_name_to_py(slf.py(), slf.as_super().inner.name())
    }

    /// `index.name = value`: this Index and its owner's index are renamed.
    #[setter]
    fn set_name(mut slf: PyRefMut<'_, Self>, name: &Bound<'_, PyAny>) -> PyResult<()> {
        let py = slf.py();
        let name = py_axis_name(name)?;
        let owner = slf.owner.clone_ref(py);
        let columns = slf.columns;
        let base = slf.as_super();
        base.inner = base.inner.set_names(name.clone());
        rename_owner_index(owner.bind(py), name, columns)
    }
}

/// Rename the row index of `owner` (the DataFrame or Series an `.index`
/// came from), or with `columns` its column axis (a `.columns`), as pandas'
/// shared Index object renames it.
fn rename_owner_index(
    owner: &Bound<'_, PyAny>,
    name: Option<LabelName>,
    columns: bool,
) -> PyResult<()> {
    if columns {
        if let Ok(mut frame) = owner.extract::<PyRefMut<'_, PyDataFrame>>() {
            frame.inner = frame.inner.clone().with_columns_name(name);
        }
        return Ok(());
    }
    if let Ok(mut frame) = owner.extract::<PyRefMut<'_, PyDataFrame>>() {
        let renamed = frame.inner.index().rename_index(name);
        frame.inner = frame.inner.with_index(renamed).map_err(frame_error_to_py)?;
    } else if let Ok(mut series) = owner.extract::<PyRefMut<'_, PySeries>>() {
        let renamed = series.inner.index().rename_index(name);
        series.inner = Series::new(series.inner.name(), renamed, series.inner.column().clone())
            .map_err(frame_error_to_py)?;
    }
    Ok(())
}

/// A DataFrame's or Series' `.index` of instants: a DatetimeIndex whose
