    /// The instants as Timestamps in the index's zone, NaT kept, as pandas
    /// (these were ISO strings; fvsao.18).
    fn to_list(&self, py: Python<'_>) -> PyResult<Vec<Py<PyAny>>> {
        self.inner
            .asi8()
            .into_iter()
            .map(|ns| self.timestamp_object(py, ns))
            .collect()
    }

    fn tolist(&self, py: Python<'_>) -> PyResult<Vec<Py<PyAny>>> {
        self.to_list(py)
    }

    /// pandas' `DatetimeIndex.values`: a datetime64[ns] numpy array (it
    /// was a list of nanosecond integers).
    #[getter]
    fn values<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        let bytes: Vec<u8> = self
            .inner
            .values()
            .into_iter()
            .flat_map(|nanos| nanos.unwrap_or(i64::MIN).to_ne_bytes())
            .collect();
        py.import("numpy")?.call_method1(
            "frombuffer",
            (pyo3::types::PyByteArray::new(py, &bytes), "datetime64[ns]"),
        )
    }

    /// pandas' `to_numpy(dtype=None, copy=False, na_value=...)`: `na_value`
    /// fills the NaT slots (it was an unknown keyword,
    /// br-frankenpandas-u6p7i).
    #[pyo3(signature = (dtype=None, copy=false, na_value=None))]
    fn to_numpy<'py>(
        &self,
        py: Python<'py>,
        dtype: Option<&Bound<'py, PyAny>>,
        copy: bool,
        na_value: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let _ = copy;
        let missing = na_value
            .map(|_| {
                labels_missing_ndarray(py, self.inner.values().into_iter().map(|ns| ns.is_none()))
            })
            .transpose()?;
        finish_to_numpy(self.values(py)?, missing, dtype, na_value)
    }

    #[pyo3(signature = (dtype=None, copy=None))]
    fn __array__<'py>(
        &self,
        py: Python<'py>,
        dtype: Option<&Bound<'py, PyAny>>,
        copy: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let _ = copy;
        finish_to_numpy(self.values(py)?, None, dtype, None)
    }

    // Timestamps in the index's zone (NaT when there is no instant), as
    // pandas; these were formatted strings (fvsao.18).
    /// pandas' `min(axis=None, skipna=True)`: a NaT with skipna=False is NaT
    /// (the keywords were unexpected - br-frankenpandas-zvn7a).
    #[pyo3(signature = (axis=None, skipna=true))]
    fn min(&self, py: Python<'_>, axis: Option<i64>, skipna: bool) -> PyResult<Py<PyAny>> {
        one_dim_axis(axis)?;
        let stamp = if !skipna && self.holds_nat() {
            Timestamp::NAT
        } else {
            self.inner.min().unwrap_or(Timestamp::NAT)
        };
        self.timestamp_object(py, stamp)
    }

    /// pandas' `max(axis=None, skipna=True)` (see [`Self::min`]).
    #[pyo3(signature = (axis=None, skipna=true))]
    fn max(&self, py: Python<'_>, axis: Option<i64>, skipna: bool) -> PyResult<Py<PyAny>> {
        one_dim_axis(axis)?;
        let stamp = if !skipna && self.holds_nat() {
            Timestamp::NAT
        } else {
            self.inner.max().unwrap_or(Timestamp::NAT)
        };
        self.timestamp_object(py, stamp)
    }

    fn mean(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.timestamp_object(py, self.inner.mean().unwrap_or(Timestamp::NAT))
    }

    fn std(&self) -> Option<f64> {
        self.inner.std().map(|v| v as f64)
    }

    fn var(&self) -> Option<f64> {
        self.inner.var()
    }

    fn unique(&self) -> PyResult<Self> {
        let inner = self
            .inner
            .unique()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDatetimeIndex { inner })
    }

    fn nunique(&self) -> usize {
        self.inner.nunique()
    }

    /// pandas' `drop_duplicates(*, keep='first')` (keep= was refused;
    /// br-frankenpandas-k2bwx).
    #[pyo3(signature = (*, keep=None))]
    fn drop_duplicates(&self, keep: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let keep = parse_duplicate_keep(keep)?;
        let inner = if matches!(keep, DuplicateKeep::First) {
            self.inner
                .drop_duplicates()
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
        } else {
            let kept = unduplicated_positions(&self.inner.duplicated(keep));
            self.inner.take(&kept).map_err(index_error_to_py)?
        };
        Ok(PyDatetimeIndex { inner })
    }

    /// pandas' `duplicated(keep='first')` (keep= was refused).
    #[pyo3(signature = (keep=None))]
    fn duplicated(&self, keep: Option<&Bound<'_, PyAny>>) -> PyResult<BoolArray> {
        Ok(self.inner.duplicated(parse_duplicate_keep(keep)?).into())
    }

    fn isna(&self) -> Vec<bool> {
        self.inner.isna()
    }

