    #[pyo3(signature = (index=None, name=None))]
    fn to_series(
        &self,
        index: Option<&Bound<'_, PyAny>>,
        name: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        // `name`, else the index's typed name (fvsao.64).
        let series_name = match name.filter(|name| !name.is_none()) {
            Some(name) => py_series_name(name)?,
            None => self.inner.name().cloned().unwrap_or_default(),
        };
        let idx = if let Some(i_obj) = index {
            if let Ok(py_idx) = plain_index_ref(i_obj) {
                py_idx.inner.clone()
            } else {
                self.inner.as_index().clone()
            }
        } else {
            self.inner.as_index().clone()
        };
        let s = Series::new(series_name, idx, self.values_column()?).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (index=true, name=None))]
    fn to_frame(&self, index: bool, name: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        // The column is `name`, else the index's typed name, else the
        // integer 0, as pandas' (fvsao.64; they were text).
        let label = match name.filter(|name| !name.is_none()) {
            Some(name) => py_series_name(name)?.label(),
            None => self
                .inner
                .name()
                .map_or(IndexLabel::Int64(0), LabelName::label),
        };
        let col_name = fp_frame::column_key(&label);
        let idx = if index {
            self.inner.as_index().clone()
        } else {
            Index::from_range(0, self.inner.len() as i64, 1)
        };
        let mut col_map = BTreeMap::new();
        col_map.insert(col_name.to_string(), self.values_column()?);
        let df = DataFrame::new_with_column_order(idx, col_map, vec![col_name.to_string()])
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (normalize=false, sort=true, ascending=false, dropna=true))]
    fn value_counts(
        &self,
        normalize: bool,
        sort: bool,
        ascending: bool,
        dropna: bool,
    ) -> PyResult<PySeries> {
        let counts = self
            .inner
            .as_index()
            .value_counts_with_options(normalize, sort, ascending, dropna);
        let mut idx_labels = Vec::with_capacity(counts.len());
        let mut vals = Vec::with_capacity(counts.len());
        for (lbl, sc) in counts {
            idx_labels.push(lbl);
            vals.push(sc);
        }
        let col = Column::from_values(vals)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        // The counted labels are this index's: its name and zone (fvsao.60);
        // a normalized count is 'proportion', as for Index (fvsao.30).
        let index = self.inner.as_index().relabeled(idx_labels);
        let name = if normalize { "proportion" } else { "count" };
        let s = Series::new(name, index, col).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `sort_values(*, return_indexer=False, ascending=True,
    /// na_position='last', key=None)` (see [`typed_sort_order`]); the take
    /// keeps the freq of an order already sorted and negates it for an exact
    /// reversal ('-1D'), as pandas (the freq was dropped; return_indexer and
    /// key were not taken, br-frankenpandas-h1kl9).
    #[pyo3(signature = (*, return_indexer=false, ascending=true, na_position="last", key=None))]
    fn sort_values(
        slf: &Bound<'_, Self>,
        return_indexer: bool,
        ascending: bool,
        na_position: &str,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        let this = slf.borrow();
        let order = typed_sort_order(
            slf.as_any(),
            this.inner.len(),
            ascending,
            na_position,
            key,
            || nat_sort_keys(&this.inner.asi8()),
        )?;
        let inner = this.inner.take(&order).map_err(index_error_to_py)?;
        sorted_index_result(slf.py(), Self { inner }, order, return_indexer)
    }

    fn sort(&self) -> PyResult<Self> {
        let order = nargsort_keys(&nat_sort_keys(&self.inner.asi8()), true, false);
        let inner = self.inner.take(&order).map_err(index_error_to_py)?;
        Ok(Self { inner })
    }

    #[getter]
    #[allow(non_snake_case)]
    fn T(&self) -> Self {
        self.clone()
    }

    fn drop(&self, labels: Vec<Bound<'_, PyAny>>) -> PyResult<PyIndex> {
        let mut to_drop = Vec::with_capacity(labels.len());
        for l in labels {
            to_drop.push(py_to_index_label(&l)?);
        }
        Ok(PyIndex {
            inner: self.inner.as_index().drop_labels(&to_drop),
        })
    }

    /// Drops NaT; a flat index drops the same labels for how='any' and 'all'.
    /// This returned the index with its NaT (fvsao.5).
    #[pyo3(signature = (how="any"))]
    fn dropna(&self, how: &str) -> PyResult<Self> {
        if !matches!(how, "any" | "all") {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid how option: {how}"
            )));
        }
        let kept = self
            .inner
            .asi8()
            .into_iter()
            .filter(|&v| v != i64::MIN)
            .collect();
        Ok(self.with_nanos(kept))
    }

    /// Fills NaT with a value of the index's own type; this returned the
    /// index unfilled whatever the value (fvsao.5). Another type (pandas
    /// casts to object) is not supported.
    #[pyo3(signature = (value=None))]
    fn fillna(&self, value: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let Some(value) = value.filter(|v| !v.is_none()) else {
            return Ok(self.clone());
        };
        let nanos = self.inner.asi8();
        if !nanos.contains(&i64::MIN) {
            return Ok(self.clone());
        }
        let fill = Self::fill_nanos(&py_to_index_label(value)?)?;
        Ok(self.with_nanos(
            nanos
                .into_iter()
                .map(|v| if v == i64::MIN { fill } else { v })
                .collect(),
        ))
    }

