    fn to_julian_date(&self) -> Vec<Option<f64>> {
        self.inner
            .asi8()
            .iter()
            .map(|&ns| {
                if ns == i64::MIN {
                    None
                } else {
                    Some((ns as f64) / 86_400_000_000_000.0 + 2440587.5)
                }
            })
            .collect()
    }

    /// pandas' `DatetimeIndex.to_period(freq)` through fp-index's calendar
    /// ordinals, NaT staying NaT. It used the day count as the ordinal of
    /// every frequency ('2024-01-05' read '3613-12' monthly) and took an
    /// unknown freq as daily.
    #[pyo3(signature = (freq=None))]
    fn to_period(&self, freq: Option<&str>) -> PyResult<PyPeriodIndex> {
        // Without a freq, the index's own (a date_range's 'D'), read as the
        // period it spans (see `offset_freq_as_period`).
        let own = self.inner.freqstr().map(|own| offset_freq_as_period(&own));
        let Some(freq) = freq.or(own.as_deref()) else {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "You must pass a freq argument as current index has none.",
            ));
        };
        let p_freq = PeriodFreq::parse(freq).ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>(format!("Invalid frequency: {freq}"))
        })?;
        // A period is a wall-clock span: a tz-aware index's zone is dropped
        // (as pandas, which warns), not its UTC clock read.
        let nanos = self
            .inner
            .tz_localize(None)
            .map_err(index_error_to_py)?
            .asi8();
        let present: Vec<i64> = nanos.iter().copied().filter(|&ns| ns != i64::MIN).collect();
        let converted = DatetimeIndex::new(present)
            .to_period(freq)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        let mut converted = converted.values().iter();
        let periods = nanos
            .iter()
            .map(|&ns| {
                if ns == i64::MIN {
                    Some(Period::new(i64::MIN, p_freq))
                } else {
                    converted.next().cloned()
                }
            })
            .collect::<Option<Vec<Period>>>()
            .ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyValueError, _>("to_period: lost a period")
            })?;
        let mut out = PeriodIndex::new(periods);
        if let Some(n) = self.inner.name() {
            out = out.set_name(n);
        }
        Ok(PyPeriodIndex { inner: out })
    }

    fn to_pydatetime(&self, py: Python<'_>) -> PyResult<Py<PyList>> {
        let dt_mod = py.import("datetime")?;
        let dt_cls = dt_mod.getattr("datetime")?;
        let mut out = Vec::with_capacity(self.inner.len());
        let years = self.inner.year();
        let months = self.inner.month();
        let days = self.inner.day();
        let hours = self.inner.hour();
        let minutes = self.inner.minute();
        let seconds = self.inner.second();
        let microseconds = self.inner.microsecond();
        for i in 0..self.inner.len() {
            if let (Some(y), Some(mo), Some(d), Some(h), Some(mi), Some(s), Some(us)) = (
                years[i],
                months[i],
                days[i],
                hours[i],
                minutes[i],
                seconds[i],
                microseconds[i],
            ) {
                let py_dt = dt_cls.call1((y, mo, d, h, mi, s, us))?;
                out.push(py_dt.into_any().unbind());
            } else {
                out.push(py.None());
            }
        }
        Ok(PyList::new(py, out)?.unbind())
    }

