    /// pandas' FrozenList of the level names, typed (fvsao.64).
    #[getter]
    fn names(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let names = self
            .inner
            .names()
            .iter()
            .map(|name| axis_name_to_py(py, name.as_ref())?.into_py_any(py))
            .collect::<PyResult<Vec<_>>>()?;
        frozen_list(py, names)
    }

    #[getter]
