    /// The positions sorting the tuples (level by level, as pandas'); the
    /// flat text put ('a', 10) before ('a', 9) (hp180).
    fn argsort(&self) -> IndexerArray {
        self.inner.argsort().into()
    }

    /// pandas' `Index.array` (see [`index_array`]; it was a method
    /// answering a list).
    #[getter]
    fn array(slf: &Bound<'_, Self>) -> PyResult<Py<PyAny>> {
        index_array(slf.as_any())
    }

    fn to_numpy<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        self.values(py)
    }

    fn asof(&self, py: Python<'_>, label: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let labels = if let Ok(seq) = label.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut row = Vec::with_capacity(len);
            for i in 0..len {
                row.push(py_to_index_label(&seq.get_item(i)?)?);
            }
            row
        } else {
            vec![py_to_index_label(label)?]
        };
        match self.inner.asof(&labels).map_err(index_error_to_py)? {
            Some(row) => {
                let items: Vec<Py<PyAny>> = row
                    .iter()
                    .map(|l| index_label_to_py(py, l))
                    .collect::<PyResult<_>>()?;
                Ok(pyo3::types::PyTuple::new(py, items)?.into_any().unbind())
            }
            None => Ok(py.None()),
        }
    }

    #[pyo3(signature = (where_, mask=None))]
    fn asof_locs(
        &self,
        where_: &Bound<'_, PyAny>,
        mask: Option<Vec<bool>>,
    ) -> PyResult<Vec<Option<usize>>> {
        let where_idx = if let Ok(py_mi) = where_.extract::<PyRef<'_, PyMultiIndex>>() {
            py_mi.inner.to_flat_index("/")
        } else if let Ok(py_idx) = plain_index_ref(where_) {
            py_idx.inner.clone()
        } else {
            PyIndex::new(Some(where_), None)?.inner
        };
        Ok(self
            .inner
            .to_flat_index("/")
            .asof_locs(&where_idx, mask.as_deref()))
    }

    /// A MultiIndex is always object dtype; pandas refuses any other (this
    /// returned the MultiIndex whatever dtype was asked for).
    fn astype(&self, dtype: &Bound<'_, PyAny>) -> PyResult<Self> {
        let dtype = index_astype_name(dtype).unwrap_or_default();
        if !matches!(dtype.as_str(), "object" | "O") {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Setting a MultiIndex dtype to anything other than object is not supported",
            ));
        }
        Ok(self.clone())
    }

    fn delete(&self, loc: usize) -> PyResult<Self> {
        self.inner
            .delete(loc)
            .map(|inner| Self { inner })
            .map_err(index_error_to_py)
    }

    /// pandas subtracts the tuples, a TypeError once any pair meets (it
    /// subtracted the flat text into NaN; hp180); too short to pair, all
    /// NaN.
    #[pyo3(signature = (periods=1))]
    fn diff(&self, periods: i64) -> PyResult<PyIndex> {
        if usize::try_from(periods.unsigned_abs()).is_ok_and(|lag| lag < self.inner.len()) {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "unsupported operand type(s) for -: 'tuple' and 'tuple'",
            ));
        }
        Ok(PyIndex {
            inner: Index::new(vec![
                IndexLabel::Float64(OrderedF64(f64::NAN));
                self.inner.len()
            ]),
        })
    }

    fn drop(&self, labels: &Bound<'_, PyAny>) -> PyResult<Self> {
        let tuples_to_drop = if let Ok(seq) = labels.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut rows = Vec::new();
            for i in 0..len {
                let item = seq.get_item(i)?;
                if let Ok(tuple_seq) = item.cast::<pyo3::types::PySequence>() {
                    let mut row = Vec::new();
                    for j in 0..tuple_seq.len()? {
                        row.push(py_to_index_label(&tuple_seq.get_item(j)?)?);
                    }
                    rows.push(row);
                } else {
                    rows.push(vec![py_to_index_label(&item)?]);
                }
            }
            rows
        } else {
            vec![vec![py_to_index_label(labels)?]]
        };
        self.inner
            .drop(&tuples_to_drop)
            .map(|inner| Self { inner })
            .map_err(index_error_to_py)
    }

    /// pandas' `drop_duplicates(*, keep='first')` (keep= was refused;
    /// br-frankenpandas-k2bwx).
    #[pyo3(signature = (*, keep=None))]
    fn drop_duplicates(&self, keep: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        Ok(Self {
            inner: self.inner.drop_duplicates_keep(parse_duplicate_keep(keep)?),
        })
    }

    /// pandas' `duplicated(keep='first')` (keep= was refused).
    #[pyo3(signature = (keep=None))]
    fn duplicated(&self, keep: Option<&Bound<'_, PyAny>>) -> PyResult<BoolArray> {
        Ok(self.inner.duplicated(parse_duplicate_keep(keep)?).into())
    }

    fn equal_levels(&self, other: &PyMultiIndex) -> bool {
        self.inner.equal_levels(&other.inner)
    }

    #[pyo3(signature = (sort=false, use_na_sentinel=true))]
    fn factorize(&self, sort: bool, use_na_sentinel: bool) -> PyResult<(Vec<isize>, Self)> {
        unsupported_params(
            "MultiIndex.factorize",
            &[("sort", !sort), ("use_na_sentinel", use_na_sentinel)],
        )?;
        let (codes, uniques) = self.inner.factorize();
        Ok((codes, Self { inner: uniques }))
    }

    fn format(&self) -> Vec<String> {
        self.inner.format()
    }

    #[classmethod]
    #[pyo3(signature = (df, sortorder=None, names=None))]
    fn from_frame(
        _cls: &Bound<'_, pyo3::types::PyType>,
        df: &Bound<'_, PyAny>,
        sortorder: Option<i64>,
        names: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Self> {
        let _ = sortorder;
        if let Ok(pdf) = df.extract::<PyRef<'_, PyDataFrame>>() {
            let cols = pdf.inner.column_names();
            let mut column_data = Vec::with_capacity(cols.len());
            for col_name in &cols {
                let col = pdf.inner.column(col_name).ok_or_else(|| {
                    PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                        "column {col_name:?} missing"
                    ))
                })?;
                let labels: Vec<IndexLabel> = col
                    .values()
                    .iter()
                    .map(|sc| match sc {
                        Scalar::Int64(v) => IndexLabel::Int64(*v),
                        Scalar::Float64(f) => IndexLabel::Float64(fp_index::OrderedF64(*f)),
                        Scalar::Utf8(s) => IndexLabel::Utf8(s.clone()),
                        Scalar::Bool(b) => IndexLabel::Bool(*b),
                        Scalar::Datetime64(d) => IndexLabel::Datetime64(*d),
                        Scalar::Timedelta64(t) => IndexLabel::Timedelta64(*t),
                        Scalar::Period(p) => IndexLabel::Int64(p.ordinal),
                        Scalar::Interval(inv) => IndexLabel::Interval(*inv),
                        Scalar::Object(object) => IndexLabel::Object(object.clone()),
                        Scalar::Null(k) => IndexLabel::Null(*k),
                    })
                    .collect();
                column_data.push((Some((*col_name).clone()), labels));
            }
            let mut mi = MultiIndex::from_frame(column_data).map_err(index_error_to_py)?;
            if let Some(ns) = extract_index_names_flexible(names)? {
                mi = mi.set_names(ns);
            }
            return Ok(Self { inner: mi });
        }
        if let Ok(columns_attr) = df.getattr("columns") {
            let mut column_data = Vec::new();
            for col_name_obj in columns_attr.try_iter()? {
                let col_name_obj = col_name_obj?;
                let col_name_str = col_name_obj.to_string();
                let col_series = df.get_item(&col_name_obj)?;
                let mut labels = Vec::new();
                for item in col_series.try_iter()? {
                    let item = item?;
                    labels.push(py_to_index_label(&item)?);
                }
                column_data.push((Some(col_name_str), labels));
            }
            let mut mi = MultiIndex::from_frame(column_data).map_err(index_error_to_py)?;
            if let Some(ns) = extract_index_names_flexible(names)? {
                mi = mi.set_names(ns);
            }
            return Ok(Self { inner: mi });
        }
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "from_frame requires a DataFrame or DataFrame-like object",
        ))
    }

    fn get_indexer_for(&self, target: &PyMultiIndex) -> PyResult<Vec<i64>> {
        self.inner
            .get_indexer_for(&target.inner)
            .map(|res| res.into_iter().map(|x| x as i64).collect())
            .map_err(index_error_to_py)
    }

    fn get_indexer_non_unique(&self, target: &PyMultiIndex) -> (Vec<isize>, Vec<usize>) {
        self.inner.get_indexer_non_unique(&target.inner)
    }

    fn get_loc_level(&self, py: Python<'_>, key: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let labels = if let Ok(seq) = key.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut row = Vec::with_capacity(len);
            for i in 0..len {
                row.push(py_to_index_label(&seq.get_item(i)?)?);
            }
            row
        } else {
            vec![py_to_index_label(key)?]
        };
        let (positions, remaining) = self
            .inner
            .get_loc_level(&labels)
            .map_err(index_error_to_py)?;
        let py_rem: Py<PyAny> = match remaining {
            Some(fp_index::MultiIndexOrIndex::Multi(mi)) => {
                Py::new(py, PyMultiIndex { inner: mi })?.into_any()
            }
            Some(fp_index::MultiIndexOrIndex::Index(idx)) => {
                Py::new(py, PyIndex { inner: idx })?.into_any()
            }
            None => py.None(),
        };
        let py_pos = PyList::new(py, positions)?;
        Ok(
            pyo3::types::PyTuple::new(py, vec![py_pos.into_any().unbind(), py_rem])?
                .into_any()
                .unbind(),
        )
    }

    fn get_locs(&self, key: &Bound<'_, PyAny>) -> PyResult<Vec<usize>> {
        let labels = if let Ok(seq) = key.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut row = Vec::with_capacity(len);
            for i in 0..len {
                row.push(py_to_index_label(&seq.get_item(i)?)?);
            }
            row
        } else {
            vec![py_to_index_label(key)?]
        };
        self.inner.get_locs(&labels).map_err(index_error_to_py)
    }

    fn get_slice_bound(&self, label: &Bound<'_, PyAny>, side: &str) -> PyResult<usize> {
        let labels = if let Ok(seq) = label.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut row = Vec::with_capacity(len);
            for i in 0..len {
                row.push(py_to_index_label(&seq.get_item(i)?)?);
            }
            row
        } else {
            vec![py_to_index_label(label)?]
        };
        self.inner
            .get_slice_bound(&labels, side)
            .map_err(index_error_to_py)
    }

    /// pandas' `MultiIndex.slice_locs(start, end, step)` (see
    /// [`stepped_slice_locs`]): a bound is a tuple of leading-level labels
    /// or one label (a string was read as its characters; the step was
    /// discarded, br-frankenpandas-h1kl9). A bound a label gives is pandas'
    /// searchsorted np.int64, an open one an int.
    #[pyo3(signature = (start=None, end=None, step=None))]
    fn slice_locs(
        &self,
        py: Python<'_>,
        start: Option<&Bound<'_, PyAny>>,
        end: Option<&Bound<'_, PyAny>>,
        step: Option<isize>,
    ) -> PyResult<(Py<PyAny>, Py<PyAny>)> {
        let (left, right) = self.stepped_bounds(start, end, step)?;
        let bound = |value: i64, searched: bool| {
            if searched {
                numpy_scalar(py, &Scalar::Int64(value))
            } else {
                value.into_py_any(py)
            }
        };
        Ok((bound(left, start.is_some())?, bound(right, end.is_some())?))
    }

    #[pyo3(signature = (start=None, end=None, step=None))]
    fn slice_indexer(
        &self,
        py: Python<'_>,
        start: Option<&Bound<'_, PyAny>>,
        end: Option<&Bound<'_, PyAny>>,
        step: Option<isize>,
    ) -> PyResult<Py<PyAny>> {
        let (left, right) = self.slice_locs(py, start, end, step)?;
        py.import("builtins")?
            .getattr("slice")?
            .call1((left, right, step))
            .map(Bound::unbind)
    }

    /// pandas' `Index.groupby(values)`: each distinct value of `values`
    /// (sorted, a missing one left out) to the MultiIndex of the tuples at
    /// its positions (they were an Index of the flat text; hp180).
    fn groupby(
        &self,
        py: Python<'_>,
        values: &Bound<'_, PyAny>,
    ) -> PyResult<Py<pyo3::types::PyDict>> {
        let mut groups: BTreeMap<IndexLabel, Vec<usize>> = BTreeMap::new();
        for (position, item) in values.try_iter()?.enumerate().take(self.inner.len()) {
            let key = py_to_index_label(&item?)?;
            if !key.is_missing() {
                groups.entry(key).or_default().push(position);
            }
        }
        let dict = PyDict::new(py);
        for (key, positions) in groups {
            let members = Self {
                inner: self.inner.take(&positions).map_err(index_error_to_py)?,
            };
            dict.set_item(index_label_to_py(py, &key)?, Bound::new(py, members)?)?;
        }
        Ok(dict.unbind())
    }

    fn identical(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_mi) = other.extract::<PyRef<'_, PyMultiIndex>>() {
            self.inner.identical(&other_mi.inner)
        } else {
            false
        }
    }

