    fn __iter__(slf: &Bound<'_, Self>) -> PyResult<Py<PyAny>> {
        iter_by_position(slf.as_any())
    }

    /// pandas refuses an index's truth value (it was its length's).
    fn __bool__(slf: &Bound<'_, Self>) -> PyResult<bool> {
        Err(ambiguous_truth_value(slf.as_any()))
    }

    /// pandas' TimedeltaIndex repr: '1 days' when every duration is whole
    /// days, else '1 days 00:00:00' for all, quoted, NaT bare, wrapped /
    /// truncated as Index's (it printed a Rust debug list of nanoseconds),
    /// with its freq (timedelta_range's; it printed freq=None always).
    pub fn __repr__(&self) -> String {
        const DAY: i64 = 86_400_000_000_000;
        let durations: Vec<Option<i64>> = self
            .inner
            .as_index()
            .labels()
            .iter()
            .map(|label| match label {
                IndexLabel::Timedelta64(nanos) if *nanos != i64::MIN => Some(*nanos),
                _ => None,
            })
            .collect();
        let long = durations
            .iter()
            .flatten()
            .any(|nanos| nanos.rem_euclid(DAY) != 0);
        let items: Vec<String> = durations
            .iter()
            .map(|nanos| match nanos {
                Some(nanos) => format!("'{}'", pandas_timedelta_text(*nanos, long)),
                None => "NaT".to_owned(),
            })
            .collect();
        let mut attrs = vec!["dtype='timedelta64[ns]'".to_owned()];
        attrs.extend(self.inner.name().map(|name| format!("name='{name}'")));
        attrs.push(match self.inner.freq() {
            Some(freq) => format!("freq='{freq}'"),
            None => "freq=None".to_owned(),
        });
        pandas_index_text("TimedeltaIndex", &items, true, attrs)
    }

    pub fn __getitem__(&self, py: Python<'_>, item: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(idx) = item.extract::<i64>() {
            let len = self.inner.len() as i64;
            let pos = if idx < 0 { len + idx } else { idx };
            if pos < 0 || pos >= len {
                return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                    "index out of bounds",
                ));
            }
            let label = &self.inner.as_index().labels()[pos as usize];
            return index_label_to_py(py, label);
        }
        if let Ok(slice) = item.cast::<pyo3::types::PySlice>() {
            let indices = slice.indices(self.inner.len() as isize)?;
            let mut sliced = Vec::new();
            let mut i = indices.start;
            if indices.step > 0 {
                while i < indices.stop {
                    if let IndexLabel::Timedelta64(ns) = self.inner.as_index().labels()[i as usize]
                    {
                        sliced.push(ns);
                    }
                    i += indices.step;
                }
            } else {
                while i > indices.stop {
                    if let IndexLabel::Timedelta64(ns) = self.inner.as_index().labels()[i as usize]
                    {
                        sliced.push(ns);
                    }
                    i += indices.step;
                }
            }
            let mut out = TimedeltaIndex::new(sliced);
            if let Some(n) = self.inner.name() {
                out = out.set_name(n);
            }
            // A slice keeps the freq scaled by its step, as pandas.
            let freq = self
                .inner
                .freq()
                .and_then(|freq| fp_index::scale_freq(&freq, i64::try_from(indices.step).ok()?));
            return Py::new(
                py,
                PyTimedeltaIndex {
                    inner: out.with_freq(freq),
                },
            )?
            .into_any()
            .into_py_any(py);
        }
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "TimedeltaIndex indices must be integers or slices",
        ))
    }

