    /// pandas' repr: the periods quoted as its Index summary lists them (NaT
    /// too: 'NaT'), then dtype and name. It printed only the length and
    /// dtype.
    pub fn __repr__(&self) -> String {
        let items: Vec<String> = self
            .inner
            .values()
            .iter()
            .map(|period| {
                if period.ordinal == i64::MIN {
                    "'NaT'".to_owned()
                } else {
                    format!("'{}'", period.calendar_string())
                }
            })
            .collect();
        let mut attrs = vec![format!("dtype='{}'", self.inner.dtype())];
        attrs.extend(self.inner.name().map(|name| format!("name='{name}'")));
        pandas_index_text("PeriodIndex", &items, false, attrs)
    }

    pub fn __getitem__(&self, py: Python<'_>, item: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(idx) = item.extract::<i64>() {
            let len = self.inner.len() as i64;
            let pos = if idx < 0 { len + idx } else { idx };
            if pos < 0 || pos >= len {
                return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                    "index out of bounds",
                ));
            }
            // A NaT period is pandas' NaT (it was Period('NaT', 'M')).
            return scalar_to_py(py, &Scalar::Period(self.inner.values()[pos as usize]));
        }
        if let Ok(slice) = item.cast::<pyo3::types::PySlice>() {
            let indices = slice.indices(self.inner.len() as isize)?;
            let mut sliced = Vec::new();
            let mut i = indices.start;
            if indices.step > 0 {
                while i < indices.stop {
                    sliced.push(self.inner.values()[i as usize]);
                    i += indices.step;
                }
            } else {
                while i > indices.stop {
                    sliced.push(self.inner.values()[i as usize]);
                    i += indices.step;
                }
            }
            let mut out = PeriodIndex::new(sliced);
            if let Some(n) = self.inner.name() {
                out = out.set_name(n);
            }
            return Py::new(py, PyPeriodIndex { inner: out })?
                .into_any()
                .into_py_any(py);
        }
        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "PeriodIndex indices must be integers or slices",
        ))
    }

