    #[pyo3(signature = (index=None, name=None))]
    pub fn to_series(
        &self,
        index: Option<&Bound<'_, PyAny>>,
        name: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        let idx = self.inner.to_index();
        // `name`, else the index's typed name (fvsao.64).
        let series_name = match name.filter(|name| !name.is_none()) {
            Some(name) => py_series_name(name)?,
            None => self.inner.name().cloned().unwrap_or_default(),
        };
        let final_idx = if let Some(i_obj) = index {
            if let Ok(py_idx) = plain_index_ref(i_obj) {
                py_idx.inner.clone()
            } else {
                idx.clone()
            }
        } else {
            idx.clone()
        };
        // Its own dtype - period / categorical - as pandas' (it was an object
        // column of the labels' text; br-frankenpandas-5y62q).
        let col = self.series_column()?;
        let s = Series::new(series_name, final_idx, col).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (index=true, name=None))]
    pub fn to_frame(&self, index: bool, name: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        // The column is `name`, else the index's typed name, else the
        // integer 0, as pandas' (fvsao.64; they were text).
        let label = match name.filter(|name| !name.is_none()) {
            Some(name) => py_series_name(name)?.label(),
            None => self
                .inner
                .name()
                .map_or(IndexLabel::Int64(0), LabelName::label),
        };
        let col_name = fp_frame::column_key(&label);
        let idx = self.inner.to_index();
        let final_idx = if index {
            idx.clone()
        } else {
            Index::from_range(0, self.inner.len() as i64, 1)
        };
        // Its own dtype - period / categorical - as pandas' (it was an object
        // column of the labels' text; br-frankenpandas-5y62q).
        let col = self.series_column()?;
        let mut col_map = BTreeMap::new();
        col_map.insert(col_name.clone(), col);
        let df = DataFrame::new_with_column_order(final_idx, col_map, vec![col_name])
            .map_err(frame_error_to_py)?
            .with_recorded_column_labels([label]);
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (normalize=false, sort=true, ascending=false, dropna=true))]
    pub fn value_counts(
        &self,
        normalize: bool,
        sort: bool,
        ascending: bool,
        dropna: bool,
    ) -> PyResult<PySeries> {
        let idx = self.inner.to_index();
        let counts = idx.value_counts_with_options(normalize, sort, ascending, dropna);
        let mut idx_labels = Vec::with_capacity(counts.len());
        let mut vals = Vec::with_capacity(counts.len());
        for (lbl, sc) in counts {
            idx_labels.push(lbl);
            vals.push(sc);
        }
        let col = Column::from_values(vals)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        let s = Series::new("count", Index::new(idx_labels), col).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `sort_values(*, return_indexer=False, ascending=True,
    /// na_position='last', key=None)` (see [`typed_sort_order`]) over the
    /// index's own sort keys (period ordinals, category codes), keeping its
    /// class - it was a plain Index, a categorical one sorted by text; the
    /// indexer and key were not taken (br-frankenpandas-h1kl9).
    #[pyo3(signature = (*, return_indexer=false, ascending=true, na_position="last", key=None))]
    pub fn sort_values(
        slf: &Bound<'_, Self>,
        return_indexer: bool,
        ascending: bool,
        na_position: &str,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        let this = slf.borrow();
        let order = typed_sort_order(
            slf.as_any(),
            this.inner.len(),
            ascending,
            na_position,
            key,
            || this.sort_keys(),
        )?;
        let inner = this.inner.take(&order).map_err(index_error_to_py)?;
        sorted_index_result(slf.py(), Self { inner }, order, return_indexer)
    }

    pub fn sort(&self) -> PyResult<Self> {
        let order = nargsort_keys(&self.sort_keys(), true, false);
        let inner = self.inner.take(&order).map_err(index_error_to_py)?;
        Ok(Self { inner })
    }

    #[getter]
    #[allow(non_snake_case)]
    pub fn T(&self) -> Self {
        self.clone()
    }

    pub fn drop(&self, labels: Vec<Bound<'_, PyAny>>) -> PyResult<PyIndex> {
        let mut to_drop = Vec::with_capacity(labels.len());
        for l in labels {
            to_drop.push(py_to_index_label(&l)?);
        }
        Ok(PyIndex {
            inner: self.inner.to_index().drop_labels(&to_drop),
        })
    }

    /// With no missing labels there is nothing to drop; dropping them is not
    /// supported yet (this returned the index with them).
    #[pyo3(signature = (how="any"))]
    pub fn dropna(&self, how: &str) -> PyResult<Self> {
        if !matches!(how, "any" | "all") {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "invalid how option: {how}"
            )));
        }
        // The NaT periods go (the index came back with them: its NaT was
        // not seen as missing; br-frankenpandas-u6p7i).
        let kept: Vec<usize> = self
            .inner
            .isna()
            .iter()
            .enumerate()
            .filter_map(|(position, &missing)| (!missing).then_some(position))
            .collect();
        let inner = self.inner.take(&kept).map_err(index_error_to_py)?;
        Ok(Self { inner })
    }

    /// pandas' `PeriodIndex.fillna(value)`: each NaT becomes `value`, a
    /// Period (or its text) of the index's frequency; any other value makes
    /// pandas an object Index, which is not supported (this returned the
    /// index with its NaT; br-frankenpandas-u6p7i).
    #[pyo3(signature = (value=None))]
    pub fn fillna(&self, value: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let missing = self.inner.isna();
        let Some(value) = value.filter(|value| !value.is_none() && missing.contains(&true)) else {
            return Ok(self.clone());
        };
        let fill = if let Ok(period) = value.extract::<PyRef<'_, PyPeriod>>() {
            Some(period.inner)
        } else if let Ok(text) = value.extract::<String>() {
            Period::parse(&text).ok()
        } else {
            None
        };
        let filled = fill.and_then(|fill| self.inner.putmask(&missing, fill).ok());
        filled.map(|inner| Self { inner }).ok_or_else(|| {
            not_implemented(
                "PeriodIndex.fillna with a value that is not a Period of its frequency (an object Index in pandas)",
            )
        })
    }

    fn as_py_index(&self) -> PyIndex {
        PyIndex {
            inner: self.inner.to_index(),
        }
    }

    fn all(&self) -> bool {
        self.as_py_index().all()
    }

    fn any(&self) -> bool {
        self.as_py_index().any()
    }

    /// pandas' `PeriodIndex.append(other)`, `other` an index or a list /
    /// tuple of them: periods stay a PeriodIndex, anything else is pandas'
    /// object Index (a lone index's elements were dropped; fvsao.60).
    fn append(&self, py: Python<'_>, other: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let pieces = append_pieces(other)?;
        let mut combined = self.inner.values().to_vec();
        for piece in &pieces {
            match piece.extract::<PyRef<'_, PyPeriodIndex>>() {
                Ok(pi) => combined.extend(pi.inner.values().iter().copied()),
                Err(_) => {
                    let this = Py::new(py, self.clone())?.into_bound(py).into_any();
                    return Ok(Py::new(py, object_index_of(this, pieces)?)?.into_any());
                }
            }
        }
        let mut out = PeriodIndex::new(combined);
        if let Some(n) = self.inner.name() {
            out = out.set_name(n);
        }
        Ok(Py::new(py, Self { inner: out })?.into_any())
    }

