    fn delete(&self, loc: &Bound<'_, PyAny>) -> PyResult<Self> {
        let dropped = delete_positions(loc, self.inner.len())?;
        let vals = self
            .inner
            .values()
            .iter()
            .enumerate()
            .filter(|(at, _)| !dropped.contains(at))
            .map(|(_, period)| *period)
            .collect();
        let mut out = PeriodIndex::new(vals);
        if let Some(n) = self.inner.name() {
            out = out.set_name(n);
        }
        Ok(Self { inner: out })
    }

