        let p_freq = PeriodFreq::parse(freq).ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>(format!("unsupported freq {freq}"))
        })?;
        Ok(Self {
            inner: PeriodIndex::from_ordinals(&ordinals, p_freq),
        })
