    /// Return the sum of the Series. Fewer than `min_count` valid values make
    /// it NaN, as in pandas.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn sum(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
        min_count: usize,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("sum", kwargs)?;
        self.refuse_string_reduction("sum")?;
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("sum")?;
        }
        // Python-object cells sum with their own + (they were joined as
        // text, ''; br-frankenpandas-8dqrn), and so does text beside a
        // missing value (8rzgf).
        if has_object_cells(self.inner.column()) || text_beside_missing(self.inner.column()) {
            return Python::attach(|py| {
                object_cells_reduce(py, &self.inner, "add", skipna, min_count)
            });
        }
        // An object column of numbers sums as Python does: a Python number,
        // 0 over none (it was a numpy one; qymo3).
        if let Some(numbers) = self.object_numbers() {
            let total = numbers.sum(axis, skipna, numeric_only, min_count, kwargs)?;
            return Python::attach(|py| {
                object_total(py, total, numbers.inner.count(), min_count, 0)
            });
        }
        if matches!(self.inner.dtype(), DType::Datetime64 { .. }) {
            // pandas' refusal, not the kernel's internal to_f64 message.
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "'DatetimeArray' with dtype datetime64[ns] does not support reduction 'sum'",
            ));
        }
        Python::attach(|py| {
            if self.inner.count() < min_count {
                return reduction_to_py(py, &self.inner, "sum", &Scalar::Null(NullKind::NaN));
            }
            let result = if !skipna {
                self.inner.sum_skipna(false)
            } else {
                self.inner.sum()
            }
            .map_err(frame_error_to_py)?;
            reduction_to_py(py, &self.inner, "sum", &result)
        })
    }

    /// Return the mean of the Series.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false, **kwargs))]
    fn mean(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("mean", kwargs)?;
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("mean")?;
        } else if let Some(numbers) = self.object_numbers() {
            // An object column of numbers averages as its numbers (it was
            // refused; qymo3).
            return numbers.mean(axis, skipna, numeric_only, kwargs);
        } else {
            // pandas sums an object column of text before reading it as a
            // number, so its refusal names the joined text.
            let column = self.inner.column();
            let texts: Option<String> = (is_object_column(column) && column.count() > 0)
                .then(|| {
                    column
                        .values()
                        .iter()
                        .filter(|value| !value.is_missing())
                        .map(|value| match value {
                            Scalar::Utf8(text) => Some(text.as_str()),
                            _ => None,
                        })
                        .collect::<Option<String>>()
                })
                .flatten();
            if let Some(joined) = texts {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "Could not convert string '{joined}' to numeric"
                )));
            }
            self.require_numeric("mean")?;
        }
        Python::attach(|py| {
            let result = if !skipna {
                self.inner.mean_skipna(false)
            } else {
                self.inner.mean()
            }
            .map_err(frame_error_to_py)?;
            // pandas' nanmean: a NaN over counted values (skipna=False
            // counts every one; inf - inf) is np.float64, a plain nan only
            // when none was counted (it was always plain;
            // br-frankenpandas-5mkvo).
            let counted = if skipna {
                self.inner.column().count()
            } else {
                self.inner.len()
            };
            if counted > 0
                && matches!(result, Scalar::Float64(value) if value.is_nan())
                && !is_nullable_extension(&self.inner.dtype())
            {
                return numpy_scalar(py, &result);
            }
            reduction_to_py(py, &self.inner, "mean", &result)
        })
    }

