    /// Return the first n elements. pandas slices `iloc[:n]`, so `n=None`
    /// keeps every element.
    #[pyo3(signature = (n=Some(5)))]
    fn head(&self, n: Option<i64>) -> PyResult<PySeries> {
        let n = n.unwrap_or(i64::MAX);
        let result = self
            .inner
            .head(n)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: result })
    }

    /// Return the last n elements.
    #[pyo3(signature = (n=5))]
    fn tail(&self, n: i64) -> PyResult<PySeries> {
        let result = self
            .inner
            .tail(n)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: result })
    }

    /// Return values as a Python list.
    fn tolist(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let column = self.inner.column();
        let values: Vec<Py<PyAny>> = materialized_values(column)
            .iter()
            .map(|s| cell_to_py(py, column, s))
            .collect::<PyResult<Vec<Py<PyAny>>>>()?;
        Ok(PyList::new(py, values)?.into_any().unbind())
    }

    /// `for v in s` yields each value as [`iterated_to_py`]; iteration fell
    /// back to `s[i]`, whose elements are numpy scalars.
    fn __iter__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let column = self.inner.column();
        let values = materialized_values(column)
            .iter()
            .map(|value| iterated_to_py(py, column, value))
            .collect::<PyResult<Vec<_>>>()?;
        Ok(PyList::new(py, values)?.try_iter()?.into_any().unbind())
    }

    /// Return the median value.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false, **kwargs))]
    fn median(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("median", kwargs)?;
        self.refuse_string_reduction("median")?;
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("median")?;
        } else if let Some(numbers) = self.object_numbers() {
            // An object column of numbers has its numbers' median (it was
            // refused; qymo3).
            return numbers.median(axis, skipna, numeric_only, kwargs);
        } else {
            self.require_numeric("median")?;
        }
        Python::attach(|py| {
            let r = if !skipna {
                self.inner.median_skipna(false)
            } else {
                self.inner.median()
            }
            .map_err(frame_error_to_py)?;
            // pandas' nanmedian returns a plain nan when skipna=False meets a
            // missing value (it was np.float64; br-frankenpandas-5mkvo).
            if !skipna
                && self.inner.column().count() < self.inner.len()
                && !is_nullable_extension(&self.inner.dtype())
            {
                return f64::NAN.into_py_any(py);
            }
            reduction_to_py(py, &self.inner, "median", &r)
        })
    }

