    /// Return the product of the values.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn prod(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
        min_count: Option<usize>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("prod", kwargs)?;
        self.refuse_string_reduction("prod")?;
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("prod")?;
        } else if has_object_cells(self.inner.column()) || text_beside_missing(self.inner.column())
        {
            // Python-object cells multiply with their own * (br-frankenpandas-8dqrn),
            // text beside a missing value too (8rzgf).
            return Python::attach(|py| {
                object_cells_reduce(py, &self.inner, "mul", skipna, min_count.unwrap_or(0))
            });
        } else if let Some(numbers) = self.object_numbers() {
            // An object column of numbers multiplies as Python does: a
            // Python number, 1 over none (it was refused; qymo3).
            let total = numbers.prod(axis, skipna, numeric_only, min_count, kwargs)?;
            return Python::attach(|py| {
                object_total(py, total, numbers.inner.count(), min_count.unwrap_or(0), 1)
            });
        } else {
            self.require_numeric("prod")?;
        }
        Python::attach(|py| {
            if self.inner.count() < min_count.unwrap_or(0) {
                return reduction_to_py(py, &self.inner, "prod", &Scalar::Null(NullKind::NaN));
            }
            let r = if !skipna {
                self.inner.prod_skipna(false)
            } else {
                self.inner.prod()
            }
            .map_err(frame_error_to_py)?;
            reduction_to_py(py, &self.inner, "prod", &r)
        })
    }

    /// Return the quantile at `q` in [0, 1].
    #[pyo3(signature = (q=None, interpolation="linear"))]
    fn quantile(
        &self,
        py: Python<'_>,
        q: Option<&Bound<'_, PyAny>>,
        interpolation: &str,
    ) -> PyResult<Py<PyAny>> {
        // Booleans and text are pandas' TypeError, not a number (o46uo).
        quantile_refusal(&[self.inner.column()], 0)?;
        if let Some(q_obj) = q {
            if let Ok(f) = q_obj.extract::<f64>() {
                let r = self
                    .inner
                    .quantile_with_interpolation(f, interpolation)
                    .map_err(frame_error_to_py)?;
                reduction_to_py(py, &self.inner, "quantile", &r)
            } else if let Ok(it) = q_obj.try_iter() {
                let mut qs = Vec::new();
                for item in it {
                    let item = item?;
                    qs.push(item.extract::<f64>()?);
                }
                let res = self
                    .inner
                    .quantile_list(&qs, interpolation)
                    .map_err(frame_error_to_py)?;
                // A masked column's quantiles are Float64 - Int64 when it
                // holds a missing value and every quantile is a whole number,
                // as pandas' masked quantile casts back (they were numpy
                // float64; br-frankenpandas-1t4kg).
                let res = match self.inner.dtype() {
                    DType::Int64Nullable | DType::Float64Nullable => {
                        let whole = self.inner.dtype() == DType::Int64Nullable
                            && self.inner.column().has_any_missing()
                            && res.column().values().iter().all(|value| match value {
                                Scalar::Float64(x) => x.fract() == 0.0,
                                Scalar::Int64(_) => true,
                                _ => false,
                            });
                        let target = if whole {
                            DType::Int64Nullable
                        } else {
                            DType::Float64Nullable
                        };
                        let column = res.column().astype(target).map_err(column_error_to_py)?;
                        Series::new(res.name().clone(), res.index().clone(), column)
                            .map_err(frame_error_to_py)?
                    }
                    _ => res,
                };
                Ok(Py::new(py, PySeries { inner: res })?.into_any())
            } else {
                Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "q must be a float or sequence of floats",
                ))
            }
        } else {
            let r = self
                .inner
                .quantile_with_interpolation(0.5, interpolation)
                .map_err(frame_error_to_py)?;
            reduction_to_py(py, &self.inner, "quantile", &r)
        }
    }

    /// Return the number of non-missing values, pandas' np.int64 (it was a
    /// Python int).
    fn count(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        numpy_scalar(
            py,
            &Scalar::Int64(i64::try_from(self.inner.count()).unwrap_or(i64::MAX)),
        )
    }

    /// Return the number of distinct non-missing values.
    #[pyo3(signature = (dropna=true))]
    fn nunique(&self, dropna: bool) -> usize {
        self.inner.nunique_with_dropna(dropna)
    }

    /// Return the sample skewness.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn skew(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<Py<PyAny>> {
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("skew")?;
        } else {
            self.require_numeric("skew")?;
        }
        // skipna=False: a missing value makes the moment NaN, as in pandas.
        if !skipna && self.inner.count() < self.inner.len() {
            return numpy_scalar(py, &Scalar::Float64(f64::NAN));
        }
        let value = self.inner.skew().map_err(frame_error_to_py)?;
        moment_to_py(py, value, self.inner.count() >= 3)
    }

    /// Return the sample (excess) kurtosis.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn kurt(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<Py<PyAny>> {
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("kurt")?;
        } else {
            self.require_numeric("kurt")?;
        }
        // skipna=False: a missing value makes the moment NaN, as in pandas.
        if !skipna && self.inner.count() < self.inner.len() {
            return numpy_scalar(py, &Scalar::Float64(f64::NAN));
        }
        let value = self.inner.kurt().map_err(frame_error_to_py)?;
        moment_to_py(py, value, self.inner.count() >= 4)
    }

    /// Return the absolute value of each element as a new Series; an
    /// object column's cell by cell ([`host_object_unary`]).
    fn abs(&self, py: Python<'_>) -> PyResult<PySeries> {
        // Text has no absolute value: Python's TypeError, as pandas' (it was
        // a ValueError; br-frankenpandas-wwbb1); no text, nothing to refuse.
        if self.inner.column().is_pandas_string() && !self.inner.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "bad operand type for abs(): 'str'",
            ));
        }
        if let Some(inner) = host_object_unary(py, &self.inner, "abs")? {
            return Ok(PySeries { inner });
        }
        let r = self
            .inner
            .abs()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: r })
    }

    /// Return the cumulative sum as a new Series.
    #[pyo3(signature = (axis=None, skipna=true, **kwargs))]
    fn cumsum(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("cumsum", kwargs)?;
        self.refuse_string_reduction("cumsum")?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        // Text beside a missing value accumulates through Python's + with
        // the missing ones as 0.0 (pandas' cumsum fill; as they are under
        // skipna=False), which is Python's TypeError where the fill meets
        // the text (it skipped them; br-frankenpandas-8rzgf).
        if text_beside_missing(self.inner.column()) {
            Python::attach(|py| -> PyResult<()> {
                let add = py.import("operator")?.getattr("add")?;
                let column = self.inner.column();
                let mut total: Option<Bound<'_, PyAny>> = None;
                for value in column.values() {
                    let cell = if skipna && value.is_missing() {
                        0.0_f64.into_bound_py_any(py)?
                    } else {
                        cell_to_py(py, column, value)?.into_bound(py)
                    };
                    total = Some(match total {
                        Some(total) => add.call1((total, cell))?,
                        None => cell,
                    });
                }
                Ok(())
            })?;
        }
        let r = self
            .inner
            .cumsum_with_skipna(skipna)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: r })
    }

    /// Return counts of unique values (descending) as a new Series. With
    /// `bins` (pandas' 4th parameter; dropna was read in its place and
    /// bins= raised TypeError) the values are counted per `pd.cut(bins,
    /// include_lowest=True)` bin, empty bins included.
    #[pyo3(signature = (normalize=false, sort=true, ascending=false, bins=None, dropna=true))]
    #[allow(clippy::cast_precision_loss)] // counts stay far below 2^53
    fn value_counts(
        &self,
        py: Python<'_>,
        normalize: bool,
        sort: bool,
        ascending: bool,
        bins: Option<&Bound<'_, PyAny>>,
        dropna: bool,
    ) -> PyResult<PySeries> {
        let counted = match bins.filter(|bins| !bins.is_none()) {
            Some(bins) => cut_series(py, &self.inner, bins, true, None, 3, true, "raise")?.0,
            None => self.inner.clone(),
        };
        let r = if bins.is_some_and(|bins| !bins.is_none()) {
            // pandas counts the bins without a missing one whatever dropna
            // says, and normalizes by the length of every value, missing
            // ones included (value_counts_internal); it kept a NaN bin under
            // dropna=False and divided by the values counted
            // (br-frankenpandas-n57tz).
            let counts = counted
                .value_counts_with_options(false, sort, ascending, true)
                .map_err(frame_error_to_py)?;
            if normalize {
                let total = self.inner.len() as f64;
                let shares = counts
                    .values()
                    .iter()
                    .map(|count| match count {
                        Scalar::Int64(count) => Scalar::Float64(*count as f64 / total),
                        other => other.clone(),
                    })
                    .collect();
                Series::new(
                    "proportion",
                    counts.index().clone(),
                    Column::from_values(shares).map_err(column_error_to_py)?,
                )
                .map_err(frame_error_to_py)?
            } else {
                counts
            }
        } else {
            counted
                .value_counts_with_options(normalize, sort, ascending, dropna)
                .map_err(frame_error_to_py)?
        };
        // pandas' binned counts sit on an unnamed index (the bins are not
        // the Series' values; it was named after the Series).
        let r = if bins.is_some_and(|bins| !bins.is_none()) {
            Series::new(
                r.name(),
                r.index().rename_index(None::<&str>),
                r.column().clone(),
            )
            .map_err(frame_error_to_py)?
        } else {
            r
        };
        // A masked array counts its missing values after its values
        // (BaseMaskedArray.value_counts), so among equal counts - and
        // unsorted - the missing row follows the others (it kept its first
        // missing value's place; br-frankenpandas-mv4w4). A numpy or a
        // `string` column keeps first appearance, as pandas.
        let r = if !dropna
            && bins.is_none_or(|bins| bins.is_none())
            && matches!(
                self.inner.column().dtype(),
                DType::Int64Nullable | DType::Float64Nullable | DType::BoolNullable
            )
            && let Some(missing) = r.index().labels().iter().position(IndexLabel::is_missing)
        {
            let counts: Vec<f64> = r
                .values()
                .iter()
                .map(|count| count.to_f64().unwrap_or(0.0))
                .collect();
            let mut rows: Vec<usize> = (0..r.len()).filter(|&row| row != missing).collect();
            let ahead = rows
                .iter()
                .take_while(|&&row| {
                    !sort
                        || if ascending {
                            counts[row] <= counts[missing]
                        } else {
                            counts[row] >= counts[missing]
                        }
                })
                .count();
            rows.insert(ahead, missing);
            let positions: Vec<i64> = rows
                .iter()
                .map(|&row| i64::try_from(row).unwrap_or(i64::MAX))
                .collect();
            r.take(&positions).map_err(frame_error_to_py)?
        } else {
            r
        };
        // A nullable Series counts in the masked Int64 (its proportions
        // Float64), as pandas' (int64 / float64) - a `string` one too
        // (fvsao.59).
        if self.inner.dtype().is_nullable() || self.inner.column().is_pandas_string() {
            let target = if normalize {
                DType::Float64Nullable
            } else {
                DType::Int64Nullable
            };
            let column = r.column().astype(target).map_err(column_error_to_py)?;
            // The missing value's label is pd.NA itself, as pandas' (it
            // printed None; 05cm6).
            let index = if r.index().labels().iter().any(IndexLabel::is_missing) {
                let na = IndexLabel::Object(fp_types::ObjectValue::Host(fp_types::HostValue::new(
                    PyHost(na_object(py)?),
                )));
                let labels = r
                    .index()
                    .labels()
                    .iter()
                    .map(|label| {
                        if label.is_missing() {
                            na.clone()
                        } else {
                            label.clone()
                        }
                    })
                    .collect();
                Index::new(labels).rename_index(r.index().name())
            } else {
                r.index().clone()
            };
            let r = Series::new(r.name(), index, column).map_err(frame_error_to_py)?;
            return Ok(PySeries { inner: r });
        }
        // A categorical's counts sit on a CategoricalIndex (cld41).
        let r = if bins.is_none_or(|bins| bins.is_none()) {
            with_key_categories(r, self.inner.column())?
        } else {
            r
        };
        Ok(PySeries { inner: r })
    }

    /// Return the distinct values (order of first appearance) as a numpy
    /// array in the column's numpy dtype, as pandas' - it was a Python list
    /// (fvsao.30).
    fn unique(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        // A categorical's are a Categorical keeping every category and the
        // ordering, as pandas' Categorical.unique; an object array dropped
        // them (br-frankenpandas-ba9pc).
        if let Some(meta) = self.inner.column().categorical() {
            let codes = self
                .inner
                .unique()
                .iter()
                .map(|value| {
                    meta.categories
                        .iter()
                        .position(|category| !value.is_missing() && category == value)
                        .map_or(-1, |position| position as i64)
                })
                .collect();
            let inner = Series::from_categorical_codes(
                self.inner.name(),
                codes,
                meta.categories.clone(),
                meta.ordered,
            )
            .map_err(frame_error_to_py)?;
            return PyCategorical { inner }.into_py_any(py);
        }
        // An extension dtype's are its array: a datetime / duration column's
        // a DatetimeArray / TimedeltaArray (in its zone; the numpy array
        // iterated numpy datetime64 / timedelta64 scalars, fvsao.17, and they
        // were then a DatetimeIndex / TimedeltaIndex), a masked or string
        // column's its IntegerArray / StringArray ... (they were numpy
        // arrays, Int64's float64; br-frankenpandas-5y62q).
        let source = self.inner.column();
        if ArrayKind::of(source) != ArrayKind::Numpy {
            let distinct = Column::new(source.dtype(), self.inner.unique())
                .map_err(column_error_to_py)?
                .keeping_dtype_of(source);
            return extension_array(py, distinct);
        }
        // The distinct values are the column's own: an int32 column's are an
        // int32 array (fvsao.23); missing values alone (or none) keep the
        // column's dtype - a float64 column's [nan] and an empty int64
        // column's [] were object arrays (wsu74).
        let distinct = self.inner.unique();
        let column = if distinct.iter().all(Scalar::is_missing) && source.dtype() != DType::Null {
            Column::new(source.dtype(), distinct)
        } else {
            Column::from_values(distinct)
        }
        .map_err(column_error_to_py)?
        .keeping_dtype_of(source);
        Ok(column_ndarray(py, &column)?.unbind())
    }

    /// Sort the Series by value, returning a new Series.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (axis=None, ascending=true, inplace=false, kind=None, na_position="last", ignore_index=false, key=None))]
    fn sort_values(
        &mut self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        ascending: bool,
        inplace: bool,
        kind: Option<&str>,
        na_position: &str,
        ignore_index: bool,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        validate_sort_kind(kind)?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }
            let sorted = match key {
                Some(key) => {
                    let keyed = key.call1((PySeries {
                        inner: self.inner.clone(),
                    },))?;
                    self.keyed_sort(py, &keyed, ascending, na_position)?
                }
                None => self
                    .inner
                    .sort_values_na(ascending, na_position)
                    .map_err(frame_error_to_py)?,
            };
            let final_series = if ignore_index {
                match sorted.reset_index(true).map_err(frame_error_to_py)? {
                    fp_frame::SeriesResetIndexResult::Series(s) => s,
                    fp_frame::SeriesResetIndexResult::DataFrame(_) => unreachable!(),
                }
            } else {
                sorted
            };
            Ok(PySeries {
                inner: final_series,
            })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Fill missing values with `value` or using `method`, returning a new Series.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (value=None, method=None, axis=None, inplace=false, limit=None, downcast=None))]
    fn fillna(
        &mut self,
        py: Python<'_>,
        value: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<usize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.fillna", &[("downcast", downcast.is_none())])?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }

            if value.is_none() && method.is_none() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Must specify a fill 'value' or 'method'.",
                ));
            }

            if value.is_some() && method.is_some() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Cannot specify both 'value' and 'method'.",
                ));
            }
            // pandas' deprecation of a fill method.
            if method.is_some_and(|m| matches!(m, "ffill" | "pad" | "bfill" | "backfill")) {
                PyErr::warn(
                    py,
                    &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
                    c"Series.fillna with 'method' is deprecated and will raise in a future version. Use obj.ffill() or obj.bfill() instead.",
                    1,
                )?;
            }

            if self.inner.is_empty() {
                return Ok(PySeries {
                    inner: self.inner.clone(),
                });
            }

            if let Some(m) = method {
                let res = match m {
                    "ffill" | "pad" => self.inner.ffill(limit).map_err(frame_error_to_py)?,
                    "bfill" | "backfill" => self.inner.bfill(limit).map_err(frame_error_to_py)?,
                    other => {
                        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                            "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                        )));
                    }
                };
                return Ok(PySeries { inner: res });
            }

            let val = value.expect("value is some");

            // A `string` Series holds text only: a scalar fill with nothing
            // missing changes nothing (it became object), and one that is
            // not text cannot fill a missing value - pandas' TypeError (it
            // was stringified; br-frankenpandas-wwbb1).
            if self.inner.column().is_pandas_string()
                && !val.is_instance_of::<PyDict>()
                && val.extract::<PyRef<PySeries>>().is_err()
            {
                // A missing fill (NaN, None, pd.NA) leaves <NA> as it is (it
                // stored a NaN printing 'nan').
                let missing_fill = isna(py, val)?.bind(py).is_truthy()?;
                if !self.inner.column().has_any_missing() || missing_fill {
                    return Ok(PySeries {
                        inner: self.inner.clone(),
                    });
                }
                if !val.is_instance_of::<pyo3::types::PyString>() {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                        "Cannot set non-string value '{}' into a StringArray.",
                        val.str()?
                    )));
                }
            }

            // 1. Value is a Series
            if let Ok(other_s) = val.extract::<PyRef<PySeries>>() {
                // An equal index - repeated labels too - fills row for row,
                // as pandas' (the reindex refused a repeated index;
                // br-frankenpandas-rbiki).
                let aligned = if other_s.inner.index() == self.inner.index() {
                    other_s.inner.clone()
                } else {
                    other_s
                        .inner
                        .reindex(self.inner.index().labels().to_vec())
                        .map_err(frame_error_to_py)?
                };
                let new_col = fill_column_with_other(self.inner.column(), aligned.column(), limit)
                    .map_err(frame_error_to_py)?;
                let out_s = Series::new(
                    self.inner.name().clone(),
                    self.inner.index().clone(),
                    new_col,
                )
                .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: out_s });
            }

            // 2. Value is a Dict
            if let Ok(dict) = val.cast::<PyDict>() {
                let fill_col =
                    py_dict_to_series_fill_column(py, dict, self.inner.index().labels())?;
                let new_col = fill_column_with_other(self.inner.column(), &fill_col, limit)
                    .map_err(frame_error_to_py)?;
                let out_s = Series::new(
                    self.inner.name().clone(),
                    self.inner.index().clone(),
                    new_col,
                )
                .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: out_s });
            }

            // 3. Scalar fill: a Python object no scalar holds (a date) fills
            // as an object cell (it raised; fvsao.67); a list is refused, as
            // pandas.
            if val.is_instance_of::<PyList>() || val.is_instance_of::<pyo3::types::PyTuple>() {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "\"value\" parameter must be a scalar or dict, but you passed a \"{}\"",
                    val.get_type().name()?
                )));
            }
            refuse_masked_int_fill(py, self.inner.column(), val)?;
            if let Some(inner) = temporal_object_fill(py, &self.inner, val, limit)? {
                return Ok(PySeries { inner });
            }
            let fill_val = py_to_cell(py, val)?;
            let new_col = fill_column_with_scalar(self.inner.column(), &fill_val, limit)
                .map_err(frame_error_to_py)?;
            let out_s = Series::new(
                self.inner.name().clone(),
                self.inner.index().clone(),
                new_col,
            )
            .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: out_s })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Drop missing values: a new Series, or in place with `inplace=True`
    /// (None returned; it was an unexpected keyword - br-frankenpandas-n57tz).
    #[pyo3(signature = (axis=None, inplace=false, how=None, ignore_index=false))]
    fn dropna(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        how: Option<&str>,
        ignore_index: bool,
    ) -> PyResult<Option<PySeries>> {
        let result = (|| -> PyResult<PySeries> {
            let ax_opt = parse_axis_param_for_type(axis, "Series")?;
            if let Some(ax) = ax_opt {
                if ax != 0 {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {ax} for object type Series"
                    )));
                }
            }
            if let Some(h) = how {
                if !matches!(h, "any" | "all") {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "invalid how option: {h}"
                    )));
                }
            }

            let mut res = self.inner.dropna().map_err(frame_error_to_py)?;
            // reset_index(drop=true) is always a Series.
            if ignore_index
                && let fp_frame::SeriesResetIndexResult::Series(s) =
                    res.reset_index(true).map_err(frame_error_to_py)?
            {
                res = s;
            }
            Ok(PySeries { inner: res })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Clone this Series (pandas' `copy(deep=True)`). A shallow copy
    /// (`deep=False`) shares its data with the original in pandas 2.2, so a
    /// write through either shows in both; frankenpandas' Series own their
    /// data, so that is refused rather than answered with a deep copy.
    #[pyo3(signature = (deep=true))]
    fn copy(&self, deep: bool) -> PyResult<PySeries> {
        if !deep {
            return Err(not_implemented(
                "Series.copy(deep=False) (a shallow copy sharing the original's data)",
            ));
        }
        Ok(self.clone())
    }

    /// Return the cumulative product as a new Series.
    #[pyo3(signature = (axis=None, skipna=true, **kwargs))]
    fn cumprod(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("cumprod", kwargs)?;
        self.refuse_string_reduction("cumprod")?;
        // A product of durations is no duration: pandas' TypeError (it
        // answered; br-frankenpandas-wwbb1).
        if self.inner.dtype() == DType::Timedelta64 {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "cumprod not supported for Timedelta.",
            ));
        }
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let r = self
            .inner
            .cumprod_with_skipna(skipna)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: r })
    }

