    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None, limit_area=None))]
    fn ffill(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
        limit_area: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.ffill", &[("downcast", downcast.is_none())])?;
        let inside = fill_limit_area(limit_area)?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }
            let limit_usize = match limit {
                Some(l) if l <= 0 => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Limit must be greater than 0",
                    ));
                }
                Some(l) => Some(l as usize),
                None => None,
            };
            let res = self.inner.ffill(limit_usize).map_err(frame_error_to_py)?;
            let res = keep_masked_dtype(self.inner.column(), res)?;
            Ok(PySeries {
                inner: series_fill_area(&self.inner, res, inside)?,
            })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None, limit_area=None))]
    fn bfill(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
        limit_area: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.bfill", &[("downcast", downcast.is_none())])?;
        let inside = fill_limit_area(limit_area)?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }
            let limit_usize = match limit {
                Some(l) if l <= 0 => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Limit must be greater than 0",
                    ));
                }
                Some(l) => Some(l as usize),
                None => None,
            };
            let res = self.inner.bfill(limit_usize).map_err(frame_error_to_py)?;
            let res = keep_masked_dtype(self.inner.column(), res)?;
            Ok(PySeries {
                inner: series_fill_area(&self.inner, res, inside)?,
            })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    #[pyo3(signature = (other, method="pearson", min_periods=None))]
    fn corr(
        &self,
        py: Python<'_>,
        other: &PySeries,
        method: Option<&str>,
        min_periods: Option<usize>,
    ) -> PyResult<Py<PyAny>> {
        let m = method.unwrap_or("pearson");
        // pandas: NaN - a Python float - when fewer than min_periods pairs are
        // both present (it was refused above 2; fewer than two pairs are NaN
        // anyway).
        if let Some(floor) = min_periods.filter(|&floor| floor > 2)
            && matches!(m, "pearson" | "spearman" | "kendall")
            && self
                .inner
                .aligned_numeric_pairs(&other.inner)
                .map_err(frame_error_to_py)?
                .len()
                < floor
        {
            return Ok(pyo3::types::PyFloat::new(py, f64::NAN).into_any().unbind());
        }
        let res = match m {
            "pearson" => self.inner.corr(&other.inner),
            "spearman" => self.inner.corr_spearman(&other.inner),
            "kendall" => self.inner.corr_kendall(&other.inner),
            other_m => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Invalid method '{other_m}', expecting one of ('pearson', 'kendall', 'spearman')"
                )));
            }
        };
        // np.float64, NaN included, as pandas' (it was a Python float).
        numpy_scalar(py, &Scalar::Float64(res.map_err(frame_error_to_py)?))
    }

    #[pyo3(signature = (other, min_periods=None, ddof=1))]
    fn cov(
        &self,
        py: Python<'_>,
        other: &PySeries,
        min_periods: Option<usize>,
        ddof: Option<usize>,
    ) -> PyResult<Py<PyAny>> {
        let ddof_val = ddof.unwrap_or(1);
        let value = self
            .inner
            .cov_with_options(&other.inner, min_periods, ddof_val)
            .map_err(frame_error_to_py)?;
        numpy_scalar(py, &Scalar::Float64(value))
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=None, frac=None, replace=false, weights=None, random_state=None, axis=None, ignore_index=false))]
    /// pandas' `Series.sample`: the rows pandas draws for the same seed,
    /// `weights` included (see [`pandas_sample_positions`]).
    fn sample(
        &self,
        py: Python<'_>,
        n: Option<i64>,
        frac: Option<f64>,
        replace: bool,
        weights: Option<&Bound<'_, PyAny>>,
        random_state: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        ignore_index: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let weights = weights
            .filter(|weights| !weights.is_none())
            .map(|weights| sample_weights(py, weights, self.inner.index().labels(), None))
            .transpose()?;
        let positions: Vec<i64> = pandas_sample_positions(
            py,
            self.inner.len(),
            n,
            frac,
            replace,
            weights,
            random_state,
        )?
        .into_iter()
        .map(|position| i64::try_from(position).unwrap_or(i64::MAX))
        .collect();
        let mut res = self.inner.take(&positions).map_err(frame_error_to_py)?;
        if ignore_index {
            res = match res
                .reset_index_with_name(true, None)
                .map_err(frame_error_to_py)?
            {
                fp_frame::SeriesResetIndexResult::Series(s) => s,
                _ => unreachable!(),
            };
        }
        Ok(PySeries { inner: res })
    }

    /// pandas' `Series.groupby` signature (br-frankenpandas-n57tz: only `by`
    /// and `sort` were accepted); as_index=False raises as it does in pandas;
    /// a category key is checked against `observed` and `sort` (see
    /// `check_category_key`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (by=None, axis=None, level=None, as_index=true, sort=true, group_keys=true, observed=None, dropna=true))]
    pub fn groupby(
        &self,
        py: Python<'_>,
        by: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        as_index: bool,
        sort: Option<bool>,
        group_keys: bool,
        observed: Option<bool>,
        dropna: bool,
    ) -> PyResult<Py<PyAny>> {
        if !as_index {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "as_index=False only valid with DataFrame",
            ));
        }
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        // pd.Grouper(freq=) is pandas' TimeGrouper over the index: the same
        // bins as resample, empty ones included (it raised).
        if let Some(Ok(grouper)) = by.map(|by| by.extract::<PyRef<'_, PyGrouper>>()) {
            return match (&grouper.key, &grouper.level, &grouper.freq) {
                (None, None, Some(freq)) => PyResampler::new(
                    ResampleTarget::Series(self.inner.clone()),
                    freq.clone(),
                    None,
                    None,
                    None,
                )?
                .into_py_any(py),
                (Some(key), _, _) => {
                    Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(key.clone()))
                }
                _ => Err(not_implemented("this pd.Grouper form on a Series")),
            };
        }
        let sort = sort.unwrap_or(true);
        let by_series = match (by.filter(|b| !b.is_none()), level.filter(|l| !l.is_none())) {
            // A list key's groups are pandas' Index of its unique values:
            // ints beside a missing value kept by dropna=False are float64
            // labels (1.0, NaN; they were int64 labels holding the gap),
            // with dropna the ints alone, int64 - unless a float NaN made
            // numpy's array of the list float64 (br-frankenpandas-u1dey).
            (Some(by), None)
                if by.cast::<PyList>().is_ok_and(|list| {
                    !dropna
                        || list
                            .iter()
                            .any(|item| item.is_instance_of::<pyo3::types::PyFloat>())
                }) =>
            {
                let key = extract_or_build_series(py, by, &self.inner)?;
                let values = pandas_promote_int_with_missing(key.values().to_vec());
                Series::from_values(key.name(), key.index().labels().to_vec(), values)
                    .map_err(frame_error_to_py)?
            }
            (Some(by), None) => extract_or_build_series(py, by, &self.inner)?,
            // pandas' level= groups by the index itself (fvsao.19); over a
            // MultiIndex by one of its levels (fvsao.36).
            (None, Some(level)) => {
                let index = self.inner.index();
                if let Some(multi) = index.row_multiindex() {
                    let positions = groupby_level_positions(multi, level)?;
                    let [position] = positions[..] else {
                        return self
                            .levels_groupby(level, sort, dropna, group_keys)?
                            .into_py_any(py);
                    };
                    let values: Vec<Scalar> = multi
                        .get_level_values(position)
                        .map_err(index_error_to_py)?
                        .labels()
                        .iter()
                        .map(index_label_to_scalar)
                        .collect();
                    let name = multi.names().get(position).cloned().flatten();
                    Series::new(
                        name.unwrap_or_default(),
                        index.clone(),
                        Column::from_values(values).map_err(column_error_to_py)?,
                    )
                    .map_err(frame_error_to_py)?
                } else {
                    let values = flat_index_level_values(index, level)?;
                    Series::new(
                        index.name().cloned().unwrap_or_default(),
                        index.clone(),
                        values,
                    )
                    .map_err(frame_error_to_py)?
                }
            }
            (Some(_), Some(_)) => {
                return Err(not_implemented("Series.groupby with both by and level"));
            }
            (None, None) => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "You have to supply one of 'by' and 'level'",
                ));
            }
        };
        refuse_unhashable_keys(py, by_series.column())?;
        let unused = if by_series.column().categorical().is_some() {
            let keys = by_series.to_frame(Some("key")).map_err(frame_error_to_py)?;
            check_category_keys(py, &keys, &["key".to_owned()], observed)?
        } else {
            Vec::new()
        };
        let (series, by) = if self.inner.index() != by_series.index()
            && !self.inner.index().has_duplicates()
            && !by_series.index().has_duplicates()
        {
            let common_labels: Vec<IndexLabel> = self
                .inner
                .index()
                .labels()
                .iter()
                .filter(|lbl| by_series.index().labels().contains(lbl))
                .cloned()
                .collect();
            let aligned_self = self
                .inner
                .reindex(common_labels.clone())
                .map_err(frame_error_to_py)?;
            let aligned_by = by_series
                .reindex(common_labels)
                .map_err(frame_error_to_py)?;
            (aligned_self, aligned_by)
        } else {
            (self.inner.clone(), by_series)
        };
        let (by, groups) = if dropna {
            (by, None)
        } else if unused.is_empty() {
            let (codes, groups) = missing_key_groups(&by, sort)?;
            (codes, Some(groups))
        } else {
            return Err(not_implemented(
                "Series.groupby(dropna=False) by a category key with unused categories",
            ));
        };
        PySeriesGroupBy {
            series,
            by,
            sort,
            as_index: true,
            groups,
            unused,
            group_keys,
        }
        .into_py_any(py)
    }

    /// pandas' `Series.resample(rule, axis, closed, label, convention, kind,
    /// on, level, origin, offset, group_keys)`; `rule` a string alias or an
    /// offset object. axis / convention / kind warn pandas' deprecations
    /// ([`resample_deprecations`]); `on` is pandas' KeyError (a Series has
    /// no columns), `level` 0 or the index's name ([`resample_level`]),
    /// `offset` moves a fixed step's origin ([`resample_offset_origin`]).
    /// group_keys keys an apply's rows by their bin (br-frankenpandas-jno5s).
    /// The first argument was named `freq` and the others were unexpected
    /// keywords (br-frankenpandas-n57tz).
    #[pyo3(signature = (
        rule,
        axis=Passed(None),
        closed=None,
        label=None,
        convention=Passed(None),
        kind=Passed(None),
        on=None,
        level=None,
        origin=None,
        offset=None,
        group_keys=false
    ))]
    #[allow(clippy::too_many_arguments)]
    fn resample(
        &self,
        py: Python<'_>,
        rule: &Bound<'_, PyAny>,
        axis: Passed<'_>,
        closed: Option<String>,
        label: Option<String>,
        convention: Passed<'_>,
        kind: Passed<'_>,
        on: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        origin: Option<String>,
        offset: Option<&Bound<'_, PyAny>>,
        group_keys: bool,
    ) -> PyResult<PyResampler> {
        resample_deprecations(py, "Series", &axis, &kind, &convention)?;
        if let Some(on) = on.filter(|on| !on.is_none()) {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                on.clone().unbind(),
            ));
        }
        resample_level(self.inner.index(), level, false)?;
        let rule = freq_alias(rule, "resample")?;
        let (mut closed, mut label) = (closed, label);
        let origin = resample_offset_origin(
            self.inner.index(),
            &rule,
            origin,
            offset,
            &mut closed,
            &mut label,
        )?;
        PyResampler::new(
            ResampleTarget::Series(self.inner.clone()),
            rule,
            closed,
            label,
            origin,
        )
        .map(|resampler| resampler.with_group_keys(group_keys))
    }

    /// pandas' `asfreq(freq, method=None, how=None, normalize=False,
    /// fill_value=None)`: `fill_value` fills the new rows (it was an
    /// unknown keyword though fp-frame took it; rvqoi).
    #[pyo3(signature = (freq, method=None, how=None, normalize=false, fill_value=None))]
    pub fn asfreq(
        &self,
        py: Python<'_>,
        freq: &str,
        method: Option<&str>,
        how: Option<&str>,
        normalize: bool,
        fill_value: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Self> {
        unsupported_params(
            "Series.asfreq",
            &[("how", how.is_none()), ("normalize", !normalize)],
        )?;
        let fill = fill_value
            .filter(|fill| !fill.is_none())
            .map(|fill| py_to_scalar(py, fill))
            .transpose()?;
        let res = self
            .inner
            .asfreq_with_options(freq, method, fill)
            .map_err(frame_error_to_py)?;
        Ok(Self { inner: res })
    }

    #[getter]
    fn hasnans(&self) -> bool {
        self.inner.hasnans()
    }

    #[getter]
    fn nbytes(&self) -> usize {
        self.inner.nbytes()
    }

