    /// The POSITIONS of the columns a moment reduction reads: a repeated
    /// column key is its own column (by name every one read the first;
    /// br-frankenpandas-i17d4).
    fn get_reduction_columns(
        &self,
        stat: &str,
        numeric_only: bool,
    ) -> Result<Vec<usize>, FrameError> {
        let mut cols = Vec::new();
        for position in 0..self.inner.num_columns() {
            if let Some(col) = self.inner.column_at(position) {
                let dtype = col.dtype();
                // A bool column holding a missing value is pandas' object
                // column: numeric_only leaves it out (br-frankenpandas-ildvj).
                let object_bool = dtype == DType::Bool && col.has_any_missing();
                if object_bool && numeric_only {
                    continue;
                }
                // pandas' masked Int64 / Float64 / boolean are numbers too
                // (they raised "could not convert"; br-frankenpandas-8u5eh).
                if matches!(
                    dtype,
                    DType::Int64
                        | DType::Float64
                        | DType::Bool
                        | DType::Int64Nullable
                        | DType::Float64Nullable
                        | DType::BoolNullable
                ) {
                    cols.push(position);
                } else if dtype == DType::Timedelta64 {
                    if !numeric_only {
                        if stat == "std" {
                            cols.push(position);
                        } else {
                            return Err(FrameError::CompatibilityRejected(format!(
                                "'TimedeltaArray' with dtype timedelta64[ns] does not support reduction '{stat}'"
                            )));
                        }
                    }
                } else if !numeric_only {
                    let witness = col
                        .values()
                        .iter()
                        .find(|v| !v.is_missing())
                        .map(|v| match v {
                            Scalar::Utf8(text) => text.clone(),
                            other => format!("{other:?}"),
                        })
                        .unwrap_or_default();
                    return Err(FrameError::CompatibilityRejected(format!(
                        "could not convert string to float: '{witness}'"
                    )));
                }
            }
        }
        Ok(cols)
    }

    fn moment_reducer_internal(
        &self,
        stat: &str,
        axis: usize,
        skipna: bool,
        ddof: usize,
        numeric_only: bool,
    ) -> Result<Series, FrameError> {
        let candidate_cols = self.get_reduction_columns(stat, numeric_only)?;

        if axis == 1 {
            let row_count = self.inner.len();
            if candidate_cols.is_empty() {
                let out_values = vec![Scalar::Null(NullKind::NaN); row_count];
                let col = Column::from_values(out_values).map_err(FrameError::Column)?;
                return Series::new("".to_string(), self.inner.index().clone(), col);
            }

            let has_td = candidate_cols.iter().any(|&position| {
                self.inner
                    .column_at(position)
                    .is_some_and(|c| c.dtype() == DType::Timedelta64)
            });
            let has_num = candidate_cols.iter().any(|&position| {
                self.inner
                    .column_at(position)
                    .is_some_and(|c| c.dtype() != DType::Timedelta64)
            });
            if has_td && has_num {
                return Err(FrameError::CompatibilityRejected(
                    "float() argument must be a string or a real number, not 'Timedelta'".into(),
                ));
            }

            let is_all_td = has_td;
            let columns: Vec<&Column> = candidate_cols
                .iter()
                .filter_map(|&position| self.inner.column_at(position))
                .collect();

            let mut out_values = Vec::with_capacity(row_count);
            for r in 0..row_count {
                let mut row_has_missing = false;
                let mut valid_nums = Vec::with_capacity(columns.len());

                for col in &columns {
                    let val = &col.values()[r];
                    if val.is_missing() {
                        row_has_missing = true;
                        if !skipna {
                            break;
                        }
                    } else {
                        let num_opt = match val {
                            Scalar::Timedelta64(ns) if *ns != Timedelta::NAT => Some(*ns as f64),
                            _ => val.to_f64().ok(),
                        };
                        if let Some(num) = num_opt {
                            valid_nums.push(num);
                        }
                    }
                }

                if !skipna && row_has_missing {
                    if is_all_td {
                        out_values.push(Scalar::Timedelta64(Timedelta::NAT));
                    } else {
                        out_values.push(Scalar::Null(NullKind::NaN));
                    }
                    continue;
                }

                let n = valid_nums.len();
                if n <= ddof {
                    if is_all_td {
                        out_values.push(Scalar::Timedelta64(Timedelta::NAT));
                    } else {
                        out_values.push(Scalar::Null(NullKind::NaN));
                    }
                } else {
                    let n_f = n as f64;
                    let mean = valid_nums.iter().sum::<f64>() / n_f;
                    let m2: f64 = valid_nums.iter().map(|x| (x - mean).powi(2)).sum();
                    let var = m2 / (n_f - ddof as f64);
                    let res = match stat {
                        "var" => var,
                        "std" => var.sqrt(),
                        "sem" => var.sqrt() / n_f.sqrt(),
                        _ => f64::NAN,
                    };
                    if is_all_td {
                        if res.is_nan() {
                            out_values.push(Scalar::Timedelta64(Timedelta::NAT));
                        } else {
                            let clamped = res.clamp(i64::MIN as f64, i64::MAX as f64);
                            out_values.push(Scalar::Timedelta64(clamped.round() as i64));
                        }
                    } else if res.is_nan() {
                        out_values.push(Scalar::Null(NullKind::NaN));
                    } else {
                        out_values.push(Scalar::Float64(res));
                    }
                }
            }

            let col = Column::from_values(out_values).map_err(FrameError::Column)?;
            Series::new("".to_string(), self.inner.index().clone(), col)
        } else {
            // axis == 0
            let mut labels = Vec::with_capacity(candidate_cols.len());
            let mut values = Vec::with_capacity(candidate_cols.len());

            let names = self.inner.column_names();
            for position in candidate_cols {
                // Indexed as a reduction: the columns' typed labels (0, not
                // '0'), their range and MultiIndex levels (g3bux).
                labels.push(self.inner.column_label(names[position]));
                if let Some(col) = self.inner.column_at(position) {
                    let val = match stat {
                        "var" => col.var_skipna(ddof, skipna),
                        "std" => col.std_skipna(ddof, skipna),
                        "sem" => col.sem_skipna(ddof, skipna),
                        _ => Scalar::Null(NullKind::NaN),
                    };
                    values.push(val);
                } else {
                    values.push(Scalar::Null(NullKind::NaN));
                }
            }

            let span = self
                .inner
                .column_range_span()
                .filter(|_| labels == self.inner.column_labels());
            Series::from_values("".to_string(), labels, values)
                .map(|series| self.inner.with_column_levels(series.with_range_span(span)))
        }
    }

    pub fn std_internal(
        &self,
        axis: usize,
        skipna: bool,
        ddof: usize,
        numeric_only: bool,
    ) -> Result<Series, FrameError> {
        self.moment_reducer_internal("std", axis, skipna, ddof, numeric_only)
    }

