    /// `"a" in df` checks the column labels, as in pandas: under a two-level
    /// column axis a `(top, sub)` tuple or a top-level label.
    fn __contains__(&self, key: &Bound<'_, PyAny>) -> PyResult<bool> {
        if let Some((_, positions)) = self.multi_column_selection(key)? {
            return Ok(!positions.is_empty());
        }
        // A column label of any type, matched typed (0 in DataFrame([[1]]),
        // not '0'; fvsao.32).
        Ok(self.column_name_for(key).is_some())
    }

    /// pandas' `describe(percentiles=None, include=None, exclude=None)` (it
    /// took no arguments; fvsao.30): the numeric columns by default,
    /// `percentiles` for the quantile rows, include / exclude by dtype, and
    /// include='all' pandas' union layout - count, unique, top, freq, then the
    /// numeric rows, NaN where a statistic does not apply.
    #[pyo3(signature = (percentiles=None, include=None, exclude=None))]
    fn describe<'py>(
        slf: &Bound<'py, Self>,
        percentiles: Option<Vec<f64>>,
        include: Option<&Bound<'py, PyAny>>,
        exclude: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let py = slf.py();
        let include = describe_dtype_names(include)?;
        let exclude = describe_dtype_names(exclude)?;
        let this = slf.borrow();
        let numeric_describe = |frame: &DataFrame| match &percentiles {
            Some(percentiles) => frame.describe_with_percentiles(percentiles),
            None => frame.describe(),
        };
        // The described columns keep their typed labels (a new column Index).
        let wrap = |frame: DataFrame| -> PyResult<Bound<'py, PyAny>> {
            Ok(Bound::new(
                py,
                PyDataFrame {
                    inner: frame.with_typed_labels_of(&this.inner),
                },
            )?
            .into_any())
        };
        if include.is_empty() && exclude.is_empty() {
            // pandas describes the numbers and the naive datetimes by default
            // (a datetime column was left out; a zoned one stays out), and
            // the text columns when there are neither (it gave an empty frame).
            let names: Vec<String> = this.inner.column_names().into_iter().cloned().collect();
            let naive_datetime = |name: &str| {
                this.inner
                    .column(name)
                    .is_some_and(|c| matches!(c.dtype(), DType::Datetime64 { tz: None }))
            };
            let number = |name: &str| this.inner.column(name).is_some_and(describe_number);
            if !names.iter().any(|name| naive_datetime(name)) {
                if !names.is_empty() && !names.iter().any(|name| number(name)) {
                    return wrap(
                        this.inner
                            .describe_dtypes(&["all"], &[])
                            .map_err(frame_error_to_py)?,
                    );
                }
                return wrap(numeric_describe(&this.inner).map_err(frame_error_to_py)?);
            }
            // By position, each column under a repeated key once (i17d4).
            let described: Vec<usize> = (0..this.inner.num_columns())
                .filter(|&position| {
                    this.inner.column_at(position).is_some_and(|c| {
                        describe_number(c) || matches!(c.dtype(), DType::Datetime64 { tz: None })
                    })
                })
                .collect();
            let frame = this
                .inner
                .take_columns(&described)
                .map_err(frame_error_to_py)?;
            let described = describe_all(py, &frame, percentiles.as_deref(), numeric_describe)?;
            let described = described.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone();
            return wrap(described);
        }
        // pandas' selection: include (every dtype when only exclude is
        // given) minus exclude; then numeric, object-style, or - both kinds
        // selected - pandas' union layout.
        // By position: each column under a repeated key is selected once
        // (by name every one was taken for each; i17d4).
        let selected: Vec<usize> = (0..this.inner.shape().1)
            .filter(|&position| {
                let Some(dtype) = this.inner.column_at(position).map(Column::dtype) else {
                    return false;
                };
                let wanted = include.is_empty()
                    || include
                        .iter()
                        .any(|spec| describe_dtype_matches(&dtype, spec));
                let dropped = exclude
                    .iter()
                    .any(|spec| describe_dtype_matches(&dtype, spec));
                wanted && !dropped
            })
            .collect();
        let frame = this
            .inner
            .take_columns(&selected)
            .map_err(frame_error_to_py)?;
        let kinds: Vec<(bool, bool)> = (0..frame.num_columns())
            .filter_map(|position| frame.column_at(position))
            .map(|c| {
                (
                    describe_number(c),
                    matches!(c.dtype(), DType::Datetime64 { .. }),
                )
            })
            .collect();
        if kinds.iter().all(|(numeric, _)| *numeric) {
            wrap(numeric_describe(&frame).map_err(frame_error_to_py)?)
        } else if !kinds
            .iter()
            .any(|(numeric, datetime)| *numeric || *datetime)
        {
            wrap(
                frame
                    .describe_dtypes(&["all"], &[])
                    .map_err(frame_error_to_py)?,
            )
        } else {
            let described = describe_all(py, &frame, percentiles.as_deref(), numeric_describe)?;
            let described = described.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone();
            wrap(described)
        }
    }

    /// pandas' `info(verbose=None, buf=None, max_cols=None, memory_usage=None,
    /// show_counts=None)`: pandas' summary written to `buf` (stdout by
    /// default), returning None. It returned fp's own text and took no
    /// arguments (fvsao.30).
    #[pyo3(signature = (verbose=None, buf=None, max_cols=None, memory_usage=None, show_counts=None))]
    fn info(
        slf: &Bound<'_, Self>,
        verbose: Option<bool>,
        buf: Option<&Bound<'_, PyAny>>,
        max_cols: Option<usize>,
        memory_usage: Option<&Bound<'_, PyAny>>,
        show_counts: Option<bool>,
    ) -> PyResult<()> {
        let py = slf.py();
        let text = pandas_info_text(slf, verbose, max_cols, memory_usage, show_counts)?;
        match buf.filter(|buf| !buf.is_none()) {
            Some(buf) => buf.call_method1("write", (text,))?,
            None => py
                .import("sys")?
                .getattr("stdout")?
                .call_method1("write", (text,))?,
        };
        Ok(())
    }

    /// Return the sum of each column or row. A column (or row) with fewer
    /// than `min_count` valid values sums to NaN, as in pandas.
    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn sum(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        min_count: usize,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("sum", kwargs)?;
        Self::warn_axis_none(py, "sum", &axis)?;
        let ax = parse_axis_param(axis.0.as_ref().filter(|axis| !axis.is_none()))?;
        self.refuse_masked_rows("sum", ax, numeric_only)?;
        if let Some(answer) = self.empty_object_rows_answer(ax, numeric_only)? {
            return Ok(answer);
        }
        let summed = self.sum_internal(ax, skipna, numeric_only);
        let summed = wrap_series(
            summed.and_then(|s| self.below_min_count_is_nan(s, ax, numeric_only, min_count)),
        )
        .and_then(|s| self.masked_answer("sum", ax, numeric_only, s))
        .and_then(|s| self.empty_object_identities("sum", numeric_only, min_count, s))?;
        self.object_cell_totals(py, summed, ax, numeric_only, skipna, min_count, "add")
    }

    /// A column reduction `result` with each column of Python-object cells'
    /// total the cells' own `op` fold (see [`object_cells_reduce`]) and the
    /// result an object Series, as pandas' (their text was joined, '';
    /// br-frankenpandas-8dqrn). Rows (axis=1) and numeric_only keep `result`.
    #[allow(clippy::too_many_arguments)]
    fn object_cell_totals(
        &self,
        py: Python<'_>,
        result: PySeries,
        axis: usize,
        numeric_only: bool,
        skipna: bool,
        min_count: usize,
        op: &str,
    ) -> PyResult<PySeries> {
        let objects: Vec<usize> = (0..self.inner.num_columns())
            .filter(|&position| {
                self.inner
                    .column_at(position)
                    .is_some_and(|column| has_object_cells(column) || text_beside_missing(column))
            })
            .collect();
        if axis != 0
            || numeric_only
            || objects.is_empty()
            || result.inner.len() != self.inner.num_columns()
        {
            return Ok(result);
        }
        let mut values = result.inner.values().to_vec();
        for position in objects {
            let column = self.column_series_at(position)?.inner;
            let total = object_cells_reduce(py, &column, op, skipna, min_count)?;
            values[position] = py_to_cell(py, total.bind(py))?;
        }
        let inner = Series::new(
            result.inner.name(),
            result.inner.index().clone(),
            Column::from_object_values(values),
        )
        .map_err(frame_error_to_py)?;
        Ok(PySeries { inner })
    }

    /// Return the mean of each column or row.
    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, **kwargs))]
    fn mean(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("mean", kwargs)?;
        if let Some(value) = self.reduce_both_axes(
            py,
            "mean",
            &axis,
            skipna,
            numeric_only.then_some(NUMERIC_DTYPES),
        )? {
            return Ok(value);
        }
        let ax = parse_axis_param(axis.0.as_ref())?;
        self.refuse_masked_rows("mean", ax, numeric_only)?;
        wrap_series(self.mean_internal(ax, skipna, numeric_only))
            .and_then(|s| self.masked_answer("mean", ax, numeric_only, s))?
            .into_py_any(py)
    }

