    /// Return the variance of each column or row.
    #[pyo3(signature = (axis=Passed(None), skipna=true, ddof=1, numeric_only=false, **kwargs))]
    fn var(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        ddof: Option<usize>,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("var", kwargs)?;
        Self::warn_axis_none(py, "var", &axis)?;
        let ax = parse_axis_param(axis.0.as_ref().filter(|axis| !axis.is_none()))?;
        let ddof_val = ddof.unwrap_or(1);
        self.refuse_masked_rows("var", ax, numeric_only)?;
        wrap_series(self.var_internal(ax, skipna, ddof_val, numeric_only))
            .and_then(|s| self.masked_answer("var", ax, numeric_only, s))
    }

    /// Return the count of non-missing values per column or row;
    /// `axis=None` is pandas' ValueError (it counted each column).
    #[pyo3(signature = (axis=Passed(None), numeric_only=false))]
    fn count(&self, axis: Passed<'_>, numeric_only: bool) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis.0.as_ref())?;
        wrap_series(self.count_internal(ax, numeric_only))
    }

    /// Return the minimum of each column or row.
    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, **kwargs))]
    fn min(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("min", kwargs)?;
        if let Some(value) = self.reduce_both_axes(
            py,
            "min",
            &axis,
            skipna,
            numeric_only.then_some(NUMERIC_DTYPES),
        )? {
            return Ok(value);
        }
        let ax = parse_axis_param(axis.0.as_ref())?;
        self.refuse_masked_rows("min", ax, numeric_only)?;
        wrap_series(self.min_internal(ax, skipna, numeric_only))
            .and_then(|s| self.masked_answer("min", ax, numeric_only, s))?
            .into_py_any(py)
    }

    /// Return the maximum of each column or row.
    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, **kwargs))]
    fn max(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("max", kwargs)?;
        if let Some(value) = self.reduce_both_axes(
            py,
            "max",
            &axis,
            skipna,
            numeric_only.then_some(NUMERIC_DTYPES),
        )? {
            return Ok(value);
        }
        let ax = parse_axis_param(axis.0.as_ref())?;
        self.refuse_masked_rows("max", ax, numeric_only)?;
        wrap_series(self.max_internal(ax, skipna, numeric_only))
            .and_then(|s| self.masked_answer("max", ax, numeric_only, s))?
            .into_py_any(py)
    }

    /// Return the column-pair correlation matrix as a DataFrame.
    #[pyo3(signature = (method="pearson", min_periods=None, numeric_only=false))]
    fn corr(
        &self,
        method: Option<&str>,
        min_periods: Option<usize>,
        numeric_only: bool,
    ) -> PyResult<PyDataFrame> {
        // Fewer than two pairs already correlate to NaN, so min_periods up to
        // 2 is the default answer; a larger floor counts each pair's
        // observations - fp-frame's pairwise Pearson does (it was refused;
        // 4qg5w.5), the rank methods do not yet.
        let m = method.unwrap_or("pearson");
        let floor = min_periods.filter(|&floor| floor > 2);
        unsupported_params(
            "DataFrame.corr",
            &[("min_periods", floor.is_none() || m == "pearson")],
        )?;
        let result = match floor {
            Some(floor) => self
                .inner
                .corr_min_periods_with_numeric_only(floor, numeric_only),
            None => self.inner.corr_method_with_numeric_only(m, numeric_only),
        }
        .map_err(float_conversion_error_to_py)?;
        Ok(PyDataFrame { inner: result })
    }

    /// Fill missing values with `value` or using `method`, returning a new DataFrame.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (value=None, method=None, axis=None, inplace=false, limit=None, downcast=None))]
    fn fillna(
        &mut self,
        py: Python<'_>,
        value: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<usize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        unsupported_params("DataFrame.fillna", &[("downcast", downcast.is_none())])?;
        let result = (|| -> PyResult<PyDataFrame> {
            let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
            if ax != 0 && ax != 1 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type DataFrame"
                )));
            }

            if value.is_none() && method.is_none() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Must specify a fill 'value' or 'method'.",
                ));
            }

            if value.is_some() && method.is_some() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Cannot specify both 'value' and 'method'.",
                ));
            }
            // pandas' deprecation of a fill method (c90rr: groupby fillna
            // warns it per group).
            if method.is_some_and(|m| matches!(m, "ffill" | "pad" | "bfill" | "backfill")) {
                PyErr::warn(
                    py,
                    &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
                    c"DataFrame.fillna with 'method' is deprecated and will raise in a future version. Use obj.ffill() or obj.bfill() instead.",
                    1,
                )?;
            }

            if self.inner.is_empty() || self.inner.num_columns() == 0 {
                return Ok(PyDataFrame {
                    inner: self.inner.clone(),
                });
            }

            if let Some(m) = method {
                let res = if ax == 0 {
                    match m {
                        "ffill" | "pad" => self.inner.ffill(limit).map_err(frame_error_to_py)?,
                        "bfill" | "backfill" => {
                            self.inner.bfill(limit).map_err(frame_error_to_py)?
                        }
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                            )));
                        }
                    }
                } else {
                    match m {
                        "ffill" | "pad" => {
                            self.inner.ffill_axis1(limit).map_err(frame_error_to_py)?
                        }
                        "bfill" | "backfill" => {
                            self.inner.bfill_axis1(limit).map_err(frame_error_to_py)?
                        }
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                            )));
                        }
                    }
                };
                return Ok(PyDataFrame { inner: res });
            }

            let val = value.expect("value is some");

            // 1. Value is a DataFrame
            if let Ok(other_df) = val.extract::<PyRef<PyDataFrame>>() {
                // An equal index - repeated labels too - fills row for row,
                // its columns read by name below (br-frankenpandas-rbiki).
                let aligned = if other_df.inner.index() == self.inner.index() {
                    other_df.inner.clone()
                } else {
                    other_df
                        .inner
                        .reindex_like(&self.inner)
                        .map_err(frame_error_to_py)?
                };
                let mut col_map = BTreeMap::new();
                let mut column_order = Vec::with_capacity(self.inner.num_columns());
                for pos in 0..self.inner.num_columns() {
                    let name = self.inner.column_name_at(pos).expect("col in bounds");
                    let col = self.inner.column_at(pos).expect("col in bounds");
                    column_order.push(name.clone());
                    if let Some(other_col) = aligned.column(&name) {
                        let new_col = fill_column_with_other(col, other_col, limit)
                            .map_err(frame_error_to_py)?;
                        col_map.insert(name, new_col);
                    } else {
                        col_map.insert(name, col.clone());
                    }
                }
                let df = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    column_order,
                )
                .map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: df });
            }

            // 2. Value is a Dict
            if let Ok(dict) = val.cast::<PyDict>() {
                if ax == 1 {
                    return Err(PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(
                        "Currently only can fill with dict/Series column by column",
                    ));
                }
                let mut col_map = BTreeMap::new();
                let mut column_order = Vec::with_capacity(self.inner.num_columns());
                for pos in 0..self.inner.num_columns() {
                    let name = self.inner.column_name_at(pos).expect("col in bounds");
                    let col = self.inner.column_at(pos).expect("col in bounds");
                    column_order.push(name.clone());

                    // Keyed by the column's typed label (0, not '0').
                    let item =
                        dict.get_item(index_label_to_py(py, &self.inner.column_label(&name))?)?;

                    if let Some(it) = item {
                        if it.is_none() {
                            col_map.insert(name, col.clone());
                        } else if let Ok(py_ser) = it.extract::<PyRef<PySeries>>() {
                            let aligned = if py_ser.inner.index() == self.inner.index() {
                                py_ser.inner.clone()
                            } else {
                                py_ser
                                    .inner
                                    .reindex(self.inner.index().labels().to_vec())
                                    .map_err(frame_error_to_py)?
                            };
                            let new_col = fill_column_with_other(col, aligned.column(), limit)
                                .map_err(frame_error_to_py)?;
                            col_map.insert(name, new_col);
                        } else if let Ok(sub_dict) = it.cast::<PyDict>() {
                            let fill_col = py_dict_to_series_fill_column(
                                py,
                                sub_dict,
                                self.inner.index().labels(),
                            )?;
                            let new_col = fill_column_with_other(col, &fill_col, limit)
                                .map_err(frame_error_to_py)?;
                            col_map.insert(name, new_col);
                        } else {
                            let scalar = py_to_scalar(py, &it)?;
                            let new_col = fill_column_with_scalar(col, &scalar, limit)
                                .map_err(frame_error_to_py)?;
                            col_map.insert(name, new_col);
                        }
                    } else {
                        col_map.insert(name, col.clone());
                    }
                }
                let df = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    column_order,
                )
                .map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: df });
            }

            // 3. Value is a Series
            if let Ok(py_ser) = val.extract::<PyRef<PySeries>>() {
                if ax == 1 {
                    return Err(PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(
                        "Currently only can fill with dict/Series column by column",
                    ));
                }
                let mut col_map = BTreeMap::new();
                let mut column_order = Vec::with_capacity(self.inner.num_columns());
                for pos in 0..self.inner.num_columns() {
                    let name = self.inner.column_name_at(pos).expect("col in bounds");
                    let col = self.inner.column_at(pos).expect("col in bounds");
                    column_order.push(name.clone());

                    let label = IndexLabel::Utf8(name.clone());
                    let loc = py_ser.inner.index().get_loc(&label).or_else(|| {
                        name.parse::<i64>()
                            .ok()
                            .and_then(|i| py_ser.inner.index().get_loc(&IndexLabel::Int64(i)))
                    });
                    if let Some(loc_pos) = loc {
                        let scalar = &py_ser.inner.column().values()[loc_pos];
                        if !scalar.is_missing() {
                            let new_col = fill_column_with_scalar(col, scalar, limit)
                                .map_err(frame_error_to_py)?;
                            col_map.insert(name, new_col);
                        } else {
                            col_map.insert(name, col.clone());
                        }
                    } else {
                        col_map.insert(name, col.clone());
                    }
                }
                let df = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    column_order,
                )
                .map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: df });
            }

            // 4. Scalar fill
            let fill_val = py_to_scalar(py, val)?;
            if ax == 0 {
                if let Some(lim) = limit {
                    let mut col_map = BTreeMap::new();
                    let mut column_order = Vec::with_capacity(self.inner.num_columns());
                    for pos in 0..self.inner.num_columns() {
                        let name = self.inner.column_name_at(pos).expect("col in bounds");
                        let col = self.inner.column_at(pos).expect("col in bounds");
                        column_order.push(name.clone());
                        let new_col = fill_column_with_scalar(col, &fill_val, Some(lim))
                            .map_err(frame_error_to_py)?;
                        col_map.insert(name, new_col);
                    }
                    let df = DataFrame::new_with_column_order(
                        self.inner.index().clone(),
                        col_map,
                        column_order,
                    )
                    .map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: df })
                } else {
                    let df = self.inner.fillna(&fill_val).map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: df })
                }
            } else {
                // ax == 1
                if let Some(lim) = limit {
                    let nrows = self.inner.len();
                    let ncols = self.inner.num_columns();
                    let mut col_vectors: Vec<Vec<Scalar>> = (0..ncols)
                        .map(|pos| {
                            self.inner
                                .column_at(pos)
                                .expect("col in bounds")
                                .values()
                                .to_vec()
                        })
                        .collect();
                    for r in 0..nrows {
                        let mut consecutive = 0;
                        for c in 0..ncols {
                            if col_vectors[c][r].is_missing() {
                                consecutive += 1;
                                if consecutive <= lim {
                                    col_vectors[c][r] = fp_types::cast_scalar(
                                        &fill_val,
                                        self.inner.column_at(c).unwrap().dtype().clone(),
                                    )
                                    .map_err(|e| {
                                        PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                                            e.to_string(),
                                        )
                                    })?;
                                }
                            } else {
                                consecutive = 0;
                            }
                        }
                    }
                    let mut col_map = BTreeMap::new();
                    let mut column_order = Vec::with_capacity(ncols);
                    for (pos, col_vals) in col_vectors.into_iter().enumerate() {
                        let name = self.inner.column_name_at(pos).expect("col in bounds");
                        let dtype = self.inner.column_at(pos).unwrap().dtype().clone();
                        let col = Column::new(dtype, col_vals)
                            .map_err(|e| frame_error_to_py(fp_frame::FrameError::Column(e)))?;
                        column_order.push(name.clone());
                        col_map.insert(name, col);
                    }
                    let df = DataFrame::new_with_column_order(
                        self.inner.index().clone(),
                        col_map,
                        column_order,
                    )
                    .map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: df })
                } else {
                    let df = self.inner.fillna(&fill_val).map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: df })
                }
            }
        })()?;
        Ok(frame_inplace(&mut self.inner, result, inplace))
    }

    /// Drop rows or columns containing missing values, returning a new DataFrame.
    #[pyo3(signature = (
        axis=None,
        how=None,
        thresh=None,
        subset=None,
        inplace=false,
        ignore_index=false
    ))]
    fn dropna(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        how: Option<&str>,
        thresh: Option<usize>,
        subset: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        ignore_index: bool,
    ) -> PyResult<Option<PyDataFrame>> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);

        if how.is_some() && thresh.is_some() {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "You cannot set both the how and thresh arguments at the same time.",
            ));
        }

        let how_enum = match how {
            None | Some("any") => DropNaHow::Any,
            Some("all") => DropNaHow::All,
            Some(other) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "invalid how option: {other}"
                )));
            }
        };

        // axis=0's subset names columns, typed labels included.
        let column_subset = if ax == 0 {
            column_arg_opt(&self.inner, subset)?
        } else {
            None
        };
        let subset = if ax == 0 {
            column_subset.as_ref()
        } else {
            subset
        };
        let mut res = if ax == 0 {
            // row-wise dropna: subset selects column names
            let subset_cols: Option<Vec<String>> = if let Some(s) = subset {
                if let Ok(col_name) = s.extract::<String>() {
                    Some(vec![col_name])
                } else if let Ok(col_list) = s.extract::<Vec<String>>() {
                    Some(col_list)
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "subset must be a string or list of strings",
                    ));
                }
            } else {
                None
            };

            if let Some(t) = thresh {
                self.inner
                    .dropna_with_threshold(t, subset_cols.as_deref())
                    .map_err(frame_error_to_py)?
            } else {
                self.inner
                    .dropna_with_options(how_enum, subset_cols.as_deref())
                    .map_err(frame_error_to_py)?
            }
        } else {
            // col-wise dropna (axis=1): subset selects row labels
            let subset_rows: Option<Vec<IndexLabel>> = if let Some(s) = subset {
                if let Ok(label_str) = s.extract::<String>() {
                    Some(vec![IndexLabel::Utf8(label_str)])
                } else if let Ok(label_int) = s.extract::<i64>() {
                    Some(vec![IndexLabel::Int64(label_int)])
                } else if let Ok(label_list) = s.extract::<Vec<String>>() {
                    Some(label_list.into_iter().map(IndexLabel::Utf8).collect())
                } else if let Ok(label_list) = s.extract::<Vec<i64>>() {
                    Some(label_list.into_iter().map(IndexLabel::Int64).collect())
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "subset must be a label or list of labels",
                    ));
                }
            } else {
                None
            };

            if let Some(t) = thresh {
                self.inner
                    .dropna_columns_with_threshold(t, subset_rows.as_deref())
                    .map_err(frame_error_to_py)?
            } else {
                self.inner
                    .dropna_columns_with_options(how_enum, subset_rows.as_deref())
                    .map_err(frame_error_to_py)?
            }
        };

        if ignore_index {
            res = res.reset_index(true).map_err(frame_error_to_py)?;
        }

        // pandas' inplace=True replaces the frame and returns None
        // (br-frankenpandas-n57tz).
        if inplace {
            self.inner = res;
            return Ok(None);
        }
        Ok(Some(PyDataFrame { inner: res }))
    }

    /// Reset the index to a default integer range, returning a new DataFrame.
    /// `allow_duplicates` lets an index column repeat a column's label;
    /// `col_level` / `col_fill` label the new columns of MultiIndex columns
    /// (see [`reset_index_column_levels`]; col_fill was discarded and
    /// col_level refused, br-frankenpandas-cnpw1).
    #[pyo3(signature = (
        level = None,
        drop = false,
        inplace = false,
        col_level = None,
        col_fill = Passed(None),
        allow_duplicates = false,
        names = None
    ))]
    #[allow(clippy::too_many_arguments)]
    fn reset_index(
        &mut self,
        level: Option<&Bound<'_, PyAny>>,
        drop: bool,
        inplace: bool,
        col_level: Option<&Bound<'_, PyAny>>,
        col_fill: Passed<'_>,
        allow_duplicates: bool,
        names: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        let columns_before = self.inner.num_columns();
        let relabel = |frame: DataFrame| {
            let inserted = frame.num_columns().saturating_sub(columns_before);
            reset_index_column_levels(frame, inserted, col_level, col_fill.0.as_ref())
        };
        // reset_index(level=) over a row MultiIndex: those levels become the
        // leading columns (dropped with drop=True), the rest stay the index
        // (fvsao.36; it raised NotImplementedError).
        if let Some(level) = level.filter(|level| !level.is_none())
            && let Some(multi) = self.inner.row_multiindex().cloned()
            && names.is_none_or(|names| names.is_none())
        {
            // pandas moves the levels in index order, whatever order named.
            let mut moved = multiindex_level_positions(&multi, level)?;
            moved.sort_unstable();
            let keep: Vec<usize> = (0..multi.nlevels())
                .filter(|level| !moved.contains(level))
                .collect();
            if !keep.is_empty() {
                let rows: Vec<usize> = (0..self.inner.len()).collect();
                let (index, rest) = multiindex_levels_index(&multi, &rows, &keep)?;
                let mut out = self.inner.with_index(index).map_err(frame_error_to_py)?;
                if !drop {
                    for (slot, &position) in moved.iter().enumerate() {
                        let values: Vec<Scalar> = multi
                            .get_level_values(position)
                            .map_err(index_error_to_py)?
                            .labels()
                            .iter()
                            .map(index_label_to_scalar)
                            .collect();
                        let name = multi
                            .names()
                            .get(position)
                            .cloned()
                            .flatten()
                            .map_or_else(|| format!("level_{position}"), String::from);
                        out = out
                            .insert_allow_duplicates(
                                slot,
                                name,
                                Column::from_values(values).map_err(column_error_to_py)?,
                                allow_duplicates,
                            )
                            .map_err(frame_error_to_py)?;
                    }
                }
                if let Some(rest) = rest {
                    out = out.with_row_multiindex(rest).map_err(frame_error_to_py)?;
                }
                return Ok(frame_inplace(
                    &mut self.inner,
                    PyDataFrame {
                        inner: relabel(out)?,
                    },
                    inplace,
                ));
            }
        }
        let level_is_default = level.is_none_or(|l| {
            matches!(l.extract::<i64>(), Ok(0)) || self.inner.row_multiindex().is_some()
        });
        unsupported_params("DataFrame.reset_index", &[("level", level_is_default)])?;
        let reset = (|| -> PyResult<PyDataFrame> {
            let mut result = self
                .inner
                .reset_index_allow_duplicates(drop, allow_duplicates)
                .map_err(frame_error_to_py)?;
            if !drop
                && let Some(n) = names
                && !n.is_none()
            {
                // Column names are strings here; any other name raised nothing
                // and was dropped.
                let custom_name: Option<String> = if let Ok(s) = n.extract::<String>() {
                    Some(s)
                } else if let Ok(list) = n.extract::<Vec<String>>() {
                    list.into_iter().next()
                } else {
                    return Err(not_implemented(
                        "DataFrame.reset_index(names=<a non-string name>)",
                    ));
                };
                if let Some(cname) = custom_name {
                    if let Some(old_name) = result.column_names().first().map(|s| (*s).clone()) {
                        result = result
                            .rename_columns(&[(old_name.as_str(), cname.as_str())])
                            .map_err(frame_error_to_py)?;
                    }
                }
            }
            Ok(PyDataFrame {
                inner: relabel(result)?,
            })
        })()?;
        Ok(frame_inplace(&mut self.inner, reset, inplace))
    }

    /// Sort DataFrame by index labels.
    ///
    /// Matches `df.sort_index(axis=0, level=None, ascending=True, inplace=False, kind='quicksort', na_position='last', sort_remaining=True, ignore_index=False, key=None)`.
    #[pyo3(signature = (
        axis = None,
        level = None,
        ascending = None,
        inplace = false,
        kind = None,
        na_position = "last",
        sort_remaining = true,
        ignore_index = false,
        key = None
    ))]
    #[allow(clippy::too_many_arguments)]
    fn sort_index(
        &mut self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        ascending: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        kind: Option<&str>,
        na_position: &str,
        sort_remaining: bool,
        ignore_index: bool,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        // A row MultiIndex sorts by its levels: `level` first (a position, a
        // name or a list), then the others when sort_remaining - all of them
        // with no level. level= raised NotImplementedError, and a plain sort
        // compared the flat 'x/10' < 'x/2' labels (fvsao.36).
        if let Some(multi) = self.inner.row_multiindex().cloned()
            && key.is_none()
            && parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0) == 0
        {
            validate_sort_kind(kind)?;
            let rows = multiindex_sort_rows(&multi, level, ascending, sort_remaining, na_position)?;
            let mut sorted = frame_rows_keeping_multiindex(&self.inner, &multi, &rows)?;
            if ignore_index {
                sorted = sorted.reset_index(true).map_err(frame_error_to_py)?;
            }
            return Ok(frame_inplace(
                &mut self.inner,
                PyDataFrame { inner: sorted },
                inplace,
            ));
        }
        // The row index is single-level: level 0 is the default order, and
        // sort_remaining only acts on the other levels of a MultiIndex.
        let _ = sort_remaining;
        let level_is_default = level.is_none_or(|l| matches!(l.extract::<i64>(), Ok(0)));
        unsupported_params("DataFrame.sort_index", &[("level", level_is_default)])?;
        validate_sort_kind(kind)?;
        let result = (|| -> PyResult<PyDataFrame> {
            let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
            let asc = parse_ascending_bool(ascending)?;
            if key.is_some() && ax != 0 {
                return Err(not_implemented("DataFrame.sort_index(axis=1, key=...)"));
            }
            let sorted = match ax {
                0 if key.is_some() => {
                    let index = PyIndex {
                        inner: self.inner.index().clone(),
                    };
                    let keyed = key.expect("checked above").call1((index,))?;
                    // Only the index and length of `like` are read, to shape an
                    // array-like result.
                    let like = Series::from_values(
                        "key",
                        self.inner.index().labels().to_vec(),
                        vec![Scalar::Null(NullKind::Null); self.inner.len()],
                    )
                    .map_err(frame_error_to_py)?;
                    let keyed = extract_or_build_series(py, &keyed, &like)?;
                    if keyed.len() != self.inner.len() {
                        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                            "User-provided `key` function must not change the shape of the array.",
                        ));
                    }
                    let tagged = Series::from_values(
                        "key",
                        position_labels(keyed.len()),
                        keyed.values().to_vec(),
                    )
                    .map_err(frame_error_to_py)?;
                    let order = positions_from_labels(
                        tagged
                            .sort_values_na(asc, na_position)
                            .map_err(frame_error_to_py)?
                            .index()
                            .labels(),
                    )?;
                    let s = self.inner.take(&order, 0).map_err(frame_error_to_py)?;
                    if ignore_index {
                        s.reset_index(true).map_err(frame_error_to_py)?
                    } else {
                        s
                    }
                }
                0 => {
                    let s = self
                        .inner
                        .sort_index_na(asc, na_position)
                        .map_err(frame_error_to_py)?;
                    if ignore_index {
                        s.reset_index(true).map_err(frame_error_to_py)?
                    } else {
                        s
                    }
                }
                1 => {
                    let s = self
                        .inner
                        .sort_index_axis1(asc)
                        .map_err(frame_error_to_py)?;
                    if ignore_index {
                        let n_cols = s.num_columns();
                        let labels = (0..n_cols).map(|i| IndexLabel::Int64(i as i64)).collect();
                        s.set_axis(labels, 1).map_err(frame_error_to_py)?
                    } else {
                        s
                    }
                }
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {other} for object type DataFrame"
                    )));
                }
            };
            Ok(PyDataFrame { inner: sorted })
        })()?;
        Ok(frame_inplace(&mut self.inner, result, inplace))
    }

    /// Transpose: swap rows and columns, returning a new DataFrame. pandas'
    /// `transpose(*args, copy=False)` takes numpy's `axes` only as None
    /// (`np.transpose(df)` passes it; it raised).
    #[pyo3(signature = (*args, copy=None))]
    fn transpose(
        &self,
        args: &Bound<'_, PyTuple>,
        copy: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let _ = copy; // pandas' copy= does not change the result
        if args.len() > 1 || args.iter().any(|axes| !axes.is_none()) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "the 'axes' parameter is not supported in the pandas implementation of transpose()",
            ));
        }
        self.transposed()
    }

    /// pandas' `df.drop(labels=None, *, axis=0, index=None, columns=None,
    /// level=None, inplace=False, errors='raise')` (br-frankenpandas-n57tz:
    /// row labels had to be strings, `axis` an int, and index=, errors= and
    /// inplace= were absent). Missing labels raise pandas' KeyError unless
    /// `errors='ignore'`; `level` is refused.
    #[pyo3(signature = (
        labels=None,
        axis=None,
        index=None,
        columns=None,
        level=None,
        inplace=false,
        errors="raise"
    ))]
    #[allow(clippy::too_many_arguments)]
    fn drop(
        &mut self,
        py: Python<'_>,
        labels: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        errors: &str,
    ) -> PyResult<Option<PyDataFrame>> {
        let level = level.filter(|level| !level.is_none());
        let (rows, cols) = match passed(labels) {
            Some(labels) => {
                if passed(index).is_some() || passed(columns).is_some() {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Cannot specify both 'labels' and 'index'/'columns'",
                    ));
                }
                if parse_axis_param(axis)? == 1 {
                    (None, Some(labels))
                } else {
                    (Some(labels), None)
                }
            }
            None => (passed(index), passed(columns)),
        };
        if rows.is_none() && cols.is_none() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Need to specify at least one of 'labels', 'index' or 'columns'",
            ));
        }
        let ignore = errors == "ignore";
        let mut out = self.inner.clone();
        // `level` names the labels of one level of a row MultiIndex; the
        // column axis's levels are not supported.
        if level.is_some() && (cols.is_some() || out.row_multiindex().is_none()) {
            return Err(not_implemented(
                "DataFrame.drop(level=...) outside a row MultiIndex",
            ));
        }
        if let (Some(rows), Some(multi)) = (rows.as_ref(), out.row_multiindex().cloned()) {
            // Under a row MultiIndex an outer label or a tuple names every
            // row under it, as .loc reads it, and with `level` a label names
            // the rows holding it there (an outer label was a KeyError and
            // level= refused; br-frankenpandas-gvd3q).
            let keys: Vec<Bound<'_, PyAny>> = match rows.cast::<PyList>() {
                Ok(list) => list.iter().collect(),
                Err(_) => vec![rows.clone()],
            };
            let level_values = match level {
                Some(level) => {
                    let position = multiindex_level_position(&multi, level)?;
                    Some(
                        multi
                            .get_level_values(position)
                            .map_err(index_error_to_py)?,
                    )
                }
                None => None,
            };
            let mut dropped: HashSet<usize> = HashSet::new();
            let mut missing: Vec<&Bound<'_, PyAny>> = Vec::new();
            for key in &keys {
                let found: Vec<usize> = match &level_values {
                    Some(values) => {
                        let label = py_to_index_label(key)?;
                        values
                            .labels()
                            .iter()
                            .enumerate()
                            .filter(|(_, value)| **value == label)
                            .map(|(position, _)| position)
                            .collect()
                    }
                    None => multiindex_loc_rows(&multi, key, false)?.unwrap_or_default(),
                };
                if found.is_empty() {
                    missing.push(key);
                }
                dropped.extend(found);
            }
            // A missing key as pandas' _drop_axis treats it: a unique axis
            // raises from MultiIndex.drop (KeyError(key), or "labels [...]
            // not found in level"); a repeated one raises for tuples, for a
            // level only when nothing matched, and passes over a missing
            // outer label (its level-0 isin).
            if !missing.is_empty() && !ignore {
                // numpy's array text, as pandas formats these: ['a' 'zz'] -
                // the missing labels from a unique axis, every one asked
                // for from a repeated one.
                let numpy_text = |items: &[&Bound<'_, PyAny>]| -> PyResult<String> {
                    let reprs = items
                        .iter()
                        .map(|key| key.repr().map(|text| text.to_string()))
                        .collect::<PyResult<Vec<_>>>()?;
                    Ok(format!("[{}]", reprs.join(" ")))
                };
                let asked: Vec<&Bound<'_, PyAny>> = keys.iter().collect();
                let unique = out.index().is_unique();
                let tuple_keys = keys.iter().any(|key| key.is_instance_of::<PyTuple>());
                let message = match (unique, level_values.is_some()) {
                    (true, false) => {
                        return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                            missing[0].clone().unbind(),
                        ));
                    }
                    (true, true) => Some(format!(
                        "labels {} not found in level",
                        numpy_text(&missing)?
                    )),
                    (false, true) if dropped.is_empty() => {
                        Some(format!("{} not found in axis", numpy_text(&asked)?))
                    }
                    (false, false) if tuple_keys => {
                        Some(format!("{} not found in axis", numpy_text(&asked)?))
                    }
                    (false, _) => None,
                };
                if let Some(message) = message {
                    return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(message));
                }
            }
            let keep: Vec<usize> = (0..out.len())
                .filter(|position| !dropped.contains(position))
                .collect();
            let levels = multi.take(&keep).map_err(index_error_to_py)?;
            out = out
                .take_rows(&keep)
                .and_then(|frame| frame.with_row_multiindex(levels))
                .map_err(frame_error_to_py)?;
        } else if let Some(rows) = rows {
            // A point over an IntervalIndex drops the intervals holding it.
            let rows = interval_drop_labels(rows.py(), out.index(), &rows)?;
            let wanted = py_label_list(&rows)?;
            let present: HashSet<&IndexLabel> = out.index().labels().iter().collect();
            let missing: Vec<IndexLabel> = wanted
                .iter()
                .filter(|label| !present.contains(label))
                .cloned()
                .collect();
            if !missing.is_empty() && !ignore {
                return Err(not_found_in_axis(py, &missing)?);
            }
            let dropped: HashSet<&IndexLabel> = wanted.iter().collect();
            let keep: Vec<usize> = out
                .index()
                .labels()
                .iter()
                .enumerate()
                .filter(|(_, label)| !dropped.contains(label))
                .map(|(position, _)| position)
                .collect();
            out = out.take_rows(&keep).map_err(frame_error_to_py)?;
        }
        // Under MultiIndex columns a tuple names its column and a top-level
        // label every column under it (a KeyError; 7m8bq).
        if let Some(cols) = cols.as_ref().filter(|_| out.columns_multiindex().is_some()) {
            let keys: Vec<Bound<'_, PyAny>> = match cols.cast::<PyList>() {
                Ok(list) => list.iter().collect(),
                Err(_) => vec![cols.clone()],
            };
            // The row drop above leaves the column axis as it is.
            let mut positions = Vec::new();
            let mut missing = Vec::new();
            for key in &keys {
                match self.multi_prefix_positions(key)? {
                    Some((_, found)) if !found.is_empty() => positions.extend(found),
                    _ => missing.push(py_to_index_label(key)?),
                }
            }
            if !missing.is_empty() && !ignore {
                return Err(not_found_in_axis(py, &missing)?);
            }
            let keep: Vec<usize> = (0..out.num_columns())
                .filter(|position| !positions.contains(position))
                .collect();
            out = out.take_columns(&keep).map_err(frame_error_to_py)?;
        } else if let Some(cols) = cols {
            let wanted = py_label_list(&cols)?;
            let (present, missing): (Vec<&IndexLabel>, Vec<&IndexLabel>) = wanted
                .iter()
                .partition(|label| out.column(&label.to_string()).is_some());
            if !missing.is_empty() && !ignore {
                let missing: Vec<IndexLabel> = missing.into_iter().cloned().collect();
                return Err(not_found_in_axis(py, &missing)?);
            }
            let names: Vec<String> = present.iter().map(ToString::to_string).collect();
            let refs: Vec<&str> = names.iter().map(String::as_str).collect();
            out = out.drop_columns(&refs).map_err(frame_error_to_py)?;
        }
        if inplace {
            self.inner = out;
            return Ok(None);
        }
        Ok(Some(PyDataFrame { inner: out }))
    }

    /// pandas' `df.rename(mapper=None, *, index=None, columns=None, axis=None,
    /// copy=None, inplace=False, level=None, errors='ignore')`: a dict or a
    /// callable per axis (br-frankenpandas-n57tz: a bare mapping renamed the
    /// COLUMNS where pandas' `mapper` targets the index unless axis=1, and
    /// index=, callables, errors= and inplace= were absent). `copy` only
    /// decides buffer sharing in pandas; `level` maps that level of a
    /// MultiIndex axis alone (it was refused, br-frankenpandas-u6p7i).
    #[pyo3(signature = (
        mapper=None,
        index=None,
        columns=None,
        axis=None,
        copy=None,
        inplace=false,
        level=None,
        errors="ignore"
    ))]
    #[allow(clippy::too_many_arguments)]
    fn rename(
        &mut self,
        py: Python<'_>,
        mapper: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        level: Option<&Bound<'_, PyAny>>,
        errors: &str,
    ) -> PyResult<Option<PyDataFrame>> {
        let _ = copy;
        let level = level.filter(|level| !level.is_none());
        let (index, columns) = match passed(mapper) {
            Some(mapper) => {
                if passed(index).is_some() || passed(columns).is_some() {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "Cannot specify both 'mapper' and any of 'index' or 'columns'",
                    ));
                }
                if parse_axis_param(axis)? == 1 {
                    (None, Some(mapper))
                } else {
                    (Some(mapper), None)
                }
            }
            None => (passed(index), passed(columns)),
        };
        if index.is_none() && columns.is_none() {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "must pass an index to rename",
            ));
        }
        let raise = errors == "raise";
        let mut out = self.inner.clone();
        // The one level `level` names on a MultiIndex axis (a flat axis has
        // only its own, which renames as without it).
        let level_on =
            |axis: &Index, multi: Option<&fp_index::MultiIndex>| -> PyResult<Option<usize>> {
                match (level, multi) {
                    (Some(level), Some(multi)) => multiindex_level_position(multi, level).map(Some),
                    (Some(level), None) => axis_level_values(axis, None, level).map(|_| None),
                    (None, _) => Ok(None),
                }
            };
        if let Some(columns) = columns.as_ref()
            && let Some(multi) = out.columns_multiindex().cloned()
        {
            // Under MultiIndex columns every level's labels are mapped, as
            // pandas (they were left as they were; 7m8bq).
            let only = level_on(out.index(), Some(&multi))?;
            let renamed = rename_multiindex_levels(py, columns, &multi, only)?;
            out = PyDataFrame { inner: out }
                .with_column_axis(fp_index::MultiIndexOrIndex::Multi(renamed))?;
        } else if let Some(columns) = columns {
            let keys = Index::new(Vec::new()).rename_index(out.columns_name().cloned());
            level_on(&keys, None)?;
            // The mapping matches and gives typed labels ({0: 'a'},
            // {'a': 5}); the columns were matched as strings (fvsao.32).
            let names = out.column_labels();
            let pairs = rename_pairs(py, &columns, &names, raise)?;
            let new_labels: Vec<IndexLabel> = pairs.iter().map(|(_, new)| new.clone()).collect();
            let pairs: Vec<(String, String)> = pairs
                .iter()
                .map(|(old, new)| (fp_frame::column_key(old), fp_frame::column_key(new)))
                .collect();
            let refs: Vec<(&str, &str)> = pairs
                .iter()
                .map(|(old, new)| (old.as_str(), new.as_str()))
                .collect();
            out = out
                .rename_columns(&refs)
                .map_err(frame_error_to_py)?
                .with_recorded_column_labels(new_labels);
        }
        if let Some(index) = index {
            if let Some(multi) = out.row_multiindex().cloned() {
                // Under a row MultiIndex every level's labels are mapped and
                // the levels kept (they were flattened to 'n, a'; rvqoi).
                let only = level_on(out.index(), Some(&multi))?;
                let renamed = rename_multiindex_levels(py, &index, &multi, only)?;
                out = with_row_axis(out, &row_multiindex_axis(renamed)?)?;
            } else {
                level_on(out.index(), None)?;
                let labels = out.index().labels().to_vec();
                let pairs = rename_pairs(py, &index, &labels, raise)?;
                out = out.rename_index(&pairs);
            }
        }
        if inplace {
            self.inner = out;
            return Ok(None);
        }
        Ok(Some(PyDataFrame { inner: out }))
    }

    /// Merge with another DataFrame (pandas `DataFrame.merge`; see `merge_impl`).
    #[pyo3(signature = (
        right,
        how="inner",
        on=None,
        left_on=None,
        right_on=None,
        left_index=false,
        right_index=false,
        sort=false,
        suffixes=None,
        copy=None,
        indicator=None,
        validate=None
    ))]
    #[allow(clippy::too_many_arguments)]
    fn merge(
        &self,
        right: &Bound<'_, PyAny>,
        how: &str,
        on: Option<&Bound<'_, PyAny>>,
        left_on: Option<&Bound<'_, PyAny>>,
        right_on: Option<&Bound<'_, PyAny>>,
        left_index: bool,
        right_index: bool,
        sort: bool,
        suffixes: Option<&Bound<'_, PyAny>>,
        copy: Option<&Bound<'_, PyAny>>,
        indicator: Option<&Bound<'_, PyAny>>,
        validate: Option<&str>,
    ) -> PyResult<PyDataFrame> {
        let _ = copy; // pandas' copy= does not change the result
        let right = merge_side_frame(right)?;
        let args = MergeArgs {
            how,
            on,
            left_on,
            right_on,
            left_index,
            right_index,
            sort,
            suffixes,
            indicator,
            validate,
        };
        Ok(PyDataFrame {
            inner: merge_sides(&self.inner, &right, &args)?,
        })
    }

    /// Return a boolean DataFrame marking missing values (pandas `DataFrame.isna`).
    fn isna(&self) -> PyResult<PyDataFrame> {
        let result = self
            .inner
            .isna()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDataFrame { inner: result })
    }

    /// Return a boolean DataFrame marking non-missing values (pandas `notna`).
    fn notna(&self) -> PyResult<PyDataFrame> {
        let result = self
            .inner
            .notna()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDataFrame { inner: result })
    }

    /// Return a copy of this DataFrame (pandas' `copy(deep=True)`; a shallow
    /// copy sharing the frame's data is refused, as for a Series).
    #[pyo3(signature = (deep=true))]
    fn copy(&self, deep: bool) -> PyResult<PyDataFrame> {
        if !deep {
            return Err(not_implemented(
                "DataFrame.copy(deep=False) (a shallow copy sharing the original's data)",
            ));
        }
        Ok(PyDataFrame {
            inner: self.inner.copy(),
        })
    }

    /// Return a boolean DataFrame marking missing values (pandas `DataFrame.isnull`).
    fn isnull(&self) -> PyResult<PyDataFrame> {
        self.isna()
    }

    /// Return a boolean DataFrame marking non-missing values (pandas `DataFrame.notnull`).
    fn notnull(&self) -> PyResult<PyDataFrame> {
        self.notna()
    }

    /// Return the elementwise absolute value as a new DataFrame; an object
    /// column's cell by cell, so text is Python's TypeError (4qg5w.18) and
    /// numbers their abs (they became text; br-frankenpandas-47dus).
    fn abs(&self, py: Python<'_>) -> PyResult<PyDataFrame> {
        self.unary_with_objects(py, "abs", DataFrame::abs)
    }

    /// Clip values to the `[lower, upper]` range (either bound optional).
    #[pyo3(signature = (lower=None, upper=None, axis=None, inplace=false, **kwargs))]
    fn clip(
        &mut self,
        lower: Option<&Bound<'_, PyAny>>,
        upper: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Option<PyDataFrame>> {
        numpy_compat_kwargs("clip", kwargs)?;
        let result = (|| -> PyResult<PyDataFrame> {
            let ax_opt = parse_axis_param_for_type(axis, "DataFrame")?;
            // A DataFrame bound clips each cell by the bound's cell (it was
            // a TypeError; br-frankenpandas-u6p7i).
            let is_frame = |b: Option<&Bound<'_, PyAny>>| {
                b.is_some_and(|b| b.extract::<PyRef<'_, PyDataFrame>>().is_ok())
            };
            if is_frame(lower) || is_frame(upper) {
                return clip_by_frames(&self.inner, lower, upper)
                    .map(|inner| PyDataFrame { inner });
            }

            let extract_bound = |b: &Bound<'_, PyAny>| -> PyResult<SeriesOrScalarBound> {
                if let Ok(py_s) = b.extract::<PyRef<'_, PySeries>>() {
                    Ok(SeriesOrScalarBound::Series(Box::new(py_s.inner.clone())))
                } else if let Ok(dict) = b.cast::<PyDict>() {
                    let mut labels = Vec::new();
                    let mut vals = Vec::new();
                    for (k, v) in dict.iter() {
                        let col_name = k.extract::<String>()?;
                        let val = v.extract::<f64>()?;
                        labels.push(IndexLabel::Utf8(col_name));
                        vals.push(Scalar::Float64(val));
                    }
                    let s =
                        Series::from_values("bounds", labels, vals).map_err(frame_error_to_py)?;
                    Ok(SeriesOrScalarBound::Series(Box::new(s)))
                } else if let Ok(f) = b.extract::<f64>() {
                    Ok(SeriesOrScalarBound::Scalar(f))
                } else if b.is_none() {
                    Ok(SeriesOrScalarBound::Scalar(f64::NAN))
                } else {
                    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "bound must be a number, Series, or dict",
                    ))
                }
            };

            let lo = match lower {
                Some(b) if !b.is_none() => Some(extract_bound(b)?),
                _ => None,
            };
            let hi = match upper {
                Some(b) if !b.is_none() => Some(extract_bound(b)?),
                _ => None,
            };

            let has_series_bound = matches!(lo, Some(SeriesOrScalarBound::Series(_)))
                || matches!(hi, Some(SeriesOrScalarBound::Series(_)));

            if has_series_bound {
                let is_dict_bound = lower
                    .is_some_and(|b| b.is_instance_of::<pyo3::types::PyDict>())
                    || upper.is_some_and(|b| b.is_instance_of::<pyo3::types::PyDict>());

                let ax = match ax_opt {
                    Some(a) => a,
                    None => {
                        if is_dict_bound {
                            1
                        } else {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                                "Must specify axis=0 or 1",
                            ));
                        }
                    }
                };

                let to_bound_series =
                    |eb: Option<SeriesOrScalarBound>| -> PyResult<Option<Series>> {
                        match eb {
                            None => Ok(None),
                            Some(SeriesOrScalarBound::Series(s)) => Ok(Some(*s)),
                            Some(SeriesOrScalarBound::Scalar(v)) => {
                                if ax == 0 {
                                    let labels = self.inner.index().labels().to_vec();
                                    let vals = vec![Scalar::Float64(v); labels.len()];
                                    let s = Series::from_values("bounds", labels, vals)
                                        .map_err(frame_error_to_py)?;
                                    Ok(Some(s))
                                } else {
                                    let labels: Vec<IndexLabel> = self
                                        .column_labels()
                                        .into_iter()
                                        .map(IndexLabel::Utf8)
                                        .collect();
                                    let vals = vec![Scalar::Float64(v); labels.len()];
                                    let s = Series::from_values("bounds", labels, vals)
                                        .map_err(frame_error_to_py)?;
                                    Ok(Some(s))
                                }
                            }
                        }
                    };

                let lo_series = to_bound_series(lo)?;
                let hi_series = to_bound_series(hi)?;

                let res = if ax == 0 {
                    self.inner
                        .clip_with_row_bounds(lo_series.as_ref(), hi_series.as_ref())
                        .map_err(frame_error_to_py)?
                } else {
                    self.inner
                        .clip_with_column_bounds(lo_series.as_ref(), hi_series.as_ref())
                        .map_err(frame_error_to_py)?
                };
                Ok(PyDataFrame { inner: res })
            } else {
                let lo_f64 = match lo {
                    Some(SeriesOrScalarBound::Scalar(v)) => Some(v),
                    _ => None,
                };
                let hi_f64 = match hi {
                    Some(SeriesOrScalarBound::Scalar(v)) => Some(v),
                    _ => None,
                };
                let res = self.inner.clip(lo_f64, hi_f64).map_err(frame_error_to_py)?;
                Ok(PyDataFrame { inner: res })
            }
        })()?;
        Ok(frame_inplace(&mut self.inner, result, inplace))
    }

    /// Round each numeric value to `decimals` places, returning a new DataFrame.
    #[pyo3(signature = (decimals=None, **kwargs))]
    fn round(
        &self,
        decimals: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyDataFrame> {
        numpy_compat_kwargs("round", kwargs)?;
        match decimals {
            None => {
                let res = self.inner.round(0).map_err(frame_error_to_py)?;
                Ok(PyDataFrame { inner: res })
            }
            Some(d) => {
                if let Ok(n) = d.extract::<i32>() {
                    let res = self.inner.round(n).map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: res })
                } else if let Ok(dict) = d.cast::<PyDict>() {
                    let mut btree = BTreeMap::new();
                    for (k, v) in column_dict_arg(&self.inner, dict)?.iter() {
                        let name = k.extract::<String>()?;
                        let dec = v.extract::<i32>()?;
                        btree.insert(name, dec);
                    }
                    let res = self
                        .inner
                        .round_columns(&btree)
                        .map_err(frame_error_to_py)?;
                    Ok(PyDataFrame {
                        inner: res.with_labels_of(&self.inner),
                    })
                } else if let Ok(py_s) = d.extract::<PyRef<'_, PySeries>>() {
                    let mut btree = BTreeMap::new();
                    for (idx_label, val) in py_s
                        .inner
                        .index()
                        .labels()
                        .iter()
                        .zip(py_s.inner.column().values().iter())
                    {
                        let name = idx_label.to_string();
                        if let Ok(dec) = val.to_i64() {
                            btree.insert(name, dec as i32);
                        }
                    }
                    let res = self
                        .inner
                        .round_columns(&btree)
                        .map_err(frame_error_to_py)?;
                    Ok(PyDataFrame { inner: res })
                } else {
                    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "decimals must be an integer, dict, or Series",
                    ))
                }
            }
        }
    }

    /// Replace values dynamically or via mappings (pandas `DataFrame.replace`).
    /// An explicit `value=None` is a value, as for a Series
    /// (br-frankenpandas-y1092).
    #[pyo3(signature = (to_replace=None, value=Passed(None), inplace=false, limit=None, regex=None, method=None))]
    #[allow(clippy::too_many_arguments)]
    fn replace(
        &mut self,
        py: Python<'_>,
        to_replace: Option<&Bound<'_, PyAny>>,
        value: Passed<'_>,
        inplace: bool,
        limit: Option<usize>,
        regex: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
    ) -> PyResult<Option<PyDataFrame>> {
        let value = value.0.as_ref();
        let dict_to_replace = to_replace.is_some_and(|t| t.cast::<PyDict>().is_ok());
        let regex_false = regex.is_none_or(|r| r.extract::<bool>().is_ok_and(|b| !b));
        warn_replace_args(
            py,
            "DataFrame",
            method,
            limit,
            value.is_none() && !dict_to_replace && regex_false,
        )?;
        // The downcasting warnings: one per downcast column (a list or a
        // dict goes pair by pair or column by column), one in all for a
        // single scalar or pattern (`per_column` false), or as counted.
        let mut per_column = true;
        let mut counted: Option<usize> = None;
        let result = (|| -> PyResult<PyDataFrame> {
            let mut is_regex = false;
            let mut effective_to_replace = to_replace;
            let mut pattern_kw = false;

            if let Some(reg) = regex {
                if let Ok(b) = reg.extract::<bool>() {
                    is_regex = b;
                } else if reg.extract::<String>().is_ok() || reg.cast::<PyDict>().is_ok() {
                    is_regex = true;
                    if effective_to_replace.is_none() {
                        effective_to_replace = Some(reg);
                        pattern_kw = true;
                    }
                }
            }

            // pandas 2.2 (deprecated there, still its behaviour, fvsao.5): with no
            // `to_replace` the targets are the missing values, and with no
            // `value` each target is padded from its neighbour (`method`, default
            // pad). This returned the frame unchanged.
            let value_given = value.is_some();
            let Some(to_repl) = effective_to_replace.filter(|t| !t.is_none()) else {
                if is_regex {
                    return Ok(PyDataFrame {
                        inner: self.inner.clone(),
                    });
                }
                if value_given {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "'regex' must be a string or a compiled regular expression or a list or dict of strings or regular expressions, you passed a 'bool'",
                    ));
                }
                let filled = match method.unwrap_or("pad") {
                "pad" | "ffill" => self.inner.ffill(limit),
                "backfill" | "bfill" => self.inner.bfill(limit),
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                    )));
                }
            }
            .map_err(frame_error_to_py)?;
                counted = Some(0);
                return Ok(PyDataFrame { inner: filled });
            };
            let dict_like = to_repl.cast::<PyDict>().is_ok();
            // With no value, a to_replace that is not a dict pads its
            // targets taken literally, regex=True or not (as a Series).
            let method = if !value_given && !pattern_kw && !dict_like {
                method.or(Some("pad"))
            } else {
                method
            };

            if let Some(m) = method {
                let is_ffill = match m {
                    "pad" | "ffill" => true,
                    "backfill" | "bfill" => false,
                    other => {
                        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                            "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                        )));
                    }
                };
                let targets = if is_py_collection(to_repl) {
                    py_sequence_to_scalars(py, to_repl)?
                } else {
                    vec![py_to_scalar(py, to_repl)?]
                };
                let n_cols = self.inner.num_columns();
                let mut col_map = BTreeMap::new();
                let mut column_order = Vec::with_capacity(n_cols);
                for pos in 0..n_cols {
                    if let (Some(name), Some(col)) =
                        (self.inner.column_name_at(pos), self.inner.column_at(pos))
                    {
                        let s = Series::new(name.clone(), self.inner.index().clone(), col.clone())
                            .map_err(frame_error_to_py)?;
                        let replaced_s = series_replace_with_method(&s, &targets, is_ffill, limit)
                            .map_err(frame_error_to_py)?;
                        col_map.insert(name.clone(), replaced_s.column().clone());
                        column_order.push(name.clone());
                    }
                }
                let out = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    column_order,
                )
                .map_err(frame_error_to_py)?;
                counted = Some(0);
                return Ok(PyDataFrame { inner: out });
            }

            if is_regex {
                if let Ok(dict) = to_repl.cast::<PyDict>() {
                    let mut has_nested_dict = false;
                    for (_, v) in dict.iter() {
                        if v.cast::<PyDict>().is_ok() {
                            has_nested_dict = true;
                            break;
                        }
                    }
                    if has_nested_dict {
                        let n_cols = self.inner.num_columns();
                        let mut col_map = BTreeMap::new();
                        let mut column_order = Vec::with_capacity(n_cols);
                        for pos in 0..n_cols {
                            if let (Some(name), Some(col)) =
                                (self.inner.column_name_at(pos), self.inner.column_at(pos))
                            {
                                column_order.push(name.clone());
                                if let Ok(Some(inner_obj)) = dict.get_item(&name) {
                                    if let Ok(inner_dict) = inner_obj.cast::<PyDict>() {
                                        let mut s = Series::new(
                                            name.clone(),
                                            self.inner.index().clone(),
                                            col.clone(),
                                        )
                                        .map_err(frame_error_to_py)?;
                                        for (pat_obj, repl_obj) in inner_dict.iter() {
                                            let pat: &str = pat_obj.extract()?;
                                            s = RegexValue::from_py(py, &repl_obj)?
                                                .series(&s, pat)?;
                                        }
                                        col_map.insert(name.clone(), s.column().clone());
                                        continue;
                                    }
                                }
                                col_map.insert(name.clone(), col.clone());
                            }
                        }
                        let out = DataFrame::new_with_column_order(
                            self.inner.index().clone(),
                            col_map,
                            column_order,
                        )
                        .map_err(frame_error_to_py)?;
                        return Ok(PyDataFrame { inner: out });
                    }

                    let all_keys_are_columns = !dict.is_empty()
                        && dict.keys().iter().all(|k| {
                            k.extract::<&str>()
                                .is_ok_and(|col: &str| self.inner.column(col).is_some())
                        });
                    if all_keys_are_columns && value.is_some() {
                        let n_cols = self.inner.num_columns();
                        let mut col_map = BTreeMap::new();
                        let mut column_order = Vec::with_capacity(n_cols);
                        for pos in 0..n_cols {
                            if let (Some(name), Some(col)) =
                                (self.inner.column_name_at(pos), self.inner.column_at(pos))
                            {
                                column_order.push(name.clone());
                                if let Ok(Some(pat_obj)) = dict.get_item(&name) {
                                    let mut s = Series::new(
                                        name.clone(),
                                        self.inner.index().clone(),
                                        col.clone(),
                                    )
                                    .map_err(frame_error_to_py)?;
                                    let repl = if let Some(val_obj) = value {
                                        if let Ok(val_dict) = val_obj.cast::<PyDict>() {
                                            if let Ok(Some(col_repl)) = val_dict.get_item(&name) {
                                                RegexValue::from_py(py, &col_repl)?
                                            } else {
                                                col_map.insert(name.clone(), col.clone());
                                                continue;
                                            }
                                        } else {
                                            RegexValue::from_py(py, val_obj)?
                                        }
                                    } else {
                                        RegexValue::Sub(String::new())
                                    };
                                    if is_py_collection(&pat_obj) {
                                        for item in pat_obj.try_iter()? {
                                            let pat_str: String = item?.extract()?;
                                            s = repl.series(&s, &pat_str)?;
                                        }
                                    } else {
                                        let pat_str: String = pat_obj.extract()?;
                                        s = repl.series(&s, &pat_str)?;
                                    }
                                    col_map.insert(name.clone(), s.column().clone());
                                } else {
                                    col_map.insert(name.clone(), col.clone());
                                }
                            }
                        }
                        let out = DataFrame::new_with_column_order(
                            self.inner.index().clone(),
                            col_map,
                            column_order,
                        )
                        .map_err(frame_error_to_py)?;
                        return Ok(PyDataFrame { inner: out });
                    }

                    // Global pattern dict, a pattern a step.
                    let mut df = self.inner.clone();
                    let mut steps = 0;
                    for (pat_obj, repl_obj) in dict.iter() {
                        let pat: &str = pat_obj.extract()?;
                        let next = RegexValue::from_py(py, &repl_obj)?.frame(&df, pat)?;
                        steps += usize::from(replace_downcasts(&df, &next) > 0);
                        df = next;
                    }
                    counted = Some(steps);
                    return Ok(PyDataFrame { inner: df });
                } else if let Ok(pat) = to_repl.extract::<&str>() {
                    let repl = match value {
                        Some(val_obj) => RegexValue::from_py(py, val_obj)?,
                        None => RegexValue::Sub(String::new()),
                    };
                    let res = repl.frame(&self.inner, pat)?;
                    per_column = false;
                    return Ok(PyDataFrame { inner: res });
                } else if is_py_collection(to_repl) {
                    let mut pat_list = Vec::new();
                    for item in to_repl.try_iter()? {
                        pat_list.push(item?.extract::<String>()?);
                    }
                    let mut df = self.inner.clone();
                    let mut steps = 0;
                    if let Some(val_obj) = value {
                        let repl_list = if is_py_collection(val_obj) {
                            let mut repl_list = Vec::new();
                            for item in val_obj.try_iter()? {
                                repl_list.push(RegexValue::from_py(py, &item?)?);
                            }
                            if pat_list.len() != repl_list.len() {
                                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                                    format!(
                                        "Replacement lists must match in length. Expecting {} got {}",
                                        pat_list.len(),
                                        repl_list.len()
                                    ),
                                ));
                            }
                            repl_list
                        } else {
                            let repl = RegexValue::from_py(py, val_obj)?;
                            pat_list.iter().map(|_| repl.clone()).collect()
                        };
                        // A pattern a step.
                        for (pat, repl) in pat_list.iter().zip(repl_list.iter()) {
                            let next = repl.frame(&df, pat)?;
                            steps += usize::from(replace_downcasts(&df, &next) > 0);
                            df = next;
                        }
                    }
                    counted = Some(steps);
                    return Ok(PyDataFrame { inner: df });
                }
            }

            // Literal replacement (regex=false)
            if let Ok(dict) = to_repl.cast::<PyDict>() {
                let mut has_nested_dict = false;
                for (_, v) in dict.iter() {
                    if v.cast::<PyDict>().is_ok() {
                        has_nested_dict = true;
                        break;
                    }
                }
                if has_nested_dict {
                    // {column: {old: new}}: the keys name columns, typed ones
                    // included (fvsao.32).
                    let dict = &column_dict_arg(&self.inner, dict)?;
                    let mut per_col: BTreeMap<String, Vec<(Scalar, Scalar)>> = BTreeMap::new();
                    for (k, v) in dict.iter() {
                        let col_name: String = k.extract()?;
                        if self.inner.column(&col_name).is_some() {
                            if let Ok(inner_dict) = v.cast::<PyDict>() {
                                let pairs = py_dict_to_scalar_pairs(py, inner_dict)?;
                                per_col.insert(col_name, pairs);
                            }
                        }
                    }
                    let res = self
                        .inner
                        .replace_dict(&per_col)
                        .map_err(frame_error_to_py)?;
                    return Ok(PyDataFrame { inner: res });
                }

                // With a value, a {column: old} dict's keys name columns.
                let column_keyed;
                let dict = if value.is_some() {
                    column_keyed = column_dict_arg(&self.inner, dict)?;
                    &column_keyed
                } else {
                    dict
                };
                let all_keys_are_columns = !dict.is_empty()
                    && dict.keys().iter().all(|k| {
                        k.extract::<&str>()
                            .is_ok_and(|col: &str| self.inner.column(col).is_some())
                    });
                if all_keys_are_columns && value.is_some() {
                    let mut per_col: BTreeMap<String, Vec<(Scalar, Scalar)>> = BTreeMap::new();
                    for (k, v) in dict.iter() {
                        let col_name: String = k.extract()?;
                        if self.inner.column(&col_name).is_some() {
                            let targets = if is_py_collection(&v) {
                                py_sequence_to_scalars(py, &v)?
                            } else {
                                vec![py_to_scalar(py, &v)?]
                            };
                            let repl_scalar = if let Some(val_obj) = value {
                                if let Ok(val_dict) = val_obj.cast::<PyDict>() {
                                    // Keyed by the column's typed label.
                                    let key =
                                        index_label_to_py(py, &self.inner.column_label(&col_name))?;
                                    if let Ok(Some(col_repl)) = val_dict.get_item(key) {
                                        py_to_scalar(py, &col_repl)?
                                    } else {
                                        continue;
                                    }
                                } else {
                                    py_to_scalar(py, val_obj)?
                                }
                            } else {
                                continue;
                            };
                            let pairs: Vec<(Scalar, Scalar)> = targets
                                .into_iter()
                                .map(|t| (t, repl_scalar.clone()))
                                .collect();
                            per_col.insert(col_name, pairs);
                        }
                    }
                    let res = self
                        .inner
                        .replace_dict(&per_col)
                        .map_err(frame_error_to_py)?;
                    return Ok(PyDataFrame { inner: res });
                }

                // Global flat {old: new} dict
                let pairs = py_dict_to_scalar_pairs(py, dict)?;
                let res = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: res });
            }

            if let Ok(py_s) = to_repl.extract::<PyRef<PySeries>>() {
                let s = &py_s.inner;
                let idx_labels = s.index().labels();
                let col_vals = s.column().values();
                let pairs: Vec<(Scalar, Scalar)> = idx_labels
                    .iter()
                    .zip(col_vals.iter())
                    .map(|(label, val)| (index_label_to_scalar(label), val.clone()))
                    .collect();
                let res = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: res });
            }

            if is_py_collection(to_repl) {
                let from_scalars = py_sequence_to_scalars(py, to_repl)?;
                let pairs: Vec<(Scalar, Scalar)> = if let Some(val_obj) = value {
                    if is_py_collection(val_obj) {
                        let to_scalars = py_sequence_to_scalars(py, val_obj)?;
                        if from_scalars.len() != to_scalars.len() {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "Replacement lists must match in length. Expecting {} got {}",
                                from_scalars.len(),
                                to_scalars.len()
                            )));
                        }
                        from_scalars.into_iter().zip(to_scalars).collect()
                    } else {
                        let to_s = py_to_scalar(py, val_obj)?;
                        from_scalars
                            .into_iter()
                            .map(|s| (s, to_s.clone()))
                            .collect()
                    }
                } else {
                    return Ok(PyDataFrame {
                        inner: self.inner.clone(),
                    });
                };
                let res = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PyDataFrame { inner: res });
            }

            // Single scalar
            if let Some(val_obj) = value {
                let from_s = py_to_scalar(py, to_repl)?;
                let to_s = py_to_scalar(py, val_obj)?;
                let res = self
                    .inner
                    .replace(&[(from_s, to_s)])
                    .map_err(frame_error_to_py)?;
                per_column = false;
                return Ok(PyDataFrame { inner: res });
            }

            Ok(PyDataFrame {
                inner: self.inner.clone(),
            })
        })()?;
        let downcasts = counted.unwrap_or_else(|| {
            let columns = replace_downcasts(&self.inner, &result.inner);
            if per_column { columns } else { columns.min(1) }
        });
        warn_replace_downcast(py, downcasts)?;
        Ok(frame_inplace(&mut self.inner, result, inplace))
    }

    /// Cast every column, or the columns a `{column: dtype}` dict names, to a
    /// dtype given as a pandas name, a Python type (`float`) or a numpy/pandas
    /// dtype. A dict key that is not a column is pandas' KeyError;
    /// errors="ignore" returns the frame unchanged on failure.
    /// (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.6.4)
    #[pyo3(signature = (dtype, copy=None, errors="raise"))]
    fn astype(
        &self,
        dtype: &Bound<'_, PyAny>,
        copy: Option<&Bound<'_, PyAny>>,
        errors: &str,
    ) -> PyResult<PyDataFrame> {
        let _ = copy; // pandas' copy= does not change the result
        // pandas' integer-cast refusals column by column, and the string
        // columns' integers as int() reads them (15crl).
        let casts: Vec<(String, Bound<'_, PyAny>)> = if let Ok(mapping) = dtype.cast::<PyDict>() {
            column_dict_arg(&self.inner, mapping)?
                .iter()
                .map(|(column, spec)| Ok((column.extract::<String>()?, spec)))
                .collect::<PyResult<_>>()?
        } else {
            self.inner
                .column_names()
                .into_iter()
                .map(|name| (name.clone(), dtype.clone()))
                .collect()
        };
        let mut read: Option<DataFrame> = None;
        for (name, spec) in &casts {
            let Some(column) = self.inner.column(name) else {
                continue;
            };
            // An object column of zoned datetimes to a datetime dtype (an1xe);
            // a dict's cast names the column it failed on, as pandas'.
            let converted = match py_dtype_arg(spec) {
                Ok(target) if column.holds_non_text() => {
                    zoned_astype(column, &target).map_err(|err| {
                        if dtype.cast::<PyDict>().is_err() {
                            return err;
                        }
                        PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                            "{}: Error while type casting for column '{name}'",
                            err.value(dtype.py())
                        ))
                    })
                }
                _ => Ok(None),
            }
            .and_then(|zoned| match zoned {
                Some(column) => Ok(Some(column)),
                None => pandas_astype_int_source(column, spec),
            });
            match converted {
                Ok(Some(column)) => {
                    let frame = read.take().unwrap_or_else(|| self.inner.clone());
                    read = Some(
                        frame
                            .with_column(name.clone(), column)
                            .map_err(frame_error_to_py)?,
                    );
                }
                Ok(None) => {}
                Err(_) if errors == "ignore" => {
                    return Ok(PyDataFrame {
                        inner: self.inner.clone(),
                    });
                }
                Err(err) => return Err(err),
            }
        }
        let source = read.as_ref().unwrap_or(&self.inner);
        // The columns cast to pandas' `string` dtype, after the rest (fvsao.59).
        let mut strings: Vec<String> = Vec::new();
        let result = if let Ok(mapping) = dtype.cast::<PyDict>() {
            let mapping = column_dict_arg(&self.inner, mapping)?;
            let mut targets: Vec<(String, DType)> = Vec::with_capacity(mapping.len());
            let mut widths: Vec<(String, NumericWidth, bool)> = Vec::new();
            let mut objects: Vec<String> = Vec::new();
            for (column, spec) in mapping.iter() {
                let column = column.extract::<String>()?;
                if self.inner.column(&column).is_none() {
                    return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                        "Only a column name can be used for the key in a dtype mappings \
                         argument. '"
                            .to_owned()
                            + &column
                            + "' not found in columns.",
                    ));
                }
                if is_object_dtype_arg(&spec) {
                    objects.push(column);
                } else if is_string_dtype_arg(&spec) {
                    strings.push(column);
                } else if let Some((width, nullable)) = py_width_arg(&spec) {
                    widths.push((column, width, nullable));
                } else {
                    targets.push((column, py_dtype_arg(&spec)?));
                }
            }
            let pairs: Vec<(&str, DType)> = targets
                .iter()
                .map(|(column, dt)| (column.as_str(), dt.clone()))
                .collect();
            let cast = match source.astype_columns(&pairs) {
                Ok(frame) => Ok(object_frame(&frame, Some(&objects))?),
                failed => failed,
            };
            widths
                .iter()
                .fold(cast, |frame, (column, width, nullable)| {
                    frame.and_then(|frame| frame.astype_column_width(column, *width, *nullable))
                })
        } else if is_object_dtype_arg(dtype) {
            Ok(object_frame(&self.inner, None)?)
        } else if is_string_dtype_arg(dtype) {
            strings = self.inner.column_names().into_iter().cloned().collect();
            Ok(self.inner.clone())
        } else if let Some((width, nullable)) = py_width_arg(dtype) {
            source.astype_width(width, nullable)
        } else {
            let target = py_dtype_arg(dtype)?;
            source.astype(target)
        };
        let result = match result {
            Ok(mut frame) => {
                for name in &strings {
                    if let Some(column) = frame.column(name) {
                        let text = pandas_string_column(column)?;
                        frame = frame
                            .with_column(name.clone(), text)
                            .map_err(frame_error_to_py)?;
                    }
                }
                Ok(frame)
            }
            failed => failed,
        };
        match result {
            Ok(inner) => Ok(PyDataFrame { inner }),
            Err(_) if errors == "ignore" => Ok(PyDataFrame {
                inner: self.inner.clone(),
            }),
            Err(e) => Err(astype_error_to_py(&e)),
        }
    }

    /// Sort DataFrame by one or more columns.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (by, axis=None, ascending=None, inplace=false, kind=None, na_position="last", ignore_index=false, key=None))]
    fn sort_values(
        &mut self,
        py: Python<'_>,
        by: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        ascending: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        kind: Option<&str>,
        na_position: &str,
        ignore_index: bool,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        validate_sort_kind(kind)?;
        let result = (|| -> PyResult<PyDataFrame> {
            let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type DataFrame (axis=1 sort not supported)"
                )));
            }

            let by_cols: Vec<String> = if let Some(names) = self.sort_key_names(by) {
                // A typed label (by=0) names its column (fvsao.32), a
                // tuple its MultiIndex column (g3bux).
                names
            } else if let Ok(single) = by.extract::<String>() {
                vec![single]
            } else if let Ok(list) = by.extract::<Vec<String>>() {
                if list.is_empty() {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Must pass at least one column to sort by",
                    ));
                }
                list
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "by must be a string or list of strings",
                ));
            };

            let asc_flags: Vec<bool> = match ascending {
                None => vec![true; by_cols.len()],
                Some(asc_obj) => {
                    if let Ok(b) = asc_obj.extract::<bool>() {
                        vec![b; by_cols.len()]
                    } else if let Ok(bool_list) = asc_obj.extract::<Vec<bool>>() {
                        if bool_list.len() != by_cols.len() {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "Length of ascending ({}) must match the length of by ({})",
                                bool_list.len(),
                                by_cols.len()
                            )));
                        }
                        bool_list
                    } else {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                            "ascending must be a bool or list of bools",
                        ));
                    }
                }
            };

            let by_refs: Vec<&str> = by_cols.iter().map(String::as_str).collect();
            let by_positions = self
                .sort_key_positions(by)
                .filter(|positions| key.is_none() && positions.len() == asc_flags.len());
            let sorted = if let Some(positions) = by_positions {
                self.inner
                    .sort_values_at(&positions, &asc_flags, na_position)
                    .map_err(frame_error_to_py)?
            } else if let Some(key) = key {
                self.keyed_sort_values(py, key, &by_cols, &asc_flags, na_position)?
            } else if by_refs.len() == 1 {
                self.inner
                    .sort_values_na(by_refs[0], asc_flags[0], na_position)
                    .map_err(frame_error_to_py)?
            } else {
                self.inner
                    .sort_values_multi(&by_refs, &asc_flags, na_position)
                    .map_err(frame_error_to_py)?
            };

            let out = if ignore_index {
                sorted.reset_index(true).map_err(frame_error_to_py)?
            } else {
                sorted
            };
            Ok(PyDataFrame { inner: out })
        })()?;
        Ok(frame_inplace(&mut self.inner, result, inplace))
    }

    /// Return boolean Series denoting duplicate rows.
    #[pyo3(signature = (subset=None, keep=None))]
    fn duplicated(
        &self,
        subset: Option<&Bound<'_, PyAny>>,
        keep: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        let keep_enum = parse_duplicate_keep(keep)?;
        let subset = column_arg_opt(&self.inner, subset)?;
        let subset_vec: Option<Vec<String>> = match subset {
            None => None,
            Some(s) => {
                if let Ok(single) = s.extract::<String>() {
                    Some(vec![single])
                } else if let Ok(list) = s.extract::<Vec<String>>() {
                    Some(list)
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "subset must be a column name or list of column names",
                    ));
                }
            }
        };
        let result = self
            .inner
            .duplicated(subset_vec.as_deref(), keep_enum)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: result })
    }

    /// Drop duplicate rows.
    #[pyo3(signature = (subset=None, keep=None, inplace=false, ignore_index=false))]
    fn drop_duplicates(
        &mut self,
        subset: Option<&Bound<'_, PyAny>>,
        keep: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        ignore_index: bool,
    ) -> PyResult<Option<PyDataFrame>> {
        let deduplicated = (|| -> PyResult<PyDataFrame> {
            let keep_enum = parse_duplicate_keep(keep)?;
            let subset = column_arg_opt(&self.inner, subset)?;
            let subset_vec: Option<Vec<String>> = match subset {
                None => None,
                Some(s) => {
                    if let Ok(single) = s.extract::<String>() {
                        Some(vec![single])
                    } else if let Ok(list) = s.extract::<Vec<String>>() {
                        Some(list)
                    } else {
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                            "subset must be a column name or list of column names",
                        ));
                    }
                }
            };
            let result = self
                .inner
                .drop_duplicates(subset_vec.as_deref(), keep_enum, ignore_index)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            Ok(PyDataFrame { inner: result })
        })()?;
        Ok(frame_inplace(&mut self.inner, deduplicated, inplace))
    }

    /// Group by one column name or a list of them, as `df.groupby("city")`
    /// and `df.groupby(["city", "year"])` both do in pandas, with pandas'
    /// `as_index`, `sort`, `group_keys` and `dropna` (br-frankenpandas-n57tz:
    /// only `by` was accepted); a category key is checked against `observed`
    /// and `sort` (see `check_category_key`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (by=None, axis=None, level=None, as_index=true, sort=true, group_keys=true, observed=None, dropna=true))]
    fn groupby(
        &self,
        py: Python<'_>,
        by: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        as_index: bool,
        sort: bool,
        group_keys: bool,
        observed: Option<bool>,
        dropna: bool,
    ) -> PyResult<Py<PyAny>> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params("DataFrame.groupby", &[("axis", ax == 0)])?;
        let by = by.filter(|b| !b.is_none());
        // A dict maps each index label to its group, as pandas' groupby does
        // (a label it lacks is a missing key; it was a KeyError on the dict;
        // br-frankenpandas-2ahoa).
        let mapped_by;
        let by = match by.map(|by| by.cast::<PyDict>()) {
            Some(Ok(mapping)) => {
                let cells = self
                    .inner
                    .index()
                    .labels()
                    .iter()
                    .map(
                        |label| match mapping.get_item(index_label_to_py(py, label)?)? {
                            Some(group) => py_to_scalar(py, &group),
                            None => Ok(Scalar::Null(NullKind::NaN)),
                        },
                    )
                    .collect::<PyResult<Vec<_>>>()?;
                let column = Column::from_values(cells).map_err(column_error_to_py)?;
                // The grouping is named after the index it maps.
                let name = self
                    .inner
                    .index()
                    .name()
                    .map(ToString::to_string)
                    .unwrap_or_default();
                let keys = Series::new(name, self.inner.index().clone(), column)
                    .map_err(frame_error_to_py)?;
                mapped_by = Bound::new(py, PySeries { inner: keys })?.into_any();
                Some(&mapped_by)
            }
            _ => by,
        };
        let level = level.filter(|l| !l.is_none());
        // A lone pd.Grouper: with freq= it is pandas' TimeGrouper - the same
        // bins as resample over `key` (or the index), empty ones included -
        // and without one it groups by its key or level. It raised KeyError
        // 'Grouper(...)'.
        let grouper_key;
        let grouper_level;
        let (by, level) = match by.map(|by| by.extract::<PyRef<'_, PyGrouper>>()) {
            Some(Ok(grouper)) => {
                if let Some(freq) = &grouper.freq {
                    if grouper.level.is_some() {
                        return Err(not_implemented("groupby(Grouper(level=..., freq=...))"));
                    }
                    let frame = match &grouper.key {
                        Some(key) => self.inner.set_index(key, true).map_err(frame_error_to_py)?,
                        None => self.inner.clone(),
                    };
                    return PyResampler::new(
                        ResampleTarget::DataFrame(frame),
                        freq.clone(),
                        None,
                        None,
                        None,
                    )?
                    .into_py_any(py);
                }
                match (&grouper.key, &grouper.level) {
                    (Some(key), None) => {
                        grouper_key = pyo3::types::PyString::new(py, key);
                        (Some(grouper_key.as_any()), level)
                    }
                    (None, Some(name)) => {
                        grouper_level = pyo3::types::PyString::new(py, name);
                        (None, Some(grouper_level.as_any()))
                    }
                    _ => return Err(not_implemented("this pd.Grouper form")),
                }
            }
            _ => (by, level),
        };
        // A pd.Grouper among several keys: its key column, binned as
        // resample bins it under freq= (pandas' TimeGrouper; only the bins
        // holding rows are groups). It was refused (br-frankenpandas-h06ox).
        if let Some(keys) = by.and_then(|by| by.cast::<PyList>().ok())
            && keys
                .iter()
                .any(|key| key.extract::<PyRef<'_, PyGrouper>>().is_ok())
        {
            let mut frame = self.inner.clone();
            let names = PyList::empty(py);
            for key in keys.iter() {
                let Ok(grouper) = key.extract::<PyRef<'_, PyGrouper>>() else {
                    names.append(key)?;
                    continue;
                };
                let (Some(name), None) = (&grouper.key, &grouper.level) else {
                    return Err(not_implemented(
                        "groupby with a pd.Grouper(level=...) among several keys",
                    ));
                };
                if let Some(freq) = &grouper.freq {
                    let column = frame.column(name).ok_or_else(|| {
                        PyErr::new::<pyo3::exceptions::PyKeyError, _>(name.clone())
                    })?;
                    if !matches!(column.dtype(), DType::Datetime64 { tz: None }) {
                        return Err(not_implemented(
                            "a pd.Grouper(freq=...) among several keys over other than naive datetimes",
                        ));
                    }
                    let instants: Vec<IndexLabel> = column
                        .values()
                        .iter()
                        .map(|value| match value {
                            Scalar::Datetime64(nanos) if *nanos != Timestamp::NAT => {
                                IndexLabel::Datetime64(*nanos)
                            }
                            _ => IndexLabel::Null(NullKind::NaT),
                        })
                        .collect();
                    let bins = fp_frame::resample_bin_labels(&instants, freq)
                        .into_iter()
                        .map(|bin| match bin {
                            Some(IndexLabel::Datetime64(nanos)) => Scalar::Datetime64(nanos),
                            _ => Scalar::Null(NullKind::NaT),
                        })
                        .collect();
                    let binned = Column::new(column.dtype(), bins).map_err(column_error_to_py)?;
                    frame = frame
                        .with_column(name.clone(), binned)
                        .map_err(frame_error_to_py)?;
                }
                names.append(name)?;
            }
            return PyDataFrame { inner: frame }.groupby(
                py,
                Some(names.as_any()),
                axis,
                level,
                as_index,
                sort,
                group_keys,
                observed,
                dropna,
            );
        }
        // A typed column label (by=0, by=[0, 'a']) names its column
        // (fvsao.32): read as the names it resolves to.
        // A full tuple names its MultiIndex column (sdyhq).
        let named_by = match by.map(|by| (by, self.sort_key_names(by))) {
            Some((by, Some(names))) if by.is_instance_of::<PyList>() => {
                Some(PyList::new(py, names)?.into_any())
            }
            Some((_, Some(names))) => names
                .into_iter()
                .next()
                .map(|name| pyo3::types::PyString::new(py, &name).into_any()),
            _ => None,
        };
        let by = named_by.as_ref().or(by);
        let (df, by, key_names) = match (by, level) {
            (Some(by), None) => resolve_groupby_keys(py, &self.inner, by)?,
            (None, Some(level)) => group_by_index_level(&self.inner, level)?,
            (Some(_), Some(_)) => {
                return Err(not_implemented("DataFrame.groupby with both by and level"));
            }
            (None, None) => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "You have to supply one of 'by' and 'level'",
                ));
            }
        };
        for key in &by {
            if let Some(column) = df.column(key) {
                refuse_unhashable_keys(py, column)?;
            }
        }
        // pandas' as_index=False output drops an unnamed array key and
        // inserts named ones as columns; only column keys are modelled there.
        let column_keys_only = by
            .iter()
            .zip(&key_names)
            .all(|(column, name)| name.as_deref() == Some(column));
        if !as_index && !column_keys_only {
            return Err(not_implemented(
                "DataFrame.groupby(as_index=False) over keys that are not columns",
            ));
        }
        let unused = check_category_keys(py, &df, &by, observed)?;
        // Repeated column names each keep their own column (47qjv).
        let (df, repeated) = RepeatedColumns::keyed(df, &by)?;
        let gb = PyGroupBy {
            df,
            by,
            key_names,
            as_index,
            sort,
            dropna,
            group_keys,
            unused,
            selection: None,
            repeated,
        };
        gb.grouped()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        gb.into_py_any(py)
    }

    /// Export to CSV (pandas `DataFrame.to_csv`). With no `path_or_buf`,
    /// returns the CSV string; otherwise writes the path or file-like object
    /// and returns `None`. pandas' default is `index=True`
    /// (br-frankenpandas-rc0923-epic-rust-parity-bugs-4qg5w.1); see
    /// `write_csv_py` for the keywords honoured (fvsao.5).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (path_or_buf=None, *, sep=",", na_rep="", float_format=None, columns=None, header=None, index=true, index_label=None, mode="w", encoding=None, compression=Some("infer"), quoting=None, quotechar="\"", lineterminator=None, chunksize=None, date_format=None, doublequote=true, escapechar=None, decimal=".", errors="strict", storage_options=None))]
    fn to_csv(
        &self,
        path_or_buf: Option<&Bound<'_, PyAny>>,
        sep: &str,
        na_rep: &str,
        float_format: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        header: Option<&Bound<'_, PyAny>>,
        index: bool,
        index_label: Option<&Bound<'_, PyAny>>,
        mode: &str,
        encoding: Option<&str>,
        compression: Option<&str>,
        quoting: Option<i64>,
        quotechar: &str,
        lineterminator: Option<&str>,
        chunksize: Option<usize>,
        date_format: Option<&str>,
        doublequote: bool,
        escapechar: Option<&str>,
        decimal: &str,
        errors: &str,
        storage_options: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<String>> {
        // chunksize only batches the writes and errors only handles encoding
        // failures, which UTF-8 output cannot have.
        let _ = (chunksize, errors);
        let args = CsvWriteArgs {
            sep,
            na_rep,
            float_format,
            columns,
            header,
            index,
            index_label,
            mode,
            encoding,
            compression,
            quoting,
            quotechar,
            lineterminator,
            date_format,
            doublequote,
            escapechar,
            decimal,
            storage_options,
        };
        write_csv_py("DataFrame.to_csv", &self.inner, path_or_buf, &args)
    }

    /// Export to a Python dictionary (pandas `DataFrame.to_dict(orient=...)`).
    #[pyo3(signature = (orient="dict"))]
    fn to_dict(&self, py: Python<'_>, orient: &str) -> PyResult<Py<PyAny>> {
        let n_rows = self.inner.len();
        let col_names = self.inner.column_names();
        // A row's key: its MultiIndex tuple, a tz-aware instant in its zone.
        let row_keys = frame_row_keys_to_py(py, &self.inner)?;
        // A column's key, by position: its typed label (0, not '0';
        // fvsao.32), its tuple under MultiIndex columns (g3bux).
        let keys = (0..col_names.len())
            .map(|position| self.column_key_py(py, position))
            .collect::<PyResult<Vec<_>>>()?;

        // Only orient='index' needs unique row keys: 'dict' is each column's
        // Series.to_dict, the last row under a repeated label winning, as
        // pandas' (it raised too; br-frankenpandas-kd16w).
        if self.inner.index().has_duplicates() && orient == "index" {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "DataFrame index must be unique for orient='index'.",
            ));
        }
        // Every column by position: under a repeated key each column is its
        // own (the dict keeps the last, as pandas', which warns so).
        let column_at = |position: usize| {
            self.inner.column_at(position).ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                    "column position {position} missing"
                ))
            })
        };
        if pyo3::types::PySet::new(py, &keys).is_ok_and(|unique| unique.len() != keys.len()) {
            PyErr::warn(
                py,
                &py.get_type::<pyo3::exceptions::PyUserWarning>(),
                c"DataFrame columns are not unique, some columns will be omitted.",
                1,
            )?;
        }

        match orient {
            "dict" => {
                let out = PyDict::new(py);
                for (position, key) in keys.iter().enumerate() {
                    let col = column_at(position)?;
                    let inner_dict = PyDict::new(py);
                    for (key, val) in row_keys.iter().zip(col.values()) {
                        inner_dict.set_item(key, to_dict_cell(py, col, val)?)?;
                    }
                    out.set_item(key, inner_dict)?;
                }
                Ok(out.into_any().unbind())
            }
            "list" => {
                let out = PyDict::new(py);
                for (position, key) in keys.iter().enumerate() {
                    let col = column_at(position)?;
                    let values: Vec<Py<PyAny>> = col
                        .values()
                        .iter()
                        .map(|s| to_dict_cell(py, col, s))
                        .collect::<PyResult<Vec<_>>>()?;
                    out.set_item(key, PyList::new(py, values)?)?;
                }
                Ok(out.into_any().unbind())
            }
            "records" => {
                let mut rows_list = Vec::with_capacity(n_rows);
                for row_idx in 0..n_rows {
                    let row_dict = PyDict::new(py);
                    for (position, key) in keys.iter().enumerate() {
                        let col = column_at(position)?;
                        let v = to_dict_cell(py, col, &col.values()[row_idx])?;
                        row_dict.set_item(key, v)?;
                    }
                    rows_list.push(row_dict);
                }
                Ok(PyList::new(py, rows_list)?.into_any().unbind())
            }
            "index" => {
                let out = PyDict::new(py);
                for (row_idx, k) in row_keys.iter().enumerate() {
                    let row_dict = PyDict::new(py);
                    for (position, key) in keys.iter().enumerate() {
                        let col = column_at(position)?;
                        let v = to_dict_cell(py, col, &col.values()[row_idx])?;
                        row_dict.set_item(key, v)?;
                    }
                    out.set_item(k, row_dict)?;
                }
                Ok(out.into_any().unbind())
            }
            "series" => {
                let out = PyDict::new(py);
                for (position, key) in keys.iter().enumerate() {
                    let col_series = self.column_series_at(position)?;
                    out.set_item(key, Py::new(py, col_series)?)?;
                }
                Ok(out.into_any().unbind())
            }
            "split" | "tight" => {
                let out = PyDict::new(py);
                out.set_item("index", PyList::new(py, &row_keys)?)?;
                out.set_item("columns", PyList::new(py, &keys)?)?;
                // Columns by position, so a duplicated name keeps its own data
                // (br-frankenpandas-5ihhi).
                let columns: Vec<&Column> = (0..col_names.len())
                    .filter_map(|position| self.inner.column_at(position))
                    .collect();
                let mut data_rows = Vec::with_capacity(n_rows);
                for row_idx in 0..n_rows {
                    let mut row_vals = Vec::with_capacity(columns.len());
                    for col in &columns {
                        row_vals.push(to_dict_cell(py, col, &col.values()[row_idx])?);
                    }
                    data_rows.push(PyList::new(py, row_vals)?);
                }
                out.set_item("data", PyList::new(py, data_rows)?)?;
                // 'tight' is 'split' and the axes' names, one per level (it
                // was refused).
                if orient == "tight" {
                    // The axis names, typed (fvsao.64).
                    let typed =
                        |names: Vec<Option<LabelName>>| -> PyResult<Vec<Option<Py<PyAny>>>> {
                            names
                                .iter()
                                .map(|name| axis_name_to_py(py, name.as_ref()))
                                .collect()
                        };
                    let index_names = typed(match self.inner.row_multiindex() {
                        Some(levels) => levels.names().to_vec(),
                        None => vec![self.inner.index().name().cloned()],
                    })?;
                    let column_names = typed(match self.inner.columns_multiindex() {
                        Some(levels) => levels.names().to_vec(),
                        None => vec![self.inner.columns_name().cloned()],
                    })?;
                    out.set_item("index_names", index_names)?;
                    out.set_item("column_names", column_names)?;
                }
                Ok(out.into_any().unbind())
            }
            other => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "orient '{other}' not understood"
            ))),
        }
    }

    /// Render the DataFrame as an HTML table (pandas `DataFrame.to_html`):
    /// `buf` (None returns the text), `columns`, `index`, and on the table
    /// tag `classes` (after 'dataframe'), `border` (1; 0 or False none) and
    /// `table_id`; the other keywords are refused at a non-default value
    /// (it took only `index`, anything else a TypeError;
    /// br-frankenpandas-jn2nd).
    #[pyo3(signature = (buf=None, columns=None, col_space=None, header=true, index=true, na_rep="NaN", formatters=None, float_format=None, sparsify=None, index_names=true, justify=None, max_rows=None, max_cols=None, show_dimensions=false, decimal=".", bold_rows=true, classes=None, escape=true, notebook=false, border=None, table_id=None, render_links=false, encoding=None))]
    #[allow(clippy::too_many_arguments, clippy::fn_params_excessive_bools)]
    fn to_html(
        &self,
        buf: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        col_space: Option<&Bound<'_, PyAny>>,
        header: bool,
        index: bool,
        na_rep: &str,
        formatters: Option<&Bound<'_, PyAny>>,
        float_format: Option<&Bound<'_, PyAny>>,
        sparsify: Option<&Bound<'_, PyAny>>,
        index_names: bool,
        justify: Option<&str>,
        max_rows: Option<usize>,
        max_cols: Option<usize>,
        show_dimensions: bool,
        decimal: &str,
        bold_rows: bool,
        classes: Option<&Bound<'_, PyAny>>,
        escape: bool,
        notebook: bool,
        border: Option<&Bound<'_, PyAny>>,
        table_id: Option<&str>,
        render_links: bool,
        encoding: Option<&str>,
    ) -> PyResult<Option<String>> {
        let unset = |value: Option<&Bound<'_, PyAny>>| value.is_none_or(|value| value.is_none());
        unsupported_params(
            "DataFrame.to_html",
            &[
                ("col_space", unset(col_space)),
                ("sparsify", unset(sparsify)),
                ("max_rows", max_rows.is_none()),
                ("max_cols", max_cols.is_none()),
                ("show_dimensions", !show_dimensions),
                ("notebook", !notebook),
                ("encoding", encoding.is_none()),
            ],
        )?;
        let frame = select_columns_arg(self.inner.clone(), columns)?;
        let flat = frame.row_multiindex().is_none() && frame.columns_multiindex().is_none();
        if !flat {
            // A MultiIndex frame keeps fp-frame's table, which reads none of
            // these (refused rather than ignored).
            unsupported_params(
                "DataFrame.to_html of a MultiIndex frame",
                &[
                    ("header", header),
                    ("na_rep", na_rep == "NaN"),
                    ("formatters", unset(formatters)),
                    ("float_format", unset(float_format)),
                    ("index_names", index_names),
                    ("justify", justify.is_none()),
                    ("decimal", decimal == "."),
                    ("bold_rows", bold_rows),
                    ("escape", escape),
                    ("render_links", !render_links),
                ],
            )?;
        }
        let classes = match classes.filter(|classes| !classes.is_none()) {
            None => String::new(),
            Some(one) if one.is_instance_of::<pyo3::types::PyString>() => {
                format!(" {}", one.extract::<String>()?)
            }
            Some(many) => many
                .try_iter()?
                .map(|class| Ok(format!(" {}", class?.extract::<String>()?)))
                .collect::<PyResult<String>>()?,
        };
        let border = match border.filter(|border| !border.is_none()) {
            None => String::from(" border=\"1\""),
            Some(flag) if flag.is_instance_of::<pyo3::types::PyBool>() => {
                if flag.is_truthy()? {
                    String::from(" border=\"1\"")
                } else {
                    String::new()
                }
            }
            Some(width) => match width.extract::<i64>()? {
                0 => String::new(),
                width => format!(" border=\"{width}\""),
            },
        };
        let id = table_id
            .map(|id| format!(" id=\"{id}\""))
            .unwrap_or_default();
        let tag = format!("<table{border} class=\"dataframe{classes}\"{id}>");
        let html = if flat {
            let text = TextKeywords {
                col_space: None,
                header: None,
                formatters,
                float_format,
                na_rep,
                decimal,
                justify: None,
                index_names,
                sparsify: None,
            };
            let html = HtmlLayout {
                index,
                header,
                index_names,
                bold_rows,
                escape,
                render_links,
                justify: justify.unwrap_or("right"),
            };
            Python::attach(|py| pandas_html(py, &frame, &tag, &text, &html))?
        } else {
            frame
                .to_html(index)
                .replacen("<table border=\"1\" class=\"dataframe\">", &tag, 1)
        };
        write_text_target(buf, html, false)
    }

    /// Render the DataFrame as a GitHub-flavored Markdown table
    /// (pandas `DataFrame.to_markdown`). pandas passes `**kwargs` to
    /// tabulate, which frankenpandas does not use, so they are refused.
    #[pyo3(signature = (buf=None, mode="wt", index=true, storage_options=None, **kwargs))]
    fn to_markdown(
        &self,
        buf: Option<&Bound<'_, PyAny>>,
        mode: &str,
        index: bool,
        storage_options: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Option<String>> {
        unsupported_params(
            "DataFrame.to_markdown",
            &[
                ("mode", matches!(mode, "w" | "wt" | "a" | "at")),
                ("storage_options", storage_options.is_none()),
            ],
        )?;
        engine_kwargs("DataFrame.to_markdown", "tabulate", kwargs)?;
        let text = self
            .inner
            .to_markdown(index, None)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        write_text_target(buf, text, mode.starts_with('a'))
    }

    /// pandas' `DataFrame.to_string`: the repr's layout (see
    /// [`pandas_frame_text`]) over `columns`, every row unless
    /// `max_rows`/`min_rows` truncate and every column unless `max_cols`
    /// does, cells cut to `max_colwidth`, blocks of `line_width`, the
    /// dimensions line per `show_dimensions` (True, False or "truncate"),
    /// the header / formatters / float_format / na_rep / decimal / col_space
    /// / justify / index_names / sparsify as pandas reads them
    /// ([`TextKeywords::style`]), written to `buf` (in `encoding`) or
    /// returned. It printed a different table (no index names, its own float
    /// widths) and took only `index` (fvsao.34); then every other keyword
    /// but the row limits raised TypeError (xn05q).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (buf=None, columns=None, col_space=None, header=None, index=true, na_rep="NaN", formatters=None, float_format=None, sparsify=None, index_names=true, justify=None, max_rows=None, max_cols=None, show_dimensions=None, decimal=".", line_width=None, min_rows=None, max_colwidth=None, encoding=None))]
    fn to_string(
        &self,
        py: Python<'_>,
        buf: Option<&Bound<'_, PyAny>>,
        columns: Option<Vec<String>>,
        col_space: Option<&Bound<'_, PyAny>>,
        header: Option<&Bound<'_, PyAny>>,
        index: bool,
        na_rep: &str,
        formatters: Option<&Bound<'_, PyAny>>,
        float_format: Option<&Bound<'_, PyAny>>,
        sparsify: Option<bool>,
        index_names: bool,
        justify: Option<&str>,
        max_rows: Option<usize>,
        max_cols: Option<usize>,
        show_dimensions: Option<&Bound<'_, PyAny>>,
        decimal: &str,
        line_width: Option<usize>,
        min_rows: Option<usize>,
        max_colwidth: Option<usize>,
        encoding: Option<&str>,
    ) -> PyResult<Option<String>> {
        let show_dimensions = match show_dimensions {
            None => Some(false),
            Some(value)
                if value
                    .extract::<String>()
                    .is_ok_and(|text| text == "truncate") =>
            {
                None
            }
            Some(value) => Some(value.is_truthy()?),
        };
        let frame = match &columns {
            Some(columns) => {
                let names: Vec<&str> = columns.iter().map(String::as_str).collect();
                self.inner
                    .select_columns(&names)
                    .map_err(frame_error_to_py)?
            }
            None => self.inner.clone(),
        };
        let limits = RowLimits {
            max_rows,
            min_rows,
            max_colwidth,
            wrap_width: line_width,
        };
        let (rows, _) = limits.shown(frame.shape().0);
        let style = TextKeywords {
            col_space,
            header,
            formatters,
            float_format,
            na_rep,
            decimal,
            justify,
            index_names,
            sparsify,
        }
        .style(py, &frame, &rows, index)?;
        let layout = match max_cols {
            Some(count) if count > 0 => ColumnLayout::Max(count),
            _ => ColumnLayout::All,
        };
        let text = pandas_frame_text(&frame, limits, index, show_dimensions, layout, &style);
        write_encoded_text(py, buf, text, encoding)
    }

    /// pandas' `DataFrame.style`: a new Styler over this frame - a property,
    /// as pandas' (it was a method; br-frankenpandas-qoltt).
    #[getter]
    fn style(slf: &Bound<'_, Self>) -> PyResult<PyStyler> {
        PyStyler::for_frame(slf.as_any())
    }

    /// pandas' `df.set_index(keys, *, drop=True, append=False, inplace=False,
    /// verify_integrity=False)`; `append=True` puts the old index's levels
    /// before the keys in a MultiIndex.
    #[pyo3(signature = (keys, drop=true, append=false, inplace=false, verify_integrity=false))]
    fn set_index(
        &mut self,
        py: Python<'_>,
        keys: &Bound<'_, PyAny>,
        drop: bool,
        append: bool,
        inplace: bool,
        verify_integrity: bool,
    ) -> PyResult<Option<PyDataFrame>> {
        // An array key (a Series, an Index, a numpy array) is the new index
        // itself, named after it; `drop` concerns columns only. It raised
        // "keys must be a column name" (fvsao.66: set_index(s.dt.date)).
        if !append
            && keys
                .getattr("ndim")
                .and_then(|ndim| ndim.extract::<usize>())
                .is_ok_and(|ndim| ndim == 1)
        {
            let index = index_from_axis_value(keys)?;
            if index.len() != self.inner.len() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Length mismatch: Expected {} rows, received array of length {}",
                    self.inner.len(),
                    index.len()
                )));
            }
            let res = self.inner.with_index(index).map_err(frame_error_to_py)?;
            return self.finish_set_index(py, res, inplace, verify_integrity);
        }
        // A full tuple, or a list holding them, names MultiIndex columns (a
        // tuple was read as two names; 7m8bq).
        let tupled = self.inner.columns_multiindex().is_some()
            && (keys.is_instance_of::<PyTuple>()
                || keys
                    .cast::<PyList>()
                    .is_ok_and(|list| list.iter().any(|item| item.is_instance_of::<PyTuple>())));
        let resolved = match self.sort_key_names(keys).filter(|_| tupled) {
            Some(names) => PyList::new(py, names)?.into_any(),
            None => keys.clone(),
        };
        let keys = &column_arg(py, &self.inner, resolved)?;
        // A typed label (or list with one) labelling no column is pandas'
        // KeyError too.
        let label_list = keys.cast::<PyList>().is_ok_and(|list| {
            list.iter().all(|item| {
                item.is_instance_of::<pyo3::types::PyString>()
                    || typed_column_label(&item).is_some()
            })
        });
        if keys.extract::<String>().is_err()
            && keys.extract::<Vec<String>>().is_err()
            && (typed_column_label(keys).is_some() || label_list)
        {
            let shown = if keys.is_instance_of::<PyList>() {
                keys.repr()?.to_string()
            } else {
                PyList::new(py, [keys])?.repr()?.to_string()
            };
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                "None of {shown} are in the columns"
            )));
        }
        // pandas' KeyError for keys that are not columns (it was ValueError).
        let wanted: Vec<String> = match keys.extract::<String>() {
            Ok(single) => vec![single],
            Err(_) => keys.extract::<Vec<String>>().unwrap_or_default(),
        };
        let missing: Vec<&String> = wanted
            .iter()
            .filter(|key| self.inner.column(key).is_none())
            .collect();
        if !missing.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                "None of {} are in the columns",
                PyList::new(py, missing)?.repr()?
            )));
        }
        let res = if append {
            let list = match keys.extract::<String>() {
                Ok(single) => vec![single],
                Err(_) => keys.extract::<Vec<String>>().map_err(|_| {
                    PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "keys must be a column name or list of column names",
                    )
                })?,
            };
            let refs: Vec<&str> = list.iter().map(String::as_str).collect();
            self.inner
                .set_index_append(&refs, drop, "/")
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
        } else if let Ok(single) = keys.extract::<String>() {
            self.inner
                .set_index(&single, drop)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
        } else if let Ok(list) = keys.extract::<Vec<String>>() {
            // One key in a list is pandas' flat Index named after it (it was
            // a one-level MultiIndex, unnamed).
            if let [single] = list.as_slice() {
                self.inner
                    .set_index(single, drop)
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
            } else {
                let refs: Vec<&str> = list.iter().map(String::as_str).collect();
                self.inner
                    .set_index_multi(&refs, drop, "/")
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
            }
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "keys must be a column name or list of column names",
            ));
        };
        self.finish_set_index(py, res, inplace, verify_integrity)
    }

    /// pandas' `DataFrame.isin(values)`: a dict per column (a column it
    /// does not name False); a Series aligned on the rows and a DataFrame
    /// on the rows and columns - `eq` of it reindexed like this frame, a
    /// duplicate axis pandas' ValueError; any other list-like the values
    /// sought in every cell, anything else pandas' TypeError. A Series was
    /// read as values, and a DataFrame, a set, an ndarray and an Index were
    /// refused (br-frankenpandas-9nmry).
    fn isin(slf: &Bound<'_, Self>, values: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        let py = slf.py();
        let this = slf.borrow();
        let series = values.extract::<PyRef<'_, PySeries>>().is_ok();
        if series || values.extract::<PyRef<'_, PyDataFrame>>().is_ok() {
            let unique = |axis: &str| -> PyResult<bool> {
                values
                    .getattr(axis)?
                    .getattr("is_unique")?
                    .extract::<bool>()
            };
            if !unique("index")? || (!series && !unique("columns")?) {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "cannot compute isin with a duplicate axis.",
                ));
            }
            let like = values.call_method1("reindex_like", (slf,))?;
            let kwargs = PyDict::new(py);
            if series {
                kwargs.set_item("axis", "index")?;
            }
            let found = slf.call_method("eq", (like,), Some(&kwargs))?;
            return Ok(PyDataFrame {
                inner: found.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone(),
            });
        }
        if let Ok(dict) = values.cast::<PyDict>() {
            let mut map: BTreeMap<String, Vec<Scalar>> = BTreeMap::new();
            for (k, v) in column_dict_arg(&this.inner, dict)?.iter() {
                let col_name = k.extract::<String>()?;
                let mut scs = Vec::new();
                // A date needle is an object cell (it raised; fvsao.67).
                if let Ok(list) = v.cast::<PyList>() {
                    for item in list.iter() {
                        scs.push(py_to_cell(py, &item)?);
                    }
                } else if let Ok(tuple) = v.cast::<pyo3::types::PyTuple>() {
                    for item in tuple.iter() {
                        scs.push(py_to_cell(py, &item)?);
                    }
                } else if let Ok(s) = v.extract::<PyRef<'_, PySeries>>() {
                    scs.extend(s.inner.values().iter().cloned());
                } else {
                    scs.push(py_to_scalar(py, &v)?);
                }
                map.insert(col_name, scs);
            }
            let res = this
                .inner
                .isin_dict(&map)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            // pandas rebuilds the columns: their labels, never a RangeIndex.
            return Ok(PyDataFrame {
                inner: res.with_typed_labels_of(&this.inner),
            });
        }
        let items = if values.is_instance_of::<pyo3::types::PyString>() {
            None
        } else {
            values.try_iter().ok()
        };
        let Some(items) = items else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "only list-like or dict-like objects are allowed to be passed to DataFrame.isin(), you passed a '{}'",
                values.get_type().name()?
            )));
        };
        let scs = items
            .map(|item| py_to_cell(py, &item?))
            .collect::<PyResult<Vec<_>>>()?;
        let res = this
            .inner
            .isin(&scs)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDataFrame { inner: res })
    }

    /// Return the first n rows ordered by columns in descending order.
    #[pyo3(signature = (n, columns, keep="first"))]
    fn nlargest(&self, n: usize, columns: &Bound<'_, PyAny>, keep: &str) -> PyResult<PyDataFrame> {
        // A tuple names its MultiIndex column (g3bux).
        let cols = match self.sort_key_names(columns) {
            Some(names) => names,
            None => extract_col_names_flexible(Some(columns))?,
        };
        if cols.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "columns cannot be empty",
            ));
        }
        self.refuse_n_method(&cols, "nlargest")?;
        if cols.len() == 1 {
            let col = &cols[0];
            let res = match keep {
                "first" => self.inner.nlargest(n, col),
                _ => self.inner.nlargest_keep(n, col, keep),
            }
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            return Ok(PyDataFrame { inner: res });
        }
        let refs: Vec<&str> = cols.iter().map(String::as_str).collect();
        let res = self
            .inner
            .nlargest_multi(n, &refs)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDataFrame { inner: res })
    }

    /// Return the first n rows ordered by columns in ascending order.
    #[pyo3(signature = (n, columns, keep="first"))]
    fn nsmallest(&self, n: usize, columns: &Bound<'_, PyAny>, keep: &str) -> PyResult<PyDataFrame> {
        // A tuple names its MultiIndex column (g3bux).
        let cols = match self.sort_key_names(columns) {
            Some(names) => names,
            None => extract_col_names_flexible(Some(columns))?,
        };
        if cols.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "columns cannot be empty",
            ));
        }
        self.refuse_n_method(&cols, "nsmallest")?;
        if cols.len() == 1 {
            let col = &cols[0];
            let res = match keep {
                "first" => self.inner.nsmallest(n, col),
                _ => self.inner.nsmallest_keep(n, col, keep),
            }
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            return Ok(PyDataFrame { inner: res });
        }
        let refs: Vec<&str> = cols.iter().map(String::as_str).collect();
        let res = self
            .inner
            .nsmallest_multi(n, &refs)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PyDataFrame { inner: res })
    }

    /// Return index of first occurrence of maximum over requested axis.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn idxmax(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let result = if ax == 1
            && let Some(levels) = self.inner.columns_multiindex()
        {
            self.tuple_idx_extreme(levels, true, skipna, numeric_only)?
        } else {
            wrap_series(self.inner.idxmax_ext(ax, skipna, numeric_only))?
        };
        warned_idx_extremes(result, "idxmax")
    }

    /// Return index of first occurrence of minimum over requested axis.
    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn idxmin(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let result = if ax == 1
            && let Some(levels) = self.inner.columns_multiindex()
        {
            self.tuple_idx_extreme(levels, false, skipna, numeric_only)?
        } else {
            wrap_series(self.inner.idxmin_ext(ax, skipna, numeric_only))?
        };
        warned_idx_extremes(result, "idxmin")
    }

    /// First discrete difference of element.
    #[pyo3(signature = (periods=1, axis=None))]
    fn diff(&self, periods: i64, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let res = match ax {
            0 => self.inner.diff(periods).map_err(frame_error_to_py)?,
            1 => self.inner.diff_axis1(periods).map_err(frame_error_to_py)?,
            other => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {other} for object type DataFrame"
                )));
            }
        };
        Ok(PyDataFrame { inner: res })
    }

    /// Percentage change between the current and a prior element.
    ///
    /// Default fill_method is 'pad' like pandas 2.2.3; `fill_method=None`
    /// disables the forward fill.
    #[pyo3(signature = (periods=1, fill_method=Passed(None), limit=Passed(None), freq=None, axis=None))]
    fn pct_change(
        &self,
        py: Python<'_>,
        periods: i64,
        fill_method: Passed<'_>,
        limit: Passed<'_>,
        freq: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.pct_change",
            &[("freq", freq.is_none() || ax == 0)],
        )?;
        let columns: Vec<&Column> = (0..self.inner.num_columns())
            .filter_map(|position| self.inner.column_at(position))
            .collect();
        let (fill_method, limit) =
            pct_change_fill_args(py, "DataFrame", &fill_method, &limit, &columns)?;
        if let Some(freq) = freq {
            let data = Bound::new(
                py,
                PyDataFrame {
                    inner: self.inner.clone(),
                },
            )?;
            let changes =
                pct_change_by_freq(data.as_any(), periods, freq, fill_method.as_deref(), limit)?;
            return Ok(PyDataFrame {
                inner: changes.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone(),
            });
        }
        let res = match ax {
            0 => self
                .inner
                .pct_change_with_fill(periods, fill_method.as_deref(), limit)
                .map_err(frame_error_to_py)?,
            1 => self
                .inner
                .pct_change_axis1(periods)
                .map_err(frame_error_to_py)?,
            other => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {other} for object type DataFrame"
                )));
            }
        };
        Ok(PyDataFrame { inner: res })
    }

