    /// pandas' `shift(periods=1, freq=None, axis=0, fill_value=None,
    /// suffix=None)`: an int is [`Self::shift_by`]; a list of ints the frame
    /// of the shifts, as pandas 2.1's (see [`shifts_frame`]; it was a
    /// TypeError; br-frankenpandas-ox034).
    #[pyo3(signature = (periods=None, freq=None, axis=None, fill_value=None, suffix=None))]
    fn shift<'py>(
        slf: &Bound<'py, Self>,
        periods: Option<&Bound<'py, PyAny>>,
        freq: Option<&str>,
        axis: Option<&Bound<'py, PyAny>>,
        fill_value: Option<&Bound<'py, PyAny>>,
        suffix: Option<&str>,
    ) -> PyResult<Py<PyAny>> {
        match ShiftPeriods::of(periods)? {
            ShiftPeriods::One(periods) => slf
                .borrow()
                .shift_by(periods, freq, axis, fill_value, suffix)?
                .into_py_any(slf.py()),
            ShiftPeriods::Many(periods) => {
                shifts_frame(slf.as_any(), periods, freq, axis, fill_value, suffix)
            }
        }
    }

    /// Assign new columns to a DataFrame, returning a new object (pandas `DataFrame.assign`).
    #[pyo3(signature = (**kwargs))]
    fn assign(&self, py: Python<'_>, kwargs: Option<&Bound<'_, PyDict>>) -> PyResult<PyDataFrame> {
        let mut df = self.inner.clone();
        if let Some(kwargs) = kwargs {
            for (key, val) in kwargs.iter() {
                let name = key.extract::<String>()?;
                let col = if val.is_callable() {
                    let py_df = Py::new(py, PyDataFrame { inner: df.clone() })?;
                    let res = val.call1((py_df,))?;
                    py_value_to_column(py, &res, df.len())?
                } else {
                    py_value_to_column(py, &val, df.len())?
                };
                df = df
                    .with_column(name, col)
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            }
        }
        Ok(PyDataFrame { inner: df })
    }

    /// Query the columns of a DataFrame with a boolean expression; pandas'
    /// `inplace=True` replaces the frame and returns None
    /// (br-frankenpandas-n57tz).
    /// `@name` references resolve as pandas' (see [`resolve_expr_locals`]);
    /// every engine / parser pandas takes gives the same rows here.
    /// Expressions must be trusted input: the Python fallback can call methods
    /// and builtins with side effects. Engine/parser selection is not a sandbox.
    #[pyo3(signature = (expr, inplace=false, local_dict=None, global_dict=None, level=0, engine=None, parser=None))]
    #[allow(clippy::too_many_arguments)]
    fn query(
        &mut self,
        py: Python<'_>,
        expr: &str,
        inplace: bool,
        local_dict: Option<&Bound<'_, PyDict>>,
        global_dict: Option<&Bound<'_, PyDict>>,
        level: usize,
        engine: Option<&str>,
        parser: Option<&str>,
    ) -> PyResult<Option<PyDataFrame>> {
        let _ = (engine, parser);
        let raw = expr;
        let (expr, locals) = resolve_expr_locals(py, raw, local_dict, global_dict, level)?;
        // Index level names resolve as pandas' query resolves them (they
        // raised 'unknown series reference'; rvqoi): each named level no
        // column shadows rides as a column while the expression runs.
        let levels = self.index_level_columns(&expr)?;
        let attempt = if levels.is_empty() {
            self.inner.query_with_locals(&expr, &locals)
        } else {
            let mut frame = self.inner.clone();
            for (name, column) in levels {
                frame = frame.with_column(name, column).map_err(frame_error_to_py)?;
            }
            let kept: Vec<&str> = self
                .inner
                .column_names()
                .into_iter()
                .map(String::as_str)
                .collect();
            frame
                .query_with_locals(&expr, &locals)
                .and_then(|res| res.select_columns(&kept).map_err(Into::into))
        };
        let res = match attempt {
            Ok(res) => res,
            // What fp-expr's grammar cannot parse (an accessor, a method
            // chain) runs as pandas' python engine runs it, the rows its
            // mask selects by loc (br-frankenpandas-sa6lb).
            Err(fp_expr::ExprError::ParseError(_)) => {
                let mask =
                    python_engine_eval(py, &self.inner, raw, local_dict, global_dict, level)?;
                let frame = Py::new(
                    py,
                    PyDataFrame {
                        inner: self.inner.clone(),
                    },
                )?
                .into_bound(py);
                let selected = frame.getattr("loc")?.get_item(mask)?;
                selected.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone()
            }
            Err(e) => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    e.to_string(),
                ));
            }
        };
        if inplace {
            self.inner = res;
            return Ok(None);
        }
        Ok(Some(PyDataFrame { inner: res }))
    }

    /// Evaluate a string describing operations on DataFrame columns. With
    /// pandas' `inplace=True` an assignment (`c = a + b`) adds the column to
    /// this frame and returns None; without one it is pandas' ValueError
    /// (br-frankenpandas-n57tz).
    /// Expressions must be trusted input: the Python fallback can call methods
    /// and builtins with side effects. Engine/parser selection is not a sandbox.
    #[pyo3(signature = (expr, inplace=false, local_dict=None, global_dict=None, level=0, engine=None, parser=None))]
    #[allow(clippy::too_many_arguments)]
    fn eval(
        &mut self,
        py: Python<'_>,
        expr: &str,
        inplace: bool,
        local_dict: Option<&Bound<'_, PyDict>>,
        global_dict: Option<&Bound<'_, PyDict>>,
        level: usize,
        engine: Option<&str>,
        parser: Option<&str>,
    ) -> PyResult<Py<PyAny>> {
        let _ = (engine, parser);
        let raw = expr;
        let (expr, locals) = resolve_expr_locals(py, raw, local_dict, global_dict, level)?;
        let expr = expr.as_str();
        // A constant's division by zero is Python's ZeroDivisionError, as
        // pandas folds it (br-frankenpandas-2blaf).
        let value_error = |e: fp_expr::ExprError| match e {
            fp_expr::ExprError::ZeroDivision(message) => {
                PyErr::new::<pyo3::exceptions::PyZeroDivisionError, _>(message)
            }
            e => PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()),
        };
        // pandas runs each non-blank line in order, a later line seeing the
        // columns an earlier one assigned; several lines must all assign
        // (a multi-line eval was one parse error; br-frankenpandas-c5b7x).
        let lines = |text: &'_ str| -> Vec<Option<(String, String)>> {
            text.lines()
                .map(str::trim)
                .filter(|line| !line.is_empty())
                .map(|line| {
                    eval_assignment_parts(line)
                        .map(|(target, rhs)| (target.to_owned(), rhs.to_owned()))
                })
                .collect()
        };
        let assignments = lines(expr);
        if assignments.len() > 1 && assignments.iter().any(Option::is_none) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Multi-line expressions are only valid if all expressions contain an assignment",
            ));
        }
        if !assignments.is_empty() && assignments.iter().all(Option::is_some) {
            // The same lines as written, for the python engine (fp-expr reads
            // the ones with their @locals resolved).
            let raw_assignments = lines(raw);
            let mut new_df = self.inner.clone();
            for (position, (target, rhs)) in assignments.into_iter().flatten().enumerate() {
                let column = match new_df.eval_with_locals(&rhs, &locals) {
                    Ok(evaluated) => evaluated.column().clone(),
                    // What fp-expr cannot parse runs as pandas' python
                    // engine runs it (br-frankenpandas-sa6lb).
                    Err(fp_expr::ExprError::ParseError(_)) => {
                        let raw_rhs = raw_assignments
                            .get(position)
                            .cloned()
                            .flatten()
                            .map_or(rhs, |(_, rhs)| rhs);
                        let value = python_engine_eval(
                            py,
                            &new_df,
                            &raw_rhs,
                            local_dict,
                            global_dict,
                            level,
                        )?;
                        py_value_to_column(py, &value, new_df.len())?
                    }
                    Err(e) => return Err(value_error(e)),
                };
                new_df = new_df
                    .with_column(target, column)
                    .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            }
            if inplace {
                self.inner = new_df;
                return Ok(py.None());
            }
            return Ok(Py::new(py, PyDataFrame { inner: new_df })?.into_any());
        }
        if inplace {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "Cannot operate inplace if there is no assignment",
            ));
        }
        // An expression naming no column is pandas' one value, computed once
        // (it was broadcast to every row; br-frankenpandas-2blaf).
        match self.inner.eval_value_with_locals(expr, &locals) {
            Ok(fp_expr::EvalValue::Series(evaluated)) => {
                Ok(Py::new(py, PySeries { inner: *evaluated })?.into_any())
            }
            Ok(fp_expr::EvalValue::Scalar(value)) => scalar_to_py(py, &value),
            Err(fp_expr::ExprError::ParseError(_)) => {
                Ok(
                    python_engine_eval(py, &self.inner, raw, local_dict, global_dict, level)?
                        .unbind(),
                )
            }
            Err(e) => Err(value_error(e)),
        }
    }

    /// pandas' `rolling(...)` ([`rolling_of`]): a row count, or a time-based
    /// window over the datetime index or the `on` column (it was refused).
    #[pyo3(signature = (
        window,
        min_periods=None,
        center=false,
        win_type=None,
        on=None,
        axis=Passed(None),
        closed=None,
        step=None,
        method="single"
    ))]
    #[allow(clippy::too_many_arguments)]
    fn rolling(
        &self,
        py: Python<'_>,
        window: &Bound<'_, PyAny>,
        min_periods: Option<usize>,
        center: bool,
        win_type: Option<&Bound<'_, PyAny>>,
        on: Option<&str>,
        axis: Passed<'_>,
        closed: Option<&str>,
        step: Option<&Bound<'_, PyAny>>,
        method: &str,
    ) -> PyResult<Py<PyAny>> {
        if let Some(win_type) = win_type.filter(|win_type| !win_type.is_none()) {
            return window_of(
                py,
                None,
                Some(self.inner.clone()),
                window,
                min_periods,
                center,
                win_type,
                on,
                &axis,
                closed,
                step,
                method,
            )?
            .into_py_any(py);
        }
        rolling_of(
            py,
            None,
            Some(self.inner.clone()),
            window,
            min_periods,
            center,
            on,
            &axis,
            closed,
            step,
            method,
        )?
        .into_py_any(py)
    }

