    #[pyo3(signature = (id_vars=None, value_vars=None, var_name=None, value_name=None, col_level=None, ignore_index=true))]
    fn melt(
        &self,
        id_vars: Option<&Bound<'_, PyAny>>,
        value_vars: Option<&Bound<'_, PyAny>>,
        var_name: Option<&str>,
        value_name: Option<&str>,
        col_level: Option<usize>,
        ignore_index: bool,
    ) -> PyResult<PyDataFrame> {
        // Columns are single-level, so level 0 is all of them.
        unsupported_params(
            "DataFrame.melt",
            &[("col_level", col_level.is_none_or(|l| l == 0))],
        )?;
        let id_strings = extract_col_names_flexible(id_vars)?;
        let val_strings = extract_col_names_flexible(value_vars)?;
        let id_refs: Vec<&str> = id_strings.iter().map(String::as_str).collect();
        let val_refs: Vec<&str> = val_strings.iter().map(String::as_str).collect();
        let mut res = self
            .inner
            .melt(&id_refs, &val_refs, var_name, value_name)
            .map_err(frame_error_to_py)?;
        if !ignore_index {
            let n_rows = self.inner.index().len();
            let actual_value_vars_len = if val_strings.is_empty() {
                self.inner
                    .column_names()
                    .into_iter()
                    .filter(|c| !id_strings.contains(c))
                    .count()
            } else {
                val_strings.len()
            };
            if actual_value_vars_len > 0 && n_rows > 0 {
                let orig_labels = self.inner.index().labels();
                let mut repeated_labels = Vec::with_capacity(n_rows * actual_value_vars_len);
                for _ in 0..actual_value_vars_len {
                    repeated_labels.extend(orig_labels.iter().cloned());
                }
                let cols = res.columns().clone();
                let order = res
                    .column_names()
                    .into_iter()
                    .cloned()
                    .collect::<Vec<String>>();
                res = DataFrame::new_with_column_order(Index::new(repeated_labels), cols, order)
                    .map_err(frame_error_to_py)?;
            }
        }
        // Every column of MultiIndex columns melted: a column per level -
        // named as it, else variable_<i> - in place of the one 'variable'
        // of flat keys, as pandas (7m8bq).
        if let Some(multi) = self.inner.columns_multiindex()
            && id_strings.is_empty()
            && val_strings.is_empty()
            && var_name.is_none()
        {
            let rows = self.inner.len();
            let value_label = value_name.unwrap_or("value");
            let value = res.column(value_label).cloned().ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyKeyError, _>(value_label.to_owned())
            })?;
            let mut columns = std::collections::BTreeMap::new();
            let mut order = Vec::with_capacity(multi.nlevels() + 1);
            // Each variable column is labelled by its level's typed name
            // (fvsao.64), else `variable_i`.
            let mut labels = Vec::with_capacity(multi.nlevels());
            for level in 0..multi.nlevels() {
                let label = multi.names().get(level).cloned().flatten().map_or_else(
                    || IndexLabel::Utf8(format!("variable_{level}")),
                    |name| name.label(),
                );
                let name = fp_frame::column_key(&label);
                labels.push(label);
                let values: Vec<Scalar> = (0..multi.len())
                    .flat_map(|column| {
                        let label = multi
                            .get_tuple(column)
                            .and_then(|tuple| tuple.get(level).map(|label| (*label).clone()))
                            .unwrap_or_else(|| IndexLabel::Utf8(String::new()));
                        std::iter::repeat_n(index_label_to_scalar(&label), rows)
                    })
                    .collect();
                columns.insert(
                    name.clone(),
                    Column::from_values(values).map_err(column_error_to_py)?,
                );
                order.push(name);
            }
            columns.insert(value_label.to_owned(), value);
            order.push(value_label.to_owned());
            res = DataFrame::new_with_column_order(res.index().clone(), columns, order)
                .map_err(frame_error_to_py)?
                .with_recorded_column_labels(labels);
        }
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (columns=None, index=None, values=None))]
    fn pivot(
        &self,
        py: Python<'_>,
        columns: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        values: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let col_name = match columns {
            Some(c) if !c.is_none() => extract_single_col_name(c)?,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "DataFrame.pivot() missing 1 required argument: 'columns'",
                ));
            }
        };

        // values= a list, or left out: each value column pivots, side by
        // side under a (value, label) column MultiIndex, as pandas' unstack
        // of the frame indexed by index / columns (it kept the first column
        // and dropped the rest). One label (a tuple is one) stays flat.
        let listed = values.is_none_or(|values| {
            values.is_none() || (is_list_like_impl(values) && !values.is_instance_of::<PyTuple>())
        });
        if listed {
            let skip = match index {
                Some(index) if !index.is_none() => extract_col_names_flexible(Some(index))?,
                _ => Vec::new(),
            };
            let names: Vec<String> = match values {
                Some(values) if !values.is_none() => extract_col_names_flexible(Some(values))?,
                _ => self
                    .inner
                    .column_names()
                    .into_iter()
                    .filter(|name| **name != col_name && !skip.contains(name))
                    .cloned()
                    .collect(),
            };
            if !names.is_empty() {
                let mut pieces = Vec::with_capacity(names.len());
                let mut keys = Vec::with_capacity(names.len());
                for name in &names {
                    let value = pyo3::types::PyString::new(py, name).into_any();
                    pieces.push(self.pivot(py, columns, index, Some(&value))?);
                    keys.push(index_label_to_py(py, &self.inner.column_label(name))?);
                }
                let side_by_side = concat(
                    py,
                    PyList::new(py, pieces)?.as_any(),
                    Some(&1_i64.into_bound_py_any(py)?),
                    "outer",
                    false,
                    Some(PyList::new(py, keys)?.as_any()),
                    false,
                    None,
                    None,
                )?;
                let mut out = side_by_side
                    .bind(py)
                    .extract::<PyRef<'_, PyDataFrame>>()?
                    .clone();
                // pandas pivots the value columns as one 2-D array: differing
                // dtypes share numpy's common one - ints beside floats
                // float64, any other mix object (a float and a bool value
                // column kept their own dtypes).
                let dtypes: Vec<DType> = names
                    .iter()
                    .filter_map(|name| self.inner.column(name).map(Column::dtype))
                    .collect();
                if dtypes.windows(2).any(|pair| pair[0] != pair[1]) {
                    let numbers = dtypes
                        .iter()
                        .all(|dtype| matches!(dtype, DType::Int64 | DType::Float64));
                    for position in 0..out.inner.num_columns() {
                        let Some(column) = out.inner.column_at(position) else {
                            continue;
                        };
                        let column = if numbers {
                            column.astype(DType::Float64).map_err(column_error_to_py)?
                        } else {
                            Column::from_object_values(column.values().to_vec())
                        };
                        out.inner = out
                            .inner
                            .isetitem(position, column)
                            .map_err(frame_error_to_py)?;
                    }
                }
                return Ok(out);
            }
        }

        let val_names = extract_col_names_flexible(values)?;
        let val_name = if !val_names.is_empty() {
            val_names[0].clone()
        } else {
            let skip_index = match index {
                Some(idx_obj) if !idx_obj.is_none() => extract_col_names_flexible(Some(idx_obj))?,
                _ => Vec::new(),
            };
            let candidate = self
                .inner
                .column_names()
                .into_iter()
                .find(|c| *c != &col_name && !skip_index.contains(c));
            match candidate {
                Some(c) => c.clone(),
                None => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "No valid column found to pivot for values",
                    ));
                }
            }
        };

        // The result's columns are the `columns` column's values, typed, and
        // named after it.
        let value_dtype = self.inner.column(&col_name).map(Column::dtype);
        // A cell column no row fills is all NaN in the values' numpy dtype:
        // float64 for numbers (it was inferred object).
        let numeric_values = self
            .inner
            .column(&val_name)
            .is_some_and(|c| matches!(c.dtype(), DType::Int64 | DType::Float64));
        let labelled = |res: DataFrame| -> PyResult<PyDataFrame> {
            let mut res = res;
            if numeric_values {
                for position in 0..res.num_columns() {
                    if let Some(column) = res.column_at(position)
                        && column.dtype() == DType::Null
                    {
                        let column = column.astype(DType::Float64).map_err(column_error_to_py)?;
                        res = res.isetitem(position, column).map_err(frame_error_to_py)?;
                    }
                }
            }
            Ok(PyDataFrame {
                inner: match &value_dtype {
                    Some(dtype) => res.with_value_labels(dtype),
                    None => res,
                }
                .with_columns_name(Some(col_name.clone())),
            })
        };
        match index {
            Some(idx_obj) if !idx_obj.is_none() => {
                let idx_name = extract_single_col_name(idx_obj)?;
                let res = self
                    .inner
                    .pivot(&idx_name, &col_name, &val_name)
                    .map_err(frame_error_to_py)?;
                labelled(res)
            }
            _ => {
                let idx_scalars: Vec<Scalar> = self
                    .inner
                    .index()
                    .labels()
                    .iter()
                    .map(index_label_to_scalar)
                    .collect();
                let idx_col = Column::from_values(idx_scalars).map_err(column_error_to_py)?;
                let mut col_map = BTreeMap::new();
                for name in self.inner.column_names() {
                    let col = self
                        .inner
                        .column(name)
                        .ok_or_else(|| {
                            PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                                "column '{name}' not found"
                            ))
                        })?
                        .clone();
                    col_map.insert(name.clone(), col);
                }
                const PIVOT_TEMP_INDEX: &str = "__fp_pivot_idx__";
                col_map.insert(PIVOT_TEMP_INDEX.to_string(), idx_col);
                let mut col_order: Vec<String> =
                    self.inner.column_names().into_iter().cloned().collect();
                col_order.push(PIVOT_TEMP_INDEX.to_string());
                let df_tmp = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    col_order,
                )
                .map_err(frame_error_to_py)?;
                let res = df_tmp
                    .pivot(PIVOT_TEMP_INDEX, &col_name, &val_name)
                    .map_err(frame_error_to_py)?;
                labelled(res)
            }
        }
    }

    /// pandas' `pivot_table`, with `fill_value` filling the cells no row
    /// reached (it was refused as an unknown keyword;
    /// br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.13). Without
    /// `columns` (pandas' most common form, which required `columns`) it is
    /// the groupby aggregate of `values` (every other column when None) over
    /// `index`; `margins` adds pandas' `All` row (and `All` column), each
    /// aggregated from the original rows, not from the cells; a list of
    /// functions puts the function level first (fvsao.29). dropna=False and
    /// sort=False are not supported yet; `observed` only matters for
    /// categorical keys.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (values=None, index=None, columns=None, aggfunc=None, fill_value=None, margins=false, dropna=true, margins_name="All", observed=None, sort=true))]
    fn pivot_table<'py>(
        slf: &Bound<'py, Self>,
        values: Option<&Bound<'py, PyAny>>,
        index: Option<&Bound<'py, PyAny>>,
        columns: Option<&Bound<'py, PyAny>>,
        aggfunc: Option<&Bound<'py, PyAny>>,
        fill_value: Option<&Bound<'py, PyAny>>,
        margins: bool,
        dropna: bool,
        margins_name: &str,
        observed: Option<bool>,
        sort: bool,
    ) -> PyResult<Bound<'py, PyAny>> {
        let py = slf.py();
        // Array-like keys pivot a copy carrying them as columns; the table's
        // axes take the keys' names.
        let array_keys = pivot_array_keys(py, &slf.borrow().inner, index, columns)?;
        if let Some(keys) = array_keys {
            let frame = Bound::new(py, PyDataFrame { inner: keys.frame })?;
            let table = Self::pivot_table(
                &frame,
                values,
                keys.index.as_ref(),
                keys.columns.as_ref(),
                aggfunc,
                fill_value,
                margins,
                dropna,
                margins_name,
                observed,
                sort,
            )?;
            let Ok(result) = table.extract::<PyRef<'_, PyDataFrame>>() else {
                return Ok(table);
            };
            let inner = named_after_keys(&result.inner, &keys.renames)?;
            return Ok(Bound::new(py, PyDataFrame { inner })?.into_any());
        }
        let names = |spec: Option<&Bound<'py, PyAny>>| -> PyResult<Vec<String>> {
            match spec.filter(|spec| !spec.is_none()) {
                None => Ok(Vec::new()),
                // Typed labels name the columns carrying them (fvsao.32).
                Some(spec) => {
                    let spec = column_arg(py, &slf.borrow().inner, spec.clone())?;
                    match spec.extract::<String>() {
                        Ok(name) => Ok(vec![name]),
                        Err(_) => spec.extract::<Vec<String>>(),
                    }
                }
            }
        };
        let index_keys = names(index)?;
        let column_keys = names(columns)?;
        if index_keys.is_empty() {
            return Err(not_implemented("DataFrame.pivot_table without index"));
        }
        let mut value_names = names(values)?;
        // A key also named as a value (br-frankenpandas-o3w6t). pandas
        // narrows the frame to `keys + values` only when that list is shorter
        // than the frame: then the key column is held twice and groupby
        // refuses it (fp answered a table); otherwise it groups the whole
        // frame and the key is simply no value.
        if let Some(key) = index_keys
            .iter()
            .chain(&column_keys)
            .find(|key| value_names.contains(key))
        {
            let selected = index_keys.len() + column_keys.len() + value_names.len();
            if selected < slf.borrow().inner.num_columns() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Grouper for '{key}' not 1-dimensional"
                )));
            }
            value_names.retain(|name| !index_keys.contains(name) && !column_keys.contains(name));
            if value_names.is_empty() {
                // Nothing left to aggregate: pandas' table is the index keys'
                // groups with no columns (it indexed an empty value list).
                let keys = PyList::new(
                    py,
                    index_keys
                        .iter()
                        .map(|name| index_label_to_py(py, &slf.borrow().inner.column_label(name)))
                        .collect::<PyResult<Vec<_>>>()?,
                )?;
                let groups = slf
                    .as_any()
                    .get_item(&keys)?
                    .call_method0("drop_duplicates")?
                    .call_method1("set_index", (&keys,))?;
                return if sort {
                    groups.call_method0("sort_index")
                } else {
                    Ok(groups)
                };
            }
        }
        if value_names.is_empty() {
            value_names = slf
                .borrow()
                .inner
                .column_names()
                .into_iter()
                .filter(|name| !index_keys.contains(name) && !column_keys.contains(name))
                .cloned()
                .collect();
        }
        let default_func = pyo3::types::PyString::new(py, "mean").into_any();
        let aggfunc = aggfunc.filter(|f| !f.is_none()).unwrap_or(&default_func);
        // pandas sorts the value columns (sort=True, the default): values
        // ['z', 'a'] come out a, z - as do the frame's other columns when
        // `values` is omitted, and a dict aggfunc's keys. They kept the given
        // order.
        let sorted_funcs;
        let aggfunc = if sort {
            {
                let frame = &slf.borrow().inner;
                value_names.sort_by_cached_key(|name| frame.column_label(name));
            }
            match aggfunc.cast::<PyDict>() {
                Ok(funcs) => {
                    let mut items: Vec<(Bound<'py, PyAny>, Bound<'py, PyAny>)> =
                        funcs.iter().collect();
                    items.sort_by_cached_key(|(key, _)| py_to_index_label(key).ok());
                    sorted_funcs = PyDict::new(py);
                    for (key, func) in items {
                        sorted_funcs.set_item(key, func)?;
                    }
                    sorted_funcs.as_any()
                }
                Err(_) => aggfunc,
            }
        } else {
            aggfunc
        };
        let keyword = |key: &str, value: Bound<'py, PyAny>| -> PyResult<Bound<'py, PyDict>> {
            let kw = PyDict::new(py);
            kw.set_item(key, value)?;
            Ok(kw)
        };
        // A list of functions: one pivot per function, the function level first.
        if aggfunc.is_instance_of::<PyList>() || aggfunc.is_instance_of::<PyTuple>() {
            let funcs: Vec<Bound<'py, PyAny>> = aggfunc.try_iter()?.collect::<PyResult<_>>()?;
            let labels = funcs.iter().map(agg_label).collect::<PyResult<Vec<_>>>()?;
            let mut results = Vec::with_capacity(funcs.len());
            for func in &funcs {
                results.push(Self::pivot_table(
                    slf,
                    values,
                    index,
                    columns,
                    Some(func),
                    fill_value,
                    margins,
                    dropna,
                    margins_name,
                    observed,
                    sort,
                )?);
            }
            return concat_side_by_side(py, results, labels);
        }
        // The keys and values as their typed column labels (fvsao.32).
        let label_of = |name: &String| -> PyResult<Py<PyAny>> {
            index_label_to_py(py, &slf.borrow().inner.column_label(name))
        };
        let key_list = |keys: &[String]| -> PyResult<Bound<'py, PyAny>> {
            Ok(if keys.len() == 1 {
                label_of(&keys[0])?.into_bound(py)
            } else {
                PyList::new(py, keys.iter().map(label_of).collect::<PyResult<Vec<_>>>()?)?
                    .into_any()
            })
        };
        let values_list = PyList::new(
            py,
            value_names
                .iter()
                .map(label_of)
                .collect::<PyResult<Vec<_>>>()?,
        )?;
        // pandas' dropna=True: a row missing a key takes no part in the
        // table (it gave a row of NaN / zeros - crosstab's key whose only
        // co-key is NaN), and the margins drop a row missing any key or
        // value; dropna=False keeps every row (a missing key its own group;
        // it was refused).
        let rows_with_every = |names: &[&String]| -> PyResult<Bound<'py, PyAny>> {
            if !dropna {
                return Ok(slf.clone().into_any());
            }
            let frame = &slf.borrow().inner;
            let cells: Vec<&[Scalar]> = names
                .iter()
                .filter_map(|name| frame.column(name))
                .map(Column::values)
                .collect();
            let keep: Vec<usize> = (0..frame.len())
                .filter(|&row| cells.iter().all(|cells| !cells[row].is_missing()))
                .collect();
            if keep.len() == frame.len() {
                return Ok(slf.clone().into_any());
            }
            let kept = frame.take_rows(&keep).map_err(frame_error_to_py)?;
            Ok(Bound::new(py, PyDataFrame { inner: kept })?.into_any())
        };
        let key_names: Vec<&String> = index_keys.iter().chain(&column_keys).collect();
        let data = rows_with_every(&key_names)?;
        // pandas groups with observed=False when it is not given, and then
        // warns of its own when a key is a category; the groupby's warning
        // (it ran with observed unset) is not pandas' (cld41).
        if observed.is_none()
            && key_names.iter().any(|key| {
                slf.borrow()
                    .inner
                    .column(key)
                    .is_some_and(|column| column.categorical().is_some())
            })
        {
            PyErr::warn(
                py,
                &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
                c"The default value of observed=False is deprecated and will change to observed=True in a future version of pandas. Specify observed=False to silence this warning and retain the current behavior",
                1,
            )?;
        }
        let aggregate =
            |source: &Bound<'py, PyAny>, keys: &[String]| -> PyResult<Bound<'py, PyAny>> {
                let groupby_kwargs = PyDict::new(py);
                groupby_kwargs.set_item("sort", sort)?;
                groupby_kwargs.set_item("dropna", dropna)?;
                groupby_kwargs.set_item("observed", observed.unwrap_or(false))?;
                source
                    .call_method("groupby", (key_list(keys)?,), Some(&groupby_kwargs))?
                    .get_item(&values_list)?
                    .call_method1("agg", (aggfunc,))
            };
        // `values` as one name (not a list, not every other column): the
        // table's columns are the columns keys' values alone, no value level.
        let single_value = values.is_some_and(|values| {
            !values.is_none()
                && !(values.is_instance_of::<PyList>() || values.is_instance_of::<PyTuple>())
        });
        // A value column holding a missing value takes pandas' definition
        // below - a cell whose values are all missing is its aggregate of
        // nothing (sum 0, count 0), a row missing every aggregate dropped -
        // where the kernel read such a cell as no cell (NaN, the row kept;
        // br-frankenpandas-9nmry). With margins / sort=False, which the
        // definition refuses, it stays on the kernel.
        let values_missing = value_names
            .first()
            .and_then(|name| slf.borrow().inner.column(name).map(Column::has_any_missing))
            .unwrap_or(false);
        let simple = single_value
            && column_keys.len() == 1
            && index_keys.len() == 1
            && aggfunc.extract::<String>().is_ok()
            && dropna
            && !(values_missing && sort && !margins);
        let mut table = if column_keys.is_empty() {
            aggregate(&data, &index_keys)?
        } else if simple {
            let name = aggfunc.extract::<String>()?;
            let frame = data.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone();
            let mut res = frame
                .pivot_table(&value_names[0], &index_keys[0], &column_keys[0], &name)
                .map_err(frame_error_to_py)?;
            // Its columns are the `columns` column's values, typed, and named
            // after it.
            if let Some(column) = frame.column(&column_keys[0]) {
                res = res.with_value_labels(&column.dtype());
            }
            res = res.with_columns_name(Some(column_keys[0].clone()));
            // pandas unstacks the aggregate: an int one (a count, or sum /
            // min / max / first / last of an int column) with every cell
            // present stays int64 (it came back float64).
            let int_aggregate = match name.as_str() {
                "count" | "size" => true,
                "sum" | "min" | "max" | "first" | "last" => frame
                    .column(&value_names[0])
                    .is_some_and(|column| column.dtype() == DType::Int64),
                _ => false,
            };
            let complete = (0..res.num_columns()).all(|position| {
                res.column_at(position)
                    .is_some_and(|column| !column.values().iter().any(Scalar::is_missing))
            });
            if int_aggregate && complete {
                res = res.astype(DType::Int64).map_err(frame_error_to_py)?;
            }
            // sort=False: rows and columns in the order their key value
            // first appears (they were refused).
            if !sort {
                let first_seen = |key: &str| {
                    let mut order: HashMap<String, usize> = HashMap::new();
                    if let Some(column) = frame.column(key) {
                        for (position, value) in column.values().iter().enumerate() {
                            order
                                .entry(scalar_to_index_label_converter(value).to_string())
                                .or_insert(position);
                        }
                    }
                    order
                };
                let rows = first_seen(&index_keys[0]);
                let mut positions: Vec<usize> = (0..res.len()).collect();
                let labels = res.index().labels().to_vec();
                positions.sort_by_key(|&row| {
                    rows.get(&labels[row].to_string())
                        .copied()
                        .unwrap_or(usize::MAX)
                });
                res = res.take_rows(&positions).map_err(frame_error_to_py)?;
                let columns = first_seen(&column_keys[0]);
                let mut names: Vec<String> = res.column_names().into_iter().cloned().collect();
                names.sort_by_key(|name| columns.get(name).copied().unwrap_or(usize::MAX));
                let refs: Vec<&str> = names.iter().map(String::as_str).collect();
                res = res.select_columns(&refs).map_err(frame_error_to_py)?;
            }
            Bound::new(py, PyDataFrame { inner: res })?.into_any()
        } else {
            // pandas' definition: the aggregate over the index and columns
            // keys, a row whose every value is missing dropped, the columns
            // keys' levels unstacked (filled as it goes), a column whose
            // every value is missing dropped, the columns sorted; a single
            // `values` name (not a list) keeps no value level
            // (br-frankenpandas-xbl2k; it was refused).
            if margins {
                return Err(not_implemented(
                    "DataFrame.pivot_table(margins=True) with several index / columns / values keys",
                ));
            }
            if !sort {
                return Err(not_implemented(
                    "DataFrame.pivot_table(sort=False) with several index / columns / values keys",
                ));
            }
            let mut keys = index_keys.clone();
            keys.extend(column_keys.iter().cloned());
            let all = || keyword("how", pyo3::types::PyString::new(py, "all").into_any());
            let agged = aggregate(&data, &keys)?;
            let agged = if dropna {
                agged.call_method("dropna", (), Some(&all()?))?
            } else {
                agged
            };
            let agged = if single_value {
                agged.get_item(label_of(&value_names[0])?)?
            } else {
                agged
            };
            let unstack_kwargs = PyDict::new(py);
            if let Some(fill) = fill_value.filter(|fill| !fill.is_none()) {
                unstack_kwargs.set_item("fill_value", fill)?;
            }
            let moved = PyList::new(py, index_keys.len()..keys.len())?;
            let table = agged.call_method("unstack", (moved,), Some(&unstack_kwargs))?;
            let table = if dropna {
                let by_columns = all()?;
                by_columns.set_item("axis", 1)?;
                table.call_method("dropna", (), Some(&by_columns))?
            } else {
                table
            };
            let sorted = table
                .extract::<PyRef<'_, PyDataFrame>>()?
                .inner
                .sort_index_axis1(true)
                .map_err(frame_error_to_py)?;
            Bound::new(py, PyDataFrame { inner: sorted })?.into_any()
        };
        // pandas' dropna=True drops each aggregated row whose every value is
        // missing before it unstacks (var / std / sem of one value, skew of
        // fewer than three), as the branch above does - the kernel's table
        // and the groupby of no `columns` kept it (br-frankenpandas-c6xs9) -
        // and, last of all, each column whose every value is missing.
        let all_missing = |axis: i64| -> PyResult<Bound<'py, PyDict>> {
            let kwargs = keyword("how", pyo3::types::PyString::new(py, "all").into_any())?;
            kwargs.set_item("axis", axis)?;
            Ok(kwargs)
        };
        if dropna && (column_keys.is_empty() || simple) {
            table = table.call_method("dropna", (), Some(&all_missing(0)?))?;
            // With `columns`, a column whose every cell was dropped never
            // unstacks, so no fill_value reaches it.
            if simple {
                table = table.call_method("dropna", (), Some(&all_missing(1)?))?;
            }
        }
        let without_empty_columns = |table: Bound<'py, PyAny>| -> PyResult<Bound<'py, PyAny>> {
            if dropna {
                table.call_method("dropna", (), Some(&all_missing(1)?))
            } else {
                Ok(table)
            }
        };
        if let Some(fill) = fill_value.filter(|fill| !fill.is_none()) {
            let fill = py_to_scalar(py, fill)?;
            let res = table
                .extract::<PyRef<'_, PyDataFrame>>()?
                .inner
                .fillna(&fill)
                .map_err(frame_error_to_py)?;
            // pandas fills while unstacking the aggregate, so an int
            // aggregate (sum/min/max/first/last/count of an int column)
            // filled with an int stays int64.
            let int_aggregate = value_names.len() == 1
                && slf
                    .borrow()
                    .inner
                    .column(&value_names[0])
                    .is_some_and(|c| c.dtype() == DType::Int64)
                && aggfunc.extract::<String>().is_ok_and(|name| {
                    matches!(
                        name.as_str(),
                        "sum" | "min" | "max" | "first" | "last" | "count" | "size"
                    )
                });
            let res = if int_aggregate && matches!(fill, Scalar::Int64(_)) {
                res.astype(DType::Int64).map_err(frame_error_to_py)?
            } else {
                res
            };
            table = Bound::new(py, PyDataFrame { inner: res })?.into_any();
        }
        if !margins {
            return without_empty_columns(table);
        }
        if index_keys.len() != 1 {
            return Err(not_implemented(
                "DataFrame.pivot_table(margins=True) over several index keys",
            ));
        }
        let index_name = pyo3::types::PyString::new(py, &index_keys[0]).into_any();
        let concat = py.import("frankenpandas")?.getattr("concat")?;
        let one_row = |cells: Bound<'py, PyDict>| -> PyResult<Bound<'py, PyAny>> {
            let labels = PyList::new(py, [margins_name])?;
            py.get_type::<PyDataFrame>()
                .call((cells,), Some(&keyword("index", labels.into_any())?))
        };
        let margin_names: Vec<&String> = key_names.iter().copied().chain(&value_names).collect();
        let margin_data = rows_with_every(&margin_names)?;
        let totals = margin_data
            .get_item(&values_list)?
            .call_method1("agg", (aggfunc,))?;
        let with_row = if column_keys.is_empty() {
            let cells = PyDict::new(py);
            for name in &value_names {
                cells.set_item(name, PyList::new(py, [totals.get_item(name)?])?)?;
            }
            concat.call1((PyList::new(py, [table, one_row(cells)?])?,))?
        } else {
            // The All column: each index group over every column label; the
            // All row: each column label over every index group; the corner:
            // everything.
            let value = &value_names[0];
            let by_index = aggregate(&margin_data, &index_keys)?.get_item(value)?;
            let by_column = aggregate(&margin_data, &column_keys)?.get_item(value)?;
            table.set_item(margins_name, by_index)?;
            let cells = PyDict::new(py);
            for label in table.getattr("columns")?.try_iter()? {
                let label = label?;
                // A column label no complete row has (its every value
                // missing) totals NaN (it raised KeyError).
                let cell = if label.eq(margins_name)? {
                    totals.get_item(value)?
                } else {
                    by_column.call_method1("get", (&label, f64::NAN))?
                };
                cells.set_item(label, PyList::new(py, [cell])?)?;
            }
            concat.call1((PyList::new(py, [table, one_row(cells)?])?,))?
        };
        with_row.getattr("index")?.setattr("name", index_name)?;
        without_empty_columns(with_row)
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=None, frac=None, replace=false, weights=None, random_state=None, axis=None, ignore_index=false))]
    /// pandas' `DataFrame.sample`: the rows (or, axis=1, columns) pandas
    /// draws for the same seed, `weights` included - a column name, a Series
    /// aligned by label, or one weight per item (see
    /// [`pandas_sample_positions`]; fp-frame's own generator drew others,
    /// and weights were refused).
    fn sample(
        &self,
        py: Python<'_>,
        n: Option<i64>,
        frac: Option<f64>,
        replace: bool,
        weights: Option<&Bound<'_, PyAny>>,
        random_state: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        ignore_index: bool,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param(axis)?;
        let names: Vec<String> = self.inner.column_names().into_iter().cloned().collect();
        let labels: Vec<IndexLabel> = if ax == 1 {
            names
                .iter()
                .map(|name| IndexLabel::Utf8(name.clone()))
                .collect()
        } else {
            self.inner.index().labels().to_vec()
        };
        let weights = weights
            .filter(|weights| !weights.is_none())
            .map(|weights| sample_weights(py, weights, &labels, (ax == 0).then_some(&self.inner)))
            .transpose()?;
        let positions =
            pandas_sample_positions(py, labels.len(), n, frac, replace, weights, random_state)?;
        let mut res = if ax == 1 {
            let picked: Vec<&str> = positions
                .iter()
                .map(|&position| names[position].as_str())
                .collect();
            self.inner
                .select_columns(&picked)
                .map_err(frame_error_to_py)?
        } else {
            self.inner
                .take_rows(&positions)
                .map_err(frame_error_to_py)?
        };
        if ignore_index {
            res = res.reset_index(true).map_err(frame_error_to_py)?;
        }
        Ok(PyDataFrame { inner: res })
    }

    /// pandas' `DataFrame.resample(rule, axis, closed, label, convention,
    /// kind, on, level, origin, offset, group_keys)`: `rule` a string alias
    /// or an offset object; `on` bins by that datetime column instead of the
    /// index (it becomes the result's index and leaves the aggregated
    /// columns), as pandas. axis / convention / kind warn pandas'
    /// deprecations (axis=1 is then refused), `level` is 0 or the index's
    /// name (a MultiIndex level is refused), `offset` moves a fixed step's
    /// origin; group_keys as Series.resample. The first argument was named
    /// `freq`, `level` was refused and the others were unexpected keywords
    /// (br-frankenpandas-n57tz).
    #[pyo3(signature = (
        rule,
        axis=Passed(None),
        closed=None,
        label=None,
        convention=Passed(None),
        kind=Passed(None),
        on=None,
        level=None,
        origin=None,
        offset=None,
        group_keys=false
    ))]
    #[allow(clippy::too_many_arguments)]
    fn resample(
        &self,
        py: Python<'_>,
        rule: &Bound<'_, PyAny>,
        axis: Passed<'_>,
        closed: Option<String>,
        label: Option<String>,
        convention: Passed<'_>,
        kind: Passed<'_>,
        on: Option<&str>,
        level: Option<&Bound<'_, PyAny>>,
        origin: Option<String>,
        offset: Option<&Bound<'_, PyAny>>,
        group_keys: bool,
    ) -> PyResult<PyResampler> {
        resample_deprecations(py, "DataFrame", &axis, &kind, &convention)?;
        if level.is_some_and(|level| !level.is_none()) && self.inner.row_multiindex().is_some() {
            return Err(not_implemented(
                "DataFrame.resample(level=) of a MultiIndex",
            ));
        }
        resample_level(self.inner.index(), level, on.is_some())?;
        let frame = match on {
            Some(on) => self.inner.set_index(on, true).map_err(frame_error_to_py)?,
            None => self.inner.clone(),
        };
        let rule = freq_alias(rule, "resample")?;
        let (mut closed, mut label) = (closed, label);
        let origin = resample_offset_origin(
            frame.index(),
            &rule,
            origin,
            offset,
            &mut closed,
            &mut label,
        )?;
        PyResampler::new(
            ResampleTarget::DataFrame(frame),
            rule,
            closed,
            label,
            origin,
        )
        .map(|resampler| resampler.with_group_keys(group_keys))
    }

    /// pandas' `asfreq(freq, method=None, how=None, normalize=False,
    /// fill_value=None)`: `fill_value` fills the new rows (rvqoi).
    #[pyo3(signature = (freq, method=None, how=None, normalize=false, fill_value=None))]
    pub fn asfreq(
        &self,
        py: Python<'_>,
        freq: &str,
        method: Option<&str>,
        how: Option<&str>,
        normalize: bool,
        fill_value: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Self> {
        unsupported_params(
            "DataFrame.asfreq",
            &[("how", how.is_none()), ("normalize", !normalize)],
        )?;
        let fill = fill_value
            .filter(|fill| !fill.is_none())
            .map(|fill| py_to_scalar(py, fill))
            .transpose()?;
        let res = self
            .inner
            .asfreq_with_options(freq, method, fill)
            .map_err(frame_error_to_py)?;
        Ok(Self { inner: res })
    }

    /// pandas' `DataFrame.any(axis=0, bool_only=False, skipna=True)`:
    /// `bool_only` looks at the bool columns alone, and with skipna=False
    /// a missing value counts as its Python truth (both were unknown
    /// keywords; br-frankenpandas-u6p7i).
    #[pyo3(signature = (axis=Passed(None), bool_only=false, skipna=true, **kwargs))]
    fn any(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        bool_only: bool,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("any", kwargs)?;
        if let Some(value) =
            self.reduce_both_axes(py, "any", &axis, skipna, bool_only.then_some(&["bool"][..]))?
        {
            return Ok(value);
        }
        let rows = parse_axis_param(axis.0.as_ref())? == 1;
        let inner = self.logical_reduction(py, false, rows, bool_only, skipna)?;
        PySeries { inner }.into_py_any(py)
    }

    /// pandas' `DataFrame.all(axis=0, bool_only=False, skipna=True)`
    /// (see [`PyDataFrame::any`]).
    #[pyo3(signature = (axis=Passed(None), bool_only=false, skipna=true, **kwargs))]
    fn all(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        bool_only: bool,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        numpy_compat_kwargs("all", kwargs)?;
        if let Some(value) =
            self.reduce_both_axes(py, "all", &axis, skipna, bool_only.then_some(&["bool"][..]))?
        {
            return Ok(value);
        }
        let rows = parse_axis_param(axis.0.as_ref())? == 1;
        let inner = self.logical_reduction(py, true, rows, bool_only, skipna)?;
        PySeries { inner }.into_py_any(py)
    }

    #[pyo3(signature = (axis=None, numeric_only=false, dropna=true))]
    fn mode(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        numeric_only: bool,
        dropna: bool,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param(axis)?;
        let res = self
            .inner
            .mode_with_options(ax, numeric_only, dropna)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn prod(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        min_count: Option<usize>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("prod", kwargs)?;
        Self::warn_axis_none(py, "prod", &axis)?;
        let ax = parse_axis_param(axis.0.as_ref().filter(|axis| !axis.is_none()))?;
        self.refuse_masked_rows("prod", ax, numeric_only)?;
        if let Some(answer) = self.empty_object_rows_answer(ax, numeric_only)? {
            return Ok(answer);
        }
        let product = self.prod_internal(ax, skipna, numeric_only);
        let min_count = min_count.unwrap_or(0);
        wrap_series(
            product.and_then(|s| self.below_min_count_is_nan(s, ax, numeric_only, min_count)),
        )
        .and_then(|s| self.masked_answer("prod", ax, numeric_only, s))
        .and_then(|s| self.empty_object_identities("prod", numeric_only, min_count, s))
    }

    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn product(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
        min_count: Option<usize>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        self.prod(py, axis, skipna, numeric_only, min_count, kwargs)
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (q=None, axis=None, numeric_only=false, interpolation="linear", method="single"))]
    fn quantile(
        &self,
        py: Python<'_>,
        q: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        numeric_only: bool,
        interpolation: &str,
        method: Option<&str>,
    ) -> PyResult<Py<PyAny>> {
        unsupported_params(
            "DataFrame.quantile",
            &[("method", matches!(method, None | Some("single")))],
        )?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        // numeric_only keeps the nullable numeric columns too (4qg5w.5).
        let target_df = if numeric_only {
            self.inner
                .select_dtypes(
                    &[
                        DType::Int64,
                        DType::Float64,
                        DType::Bool,
                        DType::Int64Nullable,
                        DType::Float64Nullable,
                        DType::BoolNullable,
                    ],
                    &[],
                )
                .map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };
        let columns: Vec<&Column> = target_df
            .column_names()
            .into_iter()
            .filter_map(|name| target_df.column(name))
            .collect();
        quantile_refusal(&columns, ax)?;

        let mut q_scalar: Option<f64> = None;
        let mut q_vec: Option<Vec<f64>> = None;

        if let Some(q_obj) = q {
            if let Ok(f) = q_obj.extract::<f64>() {
                q_scalar = Some(f);
            } else if let Ok(it) = q_obj.try_iter() {
                let mut vec = Vec::new();
                for item in it {
                    let item = item?;
                    vec.push(item.extract::<f64>()?);
                }
                q_vec = Some(vec);
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "q must be a float or sequence of floats",
                ));
            }
        } else {
            q_scalar = Some(0.5);
        }

        if let Some(q_val) = q_scalar {
            let res = match ax {
                0 => target_df.quantile(q_val).map_err(frame_error_to_py)?,
                1 => target_df.quantile_axis1(q_val).map_err(frame_error_to_py)?,
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {other} for object type DataFrame"
                    )));
                }
            };
            // pandas names the result after q, the float, along either axis
            // (axis=1 was named 'quantile'; the name was the text '0.3').
            let res = res
                .rename(LabelName::typed(IndexLabel::Float64(OrderedF64(q_val))))
                .map_err(frame_error_to_py)?;
            // A masked column makes the quantiles pandas' Float64 (8u5eh).
            let answer = |res: Series| -> PyResult<Py<PyAny>> {
                let res = PySeries { inner: res };
                let res = if ax == 0 {
                    self.masked_answer("quantile", 0, numeric_only, res)?
                } else {
                    res
                };
                Ok(Py::new(py, res)?.into_any())
            };
            if interpolation == "linear" {
                return answer(res);
            }
            // Any other interpolation was ignored for a single q: each
            // numeric column's (axis=0) or row's (axis=1) quantile under it,
            // over the cells the linear result used.
            let numeric: Vec<(&String, &Column)> = target_df
                .column_names()
                .into_iter()
                .filter_map(|name| target_df.column(name).map(|column| (name, column)))
                .filter(|(_, column)| column.dtype().is_numeric())
                .collect();
            let quantile = |values: Vec<Scalar>| {
                let labels = (0..values.len())
                    .map(|position| IndexLabel::Int64(position as i64))
                    .collect();
                Series::from_values("", labels, values)
                    .and_then(|series| series.quantile_with_interpolation(q_val, interpolation))
            };
            let values = if ax == 0 {
                numeric
                    .iter()
                    .map(|(_, column)| quantile(column.values().to_vec()))
                    .collect::<Result<Vec<_>, _>>()
            } else {
                (0..target_df.len())
                    .map(|row| {
                        quantile(
                            numeric
                                .iter()
                                .map(|(_, column)| column.values()[row].clone())
                                .collect(),
                        )
                    })
                    .collect::<Result<Vec<_>, _>>()
            }
            .map_err(frame_error_to_py)?;
            let column = Column::from_values(values).map_err(column_error_to_py)?;
            let res =
                Series::new(res.name(), res.index().clone(), column).map_err(frame_error_to_py)?;
            return answer(res);
        }

        if let Some(qs) = q_vec {
            let df_to_use = match ax {
                0 => target_df,
                1 => target_df.transpose().map_err(frame_error_to_py)?,
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {other} for object type DataFrame"
                    )));
                }
            };

            let mut series_list = Vec::new();
            for col_name in df_to_use.column_names() {
                if let Some(col) = df_to_use.column(col_name) {
                    if corr_numeric(&col.dtype()) {
                        let s =
                            Series::new(col_name.clone(), df_to_use.index().clone(), col.clone())
                                .map_err(frame_error_to_py)?;
                        let mut q_s = s
                            .quantile_list(&qs, interpolation)
                            .map_err(frame_error_to_py)?;
                        // A masked column's quantiles are pandas' Float64
                        // (8u5eh).
                        if ax == 0 && col.dtype().is_nullable() {
                            let column = q_s
                                .column()
                                .astype(DType::Float64Nullable)
                                .map_err(column_error_to_py)?;
                            q_s = Series::new(q_s.name(), q_s.index().clone(), column)
                                .map_err(frame_error_to_py)?;
                        }
                        series_list.push(q_s);
                    }
                }
            }
            let res_df = if series_list.is_empty() {
                let index_labels: Vec<IndexLabel> = qs
                    .iter()
                    .map(|&q| IndexLabel::Float64(fp_index::OrderedF64(q)))
                    .collect();
                DataFrame::new_with_column_order(
                    Index::new(index_labels),
                    std::collections::BTreeMap::<String, Column>::new(),
                    Vec::<String>::new(),
                )
                .map_err(frame_error_to_py)?
            } else {
                DataFrame::from_series(series_list).map_err(frame_error_to_py)?
            };
            // Along the rows the columns keep their labels (0, not '0') and
            // MultiIndex levels (g3bux).
            let res_df = if ax == 0 {
                res_df.with_labels_of(&self.inner)
            } else {
                res_df
            };
            return Ok(Py::new(py, PyDataFrame { inner: res_df })?.into_any());
        }

        Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "Failed to evaluate quantile",
        ))
    }

    /// pandas' `DataFrame.rank`; the first positional argument is the axis,
    /// as for `Series.rank`.
    #[pyo3(signature = (
        axis=None,
        method=RankOption::text("average"),
        numeric_only=Truthy(false),
        na_option=RankOption::text("keep"),
        ascending=Truthy(true),
        pct=Truthy(false)
    ))]
    #[allow(clippy::too_many_arguments)]
    fn rank(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        method: RankOption,
        numeric_only: Truthy,
        na_option: RankOption,
        ascending: Truthy,
        pct: Truthy,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let (m, na) = rank_options(py, &method, &na_option)?;
        let (asc, pct) = (ascending.0, pct.0);

        let target_df = if numeric_only.0 {
            self.inner
                .select_dtypes(&[DType::Int64, DType::Float64, DType::Bool], &[])
                .map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };

        let res = if ax == 0 {
            target_df
                .rank_with_pct(m, asc, na, pct)
                .map_err(frame_error_to_py)?
        } else {
            target_df
                .rank_axis1_with_pct(m, asc, na, pct)
                .map_err(frame_error_to_py)?
        };
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (axis=Passed(None), skipna=true, ddof=1, numeric_only=false))]
    fn sem(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        ddof: Option<usize>,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        Self::warn_axis_none(py, "sem", &axis)?;
        let ax = parse_axis_param(axis.0.as_ref().filter(|axis| !axis.is_none()))?;
        let ddof_val = ddof.unwrap_or(1);
        self.refuse_masked_rows("sem", ax, numeric_only)?;
        wrap_series(self.sem_internal(ax, skipna, ddof_val, numeric_only))
            .and_then(|s| self.masked_answer("sem", ax, numeric_only, s))
    }

    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false))]
    fn skew(
        &self,
        py: Python<'_>,
        axis: Passed<'_>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<Py<PyAny>> {
        if let Some(value) = self.reduce_both_axes(
            py,
            "skew",
            &axis,
            skipna,
            numeric_only.then_some(NUMERIC_DTYPES),
        )? {
            return Ok(value);
        }
        let ax = parse_axis_param(axis.0.as_ref())?;
        self.refuse_masked_rows("skew", ax, numeric_only)?;
        let skewed = self.skew_internal(ax, numeric_only);
        wrap_series(skewed.and_then(|s| self.missing_is_nan(s, ax, numeric_only, skipna)))
            .and_then(|s| self.masked_answer("skew", ax, numeric_only, s))?
            .into_py_any(py)
    }

    #[pyo3(signature = (axis=Passed(None), skipna=true, numeric_only=false))]
