#[pyfunction(name = "is_dtype_equal")]
fn api_is_dtype_equal(source: &Bound<'_, PyAny>, target: &Bound<'_, PyAny>) -> bool {
    if source.is(target) {
        return true;
    }
    if let (Ok(s1), Ok(s2)) = (source.extract::<String>(), target.extract::<String>()) {
        return s1 == s2;
    }
    false
}

#[pyfunction(name = "infer_dtype", signature = (value, skipna=true))]
fn api_infer_dtype(value: &Bound<'_, PyAny>, skipna: bool) -> PyResult<&'static str> {
    infer_dtype_impl(value, skipna)
}

/// pandas' `api.types.union_categoricals(to_union, sort_categories=False,
/// ignore_order=False)`: the values of each Categorical / category Series /
/// CategoricalIndex in turn, as one Categorical. Categories that match (as a
/// set, in one order when ordered) keep the first's order and orderedness;
/// else, unordered, their union in order of appearance; ordered ones that
/// differ are pandas' TypeError (it was missing; br-frankenpandas-h06ox).
#[pyfunction(name = "union_categoricals", signature = (to_union, sort_categories=false, ignore_order=false))]
fn api_union_categoricals(
    py: Python<'_>,
    to_union: &Bound<'_, PyAny>,
    sort_categories: bool,
    ignore_order: bool,
) -> PyResult<PyCategorical> {
    let type_error =
        |message: &str| PyErr::new::<pyo3::exceptions::PyTypeError, _>(message.to_owned());
    let mut parts = Vec::new();
    for item in to_union.try_iter()? {
        let item = item?;
        let dtype = item.getattr("dtype").ok();
        if !dtype
            .as_ref()
            .is_some_and(|dtype| dtype.is_instance_of::<PyCategoricalDtype>())
        {
            // pandas unwraps a Series / Index to its array first, which
            // then has no categories.
            let unwrapped = item.is_instance_of::<PySeries>() || item.is_instance_of::<PyIndex>();
            return Err(if unwrapped {
                PyErr::new::<pyo3::exceptions::PyAttributeError, _>(
                    "'numpy.ndarray' object has no attribute 'categories'",
                )
            } else {
                type_error("all components to combine must be Categorical")
            });
        }
        let dtype = item.getattr("dtype")?;
        let categories = dtype
            .getattr("categories")?
            .try_iter()?
            .collect::<PyResult<Vec<_>>>()?;
        let ordered = dtype.getattr("ordered")?.is_truthy()?;
        parts.push((item, categories, ordered));
    }
    let Some((_, first_categories, first_ordered)) = parts.first() else {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "No Categoricals to union",
        ));
    };
    let same = |a: &[Bound<'_, PyAny>], b: &[Bound<'_, PyAny>]| -> PyResult<bool> {
        Ok(a.len() == b.len() && PySet::new(py, a)?.eq(PySet::new(py, b)?)?)
    };
    let in_order = |a: &[Bound<'_, PyAny>], b: &[Bound<'_, PyAny>]| -> PyResult<bool> {
        Ok(a.len() == b.len() && PyList::new(py, a)?.eq(PyList::new(py, b)?)?)
    };
    let mut matching = true;
    for (_, categories, ordered) in &parts[1..] {
        let matches = if *first_ordered || *ordered {
            ordered == first_ordered && in_order(first_categories, categories)?
        } else {
            same(first_categories, categories)?
        };
        matching &= matches;
    }
    let (categories, mut ordered) = if matching {
        if sort_categories && !ignore_order && *first_ordered {
            return Err(type_error(
                "Cannot use sort_categories=True with ordered Categoricals",
            ));
        }
        (PyList::new(py, first_categories)?, *first_ordered)
    } else if ignore_order || parts.iter().all(|(_, _, ordered)| !ordered) {
        let union = PyList::empty(py);
        let seen = PySet::empty(py)?;
        for (_, categories, _) in &parts {
            for category in categories {
                if !seen.contains(category)? {
                    seen.add(category)?;
                    union.append(category)?;
                }
            }
        }
        (union, false)
    } else if parts.iter().all(|(_, _, ordered)| *ordered) {
        return Err(type_error(
            "to union ordered Categoricals, all categories must be the same",
        ));
    } else {
        return Err(type_error("Categorical.ordered must be the same"));
    };
    if sort_categories {
        categories.sort()?;
    }
    if ignore_order {
        ordered = false;
    }
    let values = PyList::empty(py);
    for (item, _, _) in &parts {
        for value in item.try_iter()? {
            values.append(value?)?;
        }
    }
    PyCategorical::new(
        py,
        values.as_any(),
        Some(categories.as_any()),
        Some(ordered),
    )
}

/// pandas' `pandas_dtype(dtype)`: the dtype object an argument names - a
/// numpy dtype for numpy's names and types ('int64', int, np.int32, 'O',
/// 'M8[ns]'), pandas' extension dtype for its names ('Int64', 'boolean',
/// 'string[python]', 'category', 'datetime64[ns, UTC]', 'period[M]',
/// 'interval[int64, right]', 'Sparse[int64]'); a dtype object as it is, a
/// Series its dtype, None float64; any other name numpy's TypeError. It
/// returned the argument unchanged (br-frankenpandas-0uavl).
#[pyfunction(name = "pandas_dtype")]
fn api_pandas_dtype<'py>(dtype: &Bound<'py, PyAny>) -> PyResult<Bound<'py, PyAny>> {
    let py = dtype.py();
    let module = py.import("frankenpandas")?;
    let numpy_dtype = |spec: &Bound<'py, PyAny>| py.import("numpy")?.call_method1("dtype", (spec,));
    if dtype.is_none() {
        return numpy_dtype(&"float64".into_bound_py_any(py)?);
    }
    if dtype.is_instance_of::<PySeries>() {
        return dtype.getattr("dtype");
    }
    let Ok(name) = dtype.extract::<String>() else {
        // A dtype object (numpy's or pandas') is itself; a type numpy's.
        if !dtype.is_instance_of::<pyo3::types::PyType>() && dtype.hasattr("kind")? {
            return Ok(dtype.clone());
        }
        return numpy_dtype(dtype);
    };
    let bracketed = |prefix: &str| {
        name.strip_prefix(prefix)
            .and_then(|rest| rest.strip_suffix(']'))
            .map(|inner| inner.split(',').map(str::trim).collect::<Vec<&str>>())
    };
    match name.as_str() {
        "Int8" | "Int16" | "Int32" | "Int64" | "UInt8" | "UInt16" | "UInt32" | "UInt64"
        | "Float32" | "Float64" => return module.getattr(format!("{name}Dtype").as_str())?.call0(),
        "boolean" => return module.getattr("BooleanDtype")?.call0(),
        "category" => return module.getattr("CategoricalDtype")?.call0(),
        "interval" => return module.getattr("IntervalDtype")?.call0(),
        _ => {}
    }
    if name == "string" || name.starts_with("string[") {
        return module
            .getattr("StringDtype")?
            .call_method1("construct_from_string", (name.as_str(),));
    }
    if let Some(parts) = bracketed("datetime64[")
        && let [unit, zone] = parts.as_slice()
    {
        return module.getattr("DatetimeTZDtype")?.call1((*unit, *zone));
    }
    if let Some(parts) = bracketed("period[")
        && let [freq] = parts.as_slice()
    {
        return module.getattr("PeriodDtype")?.call1((*freq,));
    }
    if let Some(parts) = bracketed("interval[") {
        let subtype = parts.first().copied();
        let closed = parts.get(1).copied();
        return module.getattr("IntervalDtype")?.call1((subtype, closed));
    }
    if let Some(parts) = bracketed("Sparse[") {
        return module
            .getattr("SparseDtype")?
            .call1((parts.first().copied(),));
    }
    numpy_dtype(dtype)
}

fn scalar_to_label_str(s: &Scalar) -> String {
    s.to_string()
}

fn scalar_to_index_label_converter(s: &Scalar) -> IndexLabel {
    match s {
        Scalar::Int64(v) => IndexLabel::Int64(*v),
        Scalar::Float64(f) => IndexLabel::Float64(fp_index::OrderedF64(*f)),
        Scalar::Utf8(s) => IndexLabel::Utf8(s.clone()),
        Scalar::Bool(b) => IndexLabel::Bool(*b),
        Scalar::Datetime64(d) => IndexLabel::Datetime64(*d),
        Scalar::Timedelta64(t) => IndexLabel::Timedelta64(*t),
        // A period is its own label (it was its ordinal - pd.Index of
        // periods held ints; 45fzr).
        Scalar::Period(p) => IndexLabel::Period(*p),
        // An interval is its own label (it was its text; c27hq).
        Scalar::Interval(inv) => IndexLabel::Interval(*inv),
        Scalar::Object(object) => IndexLabel::Object(object.clone()),
        Scalar::Null(k) => IndexLabel::Null(*k),
    }
}

#[pyfunction]
fn unique(py: Python<'_>, values: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
    if let Ok(s) = values.extract::<PyRef<'_, PySeries>>() {
        return s.unique(py);
    }
    if let Ok(idx) = plain_index_ref(values) {
        // A numpy array, as pandas 2.2's pd.unique of an Index (it was a
        // list; fvsao.30).
        return Ok(labels_ndarray(py, idx.unique(None)?.inner.labels())?.unbind());
    }
    let s = PySeries::from_data(py, Some(values), None, None)?;
    s.unique(py)
}

#[pyfunction]
#[pyo3(signature = (values, sort=true, ascending=false, normalize=false, dropna=true))]
fn value_counts(
    py: Python<'_>,
    values: &Bound<'_, PyAny>,
    sort: bool,
    ascending: bool,
    normalize: bool,
    dropna: bool,
) -> PyResult<PySeries> {
    let series = if let Ok(s) = values.extract::<PyRef<'_, PySeries>>() {
        s.inner.clone()
    } else {
        PySeries::from_data(py, Some(values), None, None)?.inner
    };
    let r = series
        .value_counts_with_options(normalize, sort, ascending, dropna)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
    Ok(PySeries { inner: r })
}

#[pyfunction]
#[pyo3(signature = (values, sort=false, use_na_sentinel=true))]
fn factorize(
    py: Python<'_>,
    values: &Bound<'_, PyAny>,
    sort: bool,
    use_na_sentinel: bool,
) -> PyResult<(Py<PyAny>, Py<PyAny>)> {
    // pandas answers an Index of uniques for a Series / Index (and our
    // Categorical, its ExtensionArray), a numpy array for anything else, and
    // deprecates what is not an ndarray (a list; it was an Index for every
    // input; br-frankenpandas-c5b7x).
    let keeps_index = values.extract::<PyRef<'_, PySeries>>().is_ok()
        || plain_index_ref(values).is_ok()
        || values.extract::<PyRef<'_, PyCategorical>>().is_ok();
    if !keeps_index && !values.is_instance(&py.import("numpy")?.getattr("ndarray")?)? {
        PyErr::warn(
            py,
            &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
            c"factorize with argument that is not not a Series, Index, ExtensionArray, or np.ndarray is deprecated and will raise in a future version.",
            1,
        )?;
    }
    let s = PySeries::from_data(py, Some(values), None, None)?;
    let col_vals = s.inner.column().values();

    let mut cat_to_code: HashMap<String, i64> = HashMap::new();
    let mut uniques_labels: Vec<IndexLabel> = Vec::new();
    let mut codes: Vec<i64> = Vec::with_capacity(col_vals.len());

    for v in col_vals {
        if v.is_null() {
            if use_na_sentinel {
                codes.push(-1);
            } else {
                let null_key = "__NULL__".to_string();
                let code = match cat_to_code.get(&null_key) {
                    Some(&c) => c,
                    None => {
                        let next_code = uniques_labels.len() as i64;
                        uniques_labels.push(IndexLabel::Null(NullKind::NaN));
                        cat_to_code.insert(null_key, next_code);
                        next_code
                    }
                };
                codes.push(code);
            }
        } else {
            let key = scalar_to_label_str(v);
            let code = match cat_to_code.get(&key) {
                Some(&c) => c,
                None => {
                    let next_code = uniques_labels.len() as i64;
                    uniques_labels.push(scalar_to_index_label_converter(v));
                    cat_to_code.insert(key, next_code);
                    next_code
                }
            };
            codes.push(code);
        }
    }

    if sort && !uniques_labels.is_empty() {
        let mut sorted_pairs: Vec<(usize, IndexLabel)> =
            uniques_labels.into_iter().enumerate().collect();
        sorted_pairs.sort_by(|(_, a), (_, b)| a.cmp(b));
        let mut old_to_new = vec![0i64; sorted_pairs.len()];
        let mut new_uniques = Vec::with_capacity(sorted_pairs.len());
        for (new_idx, (old_idx, val)) in sorted_pairs.into_iter().enumerate() {
            old_to_new[old_idx] = new_idx as i64;
            new_uniques.push(val);
        }
        for code in &mut codes {
            if *code >= 0 && (*code as usize) < old_to_new.len() {
                *code = old_to_new[*code as usize];
            }
        }
        uniques_labels = new_uniques;
    }

    // The codes are pandas' int64 numpy array (they were a list).
    let py_codes = py
        .import("numpy")?
        .call_method1("array", (codes, "int64"))?
        .unbind();
    if !keeps_index {
        return Ok((py_codes, labels_ndarray(py, &uniques_labels)?.unbind()));
    }
    let py_uniques = PyIndex {
        inner: Index::new(uniques_labels),
    };
    Ok((py_codes, Py::new(py, py_uniques)?.into_any()))
}

/// pandas' hash-table identity of a get_dummies value: equal numbers - 1,
/// 1.0 and True; 0.0 and -0.0 - are one level, as pandas' factorize makes
/// them; text and other values are their own (they were keyed by their
/// text: '0' / '-0' two levels, the int 1 beside a text '1' dropped;
/// br-frankenpandas-jjoxr).
#[derive(PartialEq, Eq, Hash)]
enum DummyKey<'a> {
    Number(u64),
    Int(i64),
    Text(&'a [u8]),
    Other(IndexLabel),
}

impl<'a> DummyKey<'a> {
    fn of(value: &'a Scalar) -> Self {
        match value {
            Scalar::Utf8(text) => Self::Text(text.as_bytes()),
            Scalar::Bool(flag) => Self::Number(f64::from(u8::from(*flag)).to_bits()),
            Scalar::Int64(int) => {
                let float = *int as f64;
                if float as i128 == i128::from(*int) {
                    Self::Number(float.to_bits())
                } else {
                    Self::Int(*int)
                }
            }
            Scalar::Float64(float) if *float == 0.0 => Self::Number(0.0_f64.to_bits()),
            Scalar::Float64(float) => Self::Number(float.to_bits()),
            other => Self::Other(scalar_to_index_label_converter(other)),
        }
    }
}

/// One get_dummies indicator column per level from `first` on, each row's
/// level read from `codes` (a code past the levels marks no level): `zero`
/// everywhere but `one` in that level's rows.
fn scatter_dummies<T: Copy>(
    codes: &[u32],
    first: usize,
    count: usize,
    zero: T,
    one: T,
) -> Vec<Vec<T>> {
    let mut columns: Vec<Vec<T>> = (first..count).map(|_| vec![zero; codes.len()]).collect();
    for (row, &code) in codes.iter().enumerate() {
        if let Some(cells) = (code as usize)
            .checked_sub(first)
            .and_then(|at| columns.get_mut(at))
        {
            cells[row] = one;
        }
    }
    columns
}

/// The dtype of get_dummies' indicator cells: pandas' `dtype=` - numpy
/// bool / int64 / float64 or a narrower width (uint8, float32; it raised
/// TypeError), the masked boolean / Int / Float (they came back bool) -
/// object being pandas' ValueError (br-frankenpandas-jjoxr).
#[derive(Clone, Copy)]
enum DummyCells {
    Bool,
    Boolean,
    /// int64, or masked Int64.
    Int(bool),
    /// float64, or masked Float64.
    Float(bool),
    Narrow(NumericWidth, bool),
}

impl DummyCells {
    fn of(dtype: &Bound<'_, PyAny>) -> PyResult<Self> {
        if let Some((width, masked)) = py_width_arg(dtype) {
            return Ok(Self::Narrow(width, masked));
        }
        if matches!(dtype_arg_text(dtype)?.as_str(), "object" | "O") {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "dtype=object is not a valid dtype for get_dummies",
            ));
        }
        Ok(match pandas_dtype_name(&py_dtype_arg(dtype)?).as_str() {
            "bool" => Self::Bool,
            "boolean" => Self::Boolean,
            "int64" => Self::Int(false),
            "Int64" => Self::Int(true),
            "float64" => Self::Float(false),
            "Float64" => Self::Float(true),
            other => return Err(not_implemented(&format!("get_dummies with dtype={other}"))),
        })
    }
}

/// get_dummies of one column, as pandas' `_get_dummies_1d`: its levels - a
/// categorical's categories in order, else its distinct values sorted
/// (numbers, then other values, then text; the first of equal numbers
/// stands for them), a missing level last for `dummy_na` (NaT for datetime
/// and timedelta, NA for a `string` column, NaN else, int levels then
/// floats as pandas' Index.insert makes them) - each with its indicator
/// column in `cells` (bool when None, pandas' boolean for a `string`
/// column), the first level dropped for `drop_first`. It sorted text
/// labels, ignored a categorical's categories and added no missing level
/// when nothing was missing (br-frankenpandas-jjoxr). The column is coded
/// once, text read from its contiguous buffer when it has one, and the
/// indicators filled from the codes: a String per row, twice, made
/// get_dummies of 1M strings 2.9x pandas (br-frankenpandas-3o9vc).
fn dummy_levels(
    column: &Column,
    dummy_na: bool,
    drop_first: bool,
    cells: Option<DummyCells>,
) -> PyResult<Vec<(IndexLabel, Column)>> {
    const MISSING: u32 = u32::MAX;
    if column.len() >= MISSING as usize {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "get_dummies: too many rows",
        ));
    }
    let categories = column.categorical().map(|meta| &meta.categories);
    let mut levels: Vec<Scalar> = Vec::new();
    let mut codes: Vec<u32> = Vec::with_capacity(column.len());
    let mut seen: FxHashMap<DummyKey<'_>, u32> = FxHashMap::default();
    if let Some(categories) = categories {
        for (at, category) in categories.iter().enumerate() {
            seen.entry(DummyKey::of(category)).or_insert(at as u32);
        }
        levels.clone_from(categories);
    }
    if let Some((bytes, offsets)) = column.as_utf8_contiguous().filter(|_| categories.is_none()) {
        for bounds in offsets.windows(2) {
            let word = &bytes[bounds[0]..bounds[1]];
            let code = match seen.get(&DummyKey::Text(word)) {
                Some(&code) => code,
                None => {
                    let code = levels.len() as u32;
                    let text = std::str::from_utf8(word).map_err(|e| {
                        PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string())
                    })?;
                    levels.push(Scalar::Utf8(text.to_owned()));
                    seen.insert(DummyKey::Text(word), code);
                    code
                }
            };
            codes.push(code);
        }
    } else if let Some(ints) = column.as_i64_slice().filter(|_| categories.is_none()) {
        // An int column's levels are its distinct ints, read from its buffer
        // (a Scalar and a key per row made 1M ints 2.2x pandas).
        let mut by_int: FxHashMap<i64, u32> = FxHashMap::default();
        for &int in ints {
            let next = levels.len() as u32;
            let code = *by_int.entry(int).or_insert_with(|| {
                levels.push(Scalar::Int64(int));
                next
            });
            codes.push(code);
        }
    } else {
        for value in column.values() {
            if value.is_missing() {
                codes.push(MISSING);
                continue;
            }
            let key = DummyKey::of(value);
            let code = match seen.get(&key) {
                Some(&code) => code,
                None if categories.is_some() => MISSING,
                None => {
                    let code = levels.len() as u32;
                    levels.push(value.clone());
                    seen.insert(key, code);
                    code
                }
            };
            codes.push(code);
        }
    }
    if categories.is_none() {
        // pandas' sorted levels; numbers before text as its mixed sort puts
        // them (they sorted by kind, bools apart from the ints they equal).
        let keys: Vec<(u8, IndexLabel)> = levels
            .iter()
            .map(|value| match value {
                Scalar::Bool(flag) => (0, IndexLabel::Int64(i64::from(*flag))),
                Scalar::Int64(_) | Scalar::Float64(_) => {
                    (0, scalar_to_index_label_converter(value))
                }
                Scalar::Utf8(_) => (2, scalar_to_index_label_converter(value)),
                other => (1, scalar_to_index_label_converter(other)),
            })
            .collect();
        let mut order: Vec<usize> = (0..levels.len()).collect();
        order.sort_by(|&a, &b| keys[a].cmp(&keys[b]));
        let mut recode = vec![0_u32; levels.len()];
        for (new, &old) in order.iter().enumerate() {
            recode[old] = new as u32;
        }
        for code in &mut codes {
            if *code != MISSING {
                *code = recode[*code as usize];
            }
        }
        let unsorted = std::mem::take(&mut levels);
        levels = order.into_iter().map(|old| unsorted[old].clone()).collect();
    }
    let floats = dummy_na
        && categories.is_none()
        && levels.iter().all(|value| matches!(value, Scalar::Int64(_)));
    let mut labels: Vec<IndexLabel> = levels
        .iter()
        .map(|value| match value {
            Scalar::Int64(int) if floats => IndexLabel::Float64(fp_index::OrderedF64(*int as f64)),
            other => scalar_to_index_label_converter(other),
        })
        .collect();
    if dummy_na {
        let missing = labels.len() as u32;
        for code in &mut codes {
            if *code == MISSING {
                *code = missing;
            }
        }
        // NaT for a datetime / timedelta column, pandas' NA (`Null`) for a
        // `string` column, NaN else - as the levels' Index takes it.
        let kind = match column.dtype() {
            _ if categories.is_some() => NullKind::NaN,
            DType::Datetime64 { .. } | DType::Timedelta64 => NullKind::NaT,
            _ if column.is_pandas_string() => NullKind::Null,
            _ => NullKind::NaN,
        };
        labels.push(IndexLabel::Null(kind));
    }
    let first = usize::from(drop_first && !labels.is_empty());
    let count = labels.len();
    let cells = cells.unwrap_or(if column.is_pandas_string() {
        DummyCells::Boolean
    } else {
        DummyCells::Bool
    });
    let ints = || {
        scatter_dummies(&codes, first, count, 0_i64, 1)
            .into_iter()
            .map(Column::from_i64_values_owned)
    };
    let floats = || {
        scatter_dummies(&codes, first, count, 0.0_f64, 1.0)
            .into_iter()
            .map(Column::from_f64_values_owned)
    };
    let columns: Vec<Column> = match cells {
        DummyCells::Bool => scatter_dummies(&codes, first, count, false, true)
            .into_iter()
            .map(Column::from_bool_values)
            .collect(),
        DummyCells::Boolean => scatter_dummies(&codes, first, count, false, true)
            .into_iter()
            .map(|data| Column::from_bool_values(data).astype(DType::BoolNullable))
            .collect::<Result<_, _>>()
            .map_err(column_error_to_py)?,
        DummyCells::Int(false) => ints().collect(),
        DummyCells::Float(false) => floats().collect(),
        DummyCells::Int(true) => ints()
            .map(|column| column.astype(DType::Int64Nullable))
            .collect::<Result<_, _>>()
            .map_err(column_error_to_py)?,
        DummyCells::Float(true) => floats()
            .map(|column| column.astype(DType::Float64Nullable))
            .collect::<Result<_, _>>()
            .map_err(column_error_to_py)?,
        DummyCells::Narrow(width, masked) if width.is_float() => floats()
            .map(|column| column.cast_to_width(width, masked))
            .collect::<Result<_, _>>()
            .map_err(column_error_to_py)?,
        DummyCells::Narrow(width, masked) => ints()
            .map(|column| column.cast_to_width(width, masked))
            .collect::<Result<_, _>>()
            .map_err(column_error_to_py)?,
    };
    Ok(labels.into_iter().skip(first).zip(columns).collect())
}

/// The text pandas' f-string gives a get_dummies level in a prefixed column
/// name: '1.0' for a float, '2020-01-01 00:00:00' for a timestamp, 'nan' /
/// 'NaT' / a `string` column's '<NA>' for the missing level (they were
/// Rust's '1', 'Timestamp[ns]').
fn dummy_level_text(py: Python<'_>, label: &IndexLabel) -> PyResult<String> {
    Ok(match label {
        IndexLabel::Utf8(text) => text.clone(),
        IndexLabel::Int64(int) => int.to_string(),
        IndexLabel::Null(NullKind::NaT) => "NaT".to_owned(),
        IndexLabel::Null(NullKind::Null) => "<NA>".to_owned(),
        IndexLabel::Null(_) => "nan".to_owned(),
        other => index_label_to_py(py, other)?.bind(py).str()?.extract()?,
    })
}

/// A frame over `index` of `columns` in order, labelled as given: a label
/// twice (get_dummies' two 'o_1' columns of 1 and '1') stays twice, as
/// pandas'; two labels keyed alike (1 and '1') are refused, as every frame
/// here refuses them.
fn frame_of_labelled_columns(
    index: Index,
    columns: Vec<(IndexLabel, Column)>,
) -> PyResult<DataFrame> {
    let mut store = BTreeMap::new();
    let mut order = Vec::new();
    let mut labels = Vec::new();
    let mut seen: HashMap<String, IndexLabel> = HashMap::new();
    let mut repeats = Vec::new();
    for (position, (label, column)) in columns.into_iter().enumerate() {
        let name = fp_frame::column_key(&label);
        match seen.get(&name) {
            Some(previous) if *previous == label => repeats.push((position, name, column)),
            Some(previous) => {
                return Err(not_implemented(&format!(
                    "a frame holding both the column labels {previous:?} and {label:?} (they are \
                     keyed by the same text)"
                )));
            }
            None => {
                seen.insert(name.clone(), label.clone());
                store.insert(name.clone(), column);
                order.push(name);
                labels.push(label);
            }
        }
    }
    let mut frame = DataFrame::new_with_column_order(index, store, order)
        .map_err(frame_error_to_py)?
        .with_column_labels(labels)
        .map_err(frame_error_to_py)?;
    for (position, name, column) in repeats {
        frame = frame
            .insert_allow_duplicates(position, name, column, true)
            .map_err(frame_error_to_py)?;
    }
    Ok(frame)
}

#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (data, prefix=None, prefix_sep="_", dummy_na=false, columns=None, drop_first=false, dtype=None))]
fn get_dummies(
    py: Python<'_>,
    data: &Bound<'_, PyAny>,
    prefix: Option<&Bound<'_, PyAny>>,
    prefix_sep: &str,
    dummy_na: bool,
    columns: Option<&Bound<'_, PyAny>>,
    drop_first: bool,
    dtype: Option<&Bound<'_, PyAny>>,
) -> PyResult<PyDataFrame> {
    // A type (dtype=int, float, bool) as well as its name; a type raised
    // TypeError.
    let dtype = dtype
        .filter(|dtype| !dtype.is_none())
        .map(DummyCells::of)
        .transpose()?;
    let prefix = prefix.filter(|prefix| !prefix.is_none());
    if let Ok(df) = data.extract::<PyRef<'_, PyDataFrame>>() {
        // columns= may name typed labels (columns=[2]; fvsao.32).
        let columns: Option<Vec<String>> = column_arg_opt(&df.inner, columns)?
            .filter(|columns| !columns.is_none())
            .map(|columns| columns.extract())
            .transpose()?;
        // pandas encodes the object, string and category columns (a bool
        // column was encoded too; br-frankenpandas-jjoxr).
        let target_cols: Vec<String> = columns.unwrap_or_else(|| {
            df.inner
                .column_names()
                .into_iter()
                .enumerate()
                .filter(|(at, _)| {
                    df.inner.column_at(*at).is_some_and(|column| {
                        column.categorical().is_some()
                            || matches!(
                                column_pandas_dtype_name(column).as_str(),
                                "object" | "string" | "category"
                            )
                    })
                })
                .map(|(_, name)| name.clone())
                .collect()
        });
        // pandas' prefix for a frame: one string for every column, a list by
        // position, a dict by column (it was ignored; fvsao.30), either as
        // long as the columns encoded (br-frankenpandas-jjoxr).
        if let Some(prefix) =
            prefix.filter(|prefix| !prefix.is_instance_of::<pyo3::types::PyString>())
            && let Ok(given) = prefix.len()
            && given != target_cols.len()
        {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Length of 'prefix' ({given}) did not match the length of the columns being encoded ({}).",
                target_cols.len()
            )));
        }
        let prefix_of = |position: usize, column: &str| -> PyResult<String> {
            let Some(prefix) = prefix else {
                return Ok(column.to_owned());
            };
            if let Ok(text) = prefix.extract::<String>() {
                return Ok(text);
            }
            if prefix.is_instance_of::<PyDict>() {
                return prefix.get_item(column)?.extract();
            }
            prefix.get_item(position)?.extract()
        };
        // The other columns first, then each encoded column's indicators,
        // as pandas.
        let targets: HashSet<&String> = target_cols.iter().collect();
        let mut out: Vec<(IndexLabel, Column)> = Vec::new();
        for (at, name) in df.inner.column_names().into_iter().enumerate() {
            if let Some(column) = df.inner.column_at(at).filter(|_| !targets.contains(name)) {
                out.push((df.inner.column_label(name), column.clone()));
            }
        }
        for (position, name) in target_cols.iter().enumerate() {
            let label = prefix_of(position, name)?;
            if let Some(column) = df.inner.column(name) {
                for (level, indicator) in dummy_levels(column, dummy_na, drop_first, dtype)? {
                    let text = dummy_level_text(py, &level)?;
                    out.push((
                        IndexLabel::Utf8(format!("{label}{prefix_sep}{text}")),
                        indicator,
                    ));
                }
            }
        }
        let frame = frame_of_labelled_columns(df.inner.index().clone(), out)?;
        return Ok(PyDataFrame { inner: frame });
    }

    let s = PySeries::from_data(py, Some(data), None, None)?;
    // A Series' columns are its levels themselves, typed (fvsao.32), or the
    // prefix's text before each.
    let prefix: Option<String> = prefix.map(|prefix| prefix.str()?.extract()).transpose()?;
    if prefix.is_none() && dummy_na && s.inner.column().is_pandas_string() {
        return Err(not_implemented(
            "get_dummies of a string Series with dummy_na: pandas labels the missing level pd.NA, \
             which a column label here cannot hold apart from None",
        ));
    }
    let mut out = Vec::new();
    for (level, indicator) in dummy_levels(s.inner.column(), dummy_na, drop_first, dtype)? {
        let label = match &prefix {
            Some(prefix) => IndexLabel::Utf8(format!(
                "{prefix}{prefix_sep}{}",
                dummy_level_text(py, &level)?
            )),
            None => level,
        };
        out.push((label, indicator));
    }
    Ok(PyDataFrame {
        inner: frame_of_labelled_columns(s.inner.index().clone(), out)?,
    })
}

/// A crosstab `table` normalized as pandas' `_normalize`: over everything
/// ("all"), each row ("index") or each column ("columns"), missing cells 0.
fn crosstab_normalized<'py>(table: &Bound<'py, PyAny>, how: &str) -> PyResult<Bound<'py, PyAny>> {
    let py = table.py();
    let normalized = match how {
        "all" => {
            let total = table.call_method0("sum")?.call_method0("sum")?;
            table.call_method1("__truediv__", (total,))?
        }
        "index" => {
            let sums = PyDict::new(py);
            sums.set_item("axis", 1)?;
            let row_sums = table.call_method("sum", (), Some(&sums))?;
            let div = PyDict::new(py);
            div.set_item("axis", 0)?;
            table.call_method("div", (row_sums,), Some(&div))?
        }
        _ => {
            let column_sums = table.call_method0("sum")?;
            table.call_method1("__truediv__", (column_sums,))?
        }
    };
    normalized.call_method1("fillna", (0_i64,))
}

/// A crosstab `table` with margins normalized as pandas' `_normalize`: the
/// core (margins left out) normalized as without them, then per row the
/// margin row, per column the margin column, over everything both (their
/// shares, the corner 1), each margin over its own total (it was refused;
/// br-frankenpandas-n9zpp).
fn crosstab_normalized_margins<'py>(
    table: &Bound<'py, PyAny>,
    how: &str,
    margins_name: &str,
) -> PyResult<Bound<'py, PyAny>> {
    let py = table.py();
    let (index, columns) = (table.getattr("index")?, table.getattr("columns")?);
    let iloc = table.getattr("iloc")?;
    let all_but_last = pyo3::types::PySlice::new(py, 0, -1, 1);
    let column_margin = iloc.get_item((&all_but_last, -1))?;
    let index_margin = iloc.get_item((-1, &all_but_last))?;
    let core = crosstab_normalized(&iloc.get_item((&all_but_last, &all_but_last))?, how)?;
    let share = |margin: &Bound<'py, PyAny>| {
        margin.call_method1("__truediv__", (margin.call_method0("sum")?,))
    };
    let concat = py.import("frankenpandas")?.getattr("concat")?;
    let side_by_side = PyDict::new(py);
    side_by_side.set_item("axis", 1)?;
    let with_column = |core: &Bound<'py, PyAny>| -> PyResult<Bound<'py, PyAny>> {
        let pieces = PyList::new(py, [core.clone(), share(&column_margin)?])?;
        concat.call((pieces,), Some(&side_by_side))
    };
    let with_row =
        |core: &Bound<'py, PyAny>, row: Bound<'py, PyAny>| -> PyResult<Bound<'py, PyAny>> {
            let row = row.call_method0("to_frame")?.getattr("T")?;
            concat.call1((PyList::new(py, [core.clone(), row])?,))
        };
    let table = match how {
        "columns" => {
            let table = with_column(&core)?.call_method1("fillna", (0_i64,))?;
            table.setattr("columns", columns)?;
            table
        }
        "index" => {
            let table = with_row(&core, share(&index_margin)?)?.call_method1("fillna", (0_i64,))?;
            table.setattr("index", index)?;
            table
        }
        _ => {
            let row = share(&index_margin)?;
            row.getattr("loc")?.set_item(margins_name, 1_i64)?;
            let table = with_row(&with_column(&core)?, row)?.call_method1("fillna", (0_i64,))?;
            table.setattr("index", index)?;
            table.setattr("columns", columns)?;
            table
        }
    };
    Ok(table)
}

/// pandas' `crosstab(index, columns, values=None, rownames=None,
/// colnames=None, aggfunc=None, margins=False, margins_name='All',
/// dropna=True, normalize=False)`, built as pandas builds it: a frame of the
/// row keys, the column keys and the values (zeros when counting), pivoted
/// with `aggfunc` (a count, filled with 0, when there are no values),
/// margins included, then normalized over everything / each row / each
/// column. It counted text-converted labels (ints sorted as text: 10 before
/// 2), refused values / aggfunc / margins / names and took only a bool
/// normalize.
#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (index, columns, values=None, rownames=None, colnames=None, aggfunc=None, margins=false, margins_name="All", dropna=true, normalize=None))]
fn crosstab<'py>(
    py: Python<'py>,
    index: &Bound<'py, PyAny>,
    columns: &Bound<'py, PyAny>,
    values: Option<&Bound<'py, PyAny>>,
    rownames: Option<Vec<String>>,
    colnames: Option<Vec<String>>,
    aggfunc: Option<&Bound<'py, PyAny>>,
    margins: bool,
    margins_name: &str,
    dropna: bool,
    normalize: Option<&Bound<'py, PyAny>>,
) -> PyResult<Bound<'py, PyAny>> {
    let values = values.filter(|values| !values.is_none());
    let aggfunc = aggfunc.filter(|aggfunc| !aggfunc.is_none());
    match (values, aggfunc) {
        (None, Some(_)) => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "aggfunc cannot be used without values.",
            ));
        }
        (Some(_), None) => {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "values cannot be used without an aggfunc.",
            ));
        }
        _ => {}
    }
    // Several arrays per axis (a list of Series) make a MultiIndex axis.
    let several = |keys: &Bound<'py, PyAny>| {
        keys.is_instance_of::<PyList>()
            && keys
                .try_iter()
                .ok()
                .and_then(|mut items| items.next())
                .and_then(Result::ok)
                .is_some_and(|first| is_sequence(&first))
    };
    // Each axis's arrays: a list of them (a list of one is that array), else
    // the one array (several were refused).
    let arrays = |keys: &Bound<'py, PyAny>| -> PyResult<Vec<Bound<'py, PyAny>>> {
        if several(keys) {
            keys.try_iter()?.collect()
        } else {
            Ok(vec![keys.clone()])
        }
    };
    let row_arrays = arrays(index)?;
    let col_arrays = arrays(columns)?;
    // "all" / True over everything, "index" per row, "columns" per column.
    let normalize = match normalize.filter(|value| !value.is_none()) {
        None => None,
        Some(value) => match (value.extract::<bool>(), value.extract::<String>()) {
            (Ok(false), _) => None,
            (Ok(true), _) => Some("all".to_owned()),
            (_, Ok(how)) if matches!(how.as_str(), "all" | "index" | "columns") => Some(how),
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Not a valid normalize argument",
                ));
            }
        },
    };
    let to_series = |arrays: &[Bound<'py, PyAny>]| -> PyResult<Vec<PySeries>> {
        arrays
            .iter()
            .map(|array| PySeries::from_data(py, Some(array), None, None))
            .collect()
    };
    let rows = to_series(&row_arrays)?;
    let cols = to_series(&col_arrays)?;
    let n = rows.first().map_or(0, |row| row.inner.len());
    if rows
        .iter()
        .chain(&cols)
        .any(|series| series.inner.len() != n)
    {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "index and columns must have the same length",
        ));
    }
    // pandas' _get_names: the given name, else the array's, else row_i /
    // col_i.
    let names_of = |given: &Option<Vec<String>>, series: &[PySeries], prefix: &str| {
        series
            .iter()
            .enumerate()
            .map(|(position, series)| {
                given
                    .as_ref()
                    .and_then(|names| names.get(position).cloned())
                    .or_else(|| {
                        (!series.inner.name().is_empty()).then(|| series.inner.name().to_string())
                    })
                    .unwrap_or_else(|| format!("{prefix}_{position}"))
            })
            .collect::<Vec<String>>()
    };
    let row_names = names_of(&rownames, &rows, "row");
    let col_names = names_of(&colnames, &cols, "col");
    let mut distinct: HashSet<&String> = HashSet::new();
    if !row_names
        .iter()
        .chain(&col_names)
        .all(|name| distinct.insert(name))
    {
        return Err(not_implemented(
            "crosstab whose row and column arrays share a name",
        ));
    }
    let data = PyDict::new(py);
    for (name, series) in row_names
        .iter()
        .zip(&rows)
        .chain(col_names.iter().zip(&cols))
    {
        data.set_item(name, Py::new(py, series.clone())?)?;
    }
    let axis_keys = |names: &[String]| -> PyResult<Bound<'py, PyAny>> {
        match names {
            [one] => Ok(pyo3::types::PyString::new(py, one).into_any()),
            _ => Ok(PyList::new(py, names)?.into_any()),
        }
    };
    let pivot_kwargs = PyDict::new(py);
    match (values, aggfunc) {
        (Some(values), Some(aggfunc)) => {
            data.set_item(
                "__dummy__",
                PySeries::from_data(py, Some(values), None, None)?,
            )?;
            pivot_kwargs.set_item("aggfunc", aggfunc)?;
        }
        _ => {
            data.set_item("__dummy__", PyList::new(py, vec![0_i64; n])?)?;
            pivot_kwargs.set_item("aggfunc", "count")?;
            pivot_kwargs.set_item("fill_value", 0_i64)?;
        }
    }
    pivot_kwargs.set_item("values", "__dummy__")?;
    pivot_kwargs.set_item("index", axis_keys(&row_names)?)?;
    pivot_kwargs.set_item("columns", axis_keys(&col_names)?)?;
    pivot_kwargs.set_item("margins", margins)?;
    pivot_kwargs.set_item("margins_name", margins_name)?;
    // dropna=False keeps a missing key as its own row / column (it was
    // refused), as pandas' pivot does.
    pivot_kwargs.set_item("dropna", dropna)?;
    let frame = py.get_type::<PyDataFrame>().call1((data,))?;
    let table = frame.call_method("pivot_table", (), Some(&pivot_kwargs))?;
    let table = match normalize.as_deref() {
        None => table,
        Some(how) if margins => crosstab_normalized_margins(&table, how, margins_name)?,
        Some(how) => crosstab_normalized(&table, how)?,
    };
    if let [row_name] = row_names.as_slice() {
        table.getattr("index")?.setattr("name", row_name)?;
    }
    Ok(table)
}

fn flatten_dict(
    dict: &Bound<'_, PyDict>,
    prefix: &str,
    sep: &str,
    max_level: Option<usize>,
    current_level: usize,
    out: &mut Vec<(String, Py<PyAny>)>,
) -> PyResult<()> {
    for (k, v) in dict.iter() {
        let key_str = k.extract::<String>()?;
        let full_key = if prefix.is_empty() {
            key_str
        } else {
            format!("{prefix}{sep}{key_str}")
        };
        let should_recurse = match max_level {
            Some(max_l) => current_level < max_l,
            None => true,
        };
        if should_recurse && v.is_instance_of::<PyDict>() {
            let nested = v.cast::<PyDict>()?;
            flatten_dict(nested, &full_key, sep, max_level, current_level + 1, out)?;
        } else {
            out.push((full_key, v.into_any().unbind()));
        }
    }
    Ok(())
}

/// pandas' `json_normalize(record_path=, meta=)` (its `_recursive_extract`):
/// the records found by following `record_path` through `data`, each
/// flattened, with every `meta` path's value repeated over the records it
/// came with.
struct JsonRecords<'py> {
    py: Python<'py>,
    /// Each meta path, and its column name (the path joined by `sep`).
    meta: Vec<(Vec<Bound<'py, PyAny>>, String)>,
    ignore_missing: bool,
    sep: &'py str,
    max_level: Option<usize>,
    records: Vec<Bound<'py, PyAny>>,
    lengths: Vec<usize>,
    meta_values: Vec<Vec<Bound<'py, PyAny>>>,
}

impl<'py> JsonRecords<'py> {
    #[allow(clippy::too_many_arguments)]
    fn extract(
        py: Python<'py>,
        data: &Bound<'py, PyAny>,
        record_path: &Bound<'py, PyAny>,
        meta: Option<&Bound<'py, PyAny>>,
        meta_prefix: Option<&str>,
        record_prefix: Option<&str>,
        ignore_missing: bool,
        sep: &'py str,
        max_level: Option<usize>,
    ) -> PyResult<PyDataFrame> {
        let path_of = |spec: &Bound<'py, PyAny>| -> PyResult<Vec<Bound<'py, PyAny>>> {
            if spec.is_instance_of::<PyList>() {
                spec.try_iter()?.collect()
            } else {
                Ok(vec![spec.clone()])
            }
        };
        let meta_specs: Vec<Bound<'py, PyAny>> = match meta {
            None => Vec::new(),
            Some(meta) if meta.is_instance_of::<PyList>() => {
                meta.try_iter()?.collect::<PyResult<_>>()?
            }
            Some(meta) => vec![meta.clone()],
        };
        let mut paths = Vec::with_capacity(meta_specs.len());
        for spec in &meta_specs {
            let path = path_of(spec)?;
            let name = path
                .iter()
                .map(|field| field.str().map(|text| text.to_string()))
                .collect::<PyResult<Vec<_>>>()?
                .join(sep);
            paths.push((path, name));
        }
        let mut extractor = Self {
            py,
            meta_values: vec![Vec::new(); paths.len()],
            meta: paths,
            ignore_missing,
            sep,
            max_level,
            records: Vec::new(),
            lengths: Vec::new(),
        };
        let data = if data.is_instance_of::<PyDict>() {
            PyList::new(py, [data])?.into_any()
        } else {
            data.clone()
        };
        let mut seen = HashMap::new();
        extractor.walk(&data, &path_of(record_path)?, &mut seen, 0)?;
        let built = py
            .get_type::<PyDataFrame>()
            .call1((PyList::new(py, &extractor.records)?,))?;
        let mut frame = built.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone();
        if let Some(prefix) = record_prefix {
            let names: Vec<String> = frame.column_names().into_iter().cloned().collect();
            let renames: Vec<(String, String)> = names
                .iter()
                .map(|name| (name.clone(), format!("{prefix}{name}")))
                .collect();
            let pairs: Vec<(&str, &str)> = renames
                .iter()
                .map(|(from, to)| (from.as_str(), to.as_str()))
                .collect();
            frame = frame.rename_columns(&pairs).map_err(frame_error_to_py)?;
        }
        for ((_, name), values) in extractor.meta.iter().zip(&extractor.meta_values) {
            let name = format!("{}{name}", meta_prefix.unwrap_or(""));
            if frame.column(&name).is_some() {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Conflicting metadata name {name}, need distinguishing prefix "
                )));
            }
            // pandas repeats the values in an object array (a dict or a
            // list meta value as itself).
            let mut cells = Vec::with_capacity(extractor.records.len());
            for (value, &count) in values.iter().zip(&extractor.lengths) {
                let cell = py_to_cell(py, value)?;
                cells.extend(std::iter::repeat_n(cell, count));
            }
            frame = frame
                .with_column(name, Column::from_object_values(cells))
                .map_err(frame_error_to_py)?;
        }
        Ok(PyDataFrame { inner: frame })
    }

    /// `obj[spec...]`: pandas' `_pull_field`, a missing key its KeyError
    /// (or NaN with errors='ignore' outside the record path).
    fn pull(
        &self,
        obj: &Bound<'py, PyAny>,
        spec: &[Bound<'py, PyAny>],
        record: bool,
    ) -> PyResult<Bound<'py, PyAny>> {
        let mut value = obj.clone();
        for field in spec {
            let next = if value.is_none() {
                None
            } else {
                match value.get_item(field) {
                    Ok(next) => Some(next),
                    Err(error) if error.is_instance_of::<pyo3::exceptions::PyKeyError>(self.py) => {
                        None
                    }
                    Err(error) => return Err(error),
                }
            };
            match next {
                Some(next) => value = next,
                None => {
                    let key = field.repr()?;
                    if record {
                        return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                            "Key {key} not found. If specifying a record_path, all elements of data should have the path."
                        )));
                    }
                    if self.ignore_missing {
                        return Ok(pyo3::types::PyFloat::new(self.py, f64::NAN).into_any());
                    }
                    return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                        "Key {key} not found. To replace missing values of {key} with np.nan, pass in errors='ignore'"
                    )));
                }
            }
        }
        Ok(value)
    }

    fn walk(
        &mut self,
        data: &Bound<'py, PyAny>,
        path: &[Bound<'py, PyAny>],
        seen: &mut HashMap<usize, Bound<'py, PyAny>>,
        level: usize,
    ) -> PyResult<()> {
        let items: Vec<Bound<'py, PyAny>> = if data.is_instance_of::<PyDict>() {
            vec![data.clone()]
        } else {
            data.try_iter()?.collect::<PyResult<_>>()?
        };
        if let [head, rest @ ..] = path
            && !rest.is_empty()
        {
            for obj in &items {
                for (slot, (meta, _)) in self.meta.iter().enumerate() {
                    if level + 1 == meta.len() {
                        let value = self.pull(obj, &meta[meta.len() - 1..], false)?;
                        seen.insert(slot, value);
                    }
                }
                self.walk(&obj.get_item(head)?, rest, seen, level + 1)?;
            }
            return Ok(());
        }
        for obj in &items {
            let found = self.pull(obj, path, true)?;
            let records: Vec<Bound<'py, PyAny>> = if found.is_instance_of::<PyList>() {
                found.try_iter()?.collect::<PyResult<_>>()?
            } else if found.is_none() || found.extract::<f64>().is_ok_and(f64::is_nan) {
                Vec::new()
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "{} has non list value {} for path {}. Must be list or null.",
                    obj.repr()?,
                    found.repr()?,
                    path.last().map_or_else(
                        || Ok(String::new()),
                        |key| key.str().map(|k| k.to_string())
                    )?
                )));
            };
            self.lengths.push(records.len());
            for (slot, (meta, _)) in self.meta.iter().enumerate() {
                let value = if level + 1 > meta.len() {
                    seen.get(&slot)
                        .cloned()
                        .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyKeyError, _>(slot))?
                } else {
                    self.pull(obj, &meta[level..], false)?
                };
                self.meta_values[slot].push(value);
            }
            for record in records {
                self.records.push(match record.cast::<PyDict>() {
                    Ok(dict) => {
                        let mut flat = Vec::new();
                        flatten_dict(dict, "", self.sep, self.max_level, 0, &mut flat)?;
                        let out = PyDict::new(self.py);
                        for (key, value) in flat {
                            out.set_item(key, value)?;
                        }
                        out.into_any()
                    }
                    Err(_) => record,
                });
            }
        }
        Ok(())
    }
}

#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (data, record_path=None, meta=None, meta_prefix=None, record_prefix=None, errors="raise", sep=".", max_level=None))]
fn json_normalize(
    py: Python<'_>,
    data: &Bound<'_, PyAny>,
    record_path: Option<&Bound<'_, PyAny>>,
    meta: Option<&Bound<'_, PyAny>>,
    meta_prefix: Option<&str>,
    record_prefix: Option<&str>,
    errors: &str,
    sep: &str,
    max_level: Option<usize>,
) -> PyResult<PyDataFrame> {
    if !matches!(errors, "raise" | "ignore") {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "errors must be 'raise' or 'ignore', got '{errors}'"
        )));
    }
    // Records under `record_path`, each repeated with its `meta` fields
    // (they were refused). Without a record path pandas ignores meta and
    // the prefixes and flattens each dict, as below.
    if let Some(record_path) = record_path.filter(|path| !path.is_none()) {
        return JsonRecords::extract(
            py,
            data,
            record_path,
            meta.filter(|meta| !meta.is_none()),
            meta_prefix,
            record_prefix,
            errors == "ignore",
            sep,
            max_level,
        );
    }
    let mut records: Vec<Vec<(String, Py<PyAny>)>> = Vec::new();
    if let Ok(d) = data.cast::<PyDict>() {
        let mut row = Vec::new();
        flatten_dict(d, "", sep, max_level, 0, &mut row)?;
        records.push(row);
    } else if let Ok(list) = data.cast::<PyList>() {
        for item in list.iter() {
            let mut row = Vec::new();
            if let Ok(d) = item.cast::<PyDict>() {
                flatten_dict(d, "", sep, max_level, 0, &mut row)?;
            }
            records.push(row);
        }
    }
    let mut all_cols = Vec::new();
    let mut col_set = HashSet::new();
    for row in &records {
        for (k, _) in row {
            if col_set.insert(k.clone()) {
                all_cols.push(k.clone());
            }
        }
    }
    let mut col_map: BTreeMap<String, Column> = BTreeMap::new();
    for col_name in &all_cols {
        let mut col_values: Vec<Scalar> = Vec::with_capacity(records.len());
        for row in &records {
            let mut found = None;
            for (k, v) in row {
                if k == col_name {
                    found = Some(v.bind(py));
                    break;
                }
            }
            // A value max_level leaves unflattened (a dict) or a list is an
            // object cell, as pandas keeps it (it raised "Cannot convert
            // dict to Scalar"; br-frankenpandas-u6p7i).
            if let Some(val_bound) = found {
                col_values.push(py_to_cell(py, val_bound)?);
            } else {
                col_values.push(Scalar::Null(NullKind::NaN));
            }
        }
        // A field missing from a record makes an int column float64 with
        // NaN, as the constructor builds it (it stayed int;
        // br-frankenpandas-h06ox).
        let col = Column::from_values(pandas_promote_int_with_missing(col_values))
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        col_map.insert(col_name.clone(), col);
    }
    let len = records.len();
    let index = Index::new((0..len).map(|i| IndexLabel::Int64(i as i64)).collect());
    let df = DataFrame::new_with_column_order(index, col_map, all_cols)
        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
    Ok(PyDataFrame { inner: df })
}

