// MILESTONE I: Extension Dtypes, Options System, Interval, Serialization
// ============================================================================

macro_rules! define_simple_dtype {
    ($struct_name:ident, $class_name:literal, $dtype_name:literal, $kind:literal) => {
        #[pyclass(name = $class_name, from_py_object)]
        #[derive(Clone, Debug, PartialEq, Eq)]
        pub struct $struct_name;

        #[pymethods]
        impl $struct_name {
            #[new]
            fn new() -> Self {
                Self
            }

            /// Pickles (and deep-copies) as `<Class>()` ([`restore`]; no
            /// dtype could be pickled, so neither could `df.dtypes`;
            /// fvsao.58).
            fn __reduce__<'py>(
                &self,
                py: Python<'py>,
            ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
                restore_call(py, $class_name, constructor_payload(py, Vec::new(), &[])?)
            }

            #[getter]
            fn name(&self) -> &'static str {
                $dtype_name
            }

            #[getter]
            fn kind(&self) -> &'static str {
                $kind
            }

            fn __repr__(&self) -> String {
                if $dtype_name == "boolean" {
                    "BooleanDtype".to_string()
                } else {
                    format!("{}()", $class_name)
                }
            }

            fn __str__(&self) -> &'static str {
                $dtype_name
            }

            /// Its own name only, as pandas': Int64Dtype() == 'int64' is
            /// False (the numpy dtype; it compared case-blind, so a masked
            /// Series' dtype equalled 'int64'; br-frankenpandas-doa3k).
            fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
                if let Ok(other_self) = other.extract::<Self>() {
                    return *self == other_self;
                }
                other
                    .extract::<String>()
                    .is_ok_and(|name| name == $dtype_name)
            }

            /// Hashable, as pandas' dtypes are (a set or dict key raised
            /// TypeError).
            fn __hash__(&self) -> u64 {
                dtype_name_hash($dtype_name)
            }
        }
    };
}

/// The hash of a dtype named `name` (pandas hashes a dtype by its name).
fn dtype_name_hash(name: &str) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut hasher = std::collections::hash_map::DefaultHasher::new();
    name.hash(&mut hasher);
    hasher.finish()
}

define_simple_dtype!(PyBooleanDtype, "BooleanDtype", "boolean", "b");
define_simple_dtype!(PyInt8Dtype, "Int8Dtype", "Int8", "i");
define_simple_dtype!(PyInt16Dtype, "Int16Dtype", "Int16", "i");
define_simple_dtype!(PyInt32Dtype, "Int32Dtype", "Int32", "i");
define_simple_dtype!(PyInt64Dtype, "Int64Dtype", "Int64", "i");
define_simple_dtype!(PyUInt8Dtype, "UInt8Dtype", "UInt8", "u");
define_simple_dtype!(PyUInt16Dtype, "UInt16Dtype", "UInt16", "u");
define_simple_dtype!(PyUInt32Dtype, "UInt32Dtype", "UInt32", "u");
define_simple_dtype!(PyUInt64Dtype, "UInt64Dtype", "UInt64", "u");
define_simple_dtype!(PyFloat32Dtype, "Float32Dtype", "Float32", "f");
define_simple_dtype!(PyFloat64Dtype, "Float64Dtype", "Float64", "f");

/// pandas' `StringDtype(storage=None)`: the `string` extension dtype, its
/// storage 'python' (pandas' default) or 'pyarrow' kept for `storage`, the
/// repr and equality - the values have one representation here, so a
/// Series of either storage reports 'python'. 'pyarrow_numpy' (NaN for a
/// missing value, numpy results) is refused. It took no storage
/// (br-frankenpandas-doa3k).
#[pyclass(name = "StringDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PyStringDtype {
    storage: &'static str,
}

impl Default for PyStringDtype {
    fn default() -> Self {
        Self { storage: "python" }
    }
}

#[pymethods]
impl PyStringDtype {
    #[new]
    #[pyo3(signature = (storage=None))]
    fn new(storage: Option<&str>) -> PyResult<Self> {
        match storage.unwrap_or("python") {
            "python" => Ok(Self { storage: "python" }),
            "pyarrow" => Ok(Self { storage: "pyarrow" }),
            "pyarrow_numpy" => Err(not_implemented("StringDtype('pyarrow_numpy')")),
            other => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Storage must be 'python', 'pyarrow' or 'pyarrow_numpy'. Got {other} instead."
            ))),
        }
    }

    /// Pickles (and deep-copies) as `StringDtype(storage)` ([`restore`];
    /// fvsao.58).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let payload = constructor_payload(py, vec![self.storage.into_bound_py_any(py)?], &[])?;
        restore_call(py, "StringDtype", payload)
    }

    /// The dtype a 'string[storage]' spelling names, as pandas'.
    #[classmethod]
    fn construct_from_string(
        _cls: &Bound<'_, pyo3::types::PyType>,
        string: &str,
    ) -> PyResult<Self> {
        match string {
            "string" => Ok(Self::default()),
            "string[python]" => Self::new(Some("python")),
            "string[pyarrow]" => Self::new(Some("pyarrow")),
            "string[pyarrow_numpy]" => Self::new(Some("pyarrow_numpy")),
            other => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "Cannot construct a 'StringDtype' from '{other}'"
            ))),
        }
    }

    #[getter]
    fn name(&self) -> &'static str {
        "string"
    }

    #[getter]
    fn kind(&self) -> &'static str {
        "O"
    }

    #[getter]
    fn storage(&self) -> &'static str {
        self.storage
    }

    #[getter]
    fn na_value(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        na_object(py)
    }

    fn __repr__(&self) -> String {
        format!("string[{}]", self.storage)
    }

    fn __str__(&self) -> &'static str {
        "string"
    }

    /// pandas' equality: 'string' names any storage, 'string[s]' and a
    /// StringDtype this storage only.
    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other) = other.extract::<Self>() {
            return other.storage == self.storage;
        }
        other
            .extract::<String>()
            .is_ok_and(|name| name == "string" || name == self.__repr__())
    }

    fn __hash__(&self) -> u64 {
        dtype_name_hash("string")
    }
}

/// pandas' `CategoricalDtype`. The categories are values of their own
/// kind: they were their text, so `CategoricalDtype([1, 2])` matched no int
/// and printed `["1", "2"]` with categories_dtype=object (fvsao.54).
#[pyclass(name = "CategoricalDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq)]
pub struct PyCategoricalDtype {
    pub categories: Option<Vec<Scalar>>,
    #[pyo3(get)]
    pub ordered: bool,
}

#[pymethods]
impl PyCategoricalDtype {
    #[new]
    #[pyo3(signature = (categories=None, ordered=false))]
    fn new(
        py: Python<'_>,
        categories: Option<&Bound<'_, PyAny>>,
        ordered: Option<bool>,
    ) -> PyResult<Self> {
        Ok(Self {
            categories: categories
                .filter(|categories| !categories.is_none())
                .map(|categories| py_categories(py, categories))
                .transpose()?,
            ordered: ordered.unwrap_or(false),
        })
    }

    /// Pickles (and deep-copies) as `CategoricalDtype(categories,
    /// ordered=)`, the categories as a list of their values ([`restore`];
    /// fvsao.58).
    fn __reduce__<'py>(
        slf: &Bound<'py, Self>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let py = slf.py();
        let categories = slf.getattr("categories")?;
        let categories = if categories.is_none() {
            categories
        } else {
            PyList::new(py, categories.try_iter()?.collect::<PyResult<Vec<_>>>()?)?.into_any()
        };
        let payload = constructor_payload(
            py,
            vec![categories],
            &[("ordered", slf.getattr("ordered")?)],
        )?;
        restore_call(py, "CategoricalDtype", payload)
    }

    #[getter]
    fn name(&self) -> &'static str {
        "category"
    }

    #[getter]
    fn kind(&self) -> &'static str {
        "O"
    }

    /// The categories as an Index (an IntervalIndex of Intervals), or None.
    #[getter]
    fn categories(&self, py: Python<'_>) -> PyResult<Option<Py<PyAny>>> {
        self.categories
            .as_deref()
            .map(|categories| categories_index(py, categories))
            .transpose()
    }

    /// pandas' repr: the categories as its Index summary lists them (and
    /// wraps them, a lone ',' line after), their dtype.
    fn __repr__(&self) -> String {
        let ordered = if self.ordered { "True" } else { "False" };
        match &self.categories {
            Some(categories) => {
                let justify = !categories.iter().all(|c| matches!(c, Scalar::Utf8(_)));
                let data = pandas_object_summary(
                    Some("CategoricalDtype"),
                    &category_repr_items(categories),
                    justify,
                );
                format!(
                    "CategoricalDtype(categories={}, ordered={ordered}, categories_dtype={})",
                    data.trim_end_matches([',', ' ']),
                    categories_dtype_name(categories)
                )
            }
            None => format!(
                "CategoricalDtype(categories=None, ordered={ordered}, categories_dtype=None)"
            ),
        }
    }

    fn __str__(&self) -> &'static str {
        "category"
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_cat) = other.extract::<Self>() {
            return *self == other_cat;
        }
        if let Ok(s) = other.extract::<String>() {
            return s == "category";
        }
        false
    }
}

#[pyclass(name = "DatetimeTZDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PyDatetimeTZDtype {
    #[pyo3(get)]
    pub unit: String,
    /// The zone's canonical name; Python reads it as a tzinfo object.
    pub tz: String,
}

#[pymethods]
impl PyDatetimeTZDtype {
    /// A zone given by name or as a tzinfo object (only a str was taken),
    /// named as pandas names it ('+09:00' is 'UTC+09:00'); none is pandas'
    /// TypeError (it was UTC).
    #[new]
    #[pyo3(signature = (unit="ns", tz=None))]
    fn new(unit: Option<&str>, tz: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let zone = tz
            .filter(|tz| !tz.is_none())
            .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyTypeError, _>("A 'tz' is required."))?;
        Ok(Self {
            unit: unit.unwrap_or("ns").to_string(),
            tz: tz_name(zone)?,
        })
    }

    /// Pickles (and deep-copies) as `DatetimeTZDtype(unit=, tz=)`, the
    /// zone as its tzinfo ([`restore`]; fvsao.58).
    fn __reduce__<'py>(
        slf: &Bound<'py, Self>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let py = slf.py();
        let payload = constructor_payload(
            py,
            Vec::new(),
            &[("unit", slf.getattr("unit")?), ("tz", slf.getattr("tz")?)],
        )?;
        restore_call(py, "DatetimeTZDtype", payload)
    }

    /// The zone as pandas' tzinfo object (see [`zone_tzinfo`]; it was the
    /// name, a str).
    #[getter]
    fn tz<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        zone_tzinfo(py, &self.tz)
    }

    #[getter]
    fn name(&self) -> String {
        format!("datetime64[{}, {}]", self.unit, self.tz)
    }

    #[getter]
    fn kind(&self) -> &'static str {
        "M"
    }

    fn __repr__(&self) -> String {
        format!("datetime64[{}, {}]", self.unit, self.tz)
    }

    fn __str__(&self) -> String {
        self.name()
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_dt) = other.extract::<Self>() {
            return *self == other_dt;
        }
        if let Ok(s) = other.extract::<String>() {
            return s == self.name();
        }
        false
    }
}

