#[pyclass(name = "IntervalDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PyIntervalDtype {
    #[pyo3(get)]
    pub subtype: Option<String>,
    #[pyo3(get)]
    pub closed: Option<String>,
}

#[pymethods]
impl PyIntervalDtype {
    #[new]
    #[pyo3(signature = (subtype=None, closed=None))]
    fn new(subtype: Option<&str>, closed: Option<&str>) -> Self {
        Self {
            subtype: subtype.map(str::to_string),
            closed: closed.map(str::to_string),
        }
    }

    /// Pickles (and deep-copies) as `IntervalDtype(subtype, closed=)`
    /// ([`restore`]; fvsao.58).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let payload = constructor_payload(
            py,
            vec![self.subtype.as_deref().into_bound_py_any(py)?],
            &[("closed", self.closed.as_deref().into_bound_py_any(py)?)],
        )?;
        restore_call(py, "IntervalDtype", payload)
    }

    #[getter]
    fn name(&self) -> &'static str {
        "interval"
    }

    #[getter]
    fn kind(&self) -> &'static str {
        "O"
    }

    fn __repr__(&self) -> String {
        match (&self.subtype, &self.closed) {
            (Some(st), Some(cl)) => format!("interval[{}, {}]", st, cl),
            (Some(st), None) => format!("interval[{}]", st),
            _ => "interval".to_string(),
        }
    }

    fn __str__(&self) -> String {
        self.__repr__()
    }

    /// pandas' IntervalDtype equality: another IntervalDtype alike, or its
    /// name or full text in any case ('interval', 'interval[int64,
    /// right]'; only 'interval' matched; q69jo).
    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_dt) = other.extract::<Self>() {
            return *self == other_dt;
        }
        if let Ok(s) = other.extract::<String>() {
            let s = s.to_lowercase();
            return s == "interval" || s == self.__repr__().to_lowercase();
        }
        false
    }
}

#[pyclass(name = "SparseDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PySparseDtype {
    #[pyo3(get)]
    pub dtype: String,
    #[pyo3(get)]
    pub fill_value: String,
}

#[pymethods]
impl PySparseDtype {
    #[new]
    #[pyo3(signature = (dtype="float64", fill_value=None))]
    fn new(dtype: Option<&str>, fill_value: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let fv_str = match fill_value {
            Some(v) => {
                if v.is_none() {
                    "nan".to_string()
                } else {
                    v.str()?.to_str()?.to_string()
                }
            }
            None => "nan".to_string(),
        };
        Ok(Self {
            dtype: dtype.unwrap_or("float64").to_string(),
            fill_value: fv_str,
        })
    }

    /// Pickles (and deep-copies) as `SparseDtype(dtype, fill_value)`, the
    /// fill value as the text it keeps ([`restore`]; fvsao.58).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let payload = constructor_payload(
            py,
            vec![
                self.dtype.as_str().into_bound_py_any(py)?,
                self.fill_value.as_str().into_bound_py_any(py)?,
            ],
            &[],
        )?;
        restore_call(py, "SparseDtype", payload)
    }

    #[getter]
    fn name(&self) -> String {
        format!("Sparse[{}, {}]", self.dtype, self.fill_value)
    }

    #[getter]
    fn kind(&self) -> &'static str {
        "f"
    }

    fn __repr__(&self) -> String {
        self.name()
    }

    fn __str__(&self) -> String {
        self.name()
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_dt) = other.extract::<Self>() {
            return *self == other_dt;
        }
        if let Ok(s) = other.extract::<String>() {
            return s == self.name() || s == "Sparse";
        }
        false
    }
}

#[pyclass(name = "ArrowDtype", from_py_object)]
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PyArrowDtype {
    #[pyo3(get)]
    pub pyarrow_dtype: String,
}

#[pymethods]
impl PyArrowDtype {
    #[new]
    #[pyo3(signature = (pyarrow_dtype=None))]
    fn new(pyarrow_dtype: Option<&Bound<'_, PyAny>>) -> PyResult<Self> {
        let dt_str = match pyarrow_dtype {
            Some(v) => {
                if let Ok(s) = v.extract::<String>() {
                    s
                } else {
                    v.str()?.to_str()?.to_string()
                }
            }
            None => "null".to_string(),
        };
        Ok(Self {
            pyarrow_dtype: dt_str,
        })
    }

    /// Pickles (and deep-copies) as `ArrowDtype(pyarrow_dtype)`, the type
    /// by its name ([`restore`]; fvsao.58).
    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let payload = constructor_payload(
            py,
            vec![self.pyarrow_dtype.as_str().into_bound_py_any(py)?],
            &[],
        )?;
        restore_call(py, "ArrowDtype", payload)
    }

    #[getter]
    fn name(&self) -> String {
        format!("{}[pyarrow]", self.pyarrow_dtype)
    }

    #[getter]
    fn kind(&self) -> &'static str {
        if self.pyarrow_dtype.starts_with("uint") {
            "u"
        } else if self.pyarrow_dtype.starts_with("int") {
            "i"
        } else if self.pyarrow_dtype.starts_with("float")
            || self.pyarrow_dtype.starts_with("double")
        {
            "f"
        } else if self.pyarrow_dtype.starts_with("bool") {
            "b"
        } else if self.pyarrow_dtype.starts_with("timestamp")
            || self.pyarrow_dtype.starts_with("date")
        {
            "M"
        } else if self.pyarrow_dtype.starts_with("duration")
            || self.pyarrow_dtype.starts_with("time")
        {
            "m"
        } else {
            "O"
        }
    }

    fn __repr__(&self) -> String {
        self.name()
    }

    fn __str__(&self) -> String {
        self.name()
    }

    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        if let Ok(other_dt) = other.extract::<Self>() {
            return *self == other_dt;
        }
        if let Ok(s) = other.extract::<String>() {
            return s == self.name();
        }
        false
    }
}

// 2. Options System
#[derive(Clone, Debug, PartialEq)]
enum OptionValue {
    None,
    Int(i64),
    Float(f64),
    Bool(bool),
    Str(String),
    /// A callable - `display.float_format` (it was refused;
    /// br-frankenpandas-fzfbp).
    Object(OptionObject),
}

/// A callable option value, compared by identity.
#[derive(Clone)]
struct OptionObject(std::sync::Arc<Py<PyAny>>);

impl std::fmt::Debug for OptionObject {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("<callable>")
    }
}

impl PartialEq for OptionObject {
    fn eq(&self, other: &Self) -> bool {
        std::sync::Arc::ptr_eq(&self.0, &other.0)
    }
}

impl OptionValue {
    fn to_py<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        match self {
            Self::None => Ok(py.None().into_bound(py)),
            Self::Int(i) => i.into_bound_py_any(py),
            Self::Float(f) => f.into_bound_py_any(py),
            Self::Bool(b) => b.into_bound_py_any(py),
            Self::Str(s) => s.into_bound_py_any(py),
            Self::Object(object) => Ok(object.0.bind(py).clone()),
        }
    }

    fn from_py(val: &Bound<'_, PyAny>) -> PyResult<Self> {
        if val.is_none() {
            Ok(Self::None)
        } else if val.is_instance_of::<pyo3::types::PyBool>() {
            Ok(Self::Bool(val.extract::<bool>()?))
        } else if let Ok(i) = val.extract::<i64>() {
            Ok(Self::Int(i))
        } else if let Ok(f) = val.extract::<f64>() {
            Ok(Self::Float(f))
        } else if let Ok(s) = val.extract::<String>() {
            Ok(Self::Str(s))
        } else if val.is_callable() {
            Ok(Self::Object(OptionObject(std::sync::Arc::new(
                val.clone().unbind(),
            ))))
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Option value must be None, int, float, bool, str or a callable",
            ))
        }
    }
}

/// `display.float_format` as set: the callable every float cell of a repr is
/// rendered with, as pandas' (None when unset).
fn display_float_format() -> Option<OptionObject> {
    let map = GLOBAL_OPTIONS.lock().ok()?;
    match map.get("display.float_format")? {
        OptionValue::Object(object) => Some(object.clone()),
        _ => None,
    }
}

/// pandas' validator for `key`: display.float_format takes a callable or
/// None, the display counts a nonnegative int or None (either was stored
/// as given; br-frankenpandas-fzfbp).
fn validate_option(key: &str, value: &OptionValue) -> PyResult<()> {
    let message = match key {
        "display.float_format" => (!matches!(value, OptionValue::None | OptionValue::Object(_)))
            .then_some("Value must be a callable"),
        "display.precision"
        | "display.max_rows"
        | "display.max_columns"
        | "display.max_colwidth"
        | "display.max_dir_items" => (!matches!(
            value,
            OptionValue::None | OptionValue::Bool(_) | OptionValue::Int(0..)
        ))
        .then_some("Value must be a nonnegative integer or None"),
        _ => None,
    };
    message.map_or(Ok(()), |message| {
        Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(message))
    })
}

