#[pyfunction]
#[allow(clippy::too_many_arguments)]
#[pyo3(signature = (filepath_or_buffer, convert_dates=true, convert_categoricals=true, index_col=None, convert_missing=false, preserve_dtypes=true, columns=None, order_categoricals=true, chunksize=None, iterator=false, compression="infer", storage_options=None))]
fn read_stata(
    py: Python<'_>,
    filepath_or_buffer: &Bound<'_, PyAny>,
    convert_dates: bool,
    convert_categoricals: bool,
    index_col: Option<&Bound<'_, PyAny>>,
    convert_missing: bool,
    preserve_dtypes: bool,
    columns: Option<&Bound<'_, PyAny>>,
    order_categoricals: bool,
    chunksize: Option<i64>,
    iterator: bool,
    compression: &str,
    storage_options: Option<&Bound<'_, PyDict>>,
) -> PyResult<PyDataFrame> {
    let _ = (
        py,
        convert_dates,
        convert_categoricals,
        order_categoricals,
        compression,
    );
    if convert_missing || chunksize.is_some() || iterator || storage_options.is_some() {
        return Err(not_implemented(
            "read_stata(convert_missing/chunksize/iterator/storage_options=...)",
        ));
    }
    // preserve_dtypes keeps each numeric column's Stata width (it was
    // ignored: every number came back int64 / float64; 18pyl).
    let frame = fp_io::read_stata_bytes(&py_input_bytes(filepath_or_buffer)?, preserve_dtypes)
        .map_err(io_error_to_py)?;
    let frame = select_columns_arg(frame, columns)?;
    let frame = match index_col.filter(|i| !i.is_none()) {
        None => frame,
        Some(col) => frame
            .set_index(&col.extract::<String>()?, true)
            .map_err(frame_error_to_py)?,
    };
    Ok(PyDataFrame { inner: frame })
}

