            let id_v = pyo3::types::PyList::new(py, vec!["a"]).expect("list"); // ubs:ignore — test fixture
            let melted = py_df
                .melt(Some(id_v.as_any()), None, None, None, None, true)
                .expect("melt"); // ubs:ignore — test fixture
