    #[test]
    fn test_py_groupby_and_resampler() {
        let s = Series::from_values(
            "vals",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
            ],
            vec![
                Scalar::Float64(10.0),
                Scalar::Float64(20.0),
                Scalar::Float64(30.0),
                Scalar::Float64(40.0),
            ],
        )
        .expect("series"); // ubs:ignore — test fixture
        let py_s = PySeries { inner: s };

        let by_s = Series::from_values(
            "k",
            vec![
                IndexLabel::Int64(0),
                IndexLabel::Int64(1),
                IndexLabel::Int64(2),
                IndexLabel::Int64(3),
            ],
            vec![
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("b".to_string()),
                Scalar::Utf8("a".to_string()),
                Scalar::Utf8("b".to_string()),
            ],
        )
        .expect("by_series"); // ubs:ignore — test fixture

        let sgb = PySeriesGroupBy {
            series: py_s.inner.clone(),
            by: by_s,
            sort: true,
            as_index: true,
            groups: None,
            unused: Vec::new(),
            group_keys: true,
        };

        // Reductions return a Series (or, with as_index=False, a frame).
        let as_series = |obj: PyResult<Py<PyAny>>| -> PySeries {
            Python::attach(|py| obj.and_then(|o| o.extract::<PySeries>(py).map_err(PyErr::from)))
                .expect("a Series") // ubs:ignore — test fixture
        };
        let sum_s = as_series(sgb.sum(false, 0, None, None));
        assert_eq!(sum_s.inner.len(), 2);
        let mean_s = as_series(sgb.mean(false, None, None));
        assert_eq!(mean_s.inner.len(), 2);
        let count_s = as_series(sgb.count());
        assert_eq!(count_s.inner.len(), 2);
        let min_s = as_series(sgb.min(false, -1, None, None));
        assert_eq!(min_s.inner.len(), 2);
        let max_s = as_series(sgb.max(false, -1, None, None));
        assert_eq!(max_s.inner.len(), 2);
        let first_s = as_series(sgb.first(false, -1, true));
        assert_eq!(first_s.inner.len(), 2);
        let last_s = as_series(sgb.last(false, -1, true));
        assert_eq!(last_s.inner.len(), 2);
        let size_s = as_series(sgb.size());
        assert_eq!(size_s.inner.len(), 2);
        let nq = as_series(sgb.nunique(true));
        assert_eq!(nq.inner.len(), 2);
        assert_eq!(sgb.ngroups().expect("ngroups"), 2); // ubs:ignore — test fixture

        let df = DataFrame::from_dict(
            &["grp", "val"],
            vec![
                (
                    "grp",
                    vec![
                        Scalar::Utf8("x".to_string()),
                        Scalar::Utf8("x".to_string()),
                        Scalar::Utf8("y".to_string()),
                    ],
                ),
                (
                    "val",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(3.0),
                    ],
                ),
            ],
        )
        .expect("df"); // ubs:ignore — test fixture
        let py_df = PyDataFrame { inner: df };

        let gb = PyGroupBy {
            df: py_df.inner.clone(),
            by: vec!["grp".to_string()],
            key_names: vec![Some("grp".into())],
            as_index: true,
            sort: true,
            dropna: true,
            group_keys: true,
            unused: Vec::new(),
            selection: None,
            repeated: None,
        };
        let gb_first = gb.first(false, -1, true).expect("first"); // ubs:ignore — test fixture
        assert_eq!(gb_first.shape(), (2, 1));
        let gb_last = gb.last(false, -1, true).expect("last"); // ubs:ignore — test fixture
        assert_eq!(gb_last.shape(), (2, 1));
        let gb_size = Python::attach(|py| {
            gb.size(py)
                .and_then(|o| o.extract::<PySeries>(py).map_err(PyErr::from))
        })
        .expect("size"); // ubs:ignore — test fixture
        assert_eq!(gb_size.inner.len(), 2);
        let gb_nq = gb.nunique(true).expect("nunique"); // ubs:ignore — test fixture
        assert_eq!(gb_nq.shape(), (2, 1));
        assert_eq!(gb.ngroups().expect("ngroups"), 2); // ubs:ignore — test fixture

        Python::attach(|py| {
            let rule = pyo3::types::PyString::new(py, "1D");
            // These fixtures are integer-indexed, which pandas refuses to
            // resample (TypeError); this used to build a resampler that binned
            // nothing.
            let resample_df = |frame: &PyDataFrame| {
                frame.resample(
                    py,
                    rule.as_any(),
                    Passed(None),
                    None,
                    None,
                    Passed(None),
                    Passed(None),
                    None,
                    None,
                    None,
                    None,
                    false,
                )
            };
            let resample_s = |series: &PySeries| {
                series.resample(
                    py,
                    rule.as_any(),
                    Passed(None),
                    None,
                    None,
                    Passed(None),
                    Passed(None),
                    None,
                    None,
                    None,
                    None,
                    false,
                )
            };
            let refused = resample_df(&py_df);
            assert!(refused.is_err_and(|e| e.is_instance_of::<pyo3::exceptions::PyTypeError>(py)));
            assert!(resample_s(&py_s).is_err());

            let dated = PySeries {
                inner: Series::from_values(
                    "v",
                    vec![IndexLabel::Datetime64(0)],
                    vec![Scalar::Float64(1.0)],
                )
                .expect("series"), // ubs:ignore — test fixture
            };
            let resampler_s = resample_s(&dated).expect("resample"); // ubs:ignore — test fixture
            assert_eq!(resampler_s.freq, "1D");
        });
    }

